    /// The first-run specimens (`OnboardingAnatomy`) hand ``NotchOverlayView`` a store that is
    /// inert (no services, socket or user files), has two products, and is shut and open
    /// respectively. The width is load-bearing: the window pins trailing parts from its right
    /// edge, so the specimen must match `PanelMetrics.size` for the no-notch pill.
    @Test @MainActor
    func theFirstRunSpecimensAreTheProductAndWatchNothing() throws {
        let shut = NotchSpecimen.shut
        let hovered = NotchSpecimen.hovered

        #expect(!shut.isWatching)
        #expect(!hovered.isWatching)
        #expect(!shut.isExpanded)
        #expect(hovered.isExpanded)

        // Both products, in the bar's own order, each with its own rows.
        #expect(shut.presenceMarks.count == 2)
        #expect(shut.connectedAgents == [.codex, .claudeCode])
        #expect(shut.geometry == .noNotch)
        #expect(shut.compactHeight == PanelMetrics.referenceCompactHeight)

        // The drawing is of an answerable approval: `canBeAnswered` decides `Approve` versus `Read`.
        #expect(shut.status == .approvalNeeded)
        let waiting = try #require(hovered.sessions.first)
        #expect(waiting.status == .approvalNeeded)
        #expect(waiting.request?.canBeAnswered == true)
        #expect(
            PanelMetrics.waitingMarkWord(
                for: waiting.status,
                canBeAnswered: waiting.request?.canBeAnswered == true
            ) == PanelMetrics.waitingMarkApproveWord
        )
        #expect(shut.aggregateSessionCount == shut.sessions.count)
        #expect(shut.compactTimerText != nil)

        // The pill the pins are measured against.
        let composed = PanelMetrics.size(
            geometry: .noNotch,
            isExpanded: false,
            statusReadoutText: shut.statusDisplayName,
            trailing: shut.compactTrailingReading,
            centerOcclusionWidth: 0,
            compactHeight: shut.compactHeight,
            status: shut.status,
            matrixCount: shut.presenceMarks.count,
            sessionCount: shut.aggregateSessionCount,
            drawsMark: shut.drawsCompactMarks
        )
        #expect(shut.currentPanelSize == composed)
        // Rows on both products, so the counts column the anatomy pins measure past is drawn.
        #expect(shut.aggregateSessionCount > 0)
        #expect(shut.aggregateSubagentCount > 0)

        // The reading is drawn at its billed width (ink and ground, plus the buried-finish dot and
        // its `8` when present), so trailing pins measure inwards from the edge.
        let drawn = PanelMetrics.drawnCompactReadingWidth(shut.compactTimerText ?? "")
        let dot = shut.buriesAFinishedTurn ? PanelMetrics.buriedFinishSlotWidth : 0
        #expect(shut.compactDrawnTrailingReadingWidth == drawn + dot)

        // A buried finished turn sets the dot breathing; only the key explains it, and only this pins it.
        #expect(shut.buriesAFinishedTurn)

        // Grouped: three Codex rows and one Claude Code row reach `336`, past the grouped cap, so the
        // figure is drawn at the cap with both headings and the fourth row's top showing.
        let blocks = hovered.sessionGroups
        #expect(blocks.map(\.agent) == [.codex, .claudeCode])
        #expect(blocks.map(\.sessions.count) == [3, 1])
        #expect(
            hovered.sessionListContentHeight
                == PanelMetrics.groupHeadingsHeight(count: 2)
                    + PanelMetrics.sessionRowHeight * 4
        )
        #expect(hovered.sessionViewportHeight == PanelMetrics.groupedSessionViewportCap)
        // The first block waits on the approval, so its heading count is drawn lit.
        #expect(blocks.first?.wantsAttention == true)

        // A finished turn with subagents still working draws a badge (and keeps the mark on radar).
        // Second in the first block, so its pin lands on a listed row.
        let badged = try #require(hovered.sessions.dropFirst().first)
        #expect(badged.agent == .codex)
        #expect(badged.showsSubagentBadge)
        #expect(MonitorAggregation.effectiveStatus(of: badged) == .running)

        // No row draws its own chip: the heading names the product, and the pin says `Project`.
        #expect(!hovered.sessionGroups.isEmpty)

        // The footer: today's spend and the quota control (Codex one window, Claude Code three).
        // Pins 7 and 8 need real quota in this fixture.
        #expect(hovered.footerRules.count == 2)
        let claudeQuota = hovered.footerRules.first { $0.agent == .claudeCode }
        #expect(
            claudeQuota?.windows.map(\.label)
                == ["Current session", "All models", "Fable"]
        )
        #expect(
            hovered.footerRules.first { $0.agent == .codex }?
                .windows.map(\.label) == ["Weekly limit"]
        )
        #expect(hovered.showsQuotaFoldControl)
        #expect(hovered.footerToday.text == "519M today")
        // And the table starts shut, which is what the pins are placed against.
        #expect(!hovered.isQuotaExpanded)

        // One row departs rather than being placed, so the panel draws the Recent seam the eighth
        // pin names.
        #expect(hovered.recentDepartures.count == 1)
        #expect(hovered.recentDepartures.first?.reason == .read)
        #expect(!hovered.isRecentExpanded)
        #expect(!hovered.sessions.contains { $0.id == hovered.recentDepartures[0].session.id })
    }

    /// No two pins on a figure share a point, and every leader stops on the specimen's edge
    /// (`figma-design.md` §7.1). The key does not follow the product: a pin whose part moved stays
    /// at its formula's coordinate. Positions scale with the panel; a pin's badge is `13` pt.
    @Test @MainActor
    func theFirstRunPinsStandApartAndTheirLeadersStopAtTheEdge() {
        let figures: [(what: String, pins: [AnatomyPin], size: CGSize)] = [
            ("the collapsed bar", CollapsedBarAnatomy().pins, CollapsedBarAnatomy().specimenSize),
            ("the panel", ExpandedPanelAnatomy().pins, ExpandedPanelAnatomy().specimenSize),
            ("a permission", OpenCommandAnatomy().pins, OpenCommandAnatomy().specimenSize),
            ("a question", OpenQuestionAnatomy().pins, OpenQuestionAnatomy().specimenSize),
            ("multiple choice", OpenQuestionAnatomy(lesson: .multipleChoice).pins, OpenQuestionAnatomy(lesson: .multipleChoice).specimenSize),
            ("typed answer", OpenQuestionAnatomy(lesson: .typedAnswer).pins, OpenQuestionAnatomy(lesson: .typedAnswer).specimenSize),
            ("the queue", RecentQueueAnatomy().pins, RecentQueueAnatomy().specimenSize)
        ]

        for figure in figures {
            #expect(
                figure.pins.map(\.id) == Array(1...figure.pins.count),
                "the key on \(figure.what) is numbered from one, in order"
            )

            let points = figure.pins.map { CGPoint(x: $0.x, y: $0.y) }
            for (index, point) in points.enumerated() {
                for other in points[(index + 1)...] {
                    #expect(
                        abs(point.x - other.x) > AnatomyMetrics.pinSize
                            || abs(point.y - other.y) > AnatomyMetrics.pinSize,
                        "two pins on \(figure.what) stand on one point"
                    )
                }
            }

            let half = AnatomyMetrics.pinSize / 2
            for pin in figure.pins {
                let landing: CGFloat
                let edge: CGFloat
                switch pin.leader {
                case let .left(length):
                    landing = pin.x - half - length
                    edge = figure.size.width
                case let .right(length):
                    landing = pin.x + half + length
                    edge = 0
                case let .up(length):
                    landing = pin.y - half - length
                    edge = figure.size.height
                case let .down(length):
                    landing = pin.y + half + length
                    edge = 0
                case let .forkRight(stem, _, foot):
                    landing = pin.x + half + stem + foot
                    edge = 0
                }
                #expect(
                    abs(landing - edge) < 0.01,
                    "pin \(pin.id) on \(figure.what) stops short of its edge, or crosses it"
                )
            }
        }
    }

    /// No two callouts in a README card column stand on one line. The figure renders only with
    /// `~/.notchline-anatomy-out` set, so nothing else catches an overlap. A label centres on
    /// `target.y + drop`, so consecutive labels need one line between them. Leading and trailing
    /// columns only: `.above`/`.below` step sideways over widths this cannot know.
    @Test @MainActor
    func theReadmeCalloutsStandApartInTheirColumns() {
        let now = Date()
        let compact = AnatomyFigureRenderer.store(
            isExpanded: false,
            buriedFinish: true,
            at: now,
            on: AnatomyFigureRenderer.compactDisplay
        )
        let expanded = AnatomyFigureRenderer.store(
            isExpanded: true,
            buriedFinish: true,
            at: now,
            on: AnatomyFigureRenderer.panelDisplay
        )
        expanded.stageSpecimenQueue(AnatomyFigureRenderer.departures(at: now))
        expanded.isRecentExpanded = true
        expanded.isQuotaExpanded = true

        // One line of the card's label face: the clearance two labels need.
        let line = NSFont.systemFont(ofSize: 13).boundingRectForFont.height
        let card = ReadmeAnatomyCard(compact: compact, expanded: expanded)

        for (what, callouts) in [
            ("the panel", card.expandedCallouts),
            ("the collapsed bar", card.compactCallouts)
        ] {
            for side in [AnatomyCallout.Side.leading, .trailing] {
                let lines = callouts
                    .filter { $0.side == side }
                    .map { $0.target.y + $0.drop }
                    .sorted()
                for (above, below) in zip(lines, lines.dropFirst()) {
                    #expect(
                        below - above >= line,
                        """
                        two \(side) labels on \(what) stand \(below - above)                         apart, inside one \(line) pt line
                        """
                    )
                }
            }
        }
    }

    /// Page changes must not offer a different size to the content-sized
    /// Window scene. Exercise the real SwiftUI trees, including the tall page.
    @Test @MainActor
    func onboardingPagesKeepOneWindowSize() {
        let store = MonitorStore(preferences: nil)
        for page in OnboardingView.Page.allCases {
            let host = NSHostingView(rootView: OnboardingView(page: page).environmentObject(store))
            let expected = NSSize(width: 580, height: 840)
            host.setFrameSize(expected)
            host.layoutSubtreeIfNeeded()
            #expect(host.fittingSize == expected)
        }
    }

    /// The page-three pins belong in the middle of the card's padding,
    /// clear of both the card stroke and the plate, at their actual badge size.
    @Test @MainActor
    func openedSpecimenPinsSitInTheMiddleOfTheCardMargins() {
        let figures: [(pins: [AnatomyPin], size: CGSize)] = [
            (OpenCommandAnatomy().pins, OpenCommandAnatomy().specimenSize),
            (OpenQuestionAnatomy().pins, OpenQuestionAnatomy().specimenSize),
            (RecentQueueAnatomy().pins, RecentQueueAnatomy().specimenSize)
        ]
        for figure in figures {
            let inset = (OnboardingLayout.cardWidth - figure.size.width) / 2
            for pin in figure.pins where pin.x < 0 || pin.x > figure.size.width {
                let centre = inset + pin.x
                let distance = pin.x < 0 ? centre : OnboardingLayout.cardWidth - centre
                #expect(abs(distance - inset / 2) < 0.01)
                #expect(distance - AnatomyMetrics.pinSize / 2 >= 14)
            }
        }
    }

    @Test @MainActor
    func tutorialDraftStagingCannotChangeAWatchingStoresAnswer() async {
        let (store, service, row) = answeringStore(request: questionSet(count: 1), status: .inputNeeded)
        store.toggleOpenRow(row)
        #expect(await eventually { store.isAffirmativeArmed })
        store.answerDraftChanged(to: "My actual answer")
        store.stageSpecimenAnswer(selectedOptions: [0], draft: "Tutorial words")
        #expect(store.answerDraft == "My actual answer")
        #expect(!store.isOptionTicked(0))
        #expect(await service.answersTaken().isEmpty)
    }

    /// The answer page's request shapes and the reading page's Recent queue. A permission has a
    /// refusal and a question does not; choices keep the decoder's option identities.
    @Test @MainActor
    func theFirstRunOpenedSpecimensDrawBothRequestShapesAndAQueueOfAges() throws {
        let opened = NotchSpecimen.openedSpecimens()

        #expect(!opened.command.isWatching)
        #expect(!opened.question.isWatching)
        #expect(!NotchSpecimen.recentQueue.isWatching)

        // A permission, open: the row page two draws shut, and the same request.
        let permission = try #require(opened.command.openSession)
        #expect(permission.threadID == NotchSpecimen.shut.sessions.first?.threadID)
        let granting = try #require(permission.request?.answerRow())
        #expect(granting.affirmative == "Approve")
        #expect(granting.refusal == "Deny")

        // A question, open: no refusal at all, and answers of its own.
        let asked = try #require(opened.question.openSession)
        let answering = try #require(asked.request?.answerRow())
        #expect(answering.affirmative == "Submit")
        #expect(answering.refusal == nil)
        let body = try #require(opened.question.openRowBody)
        #expect(body.options.count == 3)
        #expect(body.options.map(\.id) == Array(body.options.indices))

        // The queue: open, and three rows that left at three different times.
        #expect(NotchSpecimen.recentQueue.isRecentExpanded)
        let queue = NotchSpecimen.recentQueue.recentDepartures
        #expect(queue.count == 3)
        #expect(Set(queue.map(\.departedAt)).count == 3)
        // Newest first, which is the order the section draws them in.
        #expect(queue == queue.sorted { $0.departedAt > $1.departedAt })
    }

    /// The first-run clock restarts every ``NotchSpecimen/clockPeriod`` via
    /// ``NotchSpecimen/cycle()``: re-staging republishes and the reading returns to zero.
    /// `max(now, start)` in ``MonitorStore`` keeps the wrap from reading a negative duration.
    @Test @MainActor
    func theFirstRunClockStartsAgainRatherThanRunningAllAfternoon() {
        // Under ten minutes: at `600` the formatter adds an hours field and the reading changes shape.
        #expect(NotchSpecimen.clockPeriod < .seconds(600))

        func staged(startedAt: Date) -> [AgentSnapshot] {
            [
                AgentSnapshot(
                    agent: .codex,
                    availability: .ready,
                    sessions: [
                        MonitoredSession(
                            agent: .codex,
                            threadID: "clock",
                            turnID: "clock-turn",
                            projectName: "notchline",
                            title: "Wire the quota footer to the fold control",
                            preview: nil,
                            status: .running,
                            startedAt: startedAt
                        )
                    ],
                    quota: .unavailable,
                    diagnostic: nil,
                    setupStatus: .active,
                    presence: .open
                )
            ]
        }

        let store = MonitorStore(
            displays: [NotchSpecimen.display],
            services: [],
            initialSnapshots: staged(startedAt: Date().addingTimeInterval(-595)),
            preferences: nil
        )
        let before = store.compactTimerText
        #expect(before != nil)
        #expect(before != "0:00")

        store.restageSpecimen(staged(startedAt: Date()))
        #expect(store.compactTimerText == "0:00")

        // The wait is the remainder, never a fresh period: going Back cancels the loop, and a sleeping
        // Mac holds the task while the wall clock runs on, so a fixed `sleep(period)` ran past 9:59.
        let stagedAt = Date()
        #expect(
            NotchSpecimen.remainingBeforeWrap(stagedAt: stagedAt, now: stagedAt)
                == NotchSpecimen.clockPeriod
        )
        let halfway = stagedAt.addingTimeInterval(300)
        #expect(
            NotchSpecimen.remainingBeforeWrap(stagedAt: stagedAt, now: halfway)
                < NotchSpecimen.clockPeriod
        )
        // Past the period -- a lid closed over lunch -- wraps at once.
        let afterLunch = stagedAt.addingTimeInterval(3_600)
        #expect(
            NotchSpecimen.remainingBeforeWrap(stagedAt: stagedAt, now: afterLunch)
                == .zero
        )
    }

    /// Each state draws the sheet's pattern. The waveforms are transcribed here because computed
    /// offsets drift silently (a flipped sign on the loom's inner ring still looks like a loom).
    /// Read off the layers, closing keyframe included, not ``NotchMatrixState/track(forCell:)``.
    @Test @MainActor
    func eachStateDrawsThePatternTheSheetDraws() throws {
        /// The lit cells of one mark, in row-major order.
        func cells(_ state: NotchMatrixState) throws -> [CALayer] {
            let view = MatrixIndicatorView(frame: CGRect(x: 0, y: 0, width: 16, height: 16))
            view.apply(state: state, size: 16, isAnimated: true, ink: NotchPalette.themeInk)
            // The unlit bed is first and never animates; any lit pass will do.
            let passes = try #require(view.layer?.sublayers)
            return try #require(passes.last?.sublayers)
        }
        func values(_ cell: CALayer) throws -> [Double] {
            let animation = try #require(
                cell.animation(forKey: "notch.matrix.opacity") as? CAKeyframeAnimation
            )
            return try #require(animation.values as? [NSNumber]).map(\.doubleValue)
        }
        // `CALayer.opacity` is a Float (good to about 6e-8); every tested difference exceeds 1e-3.
        func close(_ a: Double, _ b: Double, _ tolerance: Double = 1e-6) -> Bool {
            abs(a - b) < tolerance
        }

        // Loom: 48 frames. Two rings turn against each other about a still centre: an outer step
        // every three frames clockwise, an inner step every six the other way.
        let loom = try cells(.running)
        #expect(loom.count == MatrixGrid.cellCount)
        // The frame each cell's ring head reaches it on: outer counts up clockwise from the top-left
        // corner, inner counts down.
        let loomPeaks: [Int?] = [
             0,  3,  6,  9, 12,
            45,  0, 42, 36, 15,
            42,  6, nil, 30, 18,
            39, 12, 18, 24, 21,
            36, 33, 30, 27, 24
        ]
        for (index, cell) in loom.enumerated() {
            guard let peak = loomPeaks[index] else {
                // The centre is the pivot: it holds, so it has no animation.
                #expect(cell.animation(forKey: "notch.matrix.opacity") == nil)
                // The pivot is where the stretch puts 0.42, quoted to three decimals;
                // it moves with the floor.
                #expect(close(Double(cell.opacity), 0.404, 5e-4))
                continue
            }
            let track = try values(cell)
            // 48 frames plus the repeat of frame 0 that closes the loop.
            #expect(track.count == 49)
            #expect(track.first == track.last)
            #expect(track.firstIndex(of: try #require(track.max())) == peak)
            // Every cell on a ring takes its head, so every one reaches full.
            #expect(close(try #require(track.max()), 1))
        }
        // Only the outer ring reaches the shared floor, so the two rings read as different gears.
        #expect(close(try #require(values(loom[0]).min()), 0.10))
        #expect(try #require(values(loom[6]).min()) > 0.14)

        // Glide: 40 frames, eight a column, no row term; nothing is exempt or still.
        let glide = try cells(.inputNeeded)
        let glidePeaks = [
            0, 8, 16, 24, 32,
            0, 8, 16, 24, 32,
            0, 8, 16, 24, 32,
            0, 8, 16, 24, 32,
            0, 8, 16, 24, 32
        ]
        for (index, cell) in glide.enumerated() {
            let track = try values(cell)
            #expect(track.count == 41)
            #expect(track.first == track.last)
            #expect(track.firstIndex(of: try #require(track.max())) == glidePeaks[index])
            #expect(close(try #require(track.max()), 1))
            #expect(close(try #require(track.min()), 0.10))
        }
        for column in 0 ..< MatrixGrid.side {
            let down = try (0 ..< MatrixGrid.side)
                .map { try values(glide[$0 * MatrixGrid.side + column]) }
            #expect(down.allSatisfy { $0 == down[0] })
        }
        #expect(try Set(
            (0 ..< MatrixGrid.side).map { try values(glide[$0]).description }
        ).count == MatrixGrid.side)
        // A symmetric profile: a rule falling away only behind its head climbed `0.850` in one frame
        // and read as a strike.
        let crossing = try values(glide[0])
        #expect(close(crossing[1], crossing[crossing.count - 2], 1e-6))
        let intoTheCrest = crossing[0] - crossing[crossing.count - 2]
        #expect(close(intoTheCrest, 0.223, 5e-4))
        let steepest = (1 ..< crossing.count)
            .map { abs(crossing[$0] - crossing[$0 - 1]) }
            .max()
        #expect(close(try #require(steepest), intoTheCrest, 1e-6))

        // Double knock: every cell together, twice, 300ms apart.
        let knock = try cells(.approvalNeeded)
        let knockTrack = try values(knock[0])
        #expect(knockTrack.count == 37)
        #expect(knockTrack.indices.filter { knockTrack[$0] == 1 } == [0, 1, 9, 10, 36])
        for cell in knock {
            #expect(try values(cell) == knockTrack)
        }

        // Terrace: 72 frames. The app's mark breathing: column heights 5 4 3 2 1 (row + column <= 4);
        // a cell's level depends only on its column.
        let terrace = try cells(.completed)
        func step(_ index: Int) -> Int? {
            let row = index / MatrixGrid.side, column = index % MatrixGrid.side
            guard row + column <= MatrixGrid.side - 1 else { return nil }
            return column
        }
        let steps = try (0 ..< MatrixGrid.side).map { column in
            try values(terrace[terrace.indices.first { step($0) == column }!])
        }
        for track in steps {
            #expect(track.count == 73)
            #expect(track.first == track.last)
            #expect(track.firstIndex(of: try #require(track.max())) == 0)
        }
        // The crest frame is the logo (ladder 1.00/.80/.60/.40/.20 lifted by the shared scale); written
        // out, not derived, to catch the mark and pattern drifting apart.
        #expect(zip(steps.map(\.first), [1.0, 0.82, 0.64, 0.46, 0.28])
            .allSatisfy { close($0 ?? .nan, $1, 5e-4) })
        #expect(zip(steps, steps.dropFirst()).allSatisfy { $0.max()! > $1.max()! })
        for (index, cell) in terrace.enumerated() {
            guard let column = step(index) else {
                #expect(cell.animation(forKey: "notch.matrix.opacity") == nil)
                #expect(close(Double(cell.opacity), 0.10))
                continue
            }
            #expect(try values(cell) == steps[column])
        }
        // Every cell on the mark shares an edge with another, so ``MatrixGrid``'s constraint holds.
        #expect(terrace.indices.filter { step($0) != nil }.count == 15)
        func isOnMark(row: Int, column: Int) -> Bool {
            let side = 0 ..< MatrixGrid.side
            guard side.contains(row), side.contains(column) else { return false }
            return step(row * MatrixGrid.side + column) != nil
        }
        #expect(terrace.indices.filter { step($0) != nil }.allSatisfy { index in
            let row = index / MatrixGrid.side, column = index % MatrixGrid.side
            return isOnMark(row: row - 1, column: column)
                || isOnMark(row: row + 1, column: column)
                || isOnMark(row: row, column: column - 1)
                || isOnMark(row: row, column: column + 1)
        })
        // The tall step never goes out, so the mark keeps one silhouette.
        #expect(close(try #require(steps[0].min()), 0.465, 5e-4))

        // Connected and disconnected: a still at the floor three patterns share.
        let inactive = try cells(.inactive)
        for cell in inactive {
            #expect(cell.animation(forKey: "notch.matrix.opacity") == nil)
        }
        let resting = Double(inactive[0].opacity)

        // What separates them: a live pattern always has a lit cell; a resting mark never does.
        func dimmestMark(_ cells: [CALayer]) throws -> Double {
            var animated: [[Double]] = []
            var stillTotal = 0.0
            for cell in cells {
                if cell.animation(forKey: "notch.matrix.opacity") == nil {
                    stillTotal += Double(cell.opacity)
                } else {
                    animated.append(try values(cell))
                }
            }
            let frames = animated.first?.count ?? 1
            return (0 ..< frames)
                .map { frame in
                    (animated.reduce(stillTotal) { $0 + $1[frame] })
                        / Double(MatrixGrid.cellCount)
                }
                .min() ?? 0
        }
        #expect(try dimmestMark(loom) > resting)
        // One scale: brightest `1`, dimmest the shared floor `0.10` (since 2026-09-07, was `0.15`), so
        // quiet comes from lit area and dwell. The knock keeps its own darker silence.
        for (name, mark) in [("loom", loom), ("glide", glide), ("terrace", terrace)] {
            var levels: [Double] = []
            for cell in mark {
                if cell.animation(forKey: "notch.matrix.opacity") == nil {
                    levels.append(Double(cell.opacity))
                } else {
                    levels.append(contentsOf: try values(cell))
                }
            }
            #expect(close(try #require(levels.max()), 1, 5e-4), "\(name) must reach full")
            #expect(close(try #require(levels.min()), 0.10, 5e-4), "\(name) must floor at 0.10")
        }

        #expect(try dimmestMark(glide) > resting)
        #expect(try dimmestMark(terrace) > resting)
        // A mark waiting on a decision is darker in silence than a resting mark: half of how Approval
        // asks.
        #expect(try #require(values(knock[0]).min()) < resting)
        #expect(try dimmestMark(knock) < resting)
    }

    /// Dim-to-lit and back is a cross-fade (a cut reads as a light being thrown); a change between
    /// two live patterns stays a cut.
    @Test @MainActor
    func aMarkFadesBetweenTheStillAndAPatternButNotBetweenTwoPatterns() throws {
        let view = MatrixIndicatorView(frame: CGRect(x: 0, y: 0, width: 16, height: 16))
        func show(_ state: NotchMatrixState) {
            view.apply(
                state: state,
                size: 16,
                isAnimated: true,
                ink: NotchPalette.themeInk
            )
        }
        func passes() throws -> [CALayer] { try #require(view.layer?.sublayers) }
        func dissolve(_ layer: CALayer) -> CABasicAnimation? {
            layer.animation(forKey: MatrixIndicatorView.dissolveAnimationKey)
                as? CABasicAnimation
        }
        func crossing() throws -> (arriving: [CALayer], leaving: [CALayer]) {
            var arriving: [CALayer] = []
            var leaving: [CALayer] = []
            for layer in try passes() {
                guard let animation = dissolve(layer) else { continue }
                if (animation.toValue as? NSNumber)?.floatValue == 0 {
                    leaving.append(layer)
                } else {
                    arriving.append(layer)
                }
            }
            return (arriving, leaving)
        }

        show(.inactive)
        #expect(try passes().count == 5)
        #expect(try passes().allSatisfy { dissolve($0) == nil })

        show(.running)
        #expect(try passes().count == 9)
        let (arriving, leaving) = try crossing()
        #expect(arriving.count == 4)
        #expect(leaving.count == 4)
        for layer in arriving {
            let animation = try #require(dissolve(layer))
            #expect((animation.fromValue as? NSNumber)?.floatValue == 0)
            #expect((animation.toValue as? NSNumber)?.floatValue == layer.opacity)
            #expect(animation.duration == MatrixDissolve.duration)
        }
        for layer in leaving {
            let animation = try #require(dissolve(layer))
            #expect(try #require(animation.fromValue as? NSNumber).floatValue > 0)
        }
        // The bed draws the same cells for every pattern; fading it would fade the mark itself.
        #expect(dissolve(try #require(passes().first)) == nil)
        // The leaving still keeps animating, not a frozen frame.
        for layer in leaving {
            let cell = try #require(layer.sublayers?.first)
            #expect(cell.opacity == Float(NotchMatrixState.inactive.track(forCell: 0)[0]))
        }

        show(.completed)
        #expect(try passes().count == 5)
        #expect(try passes().allSatisfy { dissolve($0) == nil })

        show(.inactive)
        #expect(try crossing().arriving.count == 4)
        #expect(try crossing().leaving.count == 4)

        // At its midpoint the panel's `(0.22, 1, 0.36, 1)` curve is `96%` across, so a `0.20 s`
        // dissolve finished inside `60 ms`; a cross-fade needs a visible middle.
        let midpoint = Self.progress(
            of: MatrixDissolve.timingFunction,
            atFractionOfDuration: 0.5
        )
        #expect(midpoint > 0.4)
        #expect(midpoint < 0.6)
    }

    /// `CAMediaTimingFunction`'s control points are read back so the curve can be checked.
    @MainActor
    static func progress(
        of timing: CAMediaTimingFunction,
        atFractionOfDuration fraction: Double
    ) -> Double {
        func controlPoint(_ index: Int) -> (x: Double, y: Double) {
            var values = [Float](repeating: 0, count: 2)
            timing.getControlPoint(at: index, values: &values)
            return (Double(values[0]), Double(values[1]))
        }
        let first = controlPoint(1)
        let second = controlPoint(2)
        func axis(_ a: Double, _ b: Double, _ t: Double) -> Double {
            3 * pow(1 - t, 2) * t * a + 3 * (1 - t) * t * t * b + pow(t, 3)
        }
        // Parametric: solve the time axis before reading travel.
        var low = 0.0
        var high = 1.0
        for _ in 0 ..< 60 {
            let middle = (low + high) / 2
            if axis(first.x, second.x, middle) < fraction {
                low = middle
            } else {
                high = middle
            }
        }
        return axis(first.y, second.y, (low + high) / 2)
    }

    /// Phase comes from the clock, not from when a mark's layers were built, so two marks in the
    /// same state differ by whole periods.
    @Test @MainActor
    func marksShowingTheSamePatternShowItInSync() async throws {
        /// Not `phase % period == 0`: `1.2` is inexact in binary, so measure distance to the nearer end.
        func offGrid(_ phase: CFTimeInterval, _ period: TimeInterval) -> Double {
            let remainder = phase.truncatingRemainder(dividingBy: period)
            return min(remainder, period - remainder)
        }

        func beginTimes(of state: NotchMatrixState, ink: NotchPalette.MatrixInk)
            throws -> [CFTimeInterval]
        {
            let view = MatrixIndicatorView(frame: CGRect(x: 0, y: 0, width: 16, height: 16))
            view.apply(state: state, size: 16, isAnimated: true, ink: ink)
            let cells = try #require(view.layer?.sublayers).flatMap { $0.sublayers ?? [] }
            return cells.compactMap {
                $0.animation(forKey: "notch.matrix.opacity")?.beginTime
            }
        }

        let sampleInk = NotchPalette.MatrixInk(
            offRed: 0x22 / 255, offGreen: 0x1D / 255, offBlue: 0x1C / 255,
            onRed: 0xF0 / 255, onGreen: 0xE1 / 255, onBlue: 0xE0 / 255
        )
        let builtCodexAt = CACurrentMediaTime()
        let codex = try beginTimes(of: .running, ink: NotchPalette.themeInk)
        try await Task.sleep(for: .milliseconds(120))
        let builtClaudeAt = CACurrentMediaTime()
        let claudeCode = try beginTimes(of: .running, ink: sampleInk)

        // The phase is baked into each cell's track, so `beginTime` is one number per mark. 24 of 25
        // cells across four passes: the loom's centre pivot holds still.
        #expect(codex.count == (MatrixGrid.cellCount - 1) * 4)
        #expect(claudeCode.count == codex.count)
        let codexPhase = try #require(codex.first)
        let claudePhase = try #require(claudeCode.first)
        #expect(codex.allSatisfy { $0 == codexPhase })
        #expect(claudeCode.allSatisfy { $0 == claudePhase })

        // On the period grid and within one period behind build time. The default `beginTime` of 0
        // fails this: it lags the clock by the process's uptime.
        let period = try #require(NotchMatrixState.running.period)
        for (phase, builtAt) in [(codexPhase, builtCodexAt), (claudePhase, builtClaudeAt)] {
            #expect(offGrid(phase, period) < 1e-9)
            #expect(phase <= builtAt)
            #expect(builtAt - phase < period)
        }

        #expect(offGrid(claudePhase - codexPhase, period) < 1e-9)

        // The last whole-period boundary at or before now; 1.2 is the period floating point rounds.
        for period in [0.8, 1.2, 3.0] {
            let anchor = MatrixIndicatorView.phaseAnchor(for: period, now: 10.7)
            #expect(anchor <= 10.7)
            #expect(10.7 - anchor < period)
            #expect(offGrid(anchor, period) < 1e-9)
        }
    }

    @Test @MainActor
    func theMarksAreOnePerConnectedProductInAFixedOrder() throws {
        let running = MonitoredSession(
            agent: .claudeCode,
            threadID: "t", turnID: "u", projectName: "p", title: "t",
            preview: nil, status: .running, startedAt: nil
        )

        // The busy one must not jump to the front, or the marks swap under the eye.
        let both = AgentSnapshotMerge.merge([
            makeAgentSnapshot(.codex, availability: .ready),
            makeAgentSnapshot(.claudeCode, availability: .ready, sessions: [running])
        ])
        #expect(both.presenceMarks.map(\.agent) == [.codex, .claudeCode])
        #expect(both.presenceMarks.map(\.status) == [.connected, .running])

        let claudeOnly = AgentSnapshotMerge.merge([
            makeAgentSnapshot(.codex, availability: .ready, presence: .closed),
            makeAgentSnapshot(.claudeCode, availability: .ready, sessions: [running])
        ])
        #expect(claudeOnly.presenceMarks.map(\.agent) == [.claudeCode])

        let nothing = AgentSnapshotMerge.merge([
            makeAgentSnapshot(.codex, availability: .ready, presence: .closed)
        ])
        #expect(nothing.presenceMarks.count == 1)
        let resting = try #require(nothing.presenceMarks.first)
        #expect(resting.isResting)
        #expect(resting.status == .disconnected)
    }

    /// `dual-agent-design.md` §§10-11: counts ride on the mark so the dots and the badge cannot
    /// disagree.
    @Test @MainActor
    func eachMarkCountsOnlyItsOwnProductsRows() throws {
        func session(
            _ agent: AgentKind,
            _ id: String,
            subagents: Int = 0,
            waiting: Int = 0
        ) -> MonitoredSession {
            MonitoredSession(
                agent: agent,
                threadID: id, turnID: "u-\(id)", projectName: "p", title: "t",
                preview: nil, status: .running, startedAt: nil,
                runningSubagentCount: subagents,
                subagentsAwaitingApprovalCount: waiting
            )
        }

        let merged = AgentSnapshotMerge.merge([
            makeAgentSnapshot(
                .codex,
                availability: .ready,
                sessions: [
                    session(.codex, "a", subagents: 2),
                    session(.codex, "b", subagents: 1),
                    session(.codex, "c")
                ]
            ),
            makeAgentSnapshot(
                .claudeCode,
                availability: .ready,
                sessions: [session(.claudeCode, "d", subagents: 4, waiting: 2)]
            )
        ])

        let marks = merged.presenceMarks
        #expect(marks.map(\.agent) == [.codex, .claudeCode])
        #expect(marks.map(\.sessionCount) == [3, 1])
        // The badge counts every subagent: the two waiting ones are inside the `4`.
        #expect(marks.map(\.subagents) == [
            SubagentBadge(count: 3),
            SubagentBadge(count: 4, wantsAttention: true)
        ])
    }

