    /// The notch-less form: the pill keeps its width and place and gives up all but a `4` pt lip
    /// of its height, drawing nothing inside it. A Turn to attend to brings it back whole, reading
    /// included, where a notched display holds its reading back; hover opens the full panel.
    @Test @MainActor
    func hideNotchlineTucksThePillIntoTheTopEdgeUntilATurnNeedsAPerson() {
        let display = makeDisplay(id: "flat", ordinal: 1, menuBarHeight: 24, hasNotch: false)
        let store = MonitorStore(displays: [display], services: [])
        func apply(_ status: SessionStatus) {
            store.applyForTesting(
                makeAgentSnapshot(
                    .codex,
                    sessions: [
                        makeSession(
                            threadID: "t",
                            status: status,
                            startedAt: Date(timeIntervalSinceNow: -90)
                        )
                    ]
                )
            )
        }
        apply(.running)

        let shown = store.currentPanelSize
        #expect(shown.height == 24)
        #expect(store.drawsCompactMarks)
        #expect(store.drawsCompactMiddle)
        #expect(store.compactReadingSpan?.start != nil)

        store.hidesNotchline = true
        #expect(store.tucksCompactPill)
        #expect(store.currentPanelSize == CGSize(width: shown.width, height: PanelMetrics.tuckedPillHeight))
        #expect(!store.drawsCompactMarks)
        #expect(!store.drawsCompactMiddle)
        // `?.start` because the span is a tuple; nothing ticks out of sight.
        #expect(store.compactReadingSpan?.start == nil)
        #expect(store.currentPanelTrailingAnchor == nil)

        let frame = OverlayPanelLayout.frame(
            on: display.frame,
            panelSize: store.currentPanelSize,
            surfaceShoulder: store.surfaceShoulderRadius
        )
        #expect(frame.maxY == display.frame.maxY)
        #expect(frame.height == PanelMetrics.tuckedPillHeight)
        #expect(frame.midX == display.frame.midX)

        for waiting in [SessionStatus.approvalNeeded, .inputNeeded, .completed] {
            apply(waiting)
            #expect(!store.tucksCompactPill, "\(waiting)")
            #expect(store.currentPanelSize == shown, "\(waiting)")
            #expect(store.drawsCompactMarks, "\(waiting)")
            #expect(store.drawsCompactMiddle, "\(waiting)")
            if waiting != .completed {
                #expect(store.compactReadingSpan?.start != nil, "\(waiting)")
            }
        }

        apply(.running)
        #expect(store.tucksCompactPill)
        store.isExpanded = true
        #expect(!store.tucksCompactPill)
        #expect(store.currentPanelSize.height > shown.height)
    }

    /// `cover-the-words.md`: what is covered, and the pill's middle goes quiet
    /// (``MonitorStore/drawsCompactMiddle``) without writing `Name the work`. The width is pinned:
    /// a shrinking middle would move the anchored mark and reading.
    @Test @MainActor
    func privacyModeCoversEveryWordAndSilencesThePillOutright() {
        let defaults = UserDefaults(suiteName: "privacy-\(UUID().uuidString)")!
        let flat = makeDisplay(id: "flat", ordinal: 1, menuBarHeight: 24, hasNotch: false)
        let session = MonitoredSession(
            agent: .claudeCode,
            threadID: "t-1",
            turnID: "u-1",
            projectName: "notchline",
            title: "Cover the words",
            preview: "Reading the bar",
            status: .approvalNeeded,
            startedAt: Date(),
            request: AgentRequest(id: "c-1", toolName: "Bash", form: .command("ls"))
        )
        let store = MonitorStore(
            displays: [flat],
            services: [],
            initialSnapshot: makeSessionSnapshot([session]),
            preferences: defaults
        )

        #expect(!store.privacyMode)
        #expect(store.namesWorkOnPill)
        #expect(store.drawsCompactMiddle)
        #expect(!store.coversWords(of: session))
        let named = store.currentPanelSize.width

        store.togglePrivacyMode()
        #expect(store.privacyMode)
        #expect(store.coversWords(of: session))
        // `Name the work` is untouched, so turning the cover off restores the name.
        #expect(!store.drawsCompactMiddle)
        #expect(store.namesWorkOnPill)
        #expect(store.currentPanelSize.width == named)

        // An open row is a deliberate press, so it reveals.
        store.toggleOpenRow(session)
        #expect(store.openRowID == session.id)
        #expect(!store.coversWords(of: session))
        store.closeOpenRow()
        #expect(store.coversWords(of: session))

        #expect(
            MonitorStore(displays: [flat], services: [], preferences: defaults)
                .privacyMode
        )
        store.togglePrivacyMode()
        #expect(
            !MonitorStore(displays: [flat], services: [], preferences: defaults)
                .privacyMode
        )
    }

    /// `cover-the-words.md` §6: the component spans the cut-out and both shoulders with a `0.15` s
    /// dwell, so passing pointers would open it. Only opening is gated; leaving still closes.
    @Test @MainActor
    func aCoveredPanelWaitsForAPressInsteadOfOpeningOnHover() async {
        let clock = TestClock()
        let store = MonitorStore(
            displays: [makeDisplay(id: "notched", ordinal: 1, menuBarHeight: 38, hasNotch: true)],
            clock: clock
        )
        store.privacyMode = true

        // The dwell is never started, so a resting pointer costs nothing. Measured against the refresh
        // loop's own parked baseline.
        await clock.settle()
        let parked = clock.sleeperCount
        store.pointerEnteredPanel()
        await clock.settle()
        #expect(clock.sleeperCount == parked)
        await clock.advance(by: MonitorTiming.standard.hoverExpandDelay * 4)
        #expect(!store.isExpanded)

        store.openFromCollapsed()
        #expect(store.isExpanded)

        // Advanced in two steps: a scheduled task registers its sleep after the call returns, so one
        // outrunning advance would leave it parked for ever.
        store.pointerExitedPanel()
        await clock.advance(by: MonitorTiming.standard.hoverCollapseDelay / 2)
        #expect(store.isExpanded)
        await clock.advance(by: MonitorTiming.standard.hoverCollapseDelay)
        #expect(!store.isExpanded)

        // With nothing covered, hover is the way in: one answer per state.
        store.privacyMode = false
        store.openFromCollapsed()
        #expect(!store.isExpanded)
        store.pointerEnteredPanel()
        await clock.advance(by: MonitorTiming.standard.hoverExpandDelay / 2)
        #expect(!store.isExpanded)
        await clock.advance(by: MonitorTiming.standard.hoverExpandDelay)
        #expect(store.isExpanded)
    }

