    /// Three ways out: release, the panel closing (a late release would leave covers up next open),
    /// and the mode ending.
    @Test @MainActor
    func aPeekCannotBeLeftOn() {
        let flat = makeDisplay(id: "flat", ordinal: 1, menuBarHeight: 24, hasNotch: false)
        let store = MonitorStore(
            displays: [flat],
            services: [],
            initialSnapshot: makeSessionSnapshot([])
        )
        store.privacyMode = true
        store.isExpanded = true

        store.beginPeek()
        #expect(store.isPeeking)
        store.collapse()
        #expect(!store.isPeeking)

        store.isExpanded = true
        store.beginPeek()
        #expect(store.isPeeking)
        store.privacyMode = false
        #expect(!store.isPeeking)

        store.beginPeek()
        #expect(!store.isPeeking)
        store.privacyMode = true
        store.isExpanded = false
        store.beginPeek()
        #expect(!store.isPeeking)
    }

    /// A covered panel with no rows covers nothing, and is narrow enough that `restingExpandedWidth`
    /// (two control boxes) binds. The keyboard latch follows the same rule for VoiceOver.
    @Test @MainActor
    func thePeekIsOfferedOnlyWhereThereIsSomethingToLift() {
        let flat = makeDisplay(id: "flat", ordinal: 1, menuBarHeight: 24, hasNotch: false)
        let session = MonitoredSession(
            agent: .codex,
            threadID: "t-1",
            turnID: "u-1",
            projectName: "acme-billing",
            title: "Reconcile the ledger",
            preview: nil,
            status: .running,
            startedAt: Date()
        )
        let empty = MonitorStore(
            displays: [flat],
            services: [],
            initialSnapshot: makeSessionSnapshot([])
        )
        empty.privacyMode = true
        empty.isExpanded = true
        #expect(!empty.hasCoveredRows)

        let listed = MonitorStore(
            displays: [flat],
            services: [],
            initialSnapshot: makeSessionSnapshot([session])
        )
        listed.isExpanded = true
        #expect(!listed.hasCoveredRows)
        listed.privacyMode = true
        #expect(listed.hasCoveredRows)
        listed.toggleAbout()
        #expect(!listed.hasCoveredRows)
        listed.toggleAbout()
        #expect(listed.hasCoveredRows)

        // The keyboard latch holds no press, and is bounded by the panel like every peek.
        listed.togglePeek()
        #expect(listed.isPeeking)
        listed.togglePeek()
        #expect(!listed.isPeeking)
