    /// The peek's box stays mounted while a peek could be offered, and `Privacy Mode` only decides
    /// whether `PeekButton`'s bars draw, so they animate instead of blinking in.
    /// ``MonitorStore/keepsPeekRoom`` follows ``MonitorStore/hasCoveredRows`` except for the mode,
    /// the resting pill included.
    @Test @MainActor
    func theBandKeepsThePeeksRoomWhileTheModeIsOff() {
        let clock = TestClock()
        let store = MonitorStore(
            services: [],
            initialSnapshot: .connecting,
            clock: clock
        )
        store.applyForTesting(
            makeAgentSnapshot(.codex, sessions: [recentTestRow(thread: "read-me")])
        )
        store.isExpanded = true

        #expect(store.keepsPeekRoom)
        #expect(!store.hasCoveredRows)

        store.privacyMode = true
        #expect(store.keepsPeekRoom)
        #expect(store.hasCoveredRows)

        store.toggleAbout()
        #expect(!store.keepsPeekRoom)
        store.toggleAbout()
        #expect(store.keepsPeekRoom)

        store.isExpanded = false
        #expect(!store.keepsPeekRoom)
        store.isExpanded = true
        #expect(store.keepsPeekRoom)

        // The resting pill keeps no room, even with a retired row in the queue:
        // `restingExpandedWidth` is `cut-out + 2 × (clearance + mark + gear + padding)`, with no space
        // for a third box. The row retires while the product is still open.
        store.applyForTesting(makeAgentSnapshot(.codex, sessions: []))
        #expect(store.sessions.isEmpty)
        #expect(!store.recentDepartures.isEmpty)
        #expect(store.keepsPeekRoom)

        store.applyForTesting(
            makeAgentSnapshot(.codex, sessions: [], presence: .closed)
        )
        #expect(!store.recentDepartures.isEmpty)
        #expect(store.expandsToPillOnly)
        #expect(!store.keepsPeekRoom)
        #expect(!store.hasCoveredRows)
    }

    /// Measured 2026-09-10: expanding delivers a spurious `exit` ~`105 ms` after the resize and an
    /// `enter` ~`112 ms` later, pointer still. A covered ``pointerEnteredPanel()`` must still
    /// cancel as ``scheduleHoverAction(after:action:)`` does, or the pressed-open panel shuts.
    @Test @MainActor
    func aPanelOpenedByAPressSurvivesTheResizesOwnExitAndEntry() async {
        let clock = TestClock()
        let store = MonitorStore(
            displays: [makeDisplay(id: "notched", ordinal: 1, menuBarHeight: 38, hasNotch: true)],
            clock: clock
        )
        store.privacyMode = true
        store.pointerEnteredPanel()
        store.openFromCollapsed()
        #expect(store.isExpanded)

        // The exit's collapse must be parked before the entry takes it back, or an early `advance`
        // outruns it and the test passes without the fix.
        await clock.settle()
        let parked = clock.sleeperCount
        store.pointerExitedPanel()
        await clock.settle()
        #expect(clock.sleeperCount == parked + 1)

        store.pointerEnteredPanel()
        await clock.advance(by: MonitorTiming.standard.hoverCollapseDelay / 2)
        await clock.advance(by: MonitorTiming.standard.hoverCollapseDelay * 4)
        #expect(store.isExpanded)

        // A real departure still closes it: the entry takes back one exit, not the rule.
        store.pointerExitedPanel()
        await clock.advance(by: MonitorTiming.standard.hoverCollapseDelay / 2)
        #expect(store.isExpanded)
        await clock.advance(by: MonitorTiming.standard.hoverCollapseDelay)
        #expect(!store.isExpanded)
    }

    /// `.onHover` is an `NSTrackingArea` that speaks only on movement, and the entry was declined
    /// while the mode was on. Opens through the ordinary dwell.
    @Test @MainActor
    func leavingTheModeUnderAStationaryPointerOpensThePanel() async {
        let clock = TestClock()
        let store = MonitorStore(
            displays: [makeDisplay(id: "notched", ordinal: 1, menuBarHeight: 38, hasNotch: true)],
            clock: clock
        )
        store.privacyMode = true

        store.pointerEnteredPanel()
        await clock.advance(by: MonitorTiming.standard.hoverExpandDelay * 4)
        #expect(!store.isExpanded)

        store.privacyMode = false
        await clock.advance(by: MonitorTiming.standard.hoverExpandDelay / 2)
        #expect(!store.isExpanded)
        await clock.advance(by: MonitorTiming.standard.hoverExpandDelay)
        #expect(store.isExpanded)

        // Only under a pointer actually there: turning it off in Settings must not open the panel.
        store.collapse()
        store.privacyMode = true
        store.pointerExitedPanel()
        await clock.advance(by: MonitorTiming.standard.hoverCollapseDelay * 2)
        store.privacyMode = false
        await clock.advance(by: MonitorTiming.standard.hoverExpandDelay * 4)
        #expect(!store.isExpanded)
    }

    /// `cover-the-words.md` §6. `acceptsFirstMouse` hit-tests a primary press before it is
    /// `NSApp.currentEvent`, so a catcher keyed on it answers `nil` (measured 2026-09-10); the
    /// window takes the primary press, and the band's catcher only the secondary.
    @Test @MainActor
    func theBandsCatcherTakesASecondaryPressAndNothingElse() {
        #expect(SecondaryClickView.claims(.rightMouseDown))
        #expect(SecondaryClickView.claims(.rightMouseUp))
        #expect(!SecondaryClickView.claims(.leftMouseDown))
        #expect(!SecondaryClickView.claims(.leftMouseUp))
        #expect(!SecondaryClickView.claims(.scrollWheel))
        #expect(!SecondaryClickView.claims(nil))
    }

    /// Giving up the wings places the body exactly on the hardware shape; a notch with no gap
    /// between auxiliary areas is laid out as emulated, so the preference does not take effect.
    @Test @MainActor
    func aNotchWithNoMeasurableGapCannotGiveUpItsWings() {
        let frame = NSRect(x: 0, y: 0, width: 1_920, height: 1_080)
        let menuBarHeight: CGFloat = 38
        // Both auxiliary areas non-empty (so notched) but meeting, so the cut-out measures zero.
        let unplaceable = DisplayOption(
            id: "notched-unplaceable",
            displayID: nil,
            ordinal: 1,
            name: "Display 1",
            frame: frame,
            visibleFrame: NSRect(
                x: frame.minX,
                y: frame.minY,
                width: frame.width,
                height: frame.height - menuBarHeight
            ),
            safeAreaInsets: NSEdgeInsets(
                top: menuBarHeight,
                left: 0,
                bottom: 0,
                right: 0
            ),
            auxiliaryTopLeftArea: NSRect(
                x: frame.minX,
                y: frame.maxY - menuBarHeight,
                width: frame.width / 2,
                height: menuBarHeight
            ),
            auxiliaryTopRightArea: NSRect(
                x: frame.midX,
                y: frame.maxY - menuBarHeight,
                width: frame.width / 2,
                height: menuBarHeight
            ),
            fallbackMenuBarHeight: menuBarHeight
        )
        #expect(unplaceable.geometry == .notched)
        #expect(unplaceable.centerOcclusionWidth == 0)

        let store = MonitorStore(displays: [unplaceable], services: [])
        #expect(!store.canHideNotchline)

        // The emulated pill keeps its mark: hiding it would leave nothing on screen.
        store.hidesNotchline = true
        #expect(!store.givesUpCompactWings)
        #expect(store.drawsCompactMarks)
        #expect(store.currentPanelSize.width > 0)
    }

    /// Remembered and display-independent. Stands down only on the collapsed surface with hidden
    /// wings and no mark out, where it would draw two grey hooks on the shoulders; a hover panel or
    /// a mark coming out brings it back.
    @Test @MainActor
    func theOutlineIsRememberedAndStandsDownOnlyForTheHiddenCompactSurface() {
        let defaults = UserDefaults(suiteName: "outline-\(UUID().uuidString)")!
        let notched = makeDisplay(
            id: "notched",
            ordinal: 1,
            menuBarHeight: 38,
            hasNotch: true
        )
        let external = makeDisplay(
            id: "external",
            ordinal: 2,
            menuBarHeight: 24,
            hasNotch: false
        )
        let store = MonitorStore(
            displays: [notched, external],
            services: [],
            preferences: defaults
        )
        #expect(!store.drawsSurfaceOutline)
        #expect(!store.showsSurfaceOutline)

        store.drawsSurfaceOutline = true
        #expect(store.showsSurfaceOutline)
        #expect(
            MonitorStore(displays: [notched], services: [], preferences: defaults)
                .drawsSurfaceOutline
        )

        // An emulated pill has an edge too, and is most easily lost on a dark wallpaper.
        store.selectDisplay(id: external.id)
        #expect(store.showsSurfaceOutline)
        store.selectDisplay(id: notched.id)

        // The working turn is stated: a service-less store opens on `previewSnapshot`, whose Codex rows
        // are `Input needed`, which brings a wing out.
        store.applyForTesting(
            makeAgentSnapshot(
                .codex,
                sessions: [
                    makeSession(
                        status: .running,
                        startedAt: Date(timeIntervalSinceNow: -30)
                    )
                ]
            )
        )
        store.hidesNotchline = true
        #expect(store.givesUpCompactWings)
        #expect(!store.drawsCompactMarks)
        #expect(!store.showsSurfaceOutline)
        store.isExpanded = true
        #expect(store.showsSurfaceOutline)
        store.isExpanded = false

        store.applyForTesting(
            makeAgentSnapshot(
                .codex,
                sessions: [
                    makeSession(
                        status: .approvalNeeded,
                        startedAt: Date(timeIntervalSinceNow: -30)
                    )
                ]
            )
        )
        #expect(store.givesUpCompactWings)
        #expect(store.drawsCompactMarks)
        #expect(store.showsSurfaceOutline)

        store.applyForTesting(
            makeAgentSnapshot(
                .codex,
                sessions: [
                    makeSession(
                        status: .running,
                        startedAt: Date(timeIntervalSinceNow: -30)
                    )
                ]
            )
        )
        #expect(!store.drawsCompactMarks)
        #expect(!store.showsSurfaceOutline)
    }

    /// One mark and one count column for all products, so only a second digit widens this wing
    /// (`compact-view-v2.md` §5.1).
    @Test @MainActor
    func theNotchedWingStepsForASecondDigitAndForNothingElse() {
        func width(sessionCount: Int, products: Int = 1) -> CGFloat {
            PanelMetrics.size(
                geometry: .notched,
                isExpanded: false,
                statusReadoutText: "Working...",
                trailing: .empty,
                centerOcclusionWidth: 200,
                compactHeight: 46,
                status: .running,
                matrixCount: products,
                sessionCount: sessionCount
            ).width
        }
        let opened = width(sessionCount: 1) - width(sessionCount: 0)
        #expect(
            abs(
                opened
                    - (PanelMetrics.aggregateCountsGap + PanelMetrics.countsDigitWidth)
            ) <= 1
        )
        #expect(width(sessionCount: 1) == width(sessionCount: 9))
        let second = width(sessionCount: 10) - width(sessionCount: 9)
        #expect(abs(second - PanelMetrics.countsDigitWidth) <= 1)
        #expect(width(sessionCount: 10) == width(sessionCount: 99))
        for sessionCount in [0, 1, 9, 10, 99] {
            #expect(
                width(sessionCount: sessionCount, products: 2)
                    == width(sessionCount: sessionCount)
            )
        }
    }

    @Test @MainActor
    func theRestingPillGrowsSidewaysRatherThanOpeningAnEmptyPanel() {
        let store = MonitorStore(services: [])
        store.applyForTesting(
            makeAgentSnapshot(.codex, availability: .ready, presence: .closed)
        )
        #expect(store.expandsToPillOnly)

        for geometry in DisplayGeometry.allCases {
            let occlusion: CGFloat = geometry == .notched ? 200 : 0
            let resting = PanelMetrics.size(
                geometry: geometry,
                isExpanded: false,
                statusReadoutText: "Disconnected",
                trailing: .empty,
                centerOcclusionWidth: occlusion,
                compactHeight: 46,
                status: .disconnected,
                matrixCount: 1,
                drawsMark: geometry == .noNotch
            )
            let hovered = PanelMetrics.size(
                geometry: geometry,
                isExpanded: true,
                statusReadoutText: "Disconnected",
                trailing: .empty,
                centerOcclusionWidth: occlusion,
                compactHeight: 46,
                status: .disconnected,
                matrixCount: 1,
                expandsToPillOnly: true
            )
            #expect(hovered.height == 46)
            #expect(hovered.width > resting.width)
            #expect(hovered.width < PanelMetrics.expandedBaselineWidth)
        }

        store.applyForTesting(makeAgentSnapshot(.codex, availability: .ready))
        #expect(!store.expandsToPillOnly)
    }

    /// The expanded panel is centred, so each side gets `(width − cut-out) ÷ 2` and the trailing
    /// pair clears the hardware by `8`, at every cut-out (`expanded-header-v2.md` §5).
    @Test @MainActor
    func theRestingHoveredPanelClearsTheCutOutOnBothSides() {
        // The four measured cut-outs, each with its menu bar: the controls track the bar.
        for (occlusion, bar, expected) in [
            (CGFloat(127), CGFloat(22), CGFloat(247)),
            (185, 32, 323),
            (200, 46, 368),
            (220, 38, 371)
        ] {
            let width = PanelMetrics.restingExpandedWidth(
                geometry: .notched,
                centerOcclusionWidth: occlusion,
                compactHeight: bar
            )
            #expect(width == expected, "at \(occlusion) × \(bar)")
            let shoulder = (width - occlusion) / 2
            #expect(
                shoulder >= PanelMetrics.expandedTrailingSideWidth(compactHeight: bar),
                "the controls are inside the cut-out at \(occlusion)"
            )
            // The leading side is a bare mark and never binds here.
            #expect(
                shoulder >= PanelMetrics.expandedHorizontalPadding
                    + PanelMetrics.statusMatrixSize
                    + PanelMetrics.expandedNotchClearance
            )
        }

        // A flat display composes to itself: status mark, one clearance, and the pair.
        #expect(
            PanelMetrics.restingExpandedWidth(
                geometry: .noNotch,
                centerOcclusionWidth: 0,
                compactHeight: 24
            ) == ceil(
                PanelMetrics.expandedHorizontalPadding
                    + PanelMetrics.statusMatrixSize
                    + PanelMetrics.expandedTrailingSideWidth(compactHeight: 24)
            )
        )
    }

    /// Every other body moves with what is running; the About panel does not.
    @Test @MainActor
    func theAboutPanelIsOneHeightWhateverIsRunning() {
        let store = MonitorStore(services: [])
        store.isExpanded = true
        store.applyForTesting(
            makeAgentSnapshot(
                .codex,
                availability: .ready,
                sessions: [makeSession(agent: .codex, threadID: "a")]
            )
        )
        let listed = store.currentPanelSize.height

        store.toggleAbout()
        let about = store.currentPanelSize.height
        #expect(about == store.compactHeight + PanelMetrics.aboutPanelHeight)
        #expect(about != listed, "the About panel is the listed panel's height")

        store.applyForTesting(
            makeAgentSnapshot(
                .codex,
                availability: .ready,
                sessions: [
                    makeSession(agent: .codex, threadID: "a", status: .running),
                    makeSession(agent: .codex, threadID: "b", status: .running),
                    makeSession(agent: .codex, threadID: "c", status: .completed)
                ]
            )
        )
        store.isQuotaExpanded = true
        store.isRecentExpanded = true
        #expect(store.currentPanelSize.height == about)

        store.toggleAbout()
        #expect(store.currentPanelSize.height > listed)
    }

