    /// Each list caps and scrolls on its own: live at `216` (three rows), Recent at `180` (five
    /// retired rows).
    @Test @MainActor
    func eachViewportIsItsContentCappedOnItsOwn() {
        #expect(PanelMetrics.retiredRowHeight == PanelMetrics.sessionRowHeight / 2)
        #expect(PanelMetrics.sessionRowHeight == 72)
        #expect(PanelMetrics.retiredRowHeight == 36)
        #expect(PanelMetrics.recentSeamHeight == 32)
        #expect(PanelMetrics.thinExpandedBodyHeight == 48)
        #expect(PanelMetrics.sessionViewportCap == 288)
        #expect(PanelMetrics.groupedSessionViewportCap == 320)
        #expect(PanelMetrics.recentViewportCap == 180)

        // An empty live list still draws its apology; the fold falls at four `72` pt rows, grouped or
        // flat, so the switch never changes the row count (`expanded-panel-v2.md` §4.6).
        let liveCases: [(live: Int, content: CGFloat, viewport: CGFloat, what: String)] = [
            (0, 48, 48, "nothing live"),
            (1, 72, 72, "one live row"),
            (2, 144, 144, "two live rows"),
            (3, 216, 216, "three live rows"),
            (4, 288, 288, "four live rows — the cap exactly"),
            (5, 360, 288, "five live rows"),
            (12, 864, 288, "twelve live rows"),
        ]
        for row in liveCases {
            #expect(
                PanelMetrics.sessionListContentHeight(liveRowCount: row.live) == row.content,
                "content at \(row.what)"
            )
            #expect(
                PanelMetrics.sessionViewportHeight(liveRowCount: row.live) == row.viewport,
                "viewport at \(row.what)"
            )
        }

        // Recent: nothing while empty; the fold falls at five `36` pt rows.
        let recentCases: [(retired: Int, content: CGFloat, viewport: CGFloat, what: String)] = [
            (0, 0, 0, "nothing retired"),
            (1, 36, 36, "one retired row"),
            (4, 144, 144, "four retired rows"),
            (5, 180, 180, "five retired rows — the cap exactly"),
            (6, 216, 180, "six retired rows"),
            (12, 432, 180, "twelve retired rows"),
        ]
        for row in recentCases {
            #expect(
                PanelMetrics.recentContentHeight(retiredRowCount: row.retired) == row.content,
                "content at \(row.what)"
            )
            #expect(
                PanelMetrics.recentViewportHeight(retiredRowCount: row.retired) == row.viewport,
                "viewport at \(row.what)"
            )
        }

        #expect(PanelMetrics.recentSectionHeight(retiredRowCount: 0, isRecentExpanded: true) == 0)
        #expect(
            PanelMetrics.recentSectionHeight(retiredRowCount: 3, isRecentExpanded: false) == 32
        )
        // Written against the metrics, not `32 + 120`: `#expect` compares an Int literal sum with a
        // `CGFloat` as `false` on equal values.
        #expect(
            PanelMetrics.recentSectionHeight(retiredRowCount: 3, isRecentExpanded: true)
                == PanelMetrics.recentSeamHeight + PanelMetrics.retiredRowHeight * 3
        )
        #expect(
            PanelMetrics.recentSectionHeight(retiredRowCount: 12, isRecentExpanded: true)
                == 32 + PanelMetrics.recentViewportCap
        )
    }

    /// The apology stands above the seam: the floor stays `178` and a queue adds `32`
