    /// Blocks keep the fixed product order whatever the rows do; ordering by urgency is rejected as
    /// in `dual-agent-design.md` §3.1. A product with no rows gets no block (`panel-v2.md` §1, rule 2).
    @Test @MainActor
    func theBlocksKeepTheFixedProductOrderWhateverTheRowsAreDoing() {
        let store = MonitorStore(services: [])
        func session(_ agent: AgentKind, _ id: String, _ status: SessionStatus) -> MonitoredSession {
            MonitoredSession(
                agent: agent,
                threadID: id, turnID: "u-\(id)", projectName: "p", title: "t",
                preview: nil, status: status, startedAt: nil
            )
        }

        store.applyForTesting(
            makeAgentSnapshot(
                .codex, availability: .ready,
                sessions: [session(.codex, "a", .running)]
            )
        )
        store.applyForTesting(
            makeAgentSnapshot(
                .claudeCode, availability: .ready,
                sessions: [session(.claudeCode, "b", .approvalNeeded)]
            )
        )

        // Claude Code holds the only thing anybody is waiting on, and is still second.
        #expect(store.sessionGroups.map(\.agent) == [.codex, .claudeCode])
        #expect(store.sessionGroups.map(\.wantsAttention) == [false, true])
        #expect(store.sessionGroupHeaderCount == 2)

        store.applyForTesting(
            makeAgentSnapshot(
                .codex, availability: .ready,
                sessions: [session(.codex, "a", .approvalNeeded)]
            )
        )
        store.applyForTesting(
            makeAgentSnapshot(
                .claudeCode, availability: .ready,
                sessions: [session(.claudeCode, "b", .running)]
            )
        )
        #expect(store.sessionGroups.map(\.agent) == [.codex, .claudeCode])
        #expect(store.sessionGroups.map(\.wantsAttention) == [true, false])

        // Claude Code drains but stays open: one block, and no flat list to flicker back to.
        store.applyForTesting(
            makeAgentSnapshot(.claudeCode, availability: .ready, sessions: [])
        )
        #expect(store.sessionGroups.map(\.agent) == [.codex])
        #expect(store.sessionGroupHeaderCount == 1)

        // One product connected is the general form with one block in it.
        store.applyForTesting(
            makeAgentSnapshot(.claudeCode, availability: .ready, presence: .closed)
        )
        #expect(store.sessionGroups.map(\.agent) == [.codex])
        #expect(store.sessionGroupHeaderCount == 1)

        // Nothing live: no block, so the panel draws its own top rule.
        store.applyForTesting(
            makeAgentSnapshot(.codex, availability: .ready, sessions: [])
        )
        #expect(store.sessionGroups.isEmpty)
        #expect(store.sessionGroupHeaderCount == 0)
        #expect(!store.listLeadsWithABlockHeading)
    }

    /// Headings are never paid for out of rows: the cap is a badge line, four rows and a badge line
    /// (`320`) at every product count (`expanded-panel-v2.md` §4.6). With nothing live it is `48`.
    @Test @MainActor
    func aHeadingIsNeverPaidForOutOfRows() {
        let store = MonitorStore(services: [])
        func session(_ agent: AgentKind, _ id: String) -> MonitoredSession {
            MonitoredSession(
                agent: agent,
                threadID: id, turnID: "u-\(id)", projectName: "p", title: "t",
                preview: nil, status: .running, startedAt: nil
            )
        }
        let lines = PanelMetrics.productTrailHeight * 2

        store.applyForTesting(
            makeAgentSnapshot(
                .codex, availability: .ready,
                sessions: ["a", "b", "c", "d", "e"].map { session(.codex, $0) }
            )
        )
        let leading = PanelMetrics.groupHeadingsHeight(count: 1)
        #expect(leading == PanelMetrics.leadingProductGroupHeaderHeight)
        #expect(store.sessionGroupHeaderCount == 1)
        #expect(
            store.sessionListContentHeight == PanelMetrics.sessionRowHeight * 5 + leading
        )
        #expect(store.sessionViewportHeight == PanelMetrics.groupedSessionViewportCap)
        #expect(store.sessionViewportHeight - lines == PanelMetrics.sessionRowHeight * 4)

        // Two blocks: the second heading waits on the foot line, and the rows stay four whole ones.
        store.applyForTesting(
            makeAgentSnapshot(
                .claudeCode, availability: .ready,
                sessions: [session(.claudeCode, "f"), session(.claudeCode, "g")]
            )
        )
        // The leading block's heading is the short one: it stands in for the panel's top rule.
        let room = PanelMetrics.groupHeadingsHeight(count: 2)
        #expect(
            room == PanelMetrics.leadingProductGroupHeaderHeight
                + PanelMetrics.productGroupHeaderHeight
        )
        #expect(store.sessionGroupHeaderCount == 2)
        #expect(store.sessionViewportHeight == PanelMetrics.groupedSessionViewportCap)
        #expect(
            store.sessionViewportHeight - lines >= PanelMetrics.sessionRowHeight * 4,
            "a grouped list draws fewer rows than a flat one"
        )
        #expect(
            store.sessionListContentHeight
                == PanelMetrics.sessionRowHeight * 7 + room
        )

        // The flat list shows the same four, so the switch never changes the row count.
        store.groupsSessionsByProduct = false
        #expect(store.sessionViewportHeight == PanelMetrics.sessionViewportCap)
        #expect(store.sessionViewportHeight == PanelMetrics.sessionRowHeight * 4)
        store.groupsSessionsByProduct = true

        store.applyForTesting(makeAgentSnapshot(.codex, availability: .ready, sessions: []))
        store.applyForTesting(makeAgentSnapshot(.claudeCode, availability: .ready, sessions: []))
        #expect(store.sessionGroupHeaderCount == 0)
        #expect(store.sessionViewportHeight == PanelMetrics.thinExpandedBodyHeight)
    }

