    @Test @MainActor
    func notchedCompactDropsItsTrailingWingUntilATurnIsTimed() {
        let occlusion: CGFloat = 200
        func size(trailingText: String?) -> CGSize {
            PanelMetrics.size(
                geometry: .notched,
                isExpanded: false,
                statusReadoutText: "Working...",
                trailing: CompactTrailingReading(timerText: trailingText),
                centerOcclusionWidth: occlusion,
                compactHeight: 46
            )
        }

        // Idle: nothing right of the cut-out; an empty trailing wing renders as a second, fake notch.
        let idle = size(trailingText: nil)
        let leading = PanelMetrics.expandedHorizontalPadding
            + PanelMetrics.drawnLeadingGroupWidth(sessionCount: 0)
            + PanelMetrics.expandedNotchClearance
        #expect(abs(idle.width - (leading + occlusion)) <= 1)

        #expect(size(trailingText: "1:23").width > idle.width)
    }

    /// A notched compact panel's black edge lands on the cut-out's edge.
    @Test @MainActor
    func notchedCompactBodyEndsWhereTheCutOutEnds() throws {
        let display = makeDisplay(
            id: "notched",
            ordinal: 1,
            menuBarHeight: 38,
            hasNotch: true
        )
        let store = MonitorStore(displays: [display])
        let occlusionMaxX = try #require(display.centerOcclusionMaxX)

        // The cut-out's edge plus the trailing wing, which is empty until a turn is timed.
        #expect(PanelMetrics.compactTrailingWingWidth(trailing: .empty) == 0)
        #expect(
            PanelMetrics.compactTrailingWingWidth(
                trailing: CompactTrailingReading(timerText: "1:23")
            ) > 0
        )
        #expect(
            store.currentPanelTrailingAnchor
                == occlusionMaxX + PanelMetrics.compactTrailingWingWidth(
                    trailing: store.compactTrailingReading
                )
        )

        let shoulder = store.surfaceShoulderRadius
        #expect(shoulder > 0)
        let frame = OverlayPanelLayout.frame(
            on: display.frame,
            panelSize: store.currentPanelSize,
            surfaceShoulder: shoulder,
            trailingAnchor: occlusionMaxX
        )

        // The window is the panel plus a shoulder each side, rounded up; `PanelContour` draws its
        // straight sides a radius inside the rect it is given.
        #expect(frame.width == (store.currentPanelSize.width + shoulder * 2).rounded(.up))
        // Rounding may push the edge up to a point outwards (a `38` pt cut-out makes the shoulder
        // `4.75`), never inwards: out is black over the hardware's black.
        #expect(frame.maxX - shoulder >= occlusionMaxX)
        #expect(frame.maxX - shoulder < occlusionMaxX + 1)
        // The leading edge absorbs the rounding in its padding wing.
        #expect(
            abs((frame.minX + shoulder) - (occlusionMaxX - store.currentPanelSize.width)) < 1
        )

        // No notch: the panel stays centred on the display.
        let external = makeDisplay(
            id: "external",
            ordinal: 2,
            menuBarHeight: 24,
            hasNotch: false
        )
        #expect(external.centerOcclusionMaxX == nil)
        let centred = OverlayPanelLayout.frame(
            on: external.frame,
            panelSize: CGSize(width: 168, height: 24),
            surfaceShoulder: shoulder,
            trailingAnchor: nil
        )
        #expect(abs(centred.midX - external.frame.midX) <= 0.5)
    }

    /// Every requested frame is whole points: `NSWindow` drops fractions, so
    /// `OverlayPanelController.updatePanelFrame` sees `panel.frame != targetFrame` on every publish
    /// and re-animates, jittering the trailing edge. Fractional inputs: the shoulder
    /// (`panelHeight / 8`), `auxiliaryTopRightArea.minX` and the cut-out height (§3.5). Timed and
    /// empty trailing readings take different paths; both are covered.
    @Test @MainActor
    func aPanelFrameIsWholePoints() {
        let screen = NSRect(x: 0, y: 0, width: 1_920, height: 1_080)

        func isWhole(_ frame: NSRect) -> Bool {
            frame.minX == frame.minX.rounded()
                && frame.minY == frame.minY.rounded()
                && frame.width == frame.width.rounded()
                && frame.height == frame.height.rounded()
        }

        // Nothing promises `safeAreaInsets.top` lands on a point.
        let heights = [46.0, 38.0, 37.0, 32.0, 24.0, 22.0, 38.5, 31.5] as [CGFloat]
        let readings: [CompactTrailingReading] = [
            .empty,
            CompactTrailingReading(timerText: "0:00")
        ]
        let reportedEdges = [1_060.0, 1_060.5] as [CGFloat]

        for bar in heights {
        for reading in readings {
        for reportedEdge in reportedEdges {
            let shoulder = PanelMetrics.surfaceShoulderRadius(panelHeight: bar)
            // `0:00` measures `27.78` before its ground and padding, so the anchor carries a fraction.
            let wing = PanelMetrics.compactTrailingWingWidth(trailing: reading)
            let size = PanelMetrics.size(
                geometry: .notched,
                isExpanded: false,
                statusReadoutText: "Working...",
                trailing: reading,
                centerOcclusionWidth: 220,
                compactHeight: bar
            )
            let where_ = "\(bar) pt cut-out, edge \(reportedEdge)"
            // The wing is whole by construction; the shoulder, reported edge and height
            // are what must be rounded.
            #expect(wing == wing.rounded(), "\(where_)")
            let bodyEdge = reportedEdge + wing + shoulder
            if bar.truncatingRemainder(dividingBy: 8) != 0
                || reportedEdge != reportedEdge.rounded() {
                #expect(bodyEdge != bodyEdge.rounded(), "\(where_) rounds nothing")
            }
            #expect(
                isWhole(
                    OverlayPanelLayout.frame(
                        on: screen,
                        panelSize: size,
                        surfaceShoulder: shoulder,
                        trailingAnchor: reportedEdge + wing
                    )
                ),
                "notched compact frame under a \(where_)"
            )
            #expect(
                isWhole(
                    OverlayPanelLayout.frame(
                        on: screen,
                        panelSize: PanelMetrics.size(
                            geometry: .notched,
                            isExpanded: true,
                            statusReadoutText: "Working...",
                            trailing: CompactTrailingReading(timerText: "0:00"),
                            centerOcclusionWidth: 220,
                            compactHeight: bar
                        ),
                        surfaceShoulder: shoulder,
                        trailingAnchor: nil
                    )
                ),
                "expanded frame under a \(where_)"
            )
        }
        }
        }
    }

    /// The two edges of a notched collapsed bar:
    /// - The leading edge never moves for anything trailing. The wing cancels out of it only because
    ///   `compactTrailingWingWidth` is whole points.
    /// - The trailing edge follows the reading digit by digit; nothing is reserved.
    /// - The reading's own leading edge stays one `expandedNotchClearance` past the cut-out.
    @Test @MainActor
    func theCollapsedWingsMoveOnlyWhenTheirContentsArriveOrLeave() {
        let bar: CGFloat = 38
        let occlusionMaxX: CGFloat = 1_060
        let occlusion: CGFloat = 220
        let shoulder = PanelMetrics.surfaceShoulderRadius(panelHeight: bar)
        let screen = NSRect(x: 0, y: 0, width: 1_920, height: 1_080)

        func frame(_ trailing: CompactTrailingReading) -> NSRect {
            OverlayPanelLayout.frame(
                on: screen,
                panelSize: PanelMetrics.size(
                    geometry: .notched,
                    isExpanded: false,
                    statusReadoutText: "Working...",
                    trailing: trailing,
                    centerOcclusionWidth: occlusion,
                    compactHeight: bar,
                    matrixCount: 2
                ),
                surfaceShoulder: shoulder,
                trailingAnchor: occlusionMaxX + PanelMetrics.compactTrailingWingWidth(
                    trailing: trailing
                )
            )
        }

        let states: [(String, CompactTrailingReading)] = [
            ("idle", .empty),
            ("0:00", CompactTrailingReading(timerText: "0:00")),
            ("9:59", CompactTrailingReading(timerText: "9:59")),
            ("10:00", CompactTrailingReading(timerText: "10:00")),
            ("59:59", CompactTrailingReading(timerText: "59:59")),
            ("1:00:00", CompactTrailingReading(timerText: "1:00:00")),
            ("10:00:00", CompactTrailingReading(timerText: "10:00:00"))
        ]

        let leading = frame(.empty).minX
        for (name, trailing) in states {
            #expect(frame(trailing).minX == leading, "leading edge moved for \(name)")
        }

        // The window edge is ceiled outwards (`aPanelFrameIsWholePoints`), so the reading stands
        // the same fraction proud of the clearance in every state.
        func readingLeadingEdge(_ trailing: CompactTrailingReading) -> CGFloat {
            frame(trailing).maxX
                - shoulder
                - PanelMetrics.expandedHorizontalPadding
                - PanelMetrics.drawnTrailingReadingWidth(trailing)
        }
        let readingStart = readingLeadingEdge(CompactTrailingReading(timerText: "0:00"))
        for (name, trailing) in states where !trailing.isEmpty {
            #expect(readingLeadingEdge(trailing) == readingStart, "the reading moved for \(name)")
        }
        let clearance = readingStart - occlusionMaxX
        #expect(clearance >= PanelMetrics.expandedNotchClearance)
        #expect(clearance < PanelMetrics.expandedNotchClearance + 1)

        // Tabular figures hold the edge within one digit count (`0:00` and `9:59`); each extra
        // digit steps it out.
        func trailingEdge(_ trailing: CompactTrailingReading) -> CGFloat {
            frame(trailing).maxX
        }
        let timed = trailingEdge(CompactTrailingReading(timerText: "0:00"))
        #expect(trailingEdge(CompactTrailingReading(timerText: "9:59")) == timed)
        var previous = timed
        for text in ["10:00", "1:00:00", "10:00:00"] {
            let edge = trailingEdge(CompactTrailingReading(timerText: text))
            #expect(edge > previous, "trailing edge did not follow \(text)")
            previous = edge
        }

        #expect(timed > trailingEdge(.empty))
    }

    /// `ceil(leading + occlusion + wing) == ceil(leading + occlusion) + wing` holds only for an
    /// integral wing, which is what keeps a trailing reading from moving the leading matrix.
    @Test @MainActor
    func theTrailingWingIsWholePointsSoTheLeadingEdgeCannotMove() {
        let readings: [CompactTrailingReading] = [
            .empty,
            CompactTrailingReading(timerText: "0:00"),
            CompactTrailingReading(timerText: "1:23"),
            CompactTrailingReading(timerText: "10:00:00")
        ]

        for reading in readings {
            let wing = PanelMetrics.compactTrailingWingWidth(trailing: reading)
            #expect(wing == wing.rounded(), "\(reading)")
            let leadingAndCutOut = PanelMetrics.expandedHorizontalPadding
                + PanelMetrics.drawnLeadingGroupWidth(sessionCount: 0)
                + PanelMetrics.expandedNotchClearance + 220
            #expect(ceil(leadingAndCutOut + wing) == ceil(leadingAndCutOut) + wing)
        }
    }

    /// The same layout twice is the same frame, so the controller's "nothing moved" guard stops
    /// the second.
    @Test @MainActor
    func anUnchangedLayoutProducesAnIdenticalFrame() {
        let screen = NSRect(x: 0, y: 0, width: 1_920, height: 1_080)
        let shoulder = PanelMetrics.surfaceShoulderRadius(panelHeight: 38)
        let size = PanelMetrics.size(
            geometry: .notched,
            isExpanded: false,
            statusReadoutText: "Working...",
            trailing: CompactTrailingReading(timerText: "9:59"),
            centerOcclusionWidth: 220,
            compactHeight: 38
        )
        let anchor = 1_060 + PanelMetrics.compactTrailingWingWidth(
            trailing: CompactTrailingReading(timerText: "9:59")
        )
        let first = OverlayPanelLayout.frame(
            on: screen,
            panelSize: size,
            surfaceShoulder: shoulder,
            trailingAnchor: anchor
        )
        let second = OverlayPanelLayout.frame(
            on: screen,
            panelSize: size,
            surfaceShoulder: shoulder,
            trailingAnchor: anchor
        )
        #expect(first == second)
        // Tabular digits: `0:01` is `0:09`'s width.
        let laterAnchor = 1_060 + PanelMetrics.compactTrailingWingWidth(
            trailing: CompactTrailingReading(timerText: "9:58")
        )
        #expect(
            OverlayPanelLayout.frame(
                on: screen,
                panelSize: PanelMetrics.size(
                    geometry: .notched,
                    isExpanded: false,
                    statusReadoutText: "Working...",
                    trailing: CompactTrailingReading(timerText: "9:58"),
                    centerOcclusionWidth: 220,
                    compactHeight: 38
                ),
                surfaceShoulder: shoulder,
                trailingAnchor: laterAnchor
            ) == first
        )
    }

    /// A wingless trailing edge is the cut-out's reported edge. A `panelHeight / 16` step hid the
    /// shoulder fillet behind the glass flare but left a `3` pt black sliver beside the notch
    /// (reported from hardware); a hairline clipped at the top under `Outline the panel` costs less.
    @Test @MainActor
    func aWinglessTrailingEdgeIsTheCutOutsEdge() {
        let bar: CGFloat = 38

        // An empty reading is an empty wing whether or not marks are drawn.
        #expect(PanelMetrics.compactTrailingWingWidth(trailing: .empty) == 0)

        // A non-empty wing is its content plus the clearance, ceiled to a whole point.
        let timed = CompactTrailingReading(timerText: "1:23")
        #expect(
            PanelMetrics.compactTrailingWingWidth(trailing: timed) == ceil(
                PanelMetrics.compactTrailingWidth(trailing: timed)
                    + PanelMetrics.expandedNotchClearance
            )
        )

        let body = PanelMetrics.size(
            geometry: .notched,
            isExpanded: false,
            statusReadoutText: "Working...",
            trailing: .empty,
            centerOcclusionWidth: 200,
            compactHeight: bar,
            status: .running,
            matrixCount: 1
        ).width
        let leading = PanelMetrics.expandedHorizontalPadding
            + PanelMetrics.drawnLeadingGroupWidth(sessionCount: 0)
            + PanelMetrics.expandedNotchClearance
        #expect(body == ceil(leading + 200))
    }

    /// Widths measured from rendered text are asserted as relationships; an exact font-metric pixel
    /// goes red on the next system update.
    @Test @MainActor
    func compactGeometryComposesTheNotchWings() {
        func width(
            geometry: DisplayGeometry,
            trailingText: String?,
            compactHeight: CGFloat
        ) -> CGFloat {
            PanelMetrics.size(
                geometry: geometry,
                isExpanded: false,
                statusReadoutText: "Working...",
                trailing: CompactTrailingReading(timerText: trailingText),
                centerOcclusionWidth: geometry == .notched ? 200 : 0,
                compactHeight: compactHeight
            ).width
        }

        // No text is measured here, so this is exact and checkable against Figma: `12` padding +
        // `16.6` matrix + `8` clearance + the `200` cut-out = `236.6`, ceiled to `237`.
        let notchedIdle = width(geometry: .notched, trailingText: nil, compactHeight: 46)
        #expect(notchedIdle == 237)
        #expect(
            notchedIdle == ceil(
                12
                    + PanelMetrics.drawnLeadingGroupWidth(sessionCount: 0)
                    + PanelMetrics.expandedNotchClearance
                    + 200
            )
        )

        let notchedTimed = width(geometry: .notched, trailingText: "1:23", compactHeight: 46)
        let trailingWing = PanelMetrics.compactTrailingWidth(
            trailing: CompactTrailingReading(timerText: "1:23")
        )
            + PanelMetrics.expandedNotchClearance
        #expect(abs((notchedTimed - notchedIdle) - trailingWing) <= 1)

        // The pill has fixed ends and a moving middle: a reading takes its width from the name, and
        // the window does not move.
        let pillIdle = width(geometry: .noNotch, trailingText: nil, compactHeight: 24)
        let pillTimed = width(geometry: .noNotch, trailingText: "1:23", compactHeight: 24)
        #expect(pillTimed == pillIdle)
        #expect(
            PanelMetrics.pillMiddleWidth(trailing: .empty)
                - PanelMetrics.pillMiddleWidth(
                    trailing: CompactTrailingReading(timerText: "1:23")
                )
                == PanelMetrics.drawnCompactReadingWidth("1:23")
        )
    }


    /// The column breathes only when the mark buries a finished (unread `.completed`) turn. Not for
    /// an all-finished list, a buried `.inputNeeded` (`figma-design.md` §4.1), nothing finished, or
    /// a finished turn with subagents in flight (`.running` by derived status).
    @Test @MainActor
    func theColumnBreathesOnlyWhereTheMarkBuriesAFinishedTurn() {
        func session(
            _ agent: AgentKind,
            _ status: SessionStatus,
            _ id: String,
            subagents: Int = 0
        ) -> MonitoredSession {
            MonitoredSession(
                agent: agent,
                threadID: id, turnID: "u-\(id)", projectName: "p", title: "t",
                preview: nil, status: status, startedAt: nil,
                runningSubagentCount: subagents
            )
        }
        func breathes(_ sessions: [MonitoredSession]) -> Bool {
            AgentSnapshotMerge.merge([
                makeAgentSnapshot(.codex, availability: .ready, sessions: sessions)
            ])
            .presenceMarks
            .first?
            .buriesAFinishedTurn ?? false
        }

        #expect(breathes([
            session(.codex, .running, "a"),
            session(.codex, .completed, "b")
        ]))
        // Approval wins the mark; the finished rows are still buried underneath it.
        #expect(breathes([
            session(.codex, .approvalNeeded, "a"),
            session(.codex, .completed, "b"),
            session(.codex, .completed, "c")
        ]))

        #expect(!breathes([
            session(.codex, .running, "a"),
            session(.codex, .running, "b")
        ]))
        #expect(!breathes([
            session(.codex, .completed, "a"),
            session(.codex, .completed, "b")
        ]))
        // Input is buried and stays buried; this is not a general answer to burial.
        #expect(!breathes([
            session(.codex, .approvalNeeded, "a"),
            session(.codex, .inputNeeded, "b")
        ]))
        // Derived status: this turn has not finished, and the wing's badge already says two are working.
        #expect(!breathes([session(.codex, .completed, "a", subagents: 2)]))
        #expect(!breathes([]))

        // Per product: only the column that owns the buried row moves.
        let split = AgentSnapshotMerge.merge([
            makeAgentSnapshot(
                .codex,
                availability: .ready,
                sessions: [
                    session(.codex, .running, "a"),
                    session(.codex, .completed, "b")
                ]
            ),
            makeAgentSnapshot(
                .claudeCode,
                availability: .ready,
                sessions: [session(.claudeCode, .running, "c")]
            )
        ])
        #expect(split.presenceMarks.map(\.buriesAFinishedTurn) == [true, false])
    }

    /// The breath is slower than every track ``MatrixTrack`` runs. Its crest is full opacity at
    /// `#C7C7CC`, the sessions numeral's ink, which it reaches and never passes.
    @Test @MainActor
    func theBreathIsSlowerThanAnythingTheMatrixRuns() {
        for status in MonitorStatus.allCases {
            guard let period = NotchMatrixState(status).period else { continue }
            #expect(
                period < SessionDotBreath.period,
                "\(status) runs at \(period), which the breath must stay under"
            )
        }
        #expect(abs(SessionDotBreath.period - 2.8) < 0.001)
        #expect(abs(SessionDotBreath.restingOpacity - 1.0) < 0.001)
        #expect(SessionDotBreath.floorOpacity < SessionDotBreath.restingOpacity)
        #expect(
            NotchPalette.finishedDotDrawingColor
                == NotchPalette.countsSessionDrawingColor
        )

        let animation = SessionDotBreath.animation(now: 10)
        #expect(animation.keyPath == "opacity")
        // Autoreversed at half the period, so the fall and the rise are one curve.
        #expect(animation.autoreverses)
        #expect(abs(animation.duration - SessionDotBreath.period / 2) < 0.001)
        #expect(animation.repeatCount == .infinity)
        // Opens on the resting opacity, so starting is a movement rather than a step.
        #expect(
            abs((animation.fromValue as? Double ?? 0) - SessionDotBreath.restingOpacity)
                < 0.001
        )
        #expect(
            abs((animation.toValue as? Double ?? 0) - SessionDotBreath.floorOpacity) < 0.001
        )
    }

    /// The curve never reaches zero rate at either turn: `easeInEaseOut` parks at both ends, which
    /// is invisible away from the centre of vision.
    @Test @MainActor
    func theBreathNeverParksAtEitherTurn() {
        var points = [Float](repeating: 0, count: 2)
        var control: [(x: Double, y: Double)] = []
        for index in 0 ... 3 {
            SessionDotBreath.timingFunction.getControlPoint(at: index, values: &points)
            control.append((Double(points[0]), Double(points[1])))
        }
        #expect(control.count == 4)
        #expect(abs(control[0].x) < 0.001 && abs(control[0].y) < 0.001)
        #expect(abs(control[3].x - 1) < 0.001 && abs(control[3].y - 1) < 0.001)

        let opening = control[1], closing = control[2]
        #expect(opening.x > 0 && closing.x < 1)
        let startRate = opening.y / opening.x
        let endRate = (1 - closing.y) / (1 - closing.x)
        #expect(startRate > 0.3)
        #expect(endRate > 0.3)
        #expect(abs(startRate - endRate) < 0.001)
        // Slowest at the turns: still a breath.
        #expect(startRate < 1)
    }

    /// The breath starts on the next whole beat: its first value is the resting opacity, so it never
    /// jumps, and two products breathing at once are in step.
    @Test @MainActor
    func theBreathStartsOnTheNextWholeBeat() {
        let period = SessionDotBreath.period
        for now in [0.0, 1.0, 2.79, 2.8, 5.0, 12_345.678] as [CFTimeInterval] {
            let begin = SessionDotBreath.beginTime(now: now)
            #expect(begin > now)
            #expect(begin - now <= period + 0.001)
            let offGrid = begin.truncatingRemainder(dividingBy: period)
            #expect(min(offGrid, period - offGrid) < 0.001)
        }
    }

    /// At its floor the dot stays clearly brighter than the extinguished matrix, measured against the
    /// dot's own ink (`#C7C7CC`, not `#DEE8E0`). The dip may be deep because it returns every `2.8 s`.
    @Test @MainActor
    func theBreathsFloorStaysAboveTheMarkItStandsBeside() {
        let dot = NotchPalette.finishedDotDrawingColor
            .usingColorSpace(.sRGB) ?? NotchPalette.finishedDotDrawingColor
        let sampleInk = NotchPalette.MatrixInk(
            offRed: 0x22 / 255, offGreen: 0x1D / 255, offBlue: 0x1C / 255,
            onRed: 0xF0 / 255, onGreen: 0xE1 / 255, onBlue: 0xE0 / 255
        )
        for ink in [NotchPalette.themeInk, sampleInk] {
            let channels = [
                (dot.redComponent, ink.offRed),
                (dot.greenComponent, ink.offGreen),
                (dot.blueComponent, ink.offBlue)
            ]
            for (lit, off) in channels {
                // Clearly brighter: measured at more than twice on every channel of both inks.
                #expect(SessionDotBreath.floorOpacity * lit > off * 1.5)
            }
        }
        // The swing is over half the resting opacity, taken from the floor so the crest stays at the
        // numeral.
        let swing = SessionDotBreath.restingOpacity - SessionDotBreath.floorOpacity
        #expect(swing > SessionDotBreath.restingOpacity / 2)
    }


    /// Guards the silent failure: every number right and nothing handed to the render server.
    @Test @MainActor
    func theBreathReachesTheLayerAndLeavesWithTheCondition() throws {
        // The trailing wing's dot exists only while it has something to say, so its presence is the
        // condition (`compact-view-v2.md` §4.3).
        let size = PanelMetrics.buriedFinishDotSize
        let view = BreathingDotView(
            frame: NSRect(x: 0, y: 0, width: size, height: size)
        )
        let breath = try #require(view.breathAnimation as? CABasicAnimation)
        #expect(breath.keyPath == "opacity")
        #expect(breath.repeatCount == .infinity)
        #expect(breath.autoreverses)
        #expect(!breath.isRemovedOnCompletion)
        #expect(SessionDotBreath.floorOpacity < SessionDotBreath.restingOpacity)
        #expect(SessionDotBreath.restingOpacity <= 1)

        // The loop is anchored to the clock, so a second dot breathes in phase with the first.
        let other = BreathingDotView(
            frame: NSRect(x: 0, y: 0, width: size, height: size)
        )
        let second = try #require(other.breathAnimation as? CABasicAnimation)
        #expect(abs(second.beginTime - breath.beginTime) < 0.001)
    }


    /// The notched bar reserves nothing on either side, asserted against the two forms that still
    /// reserve.
    @Test @MainActor
    func theNotchedBarIsExactlyAsWideAsWhatItDraws() {
        let matrix = PanelMetrics.statusMatrixSize
        let gap = PanelMetrics.compactMatrixSpacing

        // The leading wing is the mark plus the counts where the list has rows; nothing per product.
        #expect(
            PanelMetrics.drawnLeadingGroupWidth(sessionCount: 0)
                == PanelMetrics.statusMatrixSize
        )
        #expect(
            PanelMetrics.drawnLeadingGroupWidth(sessionCount: 1)
                == PanelMetrics.statusMatrixSize
                    + PanelMetrics.aggregateCountsGap
                    + PanelMetrics.countsDigitWidth
        )
        #expect(
            PanelMetrics.drawnLeadingGroupWidth(sessionCount: 10)
                == PanelMetrics.reservedLeadingGroupWidth
        )

        // The expanded band reserves where this wing hugs: the band is sized from a baseline, while the
        // bar is pinned to the cut-out and its leading edge travels.
        #expect(
            PanelMetrics.expandedLeadingSideWidth
                == PanelMetrics.expandedHorizontalPadding
                    + matrix
                    + PanelMetrics.aggregateCountsGap
                    + PanelMetrics.reservedCountsColumnWidth
                    + PanelMetrics.expandedNotchClearance
        )
        // Otherwise the same group: the band's leading side differs from the pill's reserved group only by
        // the panel inset and the cut-out clearance (`colour-v2.md` §3).
        #expect(
            PanelMetrics.expandedLeadingSideWidth
                == PanelMetrics.reservedLeadingGroupWidth
                    + PanelMetrics.expandedHorizontalPadding
                    + PanelMetrics.expandedNotchClearance
        )

        // The trailing wing is the reading it draws at every length, including past `00:00:00`, which is
        // drawn rather than clipped.
        for text in ["0:00", "10:00", "1:00:00", "10:00:00", "000:00:00"] {
            #expect(
                PanelMetrics.drawnTrailingReadingWidth(
                    CompactTrailingReading(timerText: text)
                ) == PanelMetrics.drawnCompactReadingWidth(text)
            )
        }
        // A shorter reading is a narrower wing: `0:00` and `1:00:00` are `20` apart.
        #expect(
            PanelMetrics.drawnTrailingReadingWidth(CompactTrailingReading(timerText: "0:00"))
                < PanelMetrics.drawnTrailingReadingWidth(
                    CompactTrailingReading(timerText: "1:00:00")
                )
        )

        // Whole points without rounding (the ceiled glyph box and the ground's `8`), which holds the
        // reading's own leading edge still.
        for reading in [
            CompactTrailingReading(timerText: "0:00"),
            CompactTrailingReading(timerText: "1:23"),
            CompactTrailingReading(timerText: "10:00:00")
        ] {
            let drawn = PanelMetrics.drawnTrailingReadingWidth(reading)
            #expect(drawn == drawn.rounded(), "\(reading)")
            #expect(
                PanelMetrics.compactTrailingWingWidth(trailing: reading)
                    == drawn
                        + PanelMetrics.expandedHorizontalPadding
                        + PanelMetrics.expandedNotchClearance,
                "the wing rounded something for \(reading)"
            )
        }

        // Billed for the box the raster draws into; the bare metric is a fraction short.
        for text in ["0:00", "9:59", "10:00", "1:00:00"] {
            let font = NSFont.monospacedDigitSystemFont(ofSize: 13, weight: .light)
            #expect(
                PanelMetrics.drawnCompactReadingWidth(text)
                    == NotchTextRaster.textSize(text, font: font).width
                        + PanelMetrics.readingGroundWidthCost
            )
        }
    }

    /// A notched wing is as wide as its contents, so the window edge keeps the slot's timing: it leads
    /// on open and waits `50 ms` for the mark on close.
    @Test @MainActor
    func theWindowEdgeWaitsForAClosingWingTheWayTheColumnDoes() {
        func frame(width: CGFloat, height: CGFloat = 38) -> NSRect {
            NSRect(x: 0, y: 0, width: width, height: height)
        }

        #expect(OverlayPanelLayout.closingDelay(from: frame(width: 240), to: frame(width: 260)) == 0)
        #expect(OverlayPanelLayout.closingDelay(from: frame(width: 240), to: frame(width: 240)) == 0)
        // Read from the one declaration rather than restated as a number.
        #expect(
            OverlayPanelLayout.closingDelay(from: frame(width: 260), to: frame(width: 240))
                == PanelMotion.slotDelay(isOpening: false)
        )
        #expect(PanelMotion.slotDelay(isOpening: false) == PanelMotion.closingDelay)
        #expect(PanelMotion.slotDelay(isOpening: true) == 0)

        // A collapse is not a wing closing: hovering out must not be held back.
        #expect(
            OverlayPanelLayout.closingDelay(
                from: frame(width: 520, height: 370),
                to: frame(width: 260, height: 38)
            ) == 0
        )
    }


    /// The status name moves on the column's own curve, from one declaration: leading on the way in,
    /// waiting for the dot on the way out.
    @Test @MainActor
    func theStatusNameMovesOnTheColumnsOwnCurve() {
        let base = PanelMotion.animation
        #expect(PanelMotion.slot(isOpening: true) == base)
        // Closing waits, or the name would leave while the dot is still lit.
        #expect(
            PanelMotion.slot(isOpening: false)
                == base.delay(PanelMotion.closingDelay)
        )
        #expect(
            PanelMotion.slot(isOpening: true)
                != PanelMotion.slot(isOpening: false)
        )
    }

    /// A notched bar is pinned to the cut-out, so growing counts push the leading edge left and the
    /// mark rides with them.
    @Test @MainActor
    func theCountsPushTheLeadingEdgeAndTheMarkRidesWithThem() {
        let notched = makeDisplay(id: "notched", ordinal: 1, menuBarHeight: 38, hasNotch: true)
        let store = MonitorStore(displays: [notched], services: [])
        let digit = PanelMetrics.countsDigitWidth
        let opened = PanelMetrics.aggregateCountsGap + digit

        func leadingEdge() -> CGFloat {
            OverlayPanelLayout.frame(
                on: notched.frame,
                panelSize: store.currentPanelSize,
                surfaceShoulder: store.surfaceShoulderRadius,
                trailingAnchor: store.currentPanelTrailingAnchor
            ).minX
        }
        func markOrigin() -> CGFloat {
            leadingEdge()
                + store.surfaceShoulderRadius
                + PanelMetrics.expandedHorizontalPadding
        }
        /// Meets the cut-out's clearance, so it must not move.
        func groupEnd() -> CGFloat {
            markOrigin()
                + PanelMetrics.drawnLeadingGroupWidth(
                    sessionCount: store.aggregateSessionCount
                )
        }
        // Untimed: a timer opens the trailing wing, and `size` ceils the panel while the anchor does not,
        // shifting the leading edge by that rounding. The timer is checked at the end.
        func session(_ agent: AgentKind, _ id: String) -> MonitoredSession {
            MonitoredSession(
                agent: agent,
                threadID: id, turnID: "u-\(id)", projectName: "p", title: "t",
                preview: nil, status: .running, startedAt: nil
            )
        }

        store.applyForTesting(makeAgentSnapshot(.codex, availability: .ready))
        store.applyForTesting(makeAgentSnapshot(.claudeCode, availability: .ready))
        #expect(store.presenceMarks.count == 2)
        #expect(store.aggregateSessionCount == 0)
        let restingEdge = leadingEdge()
        let restingMark = markOrigin()
        let restingEnd = groupEnd()

        store.applyForTesting(
            makeAgentSnapshot(
                .claudeCode,
                availability: .ready,
                sessions: [session(.claudeCode, "a")]
            )
        )
        #expect(store.aggregateSessionCount == 1)
        #expect(abs(leadingEdge() - (restingEdge - opened)) <= 1)
        #expect(abs(markOrigin() - (restingMark - opened)) <= 1)
        #expect(abs(groupEnd() - restingEnd) <= 1)

        // A row on the other product is one more row and nothing else.
        let oneRow = leadingEdge()
        store.applyForTesting(
            makeAgentSnapshot(.codex, availability: .ready, sessions: [session(.codex, "b")])
        )
        #expect(store.aggregateSessionCount == 2)
        #expect(leadingEdge() == oneRow)

        // Nothing moves again until the tenth row, which costs one digit.
        store.applyForTesting(
            makeAgentSnapshot(
                .codex,
                availability: .ready,
                sessions: (0 ..< 9).map { session(.codex, "c\($0)") }
            )
        )
        #expect(store.aggregateSessionCount == 10)
        #expect(abs(leadingEdge() - (oneRow - digit)) <= 1)
        #expect(abs(groupEnd() - restingEnd) <= 1)

        store.applyForTesting(makeAgentSnapshot(.codex, availability: .ready))
        store.applyForTesting(makeAgentSnapshot(.claudeCode, availability: .ready))
        #expect(store.aggregateSessionCount == 0)
        #expect(leadingEdge() == restingEdge)
        #expect(markOrigin() == restingMark)

        // A timed turn's wing cancels out of the leading edge because it is whole points
        // (`theTrailingWingIsWholePointsSoTheLeadingEdgeCannotMove`).
        let timed = MonitoredSession(
            agent: .codex,
            threadID: "timed", turnID: "u", projectName: "p", title: "t",
            preview: nil, status: .running, startedAt: Date()
        )
        store.applyForTesting(
            makeAgentSnapshot(.codex, availability: .ready, sessions: [timed])
        )
        #expect(store.compactTimerText != nil)
        #expect(store.aggregateSessionCount == 1)
        #expect(abs(leadingEdge() - (restingEdge - opened)) <= 1)
    }

