    /// The running loom holds some cell near full on every frame of its loop, unlike the knock it
    /// replaced.
    @Test @MainActor
    func theRunningLoomStaysLegibleThroughoutItsLoop() throws {
        let loom = NotchMatrixState.running
        let cells = (0 ..< MatrixGrid.cellCount).map { loom.track(forCell: $0) }
        let frames = cells.map(\.count).max() ?? 1
        // Two rings on two clocks and a still centre, so no two frames of the loop draw the same mark.
        func mark(at frame: Int) -> [Double] { cells.map { $0[frame % $0.count] } }
        #expect(Set((0 ..< frames).map { mark(at: $0) }).count == frames)

        let brightest = (0 ..< frames).map { mark(at: $0).max() ?? 0 }
        let average = (0 ..< frames).map {
            mark(at: $0).reduce(0, +) / Double(MatrixGrid.cellCount)
        }
        // Some cell is at least 0.8 lit on every frame, and the mean stays within 0.314–0.325, so the
        // mark never pulses. Both figures are at ``MatrixTrack/floor`` `0.10` (2026-09-07).
        #expect((brightest.min() ?? 0) > 0.8)
        #expect((average.min() ?? 0) > 0.31)
        // The knock, measured the same way: through its silence the grid is darker than the still.
        let resting = try #require(NotchMatrixState.inactive.track(forCell: 0).first)
        let knock = NotchMatrixState.approvalNeeded.track(forCell: 0)
        // The knock keeps its own `0.05`: of the 18 silent frames after the second knock, all but the
        // first are at or below a resting mark. A floor below `0.10` would lose that.
        let silence = knock.suffix(knock.count / 2)
        #expect(silence.filter { $0 <= resting }.count >= silence.count - 1)
        #expect((knock.min() ?? 1) < 0.06)
    }

    /// Marks on the bar anchor to a per-period grid so two saying the same thing are in step; a
    /// Settings specimen has nothing to sync with and starts at its first frame.
    @Test @MainActor
    func aSpecimenStartsAtItsFirstFrameAndAMarkOnTheBarDoesNot() throws {
        let size = PanelMetrics.statusMatrixSize
        let ink = NotchPalette.themeInk
        let period = try #require(NotchMatrixState.running.period)

        func sweep(_ view: MatrixIndicatorView, startsAtItsFirstFrame: Bool) -> CFTimeInterval {
            view.frame = NSRect(x: 0, y: 0, width: size, height: size)
            view.apply(
                state: .inactive,
                size: size,
                isAnimated: true,
                ink: ink,
                startsAtItsFirstFrame: startsAtItsFirstFrame
            )
            view.apply(
                state: .running,
                size: size,
                isAnimated: true,
                ink: ink,
                startsAtItsFirstFrame: startsAtItsFirstFrame
            )
            return CACurrentMediaTime()
        }

        /// The opacity animation on one cell of the topmost lit pass.
        func animation(on view: MatrixIndicatorView) throws -> CAAnimation {
            let pass = try #require(view.layer?.sublayers?.last)
            let cell = try #require(pass.sublayers?.first)
            return try #require(cell.animation(forKey: "notch.matrix.opacity"))
        }

        let specimen = MatrixIndicatorView()
        let now = sweep(specimen, startsAtItsFirstFrame: true)
        #expect(abs(try animation(on: specimen).beginTime - now) < 0.05)

        let onTheBar = MatrixIndicatorView()
        let barNow = sweep(onTheBar, startsAtItsFirstFrame: false)
        let anchored = try animation(on: onTheBar).beginTime
        #expect(anchored == MatrixIndicatorView.phaseAnchor(for: period, now: barNow))
        #expect(anchored <= barNow)
        #expect(barNow - anchored < period)

        // Both dissolve: the unlit bed, four lit passes, and the four the still left behind.
        #expect(specimen.layer?.sublayers?.count == 9)
        #expect(onTheBar.layer?.sublayers?.count == 9)
    }

