    /// The leaving name draws into its middle and the arriving one opens out of it, through one
    /// size; a `CATransition` would scale old and new contents together.
    @Test @MainActor
    func theMiddleHandsOneNameToTheNextThroughOneSize() throws {
        let width = PanelMetrics.pillMiddleWidth(trailing: .empty)
        let host = NSHostingView(
            rootView: RotatingProjectName(names: ["notchline"], width: width)
        )
        host.frame = NSRect(
            x: 0,
            y: 0,
            width: width,
            height: PanelMetrics.referenceCompactHeight
        )
        host.layoutSubtreeIfNeeded()
        let view = try #require(Self.projectNameView(in: host))

        // A name drawn for the first time has nothing to take over from: it arrives alone.
        #expect(view.drawnName == "notchline")
        #expect(view.arrivingAnimation != nil)
        #expect(view.leavingAnimation == nil)

        let stood = view.nameLayer.frame
        view.apply(names: ["hello-agents"], width: width)
        #expect(view.drawnName == "hello-agents")

        func channel(_ animation: CAAnimation?, _ keyPath: String) -> CABasicAnimation? {
            (animation as? CAAnimationGroup)?.animations?
                .compactMap { $0 as? CABasicAnimation }
                .first { $0.keyPath == keyPath }
        }
        func number(_ value: Any?) -> Double? { (value as? NSNumber)?.doubleValue }

        let leavingInk = try #require(channel(view.leavingAnimation, "opacity"))
        let leavingSize = try #require(channel(view.leavingAnimation, "transform.scale"))
        let arrivingInk = try #require(channel(view.arrivingAnimation, "opacity"))
        let arrivingSize = try #require(channel(view.arrivingAnimation, "transform.scale"))

        #expect(number(leavingSize.fromValue) == 1)
        #expect(number(leavingSize.toValue) == Double(ProjectNameHandover.scale))
        #expect(number(arrivingSize.fromValue) == Double(ProjectNameHandover.scale))
        #expect(number(arrivingSize.toValue) == 1)
        // One size read by both halves: the leaving name stops where the arriving one starts.
        #expect(number(leavingSize.toValue) == number(arrivingSize.fromValue))

        #expect(number(leavingInk.fromValue) == 1)
        #expect(number(leavingInk.toValue) == 0)
        #expect(number(arrivingInk.fromValue) == 0)
        #expect(number(arrivingInk.toValue) == 1)

        // Both scale about their own glyph box's middle; anchored at an edge, a name would slide.
        #expect(view.nameLayer.anchorPoint == CGPoint(x: 0.5, y: 0.5))
        #expect(view.departingNameLayer.anchorPoint == CGPoint(x: 0.5, y: 0.5))

        // The old raster leaves from where it stood: the two names differ in width.
        #expect(view.departingNameLayer.contents != nil)
        #expect(view.departingNameLayer.frame == stood)
        #expect(view.nameLayer.frame.width != stood.width)

        // The arriving half holds its own start values through the delay; filled forwards from the
        // model, the new name would stand at full ink first and the handover would be a cut.
        let arriving = try #require(view.arrivingAnimation)
        #expect(arriving.beginTime > 0)
        #expect(arriving.fillMode == .backwards)
        #expect(try #require(view.leavingAnimation).beginTime == 0)
    }

    /// Two names never hold the middle at once, and it is never empty: their glyphs collide, so
    /// unlike ``MatrixDissolve`` the halves are offset and cross at about an eighth of full ink.
    @Test @MainActor
    func neitherNameHoldsTheMiddleWhileTheOtherIsStillInIt() {
        #expect(ProjectNameHandover.arrivingDelay > ProjectNameHandover.leavingDuration / 2)
        #expect(ProjectNameHandover.arrivingDelay < ProjectNameHandover.leavingDuration)
        // The leaving name is gone before the arriving one is half way up, so only tails overlap.
        #expect(
            ProjectNameHandover.leavingDuration
                < ProjectNameHandover.arrivingDelay + ProjectNameHandover.arrivingDuration / 2
        )
        // Leaving is quicker than arriving, as with every reading on this surface.
        #expect(ProjectNameHandover.leavingDuration < ProjectNameHandover.arrivingDuration)
        #expect(ProjectNameHandover.duration < PanelMetrics.projectNameInterval / 10)

        func leaving(at moment: Double) -> Double {
            guard moment > 0 else { return 1 }
            guard moment < ProjectNameHandover.leavingDuration else { return 0 }
            return 1 - Self.progress(
                of: ProjectNameHandover.leavingTimingFunction,
                atFractionOfDuration: moment / ProjectNameHandover.leavingDuration
            )
        }
        func arriving(at moment: Double) -> Double {
            let started = moment - ProjectNameHandover.arrivingDelay
            guard started > 0 else { return 0 }
            guard started < ProjectNameHandover.arrivingDuration else { return 1 }
            return Self.progress(
                of: ProjectNameHandover.arrivingTimingFunction,
                atFractionOfDuration: started / ProjectNameHandover.arrivingDuration
            )
        }

        /// The most ink two names ever carry at one instant.
        var together = 0.0
        /// The least ink the slot ever carries at all.
        var thinnest = 1.0
        for millisecond in 0 ... 400 {
            let moment = Double(millisecond) / 1000
            together = max(together, min(leaving(at: moment), arriving(at: moment)))
            thinnest = min(thinnest, max(leaving(at: moment), arriving(at: moment)))
        }
        #expect(together < 0.2)
        #expect(thinnest > 0.1)
    }

    private static func projectNameView(in view: NSView) -> ProjectNameView? {
        if let found = view as? ProjectNameView { return found }
        for child in view.subviews {
            if let found = projectNameView(in: child) { return found }
        }
        return nil
    }

    /// When the last turn ends the reading freezes at that turn's length and a dot arrives in front
    /// of it (`compact-view-v2.md` §4.2); the wing opens by the dot's `4` plus `8`, unreserved.
    @Test @MainActor
    func theCollapsedReadingFreezesWhenTheLastTurnEnds() async {
        let clock = TestClock(now: Date(timeIntervalSince1970: 1_000))
        let store = makeIdleStore(clock: clock)
        let started = Date(timeIntervalSince1970: 1_000)

        func session(_ status: SessionStatus, finishedAt: Date? = nil) -> MonitoredSession {
            MonitoredSession(
                agent: .codex,
                threadID: "one",
                turnID: "turn-one",
                projectName: "notchline",
                title: "Timed turn",
                preview: nil,
                status: status,
                startedAt: started,
                finishedAt: finishedAt
            )
        }

        store.applyForTesting(
            makeSessionSnapshot([session(.running)]),
            observedAt: clock.now()
        )
        await clock.settle()
        await clock.advance(by: 83)
        await clock.settle()
        let running = store.compactTrailingReading
        #expect(running.timerText == "1:23")
        #expect(!running.isFrozen)
        let runningWidth = store.compactDrawnTrailingReadingWidth

        store.applyForTesting(
            makeSessionSnapshot([session(.completed, finishedAt: clock.now())]),
            observedAt: clock.now()
        )
        await clock.settle()
        let stopped = store.compactTrailingReading
        #expect(stopped.timerText == "1:23")
        #expect(stopped.isFrozen)
        // The aggregate is Completed, so nothing is buried; the dot is drawn for this frozen row anyway.
        #expect(!store.buriesAFinishedTurn)
        #expect(stopped.drawsFinishedDot)
        // The wing opens by exactly the mark and its gap; the digits keep their width.
        #expect(
            store.compactDrawnTrailingReadingWidth
                == runningWidth + PanelMetrics.buriedFinishSlotWidth
        )

        // Stays put as the clock runs: measured between two stamps, not against the tick.
        await clock.advance(by: 600)
        await clock.settle()
        #expect(store.compactTrailingReading.timerText == "1:23")

        // It leaves when the row does, and not before (§3.3).
        store.applyForTesting(makeSessionSnapshot([]), observedAt: clock.now())
        await clock.settle()
        #expect(store.compactTrailingReading == .empty)
    }

    /// The dot marks a turn that finished while another runs, asked of the aggregate: no
    /// `PresenceMark` flag sees one product finished while the other runs (§4.3).
    @Test @MainActor
    func theBuriedFinishDotAnswersForTheTurnTheMarkCannotDraw() async {
        let clock = TestClock(now: Date(timeIntervalSince1970: 1_000))
        let store = MonitorStore(
            displays: [
                makeDisplay(id: "notched", ordinal: 1, menuBarHeight: 46, hasNotch: true)
            ],
            services: [],
            clock: clock
        )
        func session(
            _ agent: AgentKind,
            _ status: SessionStatus,
            finishedAt: Date? = nil
        ) -> MonitoredSession {
            MonitoredSession(
                agent: agent,
                threadID: "\(agent)",
                turnID: "turn-\(agent)",
                projectName: "notchline",
                title: "Turn",
                preview: nil,
                status: status,
                startedAt: Date(timeIntervalSince1970: 900),
                finishedAt: finishedAt
            )
        }

        store.applyForTesting(
            makeAgentSnapshot(.codex, availability: .ready, sessions: [session(.codex, .running)])
        )
        store.applyForTesting(
            makeAgentSnapshot(
                .claudeCode,
                availability: .ready,
                sessions: [session(.claudeCode, .running)]
            )
        )
        #expect(store.status == .running)
        #expect(!store.buriesAFinishedTurn)

        // Codex finishes while Claude Code runs: no product flag is true, and the mark draws Radar.
        store.applyForTesting(
            makeAgentSnapshot(
                .codex,
                availability: .ready,
                sessions: [session(.codex, .completed, finishedAt: clock.now())]
            )
        )
        #expect(store.status == .running)
        #expect(store.presenceMarks.allSatisfy { !$0.buriesAFinishedTurn })
        #expect(store.buriesAFinishedTurn, "the aggregate loses what no mark does")
        #expect(store.compactTrailingReading.buriesAFinishedTurn)
        #expect(store.spokenBuriedCompletionText == "1 turn finished and unread")

        // It costs the wing the dot and its `8`, and nothing else moves.
        let withDot = store.compactDrawnTrailingReadingWidth
        var without = store.compactTrailingReading
        without.buriesAFinishedTurn = false
        #expect(
            withDot - PanelMetrics.drawnTrailingReadingWidth(without)
                == PanelMetrics.buriedFinishSlotWidth
        )
        // Whole points, so the leading edge still cannot feel it.
        #expect(withDot == withDot.rounded())

        // With no reading to stand off, the dot takes its own `4` and no gap.
        #expect(
            PanelMetrics.drawnTrailingReadingWidth(
                CompactTrailingReading(buriesAFinishedTurn: true)
            ) == PanelMetrics.buriedFinishDotSize
        )

        // Once the running turn ends too the aggregate is Completed, and the dot has nothing to stand in
        // for.
        store.applyForTesting(
            makeAgentSnapshot(
                .claudeCode,
                availability: .ready,
                sessions: [session(.claudeCode, .completed, finishedAt: clock.now())]
            )
        )
        #expect(store.status == .completed)
        #expect(!store.buriesAFinishedTurn)
        #expect(store.spokenBuriedCompletionText == nil)
    }

    /// The dim tile ground is a fixed `#242424`, lifted off the unlit ink towards white. Row hover and
