    /// The lower corners leave the straight edges with zero curvature (both control points on the
    /// edge), so no join reads as a crease; asserted on all four joins.
    @Test
    func theLowerCornersLeaveTheStraightEdgesWithoutCurvature() {
        let shoulder = PanelMetrics.surfaceShoulderRadius(panelHeight: 38)
        let bottom = PanelMetrics.surfaceBottomCornerRadius(panelHeight: 38)
        let reach = PanelMetrics.smoothCornerReach(radius: bottom)
        let rect = CGRect(x: 0, y: 0, width: 265, height: 38)
        let elements = PanelContour(
            shoulderRadius: shoulder,
            bottomRadius: bottom
        ).path(in: rect).elements

        // The straight runs are cut to the corner's reach, which is further than its radius.
        #expect(reach == bottom * 1.6)
        guard case let .line(to: trailingRun) = elements[3],
              case let .line(to: bottomRun) = elements[7] else {
            Issue.record("the straight runs into the lower corners are missing")
            return
        }
        #expect(
            trailingRun.isNear(
                CGPoint(x: rect.maxX - shoulder, y: rect.maxY - reach)
            )
        )
        #expect(
            bottomRun.isNear(
                CGPoint(x: rect.minX + shoulder + reach, y: rect.maxY)
            )
        )

        // Each entry: the curve easing away from a straight edge, and the coordinate that edge holds.
        let joins: [(Int, KeyPath<CGPoint, CGFloat>, CGFloat, String)] = [
            (4, \.x, rect.maxX - shoulder, "trailing side into the lower-right corner"),
            (6, \.y, rect.maxY, "lower-right corner into the bottom edge"),
            (8, \.y, rect.maxY, "bottom edge into the lower-left corner"),
            (10, \.x, rect.minX + shoulder, "lower-left corner into the leading side"),
        ]
        for (index, axis, edge, what) in joins {
            guard case let .curve(to: _, control1: control1, control2: control2)
                = elements[index] else {
                Issue.record("\(what) is not a curve")
                continue
            }
            #expect(abs(control1[keyPath: axis] - edge) < 0.000_1, "\(what)")
            #expect(abs(control2[keyPath: axis] - edge) < 0.000_1, "\(what)")
        }
    }

    /// At smoothing `0` the corners reduce to circular arcs: the easing segments collapse and
    /// `4/3 · tan(θ/4)` becomes `0.5523`.
    @Test
    func theLowerCornersReduceToCircularArcsWithoutSmoothing() {
        let shoulder = PanelMetrics.surfaceShoulderRadius(panelHeight: 38)
        let bottom = PanelMetrics.surfaceBottomCornerRadius(panelHeight: 38)
        let rect = CGRect(x: 0, y: 0, width: 265, height: 38)
        let elements = PanelContour(
            shoulderRadius: shoulder,
            bottomRadius: bottom,
            bottomSmoothing: 0
        ).path(in: rect).elements
        let handle = bottom * 0.552_284_749_8

        // The straight run ends one radius above the bottom; the easing segments are points.
        guard case let .line(to: trailingRun) = elements[3],
              case let .curve(to: end, control1: control1, control2: control2)
                = elements[5] else {
            Issue.record("the lower-right corner is not a line into a curve")
            return
        }
        #expect(
            trailingRun.isNear(
                CGPoint(x: rect.maxX - shoulder, y: rect.maxY - bottom)
            )
        )
        #expect(
            end.isNear(CGPoint(x: rect.maxX - shoulder - bottom, y: rect.maxY))
        )
        #expect(
            control1.isNear(
                CGPoint(x: rect.maxX - shoulder, y: rect.maxY - bottom + handle)
            )
        )
        #expect(
            control2.isNear(
                CGPoint(x: rect.maxX - shoulder - bottom + handle, y: rect.maxY)
            )
        )
    }

    /// A corner that cannot fit scales both radii down in ratio, clamping on its reach rather than its
    /// radius, or a smoothed corner overruns the edge.
    @Test
    func theContourClampsOnTheCornersReachRatherThanItsRadius() {
        // Half the width is `10`; a `4` shoulder plus an `8` lower corner asks for `4 + 12.8 = 16.8`.
        let rect = CGRect(x: 0, y: 0, width: 20, height: 38)
        let elements = PanelContour(shoulderRadius: 4, bottomRadius: 8)
            .path(in: rect).elements
        let fit = 10.0 / 16.8
        let shoulder = 4 * fit
        let reach = PanelMetrics.smoothCornerReach(radius: 8 * fit)

        // The two corners meet exactly at the middle of the bottom edge.
        #expect(abs(shoulder + reach - rect.width / 2) < 0.000_1)
        guard case let .line(to: bottomEdge) = elements[7] else {
            Issue.record("the bottom edge is not a line")
            return
        }
        #expect(abs(bottomEdge.x - rect.midX) < 0.000_1)
        #expect(bottomEdge.x >= rect.minX + shoulder)
    }

    @Test @MainActor
    func expandedSizeUsesWiderBaselineAndKeepsCompactHeaderHeight() {
        let noNotchSize = PanelMetrics.size(
            geometry: .noNotch,
            isExpanded: true,
            statusReadoutText: "Working...",
            trailing: .empty,
            centerOcclusionWidth: 0,
            compactHeight: 24
        )
        // The panel is one size, on a notched screen and a flat one, whatever is open.
        let notchedSize = PanelMetrics.size(
            geometry: .notched,
            isExpanded: true,
            statusReadoutText: "Working...",
            trailing: .empty,
            centerOcclusionWidth: 200,
            compactHeight: 38
        )
        let notchedSingle = PanelMetrics.size(
            geometry: .notched,
            isExpanded: true,
            statusReadoutText: "Working...",
            trailing: .empty,
            centerOcclusionWidth: 220,
            compactHeight: 38
        )

        #expect(noNotchSize.width == 610)
        #expect(notchedSize.width == noNotchSize.width)
        #expect(notchedSingle.width == noNotchSize.width)
        #expect(noNotchSize.height == 24 + PanelMetrics.expandedContentHeight)
        #expect(notchedSize.height == 38 + PanelMetrics.expandedContentHeight)
    }

    /// The band's totals are sums over every agent and answer to what is running
    /// (`colour-v2.md` §3).
    @Test @MainActor
    func theBandsTotalsCountEveryAgentAtOnce() {
        let store = MonitorStore(services: [], initialSnapshot: makeSessionSnapshot([]))
        func session(
            _ agent: AgentKind,
            _ id: String,
            subagents: Int = 0
        ) -> MonitoredSession {
            MonitoredSession(
                agent: agent,
                threadID: id,
                turnID: "turn-\(id)",
                projectName: "notchline",
                title: "Turn",
                preview: nil,
                status: .running,
                startedAt: Date(),
                runningSubagentCount: subagents
            )
        }

        store.applyForTesting(
            makeAgentSnapshot(.codex, availability: .ready, sessions: [session(.codex, "a")])
        )
        store.applyForTesting(makeAgentSnapshot(.claudeCode, availability: .ready))
        #expect(store.presenceMarks.count == 2)
        #expect(store.aggregateSessionCount == 1)
        #expect(store.aggregateSubagentCount == 0)

        // Both figures are sums; neither gains a part.
        store.applyForTesting(
            makeAgentSnapshot(
                .claudeCode,
                availability: .ready,
                sessions: [
                    session(.claudeCode, "b", subagents: 3),
                    session(.claudeCode, "c")
                ]
            )
        )
        #expect(store.aggregateSessionCount == 3)
        #expect(store.aggregateSubagentCount == 3)

        store.applyForTesting(makeAgentSnapshot(.codex, availability: .ready))
        #expect(store.aggregateSessionCount == 2)
        #expect(store.aggregateSubagentCount == 3)

        // The sessions numeral rises to make room for the subagent row: the one thing the counts column
        // still answers to.
        #expect(
            PanelMetrics.countsSessionBaseline(hasSubagents: false)
                < PanelMetrics.countsSessionBaseline(hasSubagents: true)
        )
    }

    /// The band's leading side, now one number, fits the cut-out's shoulder on every Mac
    /// (`expanded-header-v2.md` §3, `colour-v2.md` §3).
    @Test
    func theBandClearsTheCutOutAtEveryCutOutThisProductMeets() {
        for occlusion in [127, 152, 168, 185, 200, 220] as [CGFloat] {
            let width = PanelMetrics.expandedWidth(centerOcclusionWidth: occlusion)
            // Centred on the display, so each side gets half of what the cut-out leaves.
            let availableSideWidth = (width - occlusion) / 2
            #expect(
                PanelMetrics.expandedLeadingSideWidth <= availableSideWidth,
                "leading at \(occlusion)"
            )
            // The trailing side, which binds when nothing is connected.
            #expect(
                PanelMetrics.expandedTrailingSideWidth(compactHeight: 46)
                    <= availableSideWidth
            )
        }
    }

    /// The expanded width is one number, `610`, at every cut-out, whatever is connected or running
    /// (`colour-v2.md` §3).
    @Test
    func theExpandedWidthIsOneNumber() {
        // The four cut-outs this app has measured, and none.
        for occlusion in [0, 127, 185, 200, 220] as [CGFloat] {
            #expect(
                PanelMetrics.expandedWidth(centerOcclusionWidth: occlusion) == 610,
                "at \(occlusion)"
            )
        }

        // The board's `53.8`: inset, mark, gap, two reserved digits and the cut-out's clearance, plus the
        // hundredth a drawn digit runs over the nominal `6.6`.
        #expect(abs(PanelMetrics.expandedLeadingSideWidth - 53.8) < 0.05)

        // `53.8` a side puts the cut-out branch past `502.4`, beyond any Mac's cut-out, so
        // `expandedNotchClearance` is a guard rather than the rule that decides a width.
        #expect(
            610 - PanelMetrics.expandedLeadingSideWidth * 2 > 502,
            "the baseline binds at every cut-out that exists"
        )
    }

