    /// The reset column is a written-out countdown of at most two units, zeros dropped, read from the
    /// remaining duration rather than calendar days.
    @Test
    func theResetColumnCountsDownInTwoUnitsWrittenOut() throws {
        var calendar = Calendar(identifier: .gregorian)
        calendar.timeZone = try #require(TimeZone(secondsFromGMT: 0))
        let now = try #require(calendar.date(from: DateComponents(
            year: 2026,
            month: 8,
            day: 13,
            hour: 10
        )))
        func text(afterMinutes minutes: Int) throws -> String {
            let resetsAt = try #require(
                calendar.date(byAdding: .minute, value: minutes, to: now)
            )
            return UsageSummaryFormatter.resetText(
                resetsAt: resetsAt,
                now: now,
                calendar: calendar
            )
        }

        #expect(try text(afterMinutes: 47) == "Resets in 47 minutes")
        #expect(try text(afterMinutes: 60 * 2) == "Resets in 2 hours")
        #expect(try text(afterMinutes: 60 * 8) == "Resets in 8 hours")
        #expect(
            try text(afterMinutes: 60 * 2 + 30) == "Resets in 2 hours 30 minutes"
        )
        #expect(
            try text(afterMinutes: 60 * 10 + 34) == "Resets in 10 hours 34 minutes"
        )
        // Days pair with hours: two units is the ceiling.
        #expect(try text(afterMinutes: 60 * 24) == "Resets in 1 day")
        #expect(try text(afterMinutes: 60 * 24 * 3) == "Resets in 3 days")
        #expect(
            try text(afterMinutes: 60 * (24 * 3 + 12) + 40)
                == "Resets in 3 days 12 hours"
        )
        #expect(try text(afterMinutes: 60 * 25) == "Resets in 1 day 1 hour")
        #expect(try text(afterMinutes: 1) == "Resets in 1 minute")
        #expect(try text(afterMinutes: 60) == "Resets in 1 hour")
        #expect(
            UsageSummaryFormatter.resetText(resetsAt: now, now: now) == "Resets now"
        )
    }

    /// An unreadable field draws `--` in its own place, with its unit, and is marked nowhere else
    /// (`quota-footer-v2.md` §8.3).
    @Test
    func anUnreadableFieldDrawsTwoDashes() {
        let now = Date(timeIntervalSinceReferenceDate: 0)

        #expect(UsageSummaryFormatter.today(tokens: 518_700_000).text == "519M today")
        #expect(UsageSummaryFormatter.today(tokens: nil).text == "-- today")
        #expect(UsageSummaryFormatter.share(remainingPercent: 72).text == "72% left")
        #expect(UsageSummaryFormatter.share(remainingPercent: nil).text == "-- left")
        // The timer has no unit, so its unreadable form is `--` alone.
        #expect(
            UsageSummaryFormatter.resetText(
                resetsAt: nil,
                remainingPercent: 60,
                now: now
            ) == "--"
        )
        #expect(UsageSummaryFormatter.today(tokens: nil).unit == "today")
    }

    /// Claude Code's 5-hour window has no reset until the first request: `Not started`, not `--`
    /// (`quota-footer-v2.md` §8.3). A spent window with no reset still signals changed `/usage` output.
    @Test
    func aWindowWithNothingSpentAndNoResetReadsAsNotStarted() {
        let now = Date(timeIntervalSinceReferenceDate: 0)

        #expect(
            UsageSummaryFormatter.resetText(
                resetsAt: nil,
                remainingPercent: 100,
                now: now
            ) == "Not started"
        )
        #expect(
            UsageSummaryFormatter.resetText(
                resetsAt: nil,
                remainingPercent: 60,
                now: now
            ) == "--"
        )
        #expect(
            UsageSummaryFormatter.resetText(
                resetsAt: nil,
                remainingPercent: nil,
                now: now
            ) == "--"
        )
    }

    /// `--` announces as unavailable, never zero; where the column draws a duration, the spoken form
    /// keeps the day (`resets Saturday at 16:00`) (`quota-footer-v2.md` §7).
    @Test
    func everyDashAnnouncesAsUnavailable() throws {
        var calendar = Calendar(identifier: .gregorian)
        calendar.timeZone = try #require(TimeZone(secondsFromGMT: 0))
        // A Tuesday, so the reset four days later is a Saturday.
        let now = try #require(calendar.date(from: DateComponents(
            year: 2026,
            month: 9,
            day: 1,
            hour: 10
        )))
        let resetsAt = try #require(
            calendar.date(byAdding: .hour, value: 24 * 4 + 6, to: now)
        )

        #expect(
            UsageSummaryFormatter.resetText(
                resetsAt: resetsAt,
                now: now,
                calendar: calendar
            ) == "Resets in 4 days 6 hours"
        )
        #expect(
            UsageSummaryFormatter.spokenResetText(
                resetsAt: resetsAt,
                now: now,
                calendar: calendar
            ) == "resets Saturday at 16:00"
        )
        #expect(
            UsageSummaryFormatter.spokenResetText(
                resetsAt: nil,
                remainingPercent: 60,
                now: now
            ) == "unavailable"
        )
        #expect(
            UsageSummaryFormatter.spokenResetText(
                resetsAt: nil,
                remainingPercent: 100,
                now: now
            ) == "not started"
        )
        #expect(
            UsageSummaryFormatter.today(tokens: nil).spokenText
                == "Tokens today unavailable"
        )
        #expect(
            UsageSummaryFormatter.today(tokens: 518_700_000).spokenText
                == "519M tokens today"
        )
    }

    @Test
    func elapsedFormatterRollsOverIntoHours() throws {
        let start = Date(timeIntervalSinceReferenceDate: 0)
        func elapsed(_ seconds: TimeInterval) -> String? {
            SessionElapsedFormatter.elapsed(
                since: start,
                now: start.addingTimeInterval(seconds)
            )
        }

        #expect(elapsed(0) == "0:00")
        #expect(elapsed(7) == "0:07")
        #expect(elapsed(83) == "1:23")
        #expect(elapsed(3599) == "59:59")
        #expect(elapsed(3600) == "1:00:00")
        #expect(elapsed(3723) == "1:02:03")
        // No start time, and clock skew, both read as "not timed".
        #expect(SessionElapsedFormatter.elapsed(since: nil, now: start) == nil)
        #expect(elapsed(-5) == nil)
    }

    /// VoiceOver reads the drawn `1:23` as a clock time, so the spoken form is a separate string.
    @Test
    func spokenElapsedReadsAsADurationRatherThanAClockTime() {
        let start = Date(timeIntervalSinceReferenceDate: 0)
        func spoken(_ seconds: TimeInterval) -> String? {
            SessionElapsedFormatter.spokenElapsed(
                since: start,
                now: start.addingTimeInterval(seconds)
            )
        }

        #expect(spoken(0) == "0 seconds")
        #expect(spoken(7) == "7 seconds")
        #expect(spoken(83) == "1 minute 23 seconds")
        #expect(spoken(120) == "2 minutes")
        #expect(spoken(3600) == "1 hour")
        #expect(spoken(3723) == "1 hour 2 minutes 3 seconds")
        #expect(SessionElapsedFormatter.spokenElapsed(since: nil, now: start) == nil)
        #expect(spoken(-5) == nil)
    }

    /// The timer keeps counting while a turn waits for approval: that wait is what needs a number.
    @Test @MainActor
    func timerKeepsCountingWhileATurnWaitsForApproval() async throws {
        let clock = TestClock()
        let store = makeIdleStore(clock: clock)
        let startedAt = clock.now()

        store.applyForTesting(
            makeSessionSnapshot([
                makeSession(status: .running, startedAt: startedAt)
            ]),
            observedAt: clock.now()
        )
        // Settle first, or the advance happens before there is a sleeper to wake.
        await clock.settle()
        await clock.advance(by: 30)
        #expect(store.compactTimerText == "0:30")

        // Same Turn, now blocked on a human; the count is unchanged.
        store.applyForTesting(
            makeSessionSnapshot([
                makeSession(status: .approvalNeeded, startedAt: startedAt)
            ]),
            observedAt: clock.now()
        )
        await clock.settle()
        await clock.advance(by: 90)

        #expect(store.compactTimerText == "2:00")
        #expect(store.elapsedText(for: try #require(store.sessions.first)) == "2:00")
    }

    @Test @MainActor
    func notchTimesTheLongestRunningUnfinishedTurn() async {
        let clock = TestClock()
        let store = makeIdleStore(clock: clock)
        let now = clock.now()

        store.applyForTesting(
            makeSessionSnapshot([
                // Oldest, but finished: a stopped clock cannot be the longest-running one.
                makeSession(
                    threadID: "done",
                    status: .completed,
                    startedAt: now.addingTimeInterval(-600)
                ),
                makeSession(
                    threadID: "waiting",
                    status: .approvalNeeded,
                    startedAt: now.addingTimeInterval(-300)
                ),
                makeSession(
                    threadID: "running",
                    status: .running,
                    startedAt: now.addingTimeInterval(-60)
                )
            ]),
            observedAt: now
        )
        await clock.settle()

        #expect(store.compactTimerText == "5:00")
        #expect(store.spokenLongestElapsedText == "5 minutes")
    }

    @Test @MainActor
    func completedTurnStopsItsTimerAndReleasesTheNotch() async throws {
        let clock = TestClock()
        let store = makeIdleStore(clock: clock)
        let startedAt = clock.now().addingTimeInterval(-125)

        store.applyForTesting(
            makeSessionSnapshot([
                makeSession(status: .completed, startedAt: startedAt)
            ]),
            observedAt: clock.now()
        )
        await clock.settle()

        // It stops being counted; the start time is still known.
        let session = try #require(store.sessions.first)
        #expect(session.startedAt == startedAt)
        #expect(store.elapsedText(for: session) == nil)
        #expect(store.spokenElapsedText(for: session) == nil)
        #expect(store.compactTimerText == nil)
    }

    /// With nothing to count, the monitor must not wake once a second.
    @Test @MainActor
    func elapsedTickingRunsOnlyWhileATurnIsTimed() async {
        let clock = TestClock()
        let store = makeIdleStore(clock: clock)
        await clock.settle()

        #expect(clock.sleeperCount == 0)

        let startedAt = clock.now()
        store.applyForTesting(
            makeSessionSnapshot([
                makeSession(status: .running, startedAt: startedAt)
            ]),
            observedAt: clock.now()
        )
        await clock.settle()
        #expect(clock.sleeperCount == 1)

        await clock.advance(by: 5)
        #expect(store.compactTimerText == "0:05")
        #expect(clock.sleeperCount == 1)

        store.applyForTesting(
            makeSessionSnapshot([
                makeSession(status: .completed, startedAt: startedAt)
            ]),
            observedAt: clock.now()
        )
        await clock.settle()

        #expect(clock.sleeperCount == 0)
    }

    /// The next Turn must reset the stale readout, or its first second renders blank.
