    /// Quitting Codex Desktop does not undo a dismissal: after relaunch the Hook reducer
    /// republishes the finished Turn (CR-Fable-004). Dismissals are forgotten only on their own
    /// product's word, never a neighbour's.
    @Test @MainActor
    func aDismissalSurvivesItsProductQuitting() {
        let finished = MonitoredSession(
            threadID: "thread",
            turnID: "turn-1",
            projectName: RowContentFallback.projectName,
            title: "Finished turn",
            preview: nil,
            status: .completed,
            startedAt: Date()
        )
        let store = MonitorStore(
            initialSnapshot: AgentSnapshot(
                availability: .ready,
                sessions: [finished],
                quota: .unavailable,
                diagnostic: nil
            )
        )

        #expect(store.dismiss(finished))
        #expect(store.sessions.isEmpty)

        // Desktop quits: presence says closed at once and the rows empty.
        store.applyForTesting(
            AgentSnapshot(
                availability: .ready,
                sessions: [],
                quota: .unavailable,
                diagnostic: nil,
                presence: .closed
            )
        )
        // Claude Code is not a witness to what Codex has dismissed.
        store.applyForTesting(
            AgentSnapshot(
                agent: .claudeCode,
                availability: .ready,
                sessions: [],
                quota: .unavailable,
                diagnostic: nil
            )
        )

        // Relaunched; the reducer republishes the same Turn.
        store.applyForTesting(
            AgentSnapshot(
                availability: .ready,
                sessions: [finished],
                quota: .unavailable,
                diagnostic: nil
            )
        )
        #expect(store.sessions.isEmpty)
    }

    /// A sustained `.disconnected` does not undo a dismissal: it says we stopped being able to
