    /// A row in any state can be dismissed: a Turn stuck open is never Completed.
    /// See ``MonitorStore/dismiss(_:)``.
    @Test @MainActor
    func aRowInAnyStateCanBeDismissed() {
        for status in [SessionStatus.running, .inputNeeded, .approvalNeeded] {
            let live = MonitoredSession(
                threadID: "thread-\(status)",
                turnID: "turn",
                projectName: RowContentFallback.projectName,
                title: "Live turn",
                preview: nil,
                status: status,
                startedAt: Date()
            )
            let store = MonitorStore(
                initialSnapshot: AgentSnapshot(
                    availability: .ready,
                    sessions: [live],
                    quota: .unavailable,
                    diagnostic: nil
                )
            )

            #expect(store.dismiss(live))
            #expect(store.sessions.isEmpty)
            // The Turn was dismissed, not the thread.
            let next = MonitoredSession(
                threadID: live.threadID,
                turnID: "turn-2",
                projectName: RowContentFallback.projectName,
                title: "Live turn",
                preview: nil,
                status: status,
                startedAt: Date()
            )
            store.applyForTesting(
                AgentSnapshot(
                    availability: .ready,
                    sessions: [next],
                    quota: .unavailable,
                    diagnostic: nil
                )
            )
            #expect(store.sessions.map(\.id) == [next.id])
        }
    }

