    /// The catcher covers the whole row, so it claims only the secondary press: claiming a
    /// primary press or movement would cost the row its navigation or hover.
    @Test @MainActor
    func theSecondaryClickCatcherClaimsOnlyTheSecondaryPress() {
        let claimed: [NSEvent.EventType] = [.rightMouseDown, .rightMouseUp]
        let passedThrough: [NSEvent.EventType] = [
            .leftMouseDown,
            .leftMouseUp,
            .leftMouseDragged,
            .mouseMoved,
            .mouseEntered,
            .mouseExited,
            .otherMouseDown,
            .scrollWheel,
            .keyDown
        ]

        for eventType in claimed {
            #expect(SecondaryClickView.claims(eventType))
        }
        for eventType in passedThrough {
            #expect(!SecondaryClickView.claims(eventType))
        }
        // AppKit also asks about geometry with no event in flight at all.
        #expect(!SecondaryClickView.claims(nil))
        #expect(SecondaryClickView().hitTest(.zero) == nil)
    }

    /// The catcher is a real view covering the row, and its press calls through. A synthetic
    /// mouse event would take the test host down, so the two halves are pinned separately.
    @Test @MainActor
    func theSecondaryClickCatcherCoversTheRowAndCallsThrough() {
        final class Count { var value = 0 }
        let pressed = Count()
        let rowSize = CGSize(width: 120, height: PanelMetrics.sessionRowHeight)

        let hosting = NSHostingView(
            rootView: Color.clear
                .frame(width: rowSize.width, height: rowSize.height)
                .overlay { SecondaryClickCatcher { pressed.value += 1 } }
        )
        hosting.frame = NSRect(origin: .zero, size: rowSize)
        hosting.layoutSubtreeIfNeeded()

        func catchers(in view: NSView) -> [SecondaryClickView] {
            (view as? SecondaryClickView).map { [$0] } ?? view.subviews.flatMap(catchers(in:))
        }
        let catcher = catchers(in: hosting).first
        #expect(catcher != nil)
        #expect(catcher?.frame.size == rowSize)

        catcher?.rightMouseDown(
            with: NSEvent.mouseEvent(
                with: .rightMouseDown,
                location: .zero,
                modifierFlags: [],
                timestamp: 0,
                windowNumber: 0,
                context: nil,
                eventNumber: 0,
                clickCount: 1,
                pressure: 1
            )!
        )
        #expect(pressed.value == 1)
    }

    /// Drawn over the request body, the catcher claims only the wheel, and only with
    /// ``claimsTheWheel``: a body that fits lets the wheel reach the list.
    @Test @MainActor
    func theWheelCatcherClaimsOnlyTheWheelAndOnlyWithTravel() {
        let view = WheelCatcherView()
        let passedThrough: [NSEvent.EventType] = [
            .leftMouseDown,
            .leftMouseUp,
            .leftMouseDragged,
            .rightMouseDown,
            .mouseMoved,
            .mouseEntered,
            .mouseExited,
            .cursorUpdate,
            .keyDown
        ]

        view.claimsTheWheel = true
        #expect(view.claims(.scrollWheel))
        for eventType in passedThrough {
            #expect(!view.claims(eventType))
        }
        #expect(!view.claims(nil))

        view.claimsTheWheel = false
        #expect(!view.claims(.scrollWheel))
        #expect(view.hitTest(.zero) == nil)
    }

    /// The catcher is a real view at the body's size. As a `.background` behind hit-testable
    /// lines it never received a wheel event (`system-architecture.md` §6).
    @Test @MainActor
    func theWheelCatcherCoversTheBodyItScrolls() {
        let bodySize = CGSize(width: 200, height: PanelMetrics.requestBodyMaximumHeight)

        let hosting = NSHostingView(
            rootView: Color.clear
                .frame(width: bodySize.width, height: bodySize.height)
                .overlay { WheelCatcher(claimsTheWheel: true) { _ in } }
        )
        hosting.frame = NSRect(origin: .zero, size: bodySize)
        hosting.layoutSubtreeIfNeeded()

        func catchers(in view: NSView) -> [WheelCatcherView] {
            (view as? WheelCatcherView).map { [$0] } ?? view.subviews.flatMap(catchers(in:))
        }
        let catcher = catchers(in: hosting).first
        #expect(catcher != nil)
        #expect(catcher?.frame.size == bodySize)
        #expect(catcher?.claimsTheWheel == true)
        // With no event in flight, the catcher stands aside.
        #expect(catcher?.hitTest(.zero) == nil)
    }

