    @Test
    func statusDomainsSeparateSystemAndSessionStates() {
        // Only the session states are pinned; a raw count cannot say which half changed.
        #expect(SessionStatus.allCases == [
            .running,
            .inputNeeded,
            .approvalNeeded,
            .completed
        ])
        let sessionStatuses = Set(SessionStatus.allCases.map(\.monitorStatus))
        #expect(
            sessionStatuses == [.running, .inputNeeded, .approvalNeeded, .completed]
        )
        #expect(
            Set(MonitorStatus.allCases).subtracting(sessionStatuses)
                == [
                    .connected,
                    .setupRequired,
                    .connecting,
                    .updateAgent,
                    .unsupportedVersion,
                    .disconnected
                ]
        )

        // No state names a product; saying which one is Settings' job.
        #expect(MonitorStatus.setupRequired.displayName == "Set up integration")
        #expect(MonitorStatus.inputNeeded.displayName == "Input needed")
        #expect(MonitorStatus.approvalNeeded.displayName == "Approval needed")
        #expect(MonitorStatus.connecting.displayName == "Connecting")
        #expect(MonitorStatus.unsupportedVersion.displayName == "Version unsupported")
        #expect(MonitorStatus.disconnected.displayName == "Disconnected")
    }

    @Test
    func sessionStatusMachineAllowsOnlyTheDesignedTransitions() {
        #expect(SessionStatus.running.transitioned(on: .inputNeeded) == .inputNeeded)
        #expect(SessionStatus.inputNeeded.transitioned(on: .inputNeeded) == .inputNeeded)
        #expect(SessionStatus.inputNeeded.transitioned(on: .running) == .running)
        #expect(SessionStatus.running.transitioned(on: .approvalNeeded) == .approvalNeeded)
        #expect(SessionStatus.approvalNeeded.transitioned(on: .approvalNeeded) == .approvalNeeded)
        #expect(SessionStatus.approvalNeeded.transitioned(on: .running) == .running)

        // Asymmetric by design: approval gives way to input, because a denied approval is never
        // closed and the question is the only evidence of an answer. An input wait is always
        // closed by its own `PostToolUse`, and Input outranks Approval (PRD §6.2).
        #expect(SessionStatus.approvalNeeded.transitioned(on: .inputNeeded) == .inputNeeded)
        #expect(SessionStatus.inputNeeded.transitioned(on: .approvalNeeded) == .inputNeeded)

        for status in SessionStatus.allCases {
            #expect(status.transitioned(on: .completed) == .completed)
        }
        #expect(SessionStatus.completed.transitioned(on: .running) == .completed)
        #expect(SessionStatus.completed.transitioned(on: .inputNeeded) == .completed)
        #expect(SessionStatus.completed.transitioned(on: .approvalNeeded) == .completed)
    }

