    /// Availability speaks for the aggregate only while it is not ready.
    @Test @MainActor
    func availabilitySpeaksForTheAggregateOnlyWhenNoProductHasRows() {
        let running = MonitoredSession(
            threadID: "thread",
            turnID: "turn",
            projectName: RowContentFallback.projectName,
            title: "Running task",
            preview: nil,
            status: .running,
            startedAt: Date()
        )

        let unready: [MonitorAvailability] = [
            .setupRequired,
            .connecting,
            .updateAgent,
            .unsupportedVersion,
            .disconnected
        ]
        // Collapsed, every unready product is Disconnected; the detail moved to the expanded panel.
        var reasons: Set<String> = []
        for availability in unready {
            let merged = AgentSnapshotMerge.merge([
                makeAgentSnapshot(.codex, availability: availability)
            ])
            #expect(merged.status == .disconnected)
            #expect(merged.availability == availability)
            reasons.insert(merged.availability.emptyListMessage)
        }
        #expect(reasons.count == unready.count)

        #expect(
            AgentSnapshotMerge.merge([
                makeAgentSnapshot(.codex, sessions: [running])
            ]).status == .running
        )
        #expect(AgentSnapshotMerge.merge([makeAgentSnapshot(.codex)]).status == .connected)

        // A new product's setupRequired must not take over from a running or a quiet one.
        #expect(
            AgentSnapshotMerge.merge([
                makeAgentSnapshot(.codex, sessions: [running]),
                makeAgentSnapshot(.claudeCode, availability: .setupRequired)
            ]).status == .running
        )
        #expect(
            AgentSnapshotMerge.merge([
                makeAgentSnapshot(.codex),
                makeAgentSnapshot(.claudeCode, availability: .setupRequired)
            ]).status == .connected
        )
        // With none connected the surface says one thing; the ranking survives in availability.
        let neitherConnected = AgentSnapshotMerge.merge([
            makeAgentSnapshot(.codex, availability: .connecting),
            makeAgentSnapshot(.claudeCode, availability: .setupRequired)
        ])
        #expect(neitherConnected.status == .disconnected)
        #expect(neitherConnected.availability == .setupRequired)
    }

    /// The row comparator is a total order: `sorted(by:)` is not stable, so equal keys would
    /// reshuffle the list between refreshes.
    @Test @MainActor
    func theMergedOrderIsTotalSoEqualKeysNeverSwapBetweenRefreshes() {
        let startedAt = Date(timeIntervalSince1970: 1_000)
        let sessions = (0 ..< 6).map { index in
            MonitoredSession(
                threadID: "thread-\(index)",
                turnID: "turn",
                projectName: RowContentFallback.projectName,
                title: "Task \(index)",
                preview: nil,
                status: index.isMultiple(of: 2) ? .running : .completed,
                startedAt: startedAt
            )
        }

        let forward = sessions.sorted(by: MonitorAggregation.rowOrder)
        let backward = sessions.reversed().sorted(by: MonitorAggregation.rowOrder)
        #expect(forward.map(\.id) == backward.map(\.id))

        // Across products the tie is real: simultaneous discovery reports the same millisecond.
        let mixed = AgentKind.allCases.map { agent in
            MonitoredSession(
                agent: agent,
                threadID: "same-thread",
                turnID: "same-turn",
                projectName: "notchline",
                title: "Task",
                preview: nil,
                status: .running,
                startedAt: startedAt
            )
        }
        #expect(
            mixed.reversed().sorted(by: MonitorAggregation.rowOrder).map(\.agent)
                == AgentKind.allCases
        )
    }

