    /// Measured 2026-08-22 (CLI `0.149.0-alpha.4.1`, `--approve-for-me`): `PermissionRequest`
    /// arrives 10 ms after its call and `PostToolUse` 2.5 s later. The row stays Running.
    @Test @MainActor
    func automaticallyReviewedThreadKeepsRunningWhileAnApprovalIsDecided() {
        func state(_ status: SessionStatus) -> HookTurnState {
            HookTurnState(
                threadID: "thread-auto",
                turnID: "turn-1",
                sessionStatus: status,
                pendingInput: nil,
                pendingApproval: PendingApproval(
                    toolUseID: "exec-1",
                    isInferred: true,
                    openedAt: Date(timeIntervalSince1970: 1_002),
                    request: nil
                ),
                startedAt: Date(timeIntervalSince1970: 1_000),
                lastEventAt: Date(timeIntervalSince1970: 1_002),
                retiredTurnIDs: [],
                promptPreview: "Run the build",
                assistantPreview: nil
            )
        }

        #expect(
            CodexSnapshotParser.session(
                from: state(.approvalNeeded),
                thread: codexRootThread(id: "thread-auto"),
                projectName: RowContentFallback.projectName,
                approvalsReachTheUser: false
            )?.status == .running
        )
        #expect(
            CodexSnapshotParser.session(
                from: state(.approvalNeeded),
                thread: codexRootThread(id: "thread-auto"),
                projectName: RowContentFallback.projectName,
                approvalsReachTheUser: true
            )?.status == .approvalNeeded
        )
        // Only approvals are answered elsewhere; `request_user_input` still asks the person.
        #expect(
            CodexSnapshotParser.session(
                from: state(.inputNeeded),
                thread: codexRootThread(id: "thread-auto"),
                projectName: RowContentFallback.projectName,
                approvalsReachTheUser: false
            )?.status == .inputNeeded
        )
        #expect(
            CodexSnapshotParser.session(
                from: state(.completed),
                thread: codexRootThread(id: "thread-auto"),
                projectName: RowContentFallback.projectName,
                approvalsReachTheUser: false
            )?.status == .completed
        )
    }

    /// `request_user_input_async` asks without stopping, so the next sentence overwrites the
    /// question within seconds (reported 2026-09-08). The status stays `running`.
    @Test @MainActor
    func aQuestionAskedWithoutWaitingIsWhatTheRunningRowShows() async throws {
        let paths = makeTemporaryHookPaths()
        defer {
            try? FileManager.default.removeItem(
                at: paths.supportDirectory.deletingLastPathComponent()
            )
        }
        let repository = HookEventRepository(paths: paths)
        var clock = 2_000.0
        func emit(_ event: [String: Any]) throws {
            clock += 1
            var payload = event
            payload["received_at"] = clock
            payload["session_id"] = "thread-async"
            payload["turn_id"] = "turn-async"
            try JSONSerialization.data(withJSONObject: payload).deliver(to: repository)
        }

        try emit([
            "hook_event_name": "UserPromptSubmit",
            "prompt": "Fix the funnel comparison"
        ])
        try emit([
            "hook_event_name": "PreToolUse",
            "tool_name": "request_user_input_async",
            "tool_use_id": "call-async-1",
            "tool_input": [
                "questions": [["title": "Which history fields should it compare?"]]
            ]
        ])
        // 51 ms later, whatever the person does, and the turn carries on.
        try emit([
            "hook_event_name": "PostToolUse",
            "tool_name": "request_user_input_async",
            "tool_use_id": "call-async-1"
        ])
        try emit([
            "hook_event_name": "PreToolUse",
            "tool_name": "shell",
            "tool_use_id": "exec-1"
        ])

        let turn = try #require(await repository.drainDeliveredEvents().turns.first)
        #expect(turn.status == .running)
        #expect(
            turn.questionAskedWithoutWaiting == "Which history fields should it compare?"
        )

        #expect(
            CodexSnapshotParser.session(
                from: turn,
                thread: codexRootThread(id: "thread-async"),
                projectName: "notchline",
                liveProgress: "Rewriting the query as a derived table"
            )?.preview == "Which history fields should it compare?"
        )

        // A completed turn keeps its own last word, written after the question.
        var finished = turn
        finished.sessionStatus = .completed
        finished.assistantPreview = "Rewrote the query and left the comparison as it was"
        #expect(
            CodexSnapshotParser.session(
                from: finished,
                thread: codexRootThread(id: "thread-async"),
                projectName: "notchline"
            )?.preview == "Rewrote the query and left the comparison as it was"
        )

        // A stopped turn has no last word (ADR 0011), so the question shows.
        finished.assistantPreview = nil
        #expect(
            CodexSnapshotParser.session(
                from: finished,
                thread: codexRootThread(id: "thread-async"),
                projectName: "notchline"
            )?.preview == "Which history fields should it compare?"
        )
    }

