    @Test @MainActor
    func recordedDeliveryOutlivesARestartWithoutRestoringATurn() async throws {
        let paths = makeTemporaryHookPaths()
        defer {
            try? FileManager.default.removeItem(
                at: paths.supportDirectory.deletingLastPathComponent()
            )
        }

        let registrar = CodexHookRegistrar(paths: paths)
        try await registrar.install()
        #expect(await registrar.registration() == .complete)

        // Only an observed event survives a restart, so a user who trusted the hooks is not asked
        // again.
        HookInstallStateFile.update(at: paths.installState) {
            $0.lastEventAt = Date(timeIntervalSince1970: 1_700_000_000)
        }

        let restored = HookEventRepository(paths: paths)
        let state = await restored.drainDeliveredEvents()
        #expect(state.hasObservedEvent)
        // Nothing about the current runtime comes back.
        #expect(!state.hasObservedLiveEvent)
        #expect(state.turns.isEmpty)

        let client = CodexAppServerStub(
            listedThreads: [],
            loadedListResults: []
        )
        let service = LiveCodexMonitorService(
            client: client,
            hookEvents: restored,
            hookRegistrar: registrar,
            desktopProcessIdentifierProvider: { 4_242 }
        )

        let snapshot = await service.fetchSnapshot()
        await waitForThreadListRequests(
            client,
            atLeast: 1,
            completed: true
        )
        let methods = await client.requestedMethods()
        let previousEpoch = restored.observationEpoch
        await service.disconnect()
        #expect(restored.observationEpoch != previousEpoch)
        #expect(await restored.observedState().hasObservedEvent, "disconnect does not revoke unchanged hook trust")
        #expect(await service.nextRefreshDeadline() == nil)

        #expect(snapshot.setupStatus == .active)
        #expect(snapshot.availability == .ready)
        #expect(snapshot.sessions.isEmpty)
        #expect(AgentSnapshotMerge.merge([snapshot]).status == .connected)
        #expect(methods.contains("thread/list"))
        #expect(!methods.contains("thread/loaded/list"))
        #expect(!methods.contains("thread/read"))
    }

    @Test @MainActor
    func startupNeverReconstructsPreLaunchSessions() async throws {
        let paths = makeTemporaryHookPaths()
        defer {
            try? FileManager.default.removeItem(
                at: paths.supportDirectory.deletingLastPathComponent()
            )
        }

        let installer = CodexHookRegistrar(paths: paths)
        try await installer.install()

        let projectStateFile = paths.supportDirectory
            .appendingPathComponent(".codex-global-state.json")
        let projectState = try JSONSerialization.data(withJSONObject: [
            "local-projects": [
                "project-1": ["name": "Codex in Notch"]
            ],
            "thread-project-assignments": [
                "thread-1": [
                    "projectKind": "local",
                    "projectId": "project-1"
                ]
            ],
            "projectless-thread-ids": []
        ])
        try projectState.write(to: projectStateFile, options: .atomic)

        let listedThread = JSONValue.object([
            "id": .string("thread-1"),
            "ephemeral": .bool(false),
            "parentThreadId": .null,
            "threadSource": .string("user"),
            "name": .string("Fast startup"),
            "section": .object(["name": .string("Pinned")]),
            "status": .object([
                "type": .string("active"),
                "activeFlags": .array([])
            ]),
            "turns": .array([
                .object([
                    "id": .string("turn-1"),
                    "status": .string("inProgress")
                ])
            ])
        ])
        let client = CodexAppServerStub(
            listedThreads: [listedThread],
            loadedListResults: []
        )
        let service = LiveCodexMonitorService(
            client: client,
            hookEvents: HookEventRepository(
                paths: paths
            ),
            hookRegistrar: installer,
            projectMetadata: CodexDesktopProjectMetadataRepository(
                stateFileURL: projectStateFile
            ),
            desktopProcessIdentifierProvider: { 4_242 }
        )

        let ready = await service.fetchSnapshot()
        let requestedMethods = await client.requestedMethods()

        // Only a post-launch Hook creates a session, whatever the listed thread claims.
        #expect(ready.availability == .ready)
        #expect(ready.sessions.isEmpty)
        // Presence is stated, not left to whether Codex Desktop is open on this machine.
        #expect(ready.presence == .open)
        // The App Server answered, but this newly written setup has no activation evidence.
        // Both settings and the summary withhold Connected until that separate fact is verified.
        #expect(ready.setupStatus == .reviewRequired)
        #expect(!ready.isConnected)
        #expect(AgentSnapshotMerge.merge([ready]).status == .disconnected)
        // Startup still proves the App Server answers a real read.
        #expect(requestedMethods.contains("thread/list"))
        #expect(!requestedMethods.contains("thread/loaded/list"))
        #expect(!requestedMethods.contains("thread/read"))
        #expect(await client.disconnectCount() == 0)

        await service.disconnect()
    }

