        #expect(idle.availability == .ready)
        #expect(idle.sessions.isEmpty)

        let prompt = try JSONSerialization.data(withJSONObject: [
            "received_at": Date().timeIntervalSince1970,
            "hook_event_name": "UserPromptSubmit",
            "session_id": "thread-1",
            "turn_id": "turn-1"
        ])
        prompt.deliver(to: repository)

        // The row comes from the per-thread read, before the paginated list answers.
        let startedAt = Date()
        let running = await snapshotWithSessions(from: service)
        let elapsed = Date().timeIntervalSince(startedAt)
        let threadListRequests = await client.requestCount(method: "thread/list")
        await service.disconnect()

        #expect(running.sessions.first?.status == .running)
        #expect(elapsed < 1.5)
        #expect(threadListRequests == 1)
    }

    /// A side chat, or any thread Codex will not hand over, draws no row at any point. Side
    /// chats are ephemeral: not on disk, not in `thread/list`, refused by `thread/read`.
    @Test @MainActor
    func aThreadTheAppServerRefusesDrawsNoRowAtAnyPointInItsTurn() async throws {
        let paths = makeTemporaryHookPaths()
        defer {
            try? FileManager.default.removeItem(
                at: paths.supportDirectory.deletingLastPathComponent()
            )
        }

        let installer = CodexHookRegistrar(paths: paths)
        let repository = HookEventRepository(paths: paths)
        try await installer.install()

        let client = CodexAppServerStub(
            listedThreads: [codexRootThread(id: "thread-main", name: "Real work")],
            loadedListResults: []
        )
        let service = LiveCodexMonitorService(
            client: client,
            hookEvents: repository,
            hookRegistrar: installer,
            desktopProcessIdentifierProvider: { 4_242 }
        )

        let timestamp = Date().timeIntervalSince1970
        for event in [
            [
                "received_at": timestamp,
                "hook_event_name": "UserPromptSubmit",
                "session_id": "thread-main",
                "turn_id": "turn-main"
            ],
            [
                "received_at": timestamp,
                "hook_event_name": "UserPromptSubmit",
                "session_id": "thread-side",
                "turn_id": "turn-side"
            ]
        ] {
            try JSONSerialization.data(withJSONObject: event).deliver(to: repository)
        }

        // The refusal must not park the real thread's read in the same batch.
        let running = await snapshotWithSessions(from: service)
        #expect(running.sessions.map(\.threadID) == ["thread-main"])
        await waitForThreadListRequests(client, atLeast: 1, completed: true)
        let sweepsAfterFirstPass = await client.requestCount(method: "thread/list")

        try JSONSerialization.data(withJSONObject: [
            "received_at": Date().timeIntervalSince1970,
            "hook_event_name": "Stop",
            "session_id": "thread-side",
            "turn_id": "turn-side",
            "last_assistant_message": "Answered in the side chat."
        ]).deliver(to: repository)

        for _ in 0 ..< 3 {
            let snapshot = await service.fetchSnapshot()
            #expect(snapshot.sessions.map(\.threadID) == ["thread-main"])
        }

        let sweeps = await client.requestCount(method: "thread/list")
        await service.disconnect()

        // A disowned thread is not worth re-paginating the history for.
        #expect(
            sweeps == sweepsAfterFirstPass,
            "a refused thread went on asking for the membership sweep"
        )
    }

    /// Codex sends `transcript_path` on every hook, null for a thread it will not materialise
    /// (CLI `0.153.4` schemas, 2026-09-09). A missing key says nothing.
    @Test @MainActor
    func aThreadIsWrittenDownNowhereOnlyWhileTheProductSaysSo() async throws {
        let paths = makeTemporaryHookPaths()
        defer {
            try? FileManager.default.removeItem(
                at: paths.supportDirectory.deletingLastPathComponent()
            )
        }
        let repository = HookEventRepository(paths: paths)
        var clock = 5_000.0
        func emit(_ event: [String: Any]) throws {
            clock += 1
            var payload = event
            payload["received_at"] = clock
            payload["session_id"] = "thread-side"
            payload["turn_id"] = "turn-side"
            try JSONSerialization.data(withJSONObject: payload).deliver(to: repository)
        }

        try emit([
            "hook_event_name": "UserPromptSubmit",
            "prompt": "Summarise this file",
            "transcript_path": NSNull()
        ])
        #expect(
            await repository.drainDeliveredEvents().turns.first?
                .threadHasNoTranscript == true
        )

        // A missing key is not a retraction.
        try emit([
            "hook_event_name": "PreToolUse",
            "tool_name": "shell",
            "tool_use_id": "call-1"
        ])
        #expect(
            await repository.drainDeliveredEvents().turns.first?
                .threadHasNoTranscript == true
        )

        // A path retracts: the latest answer wins. Not seen on a real thread.
        try emit([
            "hook_event_name": "Stop",
            "transcript_path": "/tmp/rollout-2026-09-09-thread-side.jsonl",
            "last_assistant_message": "Summarised."
        ])
        #expect(
            await repository.drainDeliveredEvents().turns.first?
                .threadHasNoTranscript == false
        )
    }

    /// A thread written down nowhere costs no `thread/read` (ADR 0017), which would answer
    /// `-32600 "thread not loaded"` every metadata interval.
    @Test @MainActor
    func aThreadTheProductWritesDownNowhereIsNeverAskedAbout() async throws {
        let paths = makeTemporaryHookPaths()
        defer {
            try? FileManager.default.removeItem(
                at: paths.supportDirectory.deletingLastPathComponent()
            )
        }

        let installer = CodexHookRegistrar(paths: paths)
        let repository = HookEventRepository(paths: paths)
        try await installer.install()

        // The App Server would refuse the side chat; it is never asked.
        let client = CodexAppServerStub(
            listedThreads: [codexRootThread(id: "thread-main", name: "Real work")],
            loadedListResults: []
        )
        let service = LiveCodexMonitorService(
            client: client,
            hookEvents: repository,
            hookRegistrar: installer,
            desktopProcessIdentifierProvider: { 4_242 }
        )

        let timestamp = Date().timeIntervalSince1970
        for event in [
            [
                "received_at": timestamp,
                "hook_event_name": "UserPromptSubmit",
                "session_id": "thread-main",
                "turn_id": "turn-main",
                "transcript_path": "/tmp/rollout-2026-09-09-thread-main.jsonl"
            ] as [String: Any],
            [
                "received_at": timestamp,
                "hook_event_name": "UserPromptSubmit",
                "session_id": "thread-side",
                "turn_id": "turn-side",
                "transcript_path": NSNull()
            ] as [String: Any]
        ] {
            try JSONSerialization.data(withJSONObject: event).deliver(to: repository)
        }

        let running = await snapshotWithSessions(from: service)
        #expect(running.sessions.map(\.threadID) == ["thread-main"])

        // Several refreshes pass; the read is not merely deferred.
        try JSONSerialization.data(withJSONObject: [
            "received_at": Date().timeIntervalSince1970,
            "hook_event_name": "Stop",
            "session_id": "thread-side",
            "turn_id": "turn-side",
            "transcript_path": NSNull(),
            "last_assistant_message": "Answered in the side chat."
        ]).deliver(to: repository)

        for _ in 0 ..< 3 {
            let snapshot = await service.fetchSnapshot()
            #expect(snapshot.sessions.map(\.threadID) == ["thread-main"])
        }

        let readThreadIDs = await client.recordedThreadReadParams()
            .compactMap { $0["threadId"]?.stringValue }
        await service.disconnect()

        #expect(
            !readThreadIDs.contains("thread-side"),
            "a thread Codex says it is writing down nowhere was asked about"
        )
        // The ordinary thread was read, so the service did not stop reading.
        #expect(readThreadIDs.contains("thread-main"))
    }

    @Test
    func closesWithoutOpensReportTheUntrustedPreToolUseHook() async throws {
        // Codex trusts hook definitions by content hash: a rewritten one stops running while the
        // rest keep firing. Replays that stream.
        let paths = makeTemporaryHookPaths()
        defer {
            try? FileManager.default.removeItem(
                at: paths.supportDirectory.deletingLastPathComponent()
            )
        }

        let repository = HookEventRepository(
            paths: paths
        )
        var clock = 3_000.0
        func emit(_ index: Int, _ event: [String: Any]) throws {
            clock += 1
            var payload = event
            payload["received_at"] = clock
            payload["session_id"] = "thread-untrusted"
            payload["turn_id"] = "turn-untrusted"
            try JSONSerialization.data(withJSONObject: payload).deliver(to: repository)
        }

        try emit(0, ["hook_event_name": "UserPromptSubmit"])
        for index in 1 ... 2 {
            try emit(index, [
                "hook_event_name": "PostToolUse",
                "tool_name": "Bash",
                "tool_use_id": "exec-\(index)"
            ])
        }
        #expect(await repository.drainDeliveredEvents().diagnostic == nil)

        try emit(3, [
            "hook_event_name": "PostToolUse",
            "tool_name": "Bash",
            "tool_use_id": "exec-3"
        ])
        let warned = await repository.drainDeliveredEvents().diagnostic
        #expect(warned?.contains("/hooks") == true)
        #expect(warned?.contains("PreToolUse") == true)
    }

