    /// A held prompt wakes the record sweep; otherwise the next turn waits for an event or the
    /// interval, though its record is on disk before the hook.
    @Test
    func aHeldPromptWakesTheSweepThatCanRedeemIt() async throws {
        let paths = makeTemporaryHookPaths()
        defer {
            try? FileManager.default.removeItem(
                at: paths.supportDirectory.deletingLastPathComponent()
            )
        }

        let repository = HookEventRepository(paths: paths)
        var clock = 9_400.0
        func emit(_ event: [String: Any]) throws {
            clock += 1
            var payload = event
            payload["received_at"] = clock
            payload["session_id"] = "thread-finished"
            payload["turn_id"] = payload["turn_id"] ?? "turn-first"
            try JSONSerialization.data(withJSONObject: payload).deliver(to: repository)
        }

        try emit(["hook_event_name": "UserPromptSubmit", "prompt": "the first prompt"])
        try emit(["hook_event_name": "Stop", "last_assistant_message": "Done."])
        #expect(await repository.drainDeliveredEvents().turns.first?.status == .completed)

        let prompt = try JSONSerialization.data(withJSONObject: [
            "received_at": clock + 1,
            "hook_event_name": "UserPromptSubmit",
            "session_id": "thread-finished",
            "turn_id": "turn-next",
            "prompt": "next"
        ] as [String: Any])
        let woke = await receivesChange(repository.changeEvents()) {
            prompt.deliver(to: repository)
        }
        #expect(woke, "a held prompt must wake the sweep that reads the record")
        let held = await repository.observedState().turns.first
        #expect(held?.turnID == "turn-first")
        #expect(held?.heldTurnStart?.turnID == "turn-next")
    }

    @Test @MainActor
    func permissionRequestAloneDoesNotPublishApprovalNeeded() async throws {
        let paths = makeTemporaryHookPaths()
        defer {
            try? FileManager.default.removeItem(
                at: paths.supportDirectory.deletingLastPathComponent()
            )
        }

        let installer = CodexHookRegistrar(paths: paths)
        let repository = HookEventRepository(paths: paths)
        try await installer.install()
        let timestamp = Date().timeIntervalSince1970
        let prompt = try JSONSerialization.data(withJSONObject: [
            "received_at": timestamp,
            "hook_event_name": "UserPromptSubmit",
            "session_id": "thread-1",
            "turn_id": "turn-1"
        ])
        prompt.deliver(to: repository)

        let listedThread = JSONValue.object([
            "id": .string("thread-1"),
            "ephemeral": .bool(false),
            "threadSource": .string("user"),
            "status": .object([
                "type": .string("active"),
                "activeFlags": .array([])
            ])
        ])
        let client = CodexAppServerStub(
            listedThreads: [listedThread],
            loadedListResults: []
        )
        let service = LiveCodexMonitorService(
            client: client,
            hookEvents: repository,
            hookRegistrar: installer,
            desktopProcessIdentifierProvider: { 4_242 }
        )

        // The row lands on the fetch after the App Server confirms the thread.
        let initial = await snapshotWithSessions(from: service)
        #expect(initial.sessions.first?.status == .running)
        await waitForThreadListRequests(
            client,
            atLeast: 1,
            completed: true
        )
        // Neither background App Server read may sit on the Hook -> UI path.
        await client.setThreadListDelayNanoseconds(2_000_000_000)
        await client.setThreadReadDelayNanoseconds(2_000_000_000)

        let approval = try JSONSerialization.data(withJSONObject: [
            "received_at": Date().timeIntervalSince1970,
            "hook_event_name": "PermissionRequest",
            "session_id": "thread-1",
            "turn_id": "turn-1"
        ])
        approval.deliver(to: repository)
        let startedAt = Date()
        let approvalSnapshot = await service.fetchSnapshot()
        let elapsed = Date().timeIntervalSince(startedAt)

        let input = try JSONSerialization.data(withJSONObject: [
            "received_at": Date().timeIntervalSince1970,
            "hook_event_name": "PreToolUse",
            "session_id": "thread-1",
            "turn_id": "turn-1",
            "tool_name": "request_user_input",
            "tool_use_id": "tool-1"
        ])
        input.deliver(to: repository)
        let inputSnapshot = await service.fetchSnapshot()
        let threadListRequests = await client.requestCount(method: "thread/list")
        await service.disconnect()

        #expect(approvalSnapshot.sessions.first?.status == .running)
        #expect(inputSnapshot.sessions.first?.status == .inputNeeded)
        #expect(elapsed < 1.5)
        // Hook activity on a listed thread triggers only the per-thread read.
        #expect(threadListRequests == 1)
    }

    /// End to end: an announced Bash call stays Running on an automatically reviewed thread and
    /// reaches Approval needed on a person-reviewed one.
    @Test @MainActor
    func automaticallyReviewedThreadNeverPublishesApprovalNeeded() async throws {
        func rowStatus(reviewer: String) async throws -> SessionStatus? {
            let paths = makeTemporaryHookPaths()
            defer {
                try? FileManager.default.removeItem(
                    at: paths.supportDirectory.deletingLastPathComponent()
                )
            }
            let root = FileManager.default.temporaryDirectory
                .appendingPathComponent(UUID().uuidString, isDirectory: true)
            defer { try? FileManager.default.removeItem(at: root) }
            try FileManager.default.createDirectory(
                at: root,
                withIntermediateDirectories: true
            )
            let stateFile = root
                .appendingPathComponent(".codex-global-state.json")
            try JSONSerialization.data(withJSONObject: [
                "electron-persisted-atom-state": [
                    "heartbeat-thread-permissions-by-id": [
                        "thread-1": ["approvalsReviewer": reviewer]
                    ]
                ]
            ]).write(to: stateFile, options: .atomic)

            let installer = CodexHookRegistrar(paths: paths)
            let repository = HookEventRepository(paths: paths)
            try await installer.install()
            let timestamp = Date().timeIntervalSince1970
            // Desktop rewrites this file ~0.5 s into every Turn (sending clears the persisted draft);
            // the pin takes the map only from that write.
            try FileManager.default.setAttributes(
                [.modificationDate: Date(timeIntervalSince1970: timestamp + 0.5)],
                ofItemAtPath: stateFile.path
            )
            for event in [
                [
                    "received_at": timestamp,
                    "hook_event_name": "UserPromptSubmit",
                    "session_id": "thread-1",
                    "turn_id": "turn-1"
                ],
                [
                    "received_at": timestamp + 1,
                    "hook_event_name": "PreToolUse",
                    "session_id": "thread-1",
                    "turn_id": "turn-1",
                    "tool_name": "Bash",
                    "tool_use_id": "exec-1"
                ],
                [
                    "received_at": timestamp + 2,
                    "hook_event_name": "PermissionRequest",
                    "session_id": "thread-1",
                    "turn_id": "turn-1",
                    "tool_name": "Bash"
                ]
            ] {
                try JSONSerialization.data(withJSONObject: event)
                    .deliver(to: repository)
            }

            let client = CodexAppServerStub(
                listedThreads: [
                    .object([
                        "id": .string("thread-1"),
                        "ephemeral": .bool(false),
                        "threadSource": .string("user")
                    ])
                ],
                loadedListResults: []
            )
            let service = LiveCodexMonitorService(
                client: client,
                hookEvents: repository,
                hookRegistrar: installer,
                approvalRouting: CodexDesktopApprovalRoutingRepository(
                    stateFileURL: stateFile
                ),
                desktopProcessIdentifierProvider: { 4_242 }
            )
            let snapshot = await snapshotWithSessions(from: service)
            await service.disconnect()
            return snapshot.sessions.first?.status
        }

        #expect(try await rowStatus(reviewer: "auto_review") == .running)
        #expect(try await rowStatus(reviewer: "user") == .approvalNeeded)
    }

    /// The routing answer belongs to the Turn, not the thread's current setting.
    @Test @MainActor
    func approvalRoutingPinKeepsTheAnswerTheTurnStartedUnder() {
        var pin = TurnApprovalRoutingPin()
        let turnStart = Date(timeIntervalSince1970: 1_000)
        let firstTurn = TurnApprovalRoutingPin.TurnIdentity(
            threadID: "thread-1",
            turnID: "turn-1"
        )
        let personReviews = desktopRouting(
            automatic: [], forTurnStartedAt: turnStart
        )
        let codexReviews = desktopRouting(
            automatic: ["thread-1"], forTurnStartedAt: turnStart
        )
        // Desktop rewrites the map when the reviewer changes, so the switch carries that instant.
        let codexReviewsFromTheSwitch = desktopRouting(
            automatic: ["thread-1"],
            forTurnStartedAt: turnStart,
            writtenAfter: 300
        )
        let personReviewsFromTheSwitch = desktopRouting(
            automatic: [], forTurnStartedAt: turnStart, writtenAfter: 300
        )

        let atTurnStart = pin.approvalsReachTheUser(
            forTurn: firstTurn,
            startedAt: turnStart,
            in: personReviews
        )
        // The turn in flight keeps the reviewer it started with.
        let afterTheSwitch = pin.approvalsReachTheUser(
            forTurn: firstTurn,
            startedAt: turnStart,
            in: codexReviewsFromTheSwitch
        )
        #expect(atTurnStart)
        #expect(afterTheSwitch)

        // Symmetric: switched the other way, still automatic until this turn ends.
        var reversed = TurnApprovalRoutingPin()
        let reversedAtTurnStart = reversed.approvalsReachTheUser(
            forTurn: firstTurn,
            startedAt: turnStart,
            in: codexReviews
        )
        let reversedAfterTheSwitch = reversed.approvalsReachTheUser(
            forTurn: firstTurn,
            startedAt: turnStart,
            in: personReviewsFromTheSwitch
        )
        #expect(!reversedAtTurnStart)
        #expect(!reversedAfterTheSwitch)

        let secondTurnStart = turnStart.addingTimeInterval(600)
        let secondTurn = TurnApprovalRoutingPin.TurnIdentity(
            threadID: "thread-1",
            turnID: "turn-2"
        )
        let nextTurnAnswer = pin.approvalsReachTheUser(
            forTurn: secondTurn,
            startedAt: secondTurnStart,
            in: desktopRouting(
                automatic: ["thread-1"], forTurnStartedAt: secondTurnStart
            )
        )
        #expect(!nextTurnAnswer)

        // A turn the reducer no longer holds is forgotten; its identity is a fresh question.
        pin.retain(turns: [secondTurn])
        let forgottenTurnAnswer = pin.approvalsReachTheUser(
            forTurn: firstTurn,
            startedAt: turnStart,
            in: personReviews
        )
        let retainedTurnAnswer = pin.approvalsReachTheUser(
            forTurn: secondTurn,
            startedAt: secondTurnStart,
            in: desktopRouting(
                automatic: [], forTurnStartedAt: secondTurnStart
            )
        )
        #expect(forgottenTurnAnswer)
        #expect(!retainedTurnAnswer)
    }

    /// Codex writes `turn_context` ~65 ms before `UserPromptSubmit` (2026-08-25, CLI
    /// `0.149.0-alpha.4.3`).
    @Test @MainActor
    func rolloutTurnReviewerReadsTheReviewerTheRunningTurnWasHanded() async throws {
        let root = FileManager.default.temporaryDirectory
            .appendingPathComponent(UUID().uuidString, isDirectory: true)
        defer { try? FileManager.default.removeItem(at: root) }
        try FileManager.default.createDirectory(
            at: root,
            withIntermediateDirectories: true
        )

        let stampFormatter = ISO8601DateFormatter()
        stampFormatter.formatOptions = [
            .withInternetDateTime,
            .withFractionalSeconds
        ]
        let turnStartedAt = Date()
        func line(_ object: [String: Any]) throws -> String {
            let data = try JSONSerialization.data(withJSONObject: object)
            return String(decoding: data, as: UTF8.self)
        }
        func turnContext(
            reviewer: String?,
            offsetFromTurnStart: TimeInterval,
            turnID: String? = nil
        ) throws -> String {
            var payload: [String: Any] = ["approval_policy": "on-request"]
            if let reviewer {
                payload["approvals_reviewer"] = reviewer
            }
            if let turnID {
                payload["turn_id"] = turnID
            }
            return try line([
                "timestamp": stampFormatter.string(
                    from: turnStartedAt.addingTimeInterval(offsetFromTurnStart)
                ),
                "type": "turn_context",
                "payload": payload
            ])
        }
        func writeRollout(_ lines: [String]) throws -> String {
            let file = root.appendingPathComponent("\(UUID().uuidString).jsonl")
            try Data(lines.joined(separator: "\n").appending("\n").utf8)
                .write(to: file, options: .atomic)
            return file.path
        }
        // Not a `turn_context` but carrying the word: the decode decides, not the prefilter.
        let noise = try line([
            "timestamp": stampFormatter.string(from: turnStartedAt),
            "type": "response_item",
            "payload": ["type": "message", "text": "about the turn_context"]
        ])

        let reader = CodexRolloutTurnReviewerReader()
        func read(_ path: String, asTurn turnID: String = "turn-1") async -> Bool? {
            await reader.approvalsReachTheUser(
                forTurn: turnID,
                startedAt: turnStartedAt,
                inRolloutAt: path
            )
        }

        let automatic = try writeRollout([
            noise,
            try turnContext(reviewer: "auto_review", offsetFromTurnStart: -0.065),
            noise
        ])
        #expect(await read(automatic) == false)

        let person = try writeRollout([
            try turnContext(reviewer: "user", offsetFromTurnStart: -0.065),
            noise
        ])
        #expect(await read(person) == true)

        // An unknown reviewer proves nothing, so it must not silence the state.
        let unrecognised = try writeRollout([
            try turnContext(reviewer: "team_lead", offsetFromTurnStart: -0.065)
        ])
        #expect(await read(unrecognised) == true)

        let switched = try writeRollout([
            try turnContext(reviewer: "user", offsetFromTurnStart: -600),
            noise,
            try turnContext(reviewer: "auto_review", offsetFromTurnStart: -0.065)
        ])
        #expect(await read(switched) == false)

        // Only the previous Turn's record is on disk: say nothing and leave the map to answer.
        let staleOnly = try writeRollout([
            try turnContext(reviewer: "user", offsetFromTurnStart: -600),
            noise
        ])
        #expect(await read(staleOnly) == nil)

        // Where the record names its Turn, that decides; a resumed Turn's old rollout defeats the
        // time window.
        let interruptedTurnsRecord = try writeRollout([
            try turnContext(
                reviewer: "user",
                offsetFromTurnStart: -1,
                turnID: "turn-0"
            )
        ])
        #expect(await read(interruptedTurnsRecord) == nil)

        let ownRecordReadLate = try writeRollout([
            try turnContext(
                reviewer: "auto_review",
                offsetFromTurnStart: -600,
                turnID: "turn-1"
            )
        ])
        #expect(await read(ownRecordReadLate) == false)

        let silent = try writeRollout([noise, noise])
        #expect(await read(silent) == nil)

        let reviewerless = try writeRollout([
            try turnContext(reviewer: nil, offsetFromTurnStart: -0.065)
        ])
        #expect(await read(reviewerless) == nil)

        #expect(await read(root.appendingPathComponent("absent.jsonl").path) == nil)

        // A distant head is read from the tail; the seek lands mid-record.
        let padding = try line([
            "timestamp": stampFormatter.string(from: turnStartedAt),
            "type": "response_item",
            "payload": [
                "type": "message",
                "text": String(repeating: "p", count: 8_192)
            ]
        ])
        let paddedLines = Array(repeating: padding, count: 400)
        let deepInAFile = try writeRollout(
            paddedLines
                + [try turnContext(
                    reviewer: "auto_review",
                    offsetFromTurnStart: -0.065
                )]
        )
        #expect(await read(deepInAFile) == false)

        // A record past the tail window is not claimed.
        let pastTheWindow = try writeRollout(
            [try turnContext(reviewer: "auto_review", offsetFromTurnStart: -0.065)]
                + paddedLines
        )
        #expect(await read(pastTheWindow) == nil)
    }

    /// The newest `turn_context` names the thread's Turn; a nested agent's turns go to its own
    /// rollout.
    @Test @MainActor
    func rolloutReaderNamesTheTurnTheThreadsOwnRecordIsOn() async throws {
        let root = FileManager.default.temporaryDirectory
            .appendingPathComponent(UUID().uuidString, isDirectory: true)
        defer { try? FileManager.default.removeItem(at: root) }
        try FileManager.default.createDirectory(
            at: root,
            withIntermediateDirectories: true
        )

        let stampFormatter = ISO8601DateFormatter()
        stampFormatter.formatOptions = [
            .withInternetDateTime,
            .withFractionalSeconds
        ]
        func line(_ object: [String: Any]) throws -> String {
            let data = try JSONSerialization.data(withJSONObject: object)
            return String(decoding: data, as: UTF8.self)
        }
        func turnContext(_ turnID: String?) throws -> String {
            var payload: [String: Any] = ["cwd": "/tmp"]
            if let turnID { payload["turn_id"] = turnID }
            return try line([
                "timestamp": stampFormatter.string(from: Date()),
                "type": "turn_context",
                "payload": payload
            ])
        }
        let noise = try line([
            "timestamp": stampFormatter.string(from: Date()),
            "type": "response_item",
            "payload": ["type": "message", "text": "about the turn_context"]
        ])
        func writeRollout(_ lines: [String]) throws -> String {
            let file = root.appendingPathComponent("\(UUID().uuidString).jsonl")
            try Data(lines.joined(separator: "\n").appending("\n").utf8)
                .write(to: file, options: .atomic)
            return file.path
        }

        let reader = CodexRolloutTurnAbortReader()

        let onRecord = try writeRollout([
            noise,
            try turnContext("turn-0"),
            noise,
            try turnContext("turn-1"),
            noise
        ])
        #expect(await reader.turnOnRecord(inRolloutAt: onRecord) == "turn-1")

        // Silence is the only refusal: a held prompt no record names stays held.
        let silent = try writeRollout([noise, noise])
        #expect(await reader.turnOnRecord(inRolloutAt: silent) == nil)

        // A record without the field answers nothing.
        let unnamed = try writeRollout([try turnContext(nil)])
        #expect(await reader.turnOnRecord(inRolloutAt: unnamed) == nil)

        #expect(await reader.turnOnRecord(inRolloutAt: root.path + "/absent.jsonl") == nil)
    }

    /// Stopping a Codex Turn sends no hook; the abort record ends only the Turn it names.
    @Test @MainActor
    func rolloutAbortReaderEndsOnlyTheTurnTheRecordNames() async throws {
        let root = FileManager.default.temporaryDirectory
            .appendingPathComponent(UUID().uuidString, isDirectory: true)
        defer { try? FileManager.default.removeItem(at: root) }
        try FileManager.default.createDirectory(
            at: root,
            withIntermediateDirectories: true
        )

        let stampFormatter = ISO8601DateFormatter()
        stampFormatter.formatOptions = [
            .withInternetDateTime,
            .withFractionalSeconds
        ]
        // Whole seconds survive the rollout's millisecond format, so dates compare exactly.
        let lastEventAt = Date(
            timeIntervalSince1970: Date().timeIntervalSince1970.rounded(.down)
        )
        func line(_ object: [String: Any]) throws -> String {
            let data = try JSONSerialization.data(withJSONObject: object)
            return String(decoding: data, as: UTF8.self)
        }
        /// The record Codex writes, including `reason`, which the reader never looks at.
        func abort(
            turn: String,
            offsetFromLastEvent: TimeInterval,
            reason: String = "interrupted"
        ) throws -> String {
            try line([
                "timestamp": stampFormatter.string(
                    from: lastEventAt.addingTimeInterval(offsetFromLastEvent)
                ),
                "type": "event_msg",
                "payload": [
                    "type": "turn_aborted",
                    "turn_id": turn,
                    "reason": reason,
                    "duration_ms": 4_466
                ]
            ])
        }
        /// The developer message written one line before the abort: carries the word, not the record.
        let abortNarration = try line([
            "timestamp": stampFormatter.string(from: lastEventAt),
            "type": "response_item",
            "payload": [
                "type": "message",
                "role": "developer",
                "text": "<turn_aborted>The previous turn was interrupted.</turn_aborted>"
            ]
        ])
        func writeRollout(_ lines: [String]) throws -> String {
            let file = root.appendingPathComponent("\(UUID().uuidString).jsonl")
            try Data(lines.joined(separator: "\n").appending("\n").utf8)
                .write(to: file, options: .atomic)
            return file.path
        }

        let reader = CodexRolloutTurnAbortReader()
        func read(_ path: String, turn: String = "turn-1") async -> Date? {
            await reader.abortedAt(
                turnID: turn,
                inRolloutAt: path,
                after: lastEventAt
            )
        }

        let stopped = try writeRollout([
            abortNarration,
            try abort(turn: "turn-1", offsetFromLastEvent: 4)
        ])
        #expect(
            await read(stopped) == lastEventAt.addingTimeInterval(4)
        )

        // An unknown reason still ends the Turn; requiring `interrupted` would leave it Running.
        let unknownReason = try writeRollout([
            try abort(turn: "turn-1", offsetFromLastEvent: 4, reason: "replaced")
        ])
        #expect(
            await read(unknownReason) == lastEventAt.addingTimeInterval(4)
        )

        // A record naming the previous Turn must not retire the running one.
        let previousTurn = try writeRollout([
            try abort(turn: "turn-0", offsetFromLastEvent: 4)
        ])
        #expect(await read(previousTurn) == nil)

        // A record older than the Turn's last event cannot describe it.
        let stale = try writeRollout([
            try abort(turn: "turn-1", offsetFromLastEvent: -30)
        ])
        #expect(await read(stale) == nil)

        let narrationOnly = try writeRollout([abortNarration])
        #expect(await read(narrationOnly) == nil)

        let unnamed = try writeRollout([try line([
            "timestamp": stampFormatter.string(
                from: lastEventAt.addingTimeInterval(4)
            ),
            "type": "event_msg",
            "payload": ["type": "turn_aborted", "reason": "interrupted"]
        ])])
        #expect(await read(unnamed) == nil)

        let running = try writeRollout([try line([
            "timestamp": stampFormatter.string(from: lastEventAt),
            "type": "event_msg",
            "payload": ["type": "token_count"]
        ])])
        #expect(await read(running) == nil)

        #expect(await read(root.appendingPathComponent("absent.jsonl").path) == nil)

        // Only the newest abort counts; a later one naming another Turn means the rollout moved on.
        let superseded = try writeRollout([
            try abort(turn: "turn-1", offsetFromLastEvent: 4),
            try abort(turn: "turn-2", offsetFromLastEvent: 9)
        ])
        #expect(await read(superseded) == nil)

        let padding = try line([
            "timestamp": stampFormatter.string(from: lastEventAt),
            "type": "response_item",
            "payload": [
                "type": "message",
                "text": String(repeating: "p", count: 8_192)
            ]
        ])
        let paddedLines = Array(repeating: padding, count: 64)
        let deepInAFile = try writeRollout(
            paddedLines + [try abort(turn: "turn-1", offsetFromLastEvent: 4)]
        )
        #expect(
            await read(deepInAFile) == lastEventAt.addingTimeInterval(4)
        )

        // Past the tail window: not claimed. An idle abort sits 249-940 bytes from the end.
        let pastTheWindow = try writeRollout(
            [try abort(turn: "turn-1", offsetFromLastEvent: 4)] + paddedLines
        )
        #expect(await read(pastTheWindow) == nil)

        // Cached on the file's revision (one `lstat` per refresh); a grown rollout is a new one.
        let grew = try writeRollout([padding])
        #expect(await read(grew) == nil)
        let handle = try FileHandle(forWritingTo: URL(fileURLWithPath: grew))
        _ = try handle.seekToEnd()
        try handle.write(
            contentsOf: Data(
                (try abort(turn: "turn-1", offsetFromLastEvent: 4) + "\n").utf8
            )
        )
        try handle.close()
        #expect(await read(grew) == lastEventAt.addingTimeInterval(4))
    }

    /// A map written outside the Turn's opening moments does not pin. Too old: a 500 ms debounce
    /// defers the write while the draft is typed (Desktop `26.820.60940`, 2026-08-26). Too new:
    /// a mid-turn switch describes the thread.
    @Test @MainActor
    func approvalRoutingRefusesAMapFromOutsideTheTurnsOpeningMoments() {
        var pin = TurnApprovalRoutingPin()
        let turnStart = Date(timeIntervalSince1970: 1_000)
        let turn = TurnApprovalRoutingPin.TurnIdentity(
            threadID: "thread-1",
            turnID: "turn-1"
        )

        // Written half a minute before the Turn: not provably current, so it says nothing.
        let stale = desktopRouting(
            automatic: ["thread-1"],
            forTurnStartedAt: turnStart,
            writtenAfter: -30
        )
        let onTheStaleMap = pin.approvalsReachTheUser(
            forTurn: turn, startedAt: turnStart, in: stale
        )
        #expect(
            onTheStaleMap,
            "a map from before the Turn must not silence its approvals"
        )

        // It did not pin, so the composer-clearing write moments later answers.
        let atTheTurnsStart = desktopRouting(
            automatic: ["thread-1"], forTurnStartedAt: turnStart
        )
        let onTheTurnsOwnWrite = pin.approvalsReachTheUser(
            forTurn: turn, startedAt: turnStart, in: atTheTurnsStart
        )
        #expect(
            !onTheTurnsOwnWrite,
            "the refusal must not cost the Turn its real answer"
        )

        // A map written well into the Turn describes the thread now, not the Turn.
        var late = TurnApprovalRoutingPin()
        let afterASwitch = desktopRouting(
            automatic: ["thread-1"],
            forTurnStartedAt: turnStart,
            writtenAfter: 300
        )
        let onASwitchMidTurn = late.approvalsReachTheUser(
            forTurn: turn, startedAt: turnStart, in: afterASwitch
        )
        #expect(
            onASwitchMidTurn,
            "a switch made mid-turn must not silence the Turn in flight"
        )

        // The authority still outranks both refusals.
        late.recordRolloutReading(
            false,
            forTurn: turn,
            inRolloutReportedAt: turnStart
        )
        let onTheAuthority = late.approvalsReachTheUser(
            forTurn: turn, startedAt: turnStart, in: afterASwitch
        )
        #expect(!onTheAuthority)
    }

    /// The rollout answers once, and its answer outranks the map's.
    @Test @MainActor
    func approvalRoutingPinPrefersTheRolloutAndFallsBackToTheMap() {
        var pin = TurnApprovalRoutingPin()
        let turnStart = Date(timeIntervalSince1970: 1_000)
        let turn = TurnApprovalRoutingPin.TurnIdentity(
            threadID: "thread-1",
            turnID: "turn-1"
        )
        let mapSaysPerson = desktopRouting(
            automatic: [], forTurnStartedAt: turnStart
        )

        let pathReportedAt = turnStart.addingTimeInterval(-3)

        // Before the rollout path is known, the map answers.
        #expect(
            pin.awaitsRolloutReading(
                forTurn: turn,
                startedAt: turnStart,
                inRolloutReportedAt: pathReportedAt
            )
        )
        let beforeTheReading = pin.approvalsReachTheUser(
            forTurn: turn,
            startedAt: turnStart,
            in: mapSaysPerson
        )
        #expect(beforeTheReading)

        // The rollout reading replaces the map's pinned answer.
        pin.recordRolloutReading(
            false,
            forTurn: turn,
            inRolloutReportedAt: pathReportedAt
        )
        let afterTheReading = pin.approvalsReachTheUser(
            forTurn: turn,
            startedAt: turnStart,
            in: mapSaysPerson
        )
        #expect(
            !pin.awaitsRolloutReading(
                forTurn: turn,
                startedAt: turnStart,
                inRolloutReportedAt: turnStart.addingTimeInterval(60)
            ),
            "an answered Turn is not asked again, however the path moves"
        )
        #expect(!afterTheReading)

        // The Turn's own rollout without the record closes the reading; the pinned map answers.
        var unreadable = TurnApprovalRoutingPin()
        unreadable.recordRolloutReading(
            nil,
            forTurn: turn,
            inRolloutReportedAt: turnStart.addingTimeInterval(0.5)
        )
        #expect(
            !unreadable.awaitsRolloutReading(
                forTurn: turn,
                startedAt: turnStart,
                inRolloutReportedAt: turnStart.addingTimeInterval(10)
            ),
            "a file named after this Turn began will not gain what it lacks"
        )
        let codexReviews = desktopRouting(
            automatic: ["thread-1"], forTurnStartedAt: turnStart
        )
        let fromTheMap = unreadable.approvalsReachTheUser(
            forTurn: turn,
            startedAt: turnStart,
            in: codexReviews
        )
        let afterTheMapChanged = unreadable.approvalsReachTheUser(
            forTurn: turn,
            startedAt: turnStart,
            in: mapSaysPerson
        )
        #expect(!fromTheMap)
        #expect(!afterTheMapChanged)

        // And a forgotten Turn is a fresh question, reading included.
        unreadable.retain(turns: [])
        #expect(
            unreadable.awaitsRolloutReading(
                forTurn: turn,
                startedAt: turnStart,
                inRolloutReportedAt: pathReportedAt
            )
        )
    }

    /// An empty reading of a rollout the Turn has left is not final: a resumed Turn writes a new
    /// rollout (2026-08-31, CLI `0.151.0-alpha.7.2`).
    @Test @MainActor
    func aReadingOfTheRolloutTheTurnIsNoLongerInIsNotFinal() {
        var pin = TurnApprovalRoutingPin()
        let turnStart = Date(timeIntervalSince1970: 1_000)
        let turn = TurnApprovalRoutingPin.TurnIdentity(
            threadID: "thread-1",
            turnID: "turn-2"
        )

        // The path predates the rotation, so the reading comes back empty.
        let pathFromBeforeTheTurn = turnStart.addingTimeInterval(-10)
        #expect(
            pin.awaitsRolloutReading(
                forTurn: turn,
                startedAt: turnStart,
                inRolloutReportedAt: pathFromBeforeTheTurn
            )
        )
        pin.recordRolloutReading(
            nil,
            forTurn: turn,
            inRolloutReportedAt: pathFromBeforeTheTurn
        )

        // One reading per rollout the Turn could be in, not per refresh.
        #expect(
            !pin.awaitsRolloutReading(
                forTurn: turn,
                startedAt: turnStart,
                inRolloutReportedAt: pathFromBeforeTheTurn
            ),
            "the same path must not be read again on every refresh"
        )

        // The next `thread/read` names the current rollout; the question reopens.
        let pathFromInsideTheTurn = turnStart.addingTimeInterval(6.7)
        #expect(
            pin.awaitsRolloutReading(
                forTurn: turn,
                startedAt: turnStart,
                inRolloutReportedAt: pathFromInsideTheTurn
            ),
            "a newer path is a new file to look in"
        )
        pin.recordRolloutReading(
            false,
            forTurn: turn,
            inRolloutReportedAt: pathFromInsideTheTurn
        )
        let answered = pin.approvalsReachTheUser(
            forTurn: turn,
            startedAt: turnStart,
            in: desktopRouting(
                automatic: [],
                forTurnStartedAt: turnStart,
                writtenAfter: -30
            )
        )
        #expect(
            !answered,
            "the Turn's own record outranks a map that cannot be shown current"
        )
    }

    /// Reported 2026-08-24: switched to `auto_review` mid-turn, it kept opening dialogs while the
    /// row said Running.
    @Test @MainActor
    func aReviewerChangedMidTurnDoesNotSilenceTheApprovalAlreadyBeingAsked() async throws {
        let paths = makeTemporaryHookPaths()
        defer {
            try? FileManager.default.removeItem(
                at: paths.supportDirectory.deletingLastPathComponent()
            )
        }
        let root = FileManager.default.temporaryDirectory
            .appendingPathComponent(UUID().uuidString, isDirectory: true)
        defer { try? FileManager.default.removeItem(at: root) }
        try FileManager.default.createDirectory(
            at: root,
            withIntermediateDirectories: true
        )
        let stateFile = root.appendingPathComponent(".codex-global-state.json")
        /// Stamped on the hook timeline: the pin only takes a write from a Turn's opening moments.
        func recordReviewer(
            _ reviewer: String,
            writtenAt: TimeInterval
        ) throws {
            try JSONSerialization.data(withJSONObject: [
                "electron-persisted-atom-state": [
                    "heartbeat-thread-permissions-by-id": [
                        "thread-1": ["approvalsReviewer": reviewer]
                    ]
                ]
            ]).write(to: stateFile, options: .atomic)
            try FileManager.default.setAttributes(
                [.modificationDate: Date(timeIntervalSince1970: writtenAt)],
                ofItemAtPath: stateFile.path
            )
        }

        let installer = CodexHookRegistrar(paths: paths)
        let repository = HookEventRepository(paths: paths)
        try await installer.install()
        let timestamp = Date().timeIntervalSince1970
        func deliver(_ event: [String: Any]) throws {
            try JSONSerialization.data(withJSONObject: event)
                .deliver(to: repository)
        }

        // Sending clears the persisted composer, so Desktop writes ~0.5 s into the Turn.
        try recordReviewer("user", writtenAt: timestamp + 0.5)
        try deliver([
            "received_at": timestamp,
            "hook_event_name": "UserPromptSubmit",
            "session_id": "thread-1",
            "turn_id": "turn-1"
        ])

        let client = CodexAppServerStub(
            listedThreads: [
                .object([
                    "id": .string("thread-1"),
                    "ephemeral": .bool(false),
                    "threadSource": .string("user")
                ])
            ],
            loadedListResults: []
        )
        let service = LiveCodexMonitorService(
            client: client,
            hookEvents: repository,
            hookRegistrar: installer,
            approvalRouting: CodexDesktopApprovalRoutingRepository(
                stateFileURL: stateFile
            ),
            desktopProcessIdentifierProvider: { 4_242 }
        )
        #expect(await snapshotWithSessions(from: service).sessions.first?.status == .running)

        // The switch lands inside this Turn's window; the pin must hold regardless.
        try recordReviewer("auto_review", writtenAt: timestamp + 1.5)
        try deliver([
            "received_at": timestamp + 1,
            "hook_event_name": "PreToolUse",
            "session_id": "thread-1",
            "turn_id": "turn-1",
            "tool_name": "Bash",
            "tool_use_id": "exec-1"
        ])
        try deliver([
            "received_at": timestamp + 2,
            "hook_event_name": "PermissionRequest",
            "session_id": "thread-1",
            "turn_id": "turn-1",
            "tool_name": "Bash"
        ])
        #expect(
            await service.fetchSnapshot().sessions.first?.status
                == .approvalNeeded
        )

        // The next turn asks the map again; its held prompt is redeemed here as the sweep would.
        try deliver([
            "received_at": timestamp + 2.5,
            "hook_event_name": "Stop",
            "session_id": "thread-1",
            "turn_id": "turn-1"
        ])
        try deliver([
            "received_at": timestamp + 3,
            "hook_event_name": "UserPromptSubmit",
            "session_id": "thread-1",
            "turn_id": "turn-2"
        ])
        _ = await repository.drainDeliveredEvents()
        _ = await repository.adoptTurnsOnRecord([
            TurnOnRecord(threadID: "thread-1", turnID: "turn-2")
        ])
        try recordReviewer("auto_review", writtenAt: timestamp + 3.5)
        try deliver([
            "received_at": timestamp + 4,
            "hook_event_name": "PreToolUse",
            "session_id": "thread-1",
            "turn_id": "turn-2",
            "tool_name": "Bash",
            "tool_use_id": "exec-2"
        ])
        try deliver([
            "received_at": timestamp + 5,
            "hook_event_name": "PermissionRequest",
            "session_id": "thread-1",
            "turn_id": "turn-2",
            "tool_name": "Bash"
        ])
        let afterNextTurn = await service.fetchSnapshot()
        await service.disconnect()
        #expect(afterNextTurn.sessions.first?.status == .running)
    }

    /// Reported 2026-08-25: Approval needed with nobody asked, only on sessions switched to
    /// automatic mid-way (a stale map). The map says `user`; the Turn's `turn_context` does not.
    @Test @MainActor
    func aTurnHandedToTheReviewerIsNotAnnouncedAsApprovalNeeded() async throws {
        let paths = makeTemporaryHookPaths()
        defer {
            try? FileManager.default.removeItem(
                at: paths.supportDirectory.deletingLastPathComponent()
            )
        }
        let root = FileManager.default.temporaryDirectory
            .appendingPathComponent(UUID().uuidString, isDirectory: true)
        defer { try? FileManager.default.removeItem(at: root) }
        try FileManager.default.createDirectory(
            at: root,
            withIntermediateDirectories: true
        )

        let installer = CodexHookRegistrar(paths: paths)
        let repository = HookEventRepository(paths: paths)
        try await installer.install()
        let timestamp = Date().timeIntervalSince1970
        let turnStartedAt = Date(timeIntervalSince1970: timestamp)

        // Desktop's map, still carrying the starting setting.
        let stateFile = root.appendingPathComponent(".codex-global-state.json")
        try JSONSerialization.data(withJSONObject: [
            "electron-persisted-atom-state": [
                "heartbeat-thread-permissions-by-id": [
                    "thread-1": ["approvalsReviewer": "user"]
                ]
            ]
        ]).write(to: stateFile, options: .atomic)

        // The Turn's own record, written 65 ms before the hook that starts it.
        let stampFormatter = ISO8601DateFormatter()
        stampFormatter.formatOptions = [
            .withInternetDateTime,
            .withFractionalSeconds
        ]
        let rollout = root.appendingPathComponent("rollout-thread-1.jsonl")
        try Data((String(
            decoding: try JSONSerialization.data(withJSONObject: [
                "timestamp": stampFormatter.string(
                    from: turnStartedAt.addingTimeInterval(-0.065)
                ),
                "type": "turn_context",
                "payload": ["approvals_reviewer": "auto_review"]
            ]),
            as: UTF8.self
        ) + "\n").utf8).write(to: rollout, options: .atomic)

        func deliver(_ event: [String: Any]) throws {
            try JSONSerialization.data(withJSONObject: event)
                .deliver(to: repository)
        }
        try deliver([
            "received_at": timestamp,
            "hook_event_name": "UserPromptSubmit",
            "session_id": "thread-1",
            "turn_id": "turn-1"
        ])
        // Measured 2026-08-25 (`--approve-for-me`): a reviewed call still sends `PreToolUse` and
        // `PermissionRequest` 35 ms apart, and `PostToolUse` 4.8 s later.
        try deliver([
            "received_at": timestamp + 1,
            "hook_event_name": "PreToolUse",
            "session_id": "thread-1",
            "turn_id": "turn-1",
            "tool_name": "Bash",
            "tool_use_id": "exec-1"
        ])
        try deliver([
            "received_at": timestamp + 2,
            "hook_event_name": "PermissionRequest",
            "session_id": "thread-1",
            "turn_id": "turn-1",
            "tool_name": "Bash"
