        let client = CodexAppServerStub(
            listedThreads: [
                .object([
                    "id": .string("thread-1"),
                    "ephemeral": .bool(false),
                    "threadSource": .string("user"),
                    "path": .string(rollout.path)
                ])
            ],
            loadedListResults: []
        )
        let service = LiveCodexMonitorService(
            client: client,
            hookEvents: repository,
            hookRegistrar: installer,
            approvalRouting: CodexDesktopApprovalRoutingRepository(
                stateFileURL: stateFile
            ),
            desktopProcessIdentifierProvider: { 4_242 }
        )
        let snapshot = await snapshotWithSessions(from: service)
        await service.disconnect()
        #expect(snapshot.sessions.first?.status == .running)
    }

    /// Reported 2026-08-31: a stopped and resent Turn on an "Approve for me" thread showed
    /// Approval needed. The resumed Turn went to a new rollout after this app's last
    /// `thread/read` (CLI `0.151.0-alpha.7.2`), and the map was inadmissible.
    @Test @MainActor
    func aTurnResumedAfterAnInterruptIsNotAnnouncedAsApprovalNeeded() async throws {
        let paths = makeTemporaryHookPaths()
        defer {
            try? FileManager.default.removeItem(
                at: paths.supportDirectory.deletingLastPathComponent()
            )
        }
        let root = FileManager.default.temporaryDirectory
            .appendingPathComponent(UUID().uuidString, isDirectory: true)
        defer { try? FileManager.default.removeItem(at: root) }
        try FileManager.default.createDirectory(
            at: root,
            withIntermediateDirectories: true
        )

        let installer = CodexHookRegistrar(paths: paths)
        let repository = HookEventRepository(paths: paths)
        try await installer.install()
        let timestamp = Date().timeIntervalSince1970.rounded(.down)
        let stampFormatter = ISO8601DateFormatter()
        stampFormatter.formatOptions = [
            .withInternetDateTime,
            .withFractionalSeconds
        ]
        func line(_ object: [String: Any]) throws -> String {
            String(
                decoding: try JSONSerialization.data(withJSONObject: object),
                as: UTF8.self
            )
        }
        func write(_ lines: [String], to file: URL) throws {
            try Data(lines.joined(separator: "\n").appending("\n").utf8)
                .write(to: file, options: .atomic)
        }
        func turnContext(turnID: String, at offset: TimeInterval) throws -> String {
            try line([
                "timestamp": stampFormatter.string(
                    from: Date(timeIntervalSince1970: timestamp + offset)
                ),
                "type": "turn_context",
                "payload": [
                    "turn_id": turnID,
                    "approvals_reviewer": "auto_review"
                ]
            ])
        }

        let interruptedRollout = root.appendingPathComponent("rollout-1.jsonl")
        try write(
            [try turnContext(turnID: "turn-1", at: -0.065)],
            to: interruptedRollout
        )

        // The map agrees but predates the Turn, so it is refused; the Turn's record must answer.
        let stateFile = root.appendingPathComponent(".codex-global-state.json")
        try JSONSerialization.data(withJSONObject: [
            "electron-persisted-atom-state": [
                "heartbeat-thread-permissions-by-id": [
                    "thread-1": ["approvalsReviewer": "auto_review"]
                ]
            ]
        ]).write(to: stateFile, options: .atomic)
        try FileManager.default.setAttributes(
            [.modificationDate: Date(timeIntervalSince1970: timestamp)],
            ofItemAtPath: stateFile.path
        )

        func deliver(_ event: [String: Any]) throws {
            try JSONSerialization.data(withJSONObject: event)
                .deliver(to: repository)
        }
        try deliver([
            "received_at": timestamp,
            "hook_event_name": "UserPromptSubmit",
            "session_id": "thread-1",
            "turn_id": "turn-1"
        ])

        let client = CodexAppServerStub(
            listedThreads: [
                .object([
                    "id": .string("thread-1"),
                    "ephemeral": .bool(false),
                    "threadSource": .string("user"),
                    "path": .string(interruptedRollout.path)
                ])
            ],
            loadedListResults: []
        )
        let service = LiveCodexMonitorService(
            client: client,
            hookEvents: repository,
            hookRegistrar: installer,
            approvalRouting: CodexDesktopApprovalRoutingRepository(
                stateFileURL: stateFile
            ),
            desktopProcessIdentifierProvider: { 4_242 }
        )
        defer { Task { await service.disconnect() } }
        #expect(await snapshotWithSessions(from: service).sessions.first?.status == .running)

        // The double Esc sends no hook; the rollout abort is the whole report (ADR 0011).
        try write(
            [
                try turnContext(turnID: "turn-1", at: -0.065),
                try line([
                    "timestamp": stampFormatter.string(
                        from: Date(timeIntervalSince1970: timestamp + 3)
                    ),
                    "type": "event_msg",
                    "payload": [
                        "type": "turn_aborted",
                        "turn_id": "turn-1",
                        "reason": "interrupted"
                    ]
                ])
            ],
            to: interruptedRollout
        )
        let ended = await holds {
            await service.fetchSnapshot().sessions.first?.status == .completed
        }
        #expect(ended, "the interrupted Turn never ended")

        // Resent: Codex writes a new rollout; this app still holds the old path.
        let resumedRollout = root.appendingPathComponent("rollout-2.jsonl")
        try write([try turnContext(turnID: "turn-2", at: 8.9)], to: resumedRollout)
        await client.setThreadPath(resumedRollout.path, forThread: "thread-1")
        // The new path arrives late; an empty old file must not answer for this Turn.
        await client.setThreadReadDelayNanoseconds(300_000_000)
        let readsBeforeTheResumedTurn = await client.completedThreadReadRequestCount()
        try deliver([
            "received_at": timestamp + 9,
            "hook_event_name": "UserPromptSubmit",
            "session_id": "thread-1",
            "turn_id": "turn-2"
        ])
        let onTheResumedTurn = await holds {
            await service.fetchSnapshot().sessions.first?.turnID == "turn-2"
        }
        #expect(onTheResumedTurn, "the resumed Turn never reached the row")

        // The Turn opening re-asks for the path; the first review came 17 s later.
        let pathCaughtUp = await holds {
            _ = await service.fetchSnapshot()
            return await client.completedThreadReadRequestCount()
                > readsBeforeTheResumedTurn
        }
        #expect(pathCaughtUp, "the resumed Turn never had its own path read")
        _ = await service.fetchSnapshot()

        try deliver([
            "received_at": timestamp + 10,
            "hook_event_name": "PreToolUse",
            "session_id": "thread-1",
            "turn_id": "turn-2",
            "tool_name": "Bash",
            "tool_use_id": "exec-1"
        ])
        try deliver([
            "received_at": timestamp + 11,
            "hook_event_name": "PermissionRequest",
            "session_id": "thread-1",
            "turn_id": "turn-2",
            "tool_name": "Bash"
        ])

        // Read once: the row must be right on this refresh.
        let settled = await service.fetchSnapshot().sessions.first
        #expect(settled?.turnID == "turn-2")
        #expect(settled?.status == .running)
    }

    /// Codex sends nothing when a Turn is stopped (no `Stop`, no open `PostToolUse`); the
    /// rollout abort is the only report (ADR 0011).
    @Test @MainActor
    func aStoppedCodexTurnCompletesOnTheAbortInItsRollout() async throws {
        let paths = makeTemporaryHookPaths()
        defer {
            try? FileManager.default.removeItem(
                at: paths.supportDirectory.deletingLastPathComponent()
            )
        }
        let root = FileManager.default.temporaryDirectory
            .appendingPathComponent(UUID().uuidString, isDirectory: true)
        defer { try? FileManager.default.removeItem(at: root) }
        try FileManager.default.createDirectory(
            at: root,
            withIntermediateDirectories: true
        )

        let installer = CodexHookRegistrar(paths: paths)
        let repository = HookEventRepository(paths: paths)
        try await installer.install()

        let timestamp = Date().timeIntervalSince1970.rounded(.down)
        let rollout = root.appendingPathComponent("rollout-thread-1.jsonl")
        let stampFormatter = ISO8601DateFormatter()
        stampFormatter.formatOptions = [
            .withInternetDateTime,
            .withFractionalSeconds
        ]
        func writeRollout(_ objects: [[String: Any]]) throws {
            let lines = try objects.map { object in
                String(
                    decoding: try JSONSerialization.data(withJSONObject: object),
                    as: UTF8.self
                )
            }
            try Data(lines.joined(separator: "\n").appending("\n").utf8)
                .write(to: rollout, options: .atomic)
        }
        try writeRollout([[
            "timestamp": stampFormatter.string(
                from: Date(timeIntervalSince1970: timestamp - 0.065)
            ),
            "type": "turn_context",
            "payload": ["turn_id": "turn-1", "approvals_reviewer": "user"]
        ]])

        func deliver(_ event: [String: Any]) throws {
            try JSONSerialization.data(withJSONObject: event)
                .deliver(to: repository)
        }
        try deliver([
            "received_at": timestamp,
            "hook_event_name": "UserPromptSubmit",
            "session_id": "thread-1",
            "turn_id": "turn-1",
            "prompt": "Rewrite the panel contour."
        ])
        // The user stops mid-call; its `PostToolUse` never arrives.
        try deliver([
            "received_at": timestamp + 1,
            "hook_event_name": "PreToolUse",
            "session_id": "thread-1",
            "turn_id": "turn-1",
            "tool_name": "Bash",
            "tool_use_id": "exec-1"
        ])

        let client = CodexAppServerStub(
            listedThreads: [
                codexRootThread(
                    id: "thread-1",
                    name: "Panel contour",
                    path: rollout.path
                )
            ],
            loadedListResults: []
        )
        let service = LiveCodexMonitorService(
            client: client,
            hookEvents: repository,
            hookRegistrar: installer,
            desktopProcessIdentifierProvider: { 4_242 }
        )

        let running = await snapshotWithSessions(from: service)
        #expect(running.sessions.first?.status == .running)

        // Stop: this is everything Codex reports.
        try writeRollout([
            [
                "timestamp": stampFormatter.string(
                    from: Date(timeIntervalSince1970: timestamp - 0.065)
                ),
                "type": "turn_context",
                "payload": ["turn_id": "turn-1", "approvals_reviewer": "user"]
            ],
            [
                "timestamp": stampFormatter.string(
                    from: Date(timeIntervalSince1970: timestamp + 8)
                ),
                "type": "event_msg",
                "payload": [
                    "type": "turn_aborted",
                    "turn_id": "turn-1",
                    "reason": "interrupted",
                    "duration_ms": 7_000
                ]
            ]
        ])

        var stopped = await service.fetchSnapshot()
        let ended = await holds {
            stopped = await service.fetchSnapshot()
            return stopped.sessions.first?.status == .completed
        }
        let methods = await client.requestedMethods()
        await service.disconnect()

        #expect(ended, "a stopped Codex Turn went on reporting Running")
        // The Turn ends where the abort says it did, not where this app noticed.
        #expect(
            stopped.sessions.first?.finishedAt
                == Date(timeIntervalSince1970: timestamp + 8)
        )
        // A stopped Turn has no last word, so the preview stays the prompt.
        #expect(stopped.sessions.first?.preview == "Rewrite the panel contour.")
        // Nothing about this reading asks the App Server for Turn detail.
        #expect(!methods.contains("thread/turns/list"))
        for params in await client.recordedThreadReadParams() {
            #expect(params["includeTurns"]?.boolValue == false)
        }
    }

    /// A stopped Turn's subagents stop counting for it: the stop kills the
    /// `collaborationwait_agent` (no `PostToolUse`) while the subagent runs on, so the Completed
    /// row read as Running (2026-08-29, CLI `0.151.0-alpha.7.1`).
    @Test @MainActor
    func aStoppedTurnsSubagentsStopCountingForIt() async throws {
        let paths = makeTemporaryHookPaths()
        defer {
            try? FileManager.default.removeItem(
                at: paths.supportDirectory.deletingLastPathComponent()
            )
        }
        let root = FileManager.default.temporaryDirectory
            .appendingPathComponent(UUID().uuidString, isDirectory: true)
        defer { try? FileManager.default.removeItem(at: root) }
        try FileManager.default.createDirectory(
            at: root,
            withIntermediateDirectories: true
        )

        let installer = CodexHookRegistrar(paths: paths)
        let repository = HookEventRepository(paths: paths)
        try await installer.install()

        let timestamp = Date().timeIntervalSince1970.rounded(.down)
        let rollout = root.appendingPathComponent("rollout-thread-1.jsonl")
        let stamp = ISO8601DateFormatter()
        stamp.formatOptions = [.withInternetDateTime, .withFractionalSeconds]
        let turnContext: [String: Any] = [
            "timestamp": stamp.string(
                from: Date(timeIntervalSince1970: timestamp - 0.065)
            ),
            "type": "turn_context",
            "payload": ["turn_id": "turn-1", "approvals_reviewer": "user"]
        ]
        func writeRollout(_ objects: [[String: Any]]) throws {
            let lines = try objects.map {
                String(
                    decoding: try JSONSerialization.data(withJSONObject: $0),
                    as: UTF8.self
                )
            }
            try Data(lines.joined(separator: "\n").appending("\n").utf8)
                .write(to: rollout, options: .atomic)
        }
        try writeRollout([turnContext])

        func deliver(_ event: [String: Any]) throws {
            try JSONSerialization.data(withJSONObject: event)
                .deliver(to: repository)
        }
        // The measured shape: the spawn closes, the wait does not, the subagent starts.
        try deliver([
            "received_at": timestamp, "hook_event_name": "UserPromptSubmit",
            "session_id": "thread-1", "turn_id": "turn-1",
            "prompt": "Spawn one subagent and wait for it."
        ])
        try deliver([
            "received_at": timestamp + 1, "hook_event_name": "PreToolUse",
            "session_id": "thread-1", "turn_id": "turn-1",
            "tool_name": "collaborationspawn_agent", "tool_use_id": "spawn-1"
        ])
        try deliver([
            "received_at": timestamp + 2, "hook_event_name": "PostToolUse",
            "session_id": "thread-1", "turn_id": "turn-1",
            "tool_name": "collaborationspawn_agent", "tool_use_id": "spawn-1"
        ])
        try deliver([
            "received_at": timestamp + 3, "hook_event_name": "PreToolUse",
            "session_id": "thread-1", "turn_id": "turn-1",
            "tool_name": "collaborationwait_agent", "tool_use_id": "wait-1"
        ])
        try deliver([
            "received_at": timestamp + 4, "hook_event_name": "SubagentStart",
            "session_id": "thread-1", "turn_id": "sub-turn", "agent_id": "agent-1"
        ])
        // It also waits on its own dialogue, which must not survive the stop.
        try deliver([
            "received_at": timestamp + 5, "hook_event_name": "PreToolUse",
            "session_id": "thread-1", "turn_id": "sub-turn", "agent_id": "agent-1",
            "tool_name": "Bash", "tool_use_id": "sub-call-1"
        ])
        try deliver([
            "received_at": timestamp + 6, "hook_event_name": "PermissionRequest",
            "session_id": "thread-1", "turn_id": "sub-turn", "agent_id": "agent-1",
            "tool_name": "Bash"
        ])

        let client = CodexAppServerStub(
            listedThreads: [
                codexRootThread(
                    id: "thread-1",
                    name: "Spawner",
                    path: rollout.path
                )
            ],
            loadedListResults: []
        )
        let service = LiveCodexMonitorService(
            client: client,
            hookEvents: repository,
            hookRegistrar: installer,
            desktopProcessIdentifierProvider: { 4_242 }
        )

        let running = await snapshotWithSessions(from: service)
        #expect(running.sessions.first?.runningSubagentCount == 1)
        #expect(running.sessions.first?.subagentsAwaitingApprovalCount == 1)

        try writeRollout([turnContext, [
            "timestamp": stamp.string(
                from: Date(timeIntervalSince1970: timestamp + 8)
            ),
            "type": "event_msg",
            "payload": [
                "type": "turn_aborted", "turn_id": "turn-1",
                "reason": "interrupted"
            ]
        ]])

        var stopped = await service.fetchSnapshot()
        let ended = await holds {
            stopped = await service.fetchSnapshot()
            return stopped.sessions.first?.status == .completed
        }
        #expect(ended)
        let row = try #require(stopped.sessions.first)
        #expect(row.runningSubagentCount == 0)
        #expect(row.subagentsAwaitingApprovalCount == 0)
        #expect(MonitorAggregation.effectiveStatus(of: row) == .completed)

        // The subagent's later stop names an agent no longer counted, and changes nothing.
        try deliver([
            "received_at": timestamp + 40, "hook_event_name": "SubagentStop",
            "session_id": "thread-1", "turn_id": "sub-turn", "agent_id": "agent-1"
        ])
        let after = await service.fetchSnapshot()
        await service.disconnect()
        #expect(after.sessions.first?.status == .completed)
        #expect(after.sessions.first?.runningSubagentCount == 0)
    }

    /// A Turn ending on its own `Stop` keeps its subagents: the thread will collect their work.
    /// Only a stop orphans them.
    @Test @MainActor
    func aTurnThatEndsOnItsOwnStopKeepsItsSubagents() async throws {
        let paths = makeTemporaryHookPaths()
        defer {
            try? FileManager.default.removeItem(
                at: paths.supportDirectory.deletingLastPathComponent()
            )
        }
        let repository = HookEventRepository(paths: paths)
        let timestamp = Date().timeIntervalSince1970
        func deliver(_ event: [String: Any]) throws {
            try JSONSerialization.data(withJSONObject: event)
                .deliver(to: repository)
        }
        try deliver([
            "received_at": timestamp, "hook_event_name": "UserPromptSubmit",
            "session_id": "thread-1", "turn_id": "turn-1"
        ])
        try deliver([
            "received_at": timestamp + 1, "hook_event_name": "SubagentStart",
            "session_id": "thread-1", "turn_id": "sub-turn", "agent_id": "agent-1"
        ])
        try deliver([
            "received_at": timestamp + 2, "hook_event_name": "Stop",
            "session_id": "thread-1", "turn_id": "turn-1",
            "last_assistant_message": "Started one and left it running."
        ])
        let afterStop = await repository.drainDeliveredEvents()
        #expect(afterStop.turns.first?.sessionStatus == .completed)
        #expect(afterStop.turns.first?.runningSubagentIDs == ["agent-1"])

        // The identity-free reading says nobody works on the turn; that does not orphan them.
        let afterSessionStop = await repository.endTurnsForStoppedSessions(
            ["thread-1": Date(timeIntervalSince1970: timestamp + 3)]
        )
        #expect(afterSessionStop.turns.first?.runningSubagentIDs == ["agent-1"])

        // Claude Code's interrupt claims no orphans (its subagents send `SubagentStop`).
        let afterPlainInterrupt = await repository.endInterruptedTurns([
            TurnInterruption(
                threadID: "thread-1",
                turnID: "turn-1",
                endedAt: Date(timeIntervalSince1970: timestamp + 4)
            )
        ])
        #expect(afterPlainInterrupt.turns.first?.runningSubagentIDs == ["agent-1"])
    }

