    @Test @MainActor
    func liveStopTransitionsDirectlyFromRunningToCompleted() async throws {
        let paths = makeTemporaryHookPaths()
        defer {
            try? FileManager.default.removeItem(
                at: paths.supportDirectory.deletingLastPathComponent()
            )
        }

        let installer = CodexHookRegistrar(paths: paths)
        let repository = HookEventRepository(paths: paths)
        try await installer.install()
        let prompt = try JSONSerialization.data(withJSONObject: [
            "received_at": Date().timeIntervalSince1970,
            "hook_event_name": "UserPromptSubmit",
            "session_id": "thread-terminal",
            "turn_id": "turn-terminal"
        ])
        prompt.deliver(to: repository)

        let listedThread = JSONValue.object([
            "id": .string("thread-terminal"),
            "ephemeral": .bool(false),
            "threadSource": .string("user"),
            "updatedAt": .number(Date().timeIntervalSince1970),
            "status": .object([
                "type": .string("active"),
                "activeFlags": .array([])
            ]),
            "turns": .array([
                .object([
                    "id": .string("turn-terminal"),
                    "status": .string("inProgress")
                ])
            ])
        ])
        let client = CodexAppServerStub(
            listedThreads: [listedThread],
            loadedListResults: []
        )
        let unreadState = DesktopUnreadStateStub(
            unreadThreadIDs: ["thread-terminal"]
        )
        let service = LiveCodexMonitorService(
            client: client,
            hookEvents: repository,
            hookRegistrar: installer,
            unreadState: unreadState,
            desktopProcessIdentifierProvider: { 4_242 }
        )

        let initial = await snapshotWithSessions(from: service)
        #expect(initial.sessions.first?.status == .running)
        await waitForThreadListRequests(
            client,
            atLeast: 1,
            completed: true
        )

        let stop = try JSONSerialization.data(withJSONObject: [
            "received_at": Date().timeIntervalSince1970,
            "hook_event_name": "Stop",
            "session_id": "thread-terminal",
            "turn_id": "turn-terminal"
        ])
        stop.deliver(to: repository)

        var observedStatuses: [SessionStatus] = []
        for _ in 0..<100 {
            let snapshot = await service.fetchSnapshot()
            if let status = snapshot.sessions.first?.status {
                observedStatuses.append(status)
            }
            if observedStatuses.last == .completed {
                break
            }
            try await Task.sleep(nanoseconds: 10_000_000)
        }
        await unreadState.setUnread([])
        let afterRead = await service.fetchSnapshot()
        await service.disconnect()

        #expect(observedStatuses.first == .completed)
        #expect(observedStatuses.last == .completed)
        #expect(afterRead.sessions.isEmpty)
        // Terminal status comes from the Hook reducer alone; no read is issued for an ended turn.
        for params in await client.recordedTurnItemsParams() {
            #expect(params["turnId"]?.stringValue == "turn-terminal")
        }
        // Exactly one; see `aTurnsProgressIsReadOnceWhileTheReadIsStillInFlight`.
        #expect(await client.requestCount(method: "thread/items/list") == 1)
        for params in await client.recordedThreadReadParams() {
            #expect(params["includeTurns"]?.boolValue == false)
        }
    }

    /// A progress read is asked once, even by refreshes re-entrant across its actor hop: the
    /// held record is only written on the response. The answer is held open here on purpose.
    @Test @MainActor
    func aTurnsProgressIsReadOnceWhileTheReadIsStillInFlight() async throws {
        let paths = makeTemporaryHookPaths()
        defer {
            try? FileManager.default.removeItem(
                at: paths.supportDirectory.deletingLastPathComponent()
            )
        }
        let installer = CodexHookRegistrar(paths: paths)
        let repository = HookEventRepository(paths: paths)
        try await installer.install()

        deliverHook([
            "hook_event_name": "UserPromptSubmit",
            "session_id": "thread-inflight",
            "turn_id": "turn-inflight",
            "prompt": "Pin the flake."
        ], to: repository)

        let listedThread = JSONValue.object([
            "id": .string("thread-inflight"),
            "ephemeral": .bool(false),
            "threadSource": .string("user"),
            "updatedAt": .number(Date().timeIntervalSince1970),
            "status": .object([
                "type": .string("active"),
                "activeFlags": .array([])
            ])
        ])
        let client = CodexAppServerStub(
            listedThreads: [listedThread],
            loadedListResults: [],
            supportsTurnItems: true,
            turnItemsByTurnID: [
                "turn-inflight": [
                    agentMessageEntry(turn: "turn-inflight", text: "Reading the reducer.")
                ]
            ]
        )
        // Long enough for the refreshes below to land inside the one read.
        await client.setTurnItemsDelayNanoseconds(300_000_000)
        let service = LiveCodexMonitorService(
            client: client,
            hookEvents: repository,
            hookRegistrar: installer,
            desktopProcessIdentifierProvider: { 4_242 }
        )
        defer { Task { await service.disconnect() } }

        _ = await snapshotWithSessions(from: service)
        let issued = await holds {
            await client.requestCount(method: "thread/items/list") >= 1
        }
        #expect(issued, "the running turn's progress was never read")

        for _ in 0..<10 {
            _ = await service.fetchSnapshot()
            try await Task.sleep(nanoseconds: 10_000_000)
        }
        #expect(await client.requestCount(method: "thread/items/list") == 1)

        // After the answer, the held record covers the unchanged stamp.
        let said = await holds {
            await service.fetchSnapshot().sessions.first?.preview
                == "Reading the reducer."
        }
        #expect(said, "the row never showed what the turn was saying")
        _ = await service.fetchSnapshot()
        #expect(await client.requestCount(method: "thread/items/list") == 1)
    }

    /// The same for `thread/read`, whose ``ThreadRecord`` is written on the answer. `thread/list`
    /// is held open too: on a fast list its bulk record write hides the re-queue.
    @Test @MainActor
    func aThreadsMetadataIsReadOnceWhileTheReadIsStillInFlight() async throws {
        let paths = makeTemporaryHookPaths()
        defer {
            try? FileManager.default.removeItem(
                at: paths.supportDirectory.deletingLastPathComponent()
            )
        }
        let installer = CodexHookRegistrar(paths: paths)
        let repository = HookEventRepository(paths: paths)
        try await installer.install()

        deliverHook([
            "hook_event_name": "UserPromptSubmit",
            "session_id": "thread-metadata",
            "turn_id": "turn-metadata",
            "prompt": "Close the other one."
        ], to: repository)

        let client = CodexAppServerStub(
            listedThreads: [
                codexRootThread(
                    id: "thread-metadata",
                    name: "Closing the metadata hole"
                )
            ],
            loadedListResults: [],
            threadListDelayNanoseconds: 600_000_000
        )
        await client.setThreadReadDelayNanoseconds(300_000_000)
        let service = LiveCodexMonitorService(
            client: client,
            hookEvents: repository,
            hookRegistrar: installer,
            desktopProcessIdentifierProvider: { 4_242 }
        )
        defer { Task { await service.disconnect() } }

        _ = await snapshotWithSessions(from: service)
        let issued = await holds {
            await client.requestCount(method: "thread/read") >= 1
        }
        #expect(issued, "the hook's thread was never read")

        for _ in 0..<10 {
            _ = await service.fetchSnapshot()
            try await Task.sleep(nanoseconds: 10_000_000)
        }

        // Counted after the answer lands: a mid-flight question dispatches only when the run ends.
        let answered = await holds {
            await client.completedThreadReadRequestCount() >= 1
        }
        #expect(answered, "the metadata read never answered")
        for _ in 0..<5 {
            _ = await service.fetchSnapshot()
            try await Task.sleep(nanoseconds: 10_000_000)
        }
        #expect(await client.requestCount(method: "thread/read") == 1)
        #expect(
            await service.fetchSnapshot().sessions.first?.title
                == "Closing the metadata hole"
        )
    }

    /// A build without `thread/read` is probed once, not once per thread: a thread queued behind
    /// the probe must not go out once the refusal is recorded.
    @Test @MainActor
    func aBuildWithoutThreadReadIsProbedOnceNotOncePerThread() async throws {
        let paths = makeTemporaryHookPaths()
