    /// Registration health is recomputed when it can change (this app writing the file, a
    /// recheck, the registrar's FSEvents edge), not on a cadence.
    @Test @MainActor
    func registrationHealthIsRecomputedWhenItCanChangeRatherThanOnACadence() async throws {
        let paths = makeTemporaryHookPaths()
        defer {
            try? FileManager.default.removeItem(
                at: paths.supportDirectory.deletingLastPathComponent()
            )
        }
        let registrar = CodexHookRegistrar(paths: paths)
        try await registrar.install()
        #expect(await registrar.registration() == .complete)

        var configuration = try #require(
            JSONSerialization.jsonObject(
                with: try Data(contentsOf: paths.hooksConfiguration)
            ) as? [String: Any]
        )
        var hooks = try #require(configuration["hooks"] as? [String: Any])
        hooks.removeValue(forKey: "Stop")
        configuration["hooks"] = hooks
        try JSONSerialization.data(withJSONObject: configuration)
            .write(to: paths.hooksConfiguration)

        // Recheck reports the damage as mismatched, not absent: the rest is still ours.
        await registrar.invalidateRegistration()
        #expect(await registrar.registration() == .mismatched)

        // Writing the file drops the reading.
        try await registrar.install()
        #expect(await registrar.registration() == .complete)
    }

    /// The first reading after an outside edit is the edited one by construction, not scheduling
    /// (CR-028). Defeat the change-count comparison and this fails every time.
    @Test @MainActor
    func theFirstRegistrationReadingAfterAnOutsideEditIsTheEditedOne() async throws {
        let paths = makeTemporaryHookPaths()
        defer {
            try? FileManager.default.removeItem(
                at: paths.supportDirectory.deletingLastPathComponent()
            )
        }
        let registrar = CodexHookRegistrar(paths: paths)
        try await registrar.install()
        #expect(await registrar.registration() == .complete)

        var configuration = try #require(
            JSONSerialization.jsonObject(
                with: try Data(contentsOf: paths.hooksConfiguration)
            ) as? [String: Any]
        )
        var hooks = try #require(configuration["hooks"] as? [String: Any])
        hooks.removeValue(forKey: "Stop")
        configuration["hooks"] = hooks
        let damaged = try JSONSerialization.data(withJSONObject: configuration)
        let hooksConfiguration = paths.hooksConfiguration

        // Repeat an in-place edit until the watcher reports it.
        let observed = await receivesChange(registrar.changeEvents()) {
            try damaged.write(to: hooksConfiguration)
        }
        #expect(observed)

        // No `invalidateRegistration()`: the edge alone is under test.
        #expect(await registrar.registration() == .mismatched)
    }

