        )

        // Nothing read yet, so nothing scheduled: a quiet monitor falls through to the heartbeat.
        #expect(await service.nextRefreshDeadline() == nil)

        _ = await service.fetchSnapshot()
        await waitForThreadReads(client, atLeast: 1)

        // With metadata cached, the next wake is its staleness boundary, before the membership
        // window.
        let deadline = try #require(await service.nextRefreshDeadline())
        let untilDeadline = deadline.timeIntervalSince(clock.now())
        #expect(untilDeadline <= timing.threadMetadataRefreshInterval)
        #expect(untilDeadline < timing.heartbeatInterval)
        await service.disconnect()
    }


    private static func labelLayer(
        named name: String,
        in view: NSView
    ) throws -> CALayer {
        let sublayers = try #require(view.layer?.sublayers)
        return try #require(sublayers.first { $0.name == name })
    }



    private static func alphaExtremes(
        of image: CGImage
    ) throws -> (minimum: Double, maximum: Double) {
        let width = image.width
        let height = image.height
        var pixels = [UInt8](repeating: 0, count: width * height * 4)
        let drew = pixels.withUnsafeMutableBytes { buffer -> Bool in
            guard let context = CGContext(
                data: buffer.baseAddress,
                width: width,
                height: height,
                bitsPerComponent: 8,
                bytesPerRow: width * 4,
                space: CGColorSpaceCreateDeviceRGB(),
                bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue
            ) else {
                return false
            }
            context.draw(
                image,
                in: CGRect(x: 0, y: 0, width: width, height: height)
            )
            return true
        }
        try #require(drew)

        let alphas = stride(from: 3, to: pixels.count, by: 4).map {
            Double(pixels[$0]) / 255
        }
        return (alphas.min() ?? 1, alphas.max() ?? 0)
    }

    @Test @MainActor
    func sessionRowTextFadesItsOverflowThroughCoreAnimation() throws {
        // The row owns its trailing fade; a hard clip is silent, so it is asserted on the layer.
        let font = NSFont.systemFont(ofSize: 13, weight: .light)
        let text = "A preview long enough to run past the row it is drawn in"
        let view = SessionRowTextView()
        view.apply(
            text: text,
            font: font,
            color: NotchPalette.labelDrawingColor,
            sweeps: false
        )

        let glyphWidth = view.intrinsicContentSize.width
        let rowWidth = glyphWidth / 2
        view.frame = NSRect(x: 0, y: 0, width: rowWidth, height: 18)
        view.layout()

        let root = try #require(view.layer)
        let sublayers = try #require(root.sublayers)
        // Dim and bright copies; the bright one stays hidden on a still row, so a state change
        // costs a flag, not a texture upload.
        #expect(sublayers.count == 2)
        #expect(try #require(sublayers.last).isHidden)

        // Only the visible width is drawn: no texture upload for pixels never composited.
        let glyphs = try #require(sublayers.first)
        #expect(glyphs.frame.width == rowWidth)
        #expect(glyphs.frame.width < glyphWidth)
        let contents = try #require(glyphs.contents)
        let image = unsafeDowncast(contents as AnyObject, to: CGImage.self)
        let alphas = try Self.alphaExtremes(of: image)
        #expect(alphas.minimum == 0)
        #expect(alphas.maximum > 0.5)

        let fade = try #require(root.mask as? CAGradientLayer)
        #expect(fade.frame.width == rowWidth)
        let locations = try #require(fade.locations)
        #expect(locations.count == 3)
        let fadeStart = try #require(locations.dropFirst().first).doubleValue
        #expect(fadeStart > 0)
        #expect(fadeStart < 1)
    }

    /// The body line sweeps while its turn is unfinished (`figma-design.md` page 14), on the
    /// render server (`system-architecture.md` §6); the band is bounded to the row, not glyphs.
    @Test @MainActor
    func sessionRowTextSweepsOnlyWhileItsTurnIsUnfinished() throws {
        let font = NSFont.systemFont(ofSize: 13, weight: .light)
        let text = "A preview long enough to run past the row it is drawn in"
        let view = SessionRowTextView()
        view.apply(
            text: text,
            font: font,
            color: NotchPalette.labelDrawingColor,
            sweeps: true
        )
        let rowWidth = view.intrinsicContentSize.width / 2
        view.frame = NSRect(x: 0, y: 0, width: rowWidth, height: 18)
        view.layout()

        let root = try #require(view.layer)
        let sublayers = try #require(root.sublayers)
        let highlight = try #require(sublayers.last)
        #expect(!highlight.isHidden)
        // Drawn in the searchlight white, whatever the dim copy underneath is.
        let bright = try Self.alphaExtremes(
            of: unsafeDowncast(try #require(highlight.contents) as AnyObject, to: CGImage.self)
        )
        #expect(bright.maximum > 0.5)

        // The band crosses the row, not the string.
        let band = try #require(highlight.mask as? CAGradientLayer)
        #expect(band.frame.width == rowWidth * 4)
        let sweep = try #require(
            band.animation(forKey: NotchTextRaster.sweepAnimationKey)
        )
        #expect(sweep.repeatCount == .infinity)
        #expect(sweep.duration == SessionRowTextView.sweepPeriod)
        // Phase follows the clock, not installation: text replaced more often than the 40% the peak
        // takes to arrive would never show the highlight.
        #expect(sweep.beginTime > 0)

        view.apply(
            text: text,
            font: font,
            color: NotchPalette.labelDrawingColor,
            sweeps: false
        )
        #expect(highlight.isHidden)
        #expect(band.animation(forKey: NotchTextRaster.sweepAnimationKey) == nil)
    }

    @Test @MainActor
    func elapsedTicksDoNotRepublishTheStore() async throws {
        // A store publish re-evaluates the whole overlay (~20ms; ~4% of a core on an approval), so a
        // second passing must not publish: readouts take the tick directly.
        let clock = TestClock()
        let store = makeIdleStore(clock: clock)
        let startedAt = clock.now()
        store.applyForTesting(
            makeSessionSnapshot([
                makeSession(status: .approvalNeeded, startedAt: startedAt)
            ]),
            observedAt: clock.now()
        )
        await clock.settle()

        var publishes = 0
        let subscription = store.objectWillChange.sink { _ in publishes += 1 }
        defer { subscription.cancel() }

        // 0:01 through 0:09 are all four characters: new readings, no new width.
        await clock.advance(by: 9)
        #expect(store.compactTimerText == "0:09")
        #expect(
            publishes == 0,
            "a tick republished the store \(publishes) time(s)"
        )

        // 10:00 changes the reserved width, so exactly here a publish is expected.
        await clock.advance(by: 591)
        #expect(store.compactTimerText == "10:00")
        #expect(publishes > 0, "a width change must reach the panel")
    }

    @Test @MainActor
    func refreshLoopNeverSpinsOnAnOverdueDeadline() async throws {
        // Without a floor an overdue deadline sleeps zero and runs full snapshots continuously
        // (measured 63% of a core, main thread in a synchronous LaunchServices round trip).
        let clock = TestClock()
        let timing = MonitorTiming.standard
        let service = StuckDeadlineMonitoringStub(
            deadline: clock.now().addingTimeInterval(-5)
        )
        let store = MonitorStore(
            displays: [
                makeDisplay(
                    id: "display-1",
                    ordinal: 1,
                    menuBarHeight: 38,
                    hasNotch: true
                )
            ],
            services: [service],
            initialSnapshot: .connecting,
            clock: clock,
            timing: timing
        )

        for _ in 0 ..< 8 {
            await clock.advance(by: timing.minimumRefreshInterval)
        }

        let requested = clock.requestedSleepIntervals
        #expect(!requested.isEmpty)
        #expect(requested.allSatisfy { $0 >= timing.minimumRefreshInterval })
        #expect(await service.snapshotCount() <= 10)
        store.stopMonitoring()
    }

    @Test @MainActor
    func refreshDeadlineNeverFallsIntoThePast() async throws {
        // The store sleeps `max(0, deadline - now)`, so a deadline that never advances is a busy loop.
        let paths = makeTemporaryHookPaths()
        defer {
            try? FileManager.default.removeItem(
                at: paths.supportDirectory.deletingLastPathComponent()
            )
        }
        let installer = CodexHookRegistrar(paths: paths)
        let clock = TestClock()
        let timing = MonitorTiming.standard
        let repository = HookEventRepository(
            paths: paths,
            clock: clock,
            timing: timing
        )
        try await installer.install()
        try JSONSerialization.data(withJSONObject: [
            "received_at": Date().timeIntervalSince1970,
            "hook_event_name": "UserPromptSubmit",
            "session_id": "thread-hooked",
            "turn_id": "turn-hooked"
        ]).deliver(to: repository)

        // Only `thread-hooked` is driven by a Hook; `thread-idle` is an ordinary unarchived thread.
        let client = CodexAppServerStub(
            listedThreads: [
                .object([
                    "id": .string("thread-hooked"),
                    "ephemeral": .bool(false),
                    "threadSource": .string("user"),
                    "name": .string("Hooked")
                ]),
                .object([
                    "id": .string("thread-idle"),
                    "ephemeral": .bool(false),
                    "threadSource": .string("user"),
                    "name": .string("Idle")
                ])
            ],
            loadedListResults: []
        )
        let service = LiveCodexMonitorService(
            client: client,
            hookEvents: repository,
            hookRegistrar: installer,
            clock: clock,
            timing: timing,
            desktopProcessIdentifierProvider: { 4_242 }
        )

        _ = await service.fetchSnapshot()
        await waitForThreadListRequests(client, atLeast: 1, completed: true)
        await waitForThreadReads(client, atLeast: 1)

        // Past the per-thread metadata window, still inside the membership one.
        await clock.advance(by: timing.threadMetadataRefreshInterval + 1)
        _ = await service.fetchSnapshot()
        await waitForThreadReads(client, atLeast: 2)

        let deadline = try #require(await service.nextRefreshDeadline())
        #expect(deadline >= clock.now())
        await service.disconnect()
    }

    @Test @MainActor
    func backgroundReadsHonourTheirOwnFreshnessWindows() async throws {
        let paths = makeTemporaryHookPaths()
        defer {
            try? FileManager.default.removeItem(
                at: paths.supportDirectory.deletingLastPathComponent()
            )
        }
        let installer = CodexHookRegistrar(paths: paths)
        let clock = TestClock()
        let timing = MonitorTiming.standard
        let repository = HookEventRepository(
            paths: paths,
            clock: clock,
            timing: timing
        )
        try await installer.install()

        var eventIndex = 0
        func emitHookActivity() throws {
            eventIndex += 1
            let event: [String: Any] = [
                "received_at": clock.now().timeIntervalSince1970,
                "hook_event_name": eventIndex == 1 ? "UserPromptSubmit" : "PostToolUse",
                "session_id": "thread-window",
                "turn_id": "turn-window",
                "tool_name": "Bash",
                "tool_use_id": "exec-\(eventIndex)"
            ]
            try JSONSerialization.data(withJSONObject: event).deliver(to: repository)
        }

        let client = CodexAppServerStub(
            listedThreads: [.object([
                "id": .string("thread-window"),
                "ephemeral": .bool(false),
                "threadSource": .string("user"),
                "name": .string("Windowed")
            ])],
            loadedListResults: []
        )
        let service = LiveCodexMonitorService(
            client: client,
            hookEvents: repository,
            hookRegistrar: installer,
            clock: clock,
            timing: timing,
            desktopProcessIdentifierProvider: { 4_242 }
        )

        try emitHookActivity()
        _ = await service.fetchSnapshot()
        await waitForThreadListRequests(client, atLeast: 1, completed: true)
        await waitForThreadReads(client, atLeast: 1)
        #expect(await client.requestCount(method: "thread/list") == 1)
        #expect(await client.requestCount(method: "thread/read") == 1)

        await clock.advance(by: timing.threadMetadataRefreshInterval - 1)
        try emitHookActivity()
        _ = await service.fetchSnapshot()
        await clock.settle()
        #expect(await client.requestCount(method: "thread/read") == 1)
        #expect(await client.requestCount(method: "thread/list") == 1)

        // Past the metadata window only: the cheap read repeats, membership pagination does not.
        await clock.advance(by: 2)
        try emitHookActivity()
        _ = await service.fetchSnapshot()
        await waitForThreadReads(client, atLeast: 2)
        #expect(await client.requestCount(method: "thread/list") == 1)

        await clock.advance(by: timing.threadListRefreshInterval)
        try emitHookActivity()
        _ = await service.fetchSnapshot()
        await waitForThreadListRequests(client, atLeast: 2, completed: true)
        #expect(await client.requestCount(method: "thread/list") == 2)

        await service.disconnect()
    }

    @Test @MainActor
    func hookActivityReadsOnlyItsOwnThreadsInsteadOfTheWholeList() async throws {
        let paths = makeTemporaryHookPaths()
        defer {
            try? FileManager.default.removeItem(
                at: paths.supportDirectory.deletingLastPathComponent()
            )
        }

        let installer = CodexHookRegistrar(paths: paths)
        let repository = HookEventRepository(paths: paths)
        try await installer.install()
        let prompt = try JSONSerialization.data(withJSONObject: [
            "received_at": Date().timeIntervalSince1970,
            "hook_event_name": "UserPromptSubmit",
            "session_id": "thread-active",
            "turn_id": "turn-active"
        ])
        prompt.deliver(to: repository)

        // One thread is in the Hook reducer; the rest are only history.
        let listedThreads = (0 ..< 40).map { index -> JSONValue in
            .object([
                "id": .string(index == 0 ? "thread-active" : "thread-\(index)"),
                "ephemeral": .bool(false),
                "threadSource": .string("user"),
                "name": .string(index == 0 ? "Active work" : "History \(index)"),
                "status": .object([
                    "type": .string("active"),
                    "activeFlags": .array([])
                ])
            ])
        }
        let client = CodexAppServerStub(
            listedThreads: listedThreads,
            loadedListResults: []
        )
        let service = LiveCodexMonitorService(
            client: client,
            hookEvents: repository,
            hookRegistrar: installer,
            desktopProcessIdentifierProvider: { 4_242 }
        )

        _ = await service.fetchSnapshot()
        await waitForThreadListRequests(client, atLeast: 1, completed: true)

        // Membership was just reconciled, so none of these rounds may re-paginate the full list.
        for index in 1 ... 6 {
            let event = try JSONSerialization.data(withJSONObject: [
                "received_at": Date().timeIntervalSince1970,
                "hook_event_name": "PostToolUse",
                "session_id": "thread-active",
                "turn_id": "turn-active",
                "tool_name": "shell",
                "tool_use_id": "tool-\(index)"
            ])
            event.deliver(to: repository)
            _ = await service.fetchSnapshot()
            try await Task.sleep(nanoseconds: 20_000_000)
        }

        let snapshot = await service.fetchSnapshot()
        let threadListCount = await client.requestCount(method: "thread/list")
        let readParams = await client.recordedThreadReadParams()
        await service.disconnect()

        #expect(threadListCount == 1)
        #expect(!readParams.isEmpty)
        for params in readParams {
            #expect(params["threadId"]?.stringValue == "thread-active")
            #expect(params["includeTurns"]?.boolValue == false)
        }
        #expect(snapshot.sessions.first?.title == "Active work")
    }

