    /// A server that ignores `SIGTERM` is killed, not left running: otherwise every transport
    /// reset leaves a live `codex` process (CR-Fable-014). The child also outlives its stdin.
    @Test @MainActor
    func anAppServerThatIgnoresSIGTERMIsKilled() async throws {
        let root = FileManager.default.temporaryDirectory
            .appendingPathComponent("NotchlineAppServerTests-\(UUID().uuidString)")
        defer { try? FileManager.default.removeItem(at: root) }
        try FileManager.default.createDirectory(
            at: root,
            withIntermediateDirectories: true
        )

        let executable = root.appendingPathComponent("wedged_app_server.py")
        let pidFile = root.appendingPathComponent("pid")
        let source = #"""
#!/usr/bin/python3
import json
import os
import signal
import sys
import time

signal.signal(signal.SIGTERM, signal.SIG_IGN)

with open(PID_FILE, "w") as handle:
    handle.write(str(os.getpid()))

request = json.loads(sys.stdin.readline())
print(json.dumps({"id": request["id"], "result": {}}), flush=True)

# Outlives stdin closing, so only a signal can end this.
while True:
    time.sleep(0.05)
"""#.replacingOccurrences(
            of: "PID_FILE",
            with: "\"\(pidFile.path)\""
        )
        try source.write(to: executable, atomically: true, encoding: .utf8)
        try FileManager.default.setAttributes(
            [.posixPermissions: 0o700],
            ofItemAtPath: executable.path
        )

        let clock = TestClock()
        let killGrace: TimeInterval = 2
        let client = CodexAppServerClient(
            executableURL: executable,
            killGraceNanoseconds: UInt64(killGrace * 1_000_000_000),
            clock: clock
        )
        try await client.connect()

        let pid = try #require(
            pid_t(
                String(contentsOf: pidFile, encoding: .utf8)
                    .trimmingCharacters(in: .whitespacesAndNewlines)
            )
        )
        #expect(processIsAlive(pid))

        await client.disconnect()
        await clock.settle()

        // Asserted before the grace expires, so the kill below cannot be credited to the signal.
        #expect(processIsAlive(pid))
        #expect(clock.requestedSleepIntervals.contains(killGrace))

        await clock.advance(by: killGrace)

        #expect(await processDies(pid, within: 5))
    }

