        defer { try? FileManager.default.removeItem(at: root) }

        let first = root.appendingPathComponent("1.json")
        let second = root.appendingPathComponent("2.json")
        try Data(#"{"status":"busy"}"#.utf8).write(to: first)
        try Data(#"{"status":"busy"}"#.utf8).write(to: second)

        let watcher = ClaudeCodeSessionRecordWatcher(directory: root, debounceInterval: 0.05)
        #expect(watcher.recordURL(forProcessIdentifier: 1) == first)

        watcher.watch(processIdentifiers: [1, 2])
        #expect(watcher.watchedCount == 2)

        // In place: same path, same inode, no rename.
        // Written once, not via ``receivesChange(_:whileRepeating:)``: the stages share a watcher, and
        // a repeated write's trailing debounce could answer the silence assertion about `first`.
        try Data(#"{"status":"idle"}"#.utf8).write(to: second)
        #expect(await receivesChange(watcher.events()))

        // Dropped, then silent. The budget is short because every green run spends all of it.
        watcher.watch(processIdentifiers: [2])
        #expect(watcher.watchedCount == 1)
        let afterDrop = watcher.events()
        try Data(#"{"status":"idle"}"#.utf8).write(to: first)
        #expect(await receivesChange(afterDrop, within: .seconds(1)) == false)

        try Data(#"{"status":"busy"}"#.utf8).write(to: second)
        #expect(await receivesChange(watcher.events()))

        watcher.watch(processIdentifiers: [])
        #expect(watcher.watchedCount == 0)
    }

    @Test
    func watcherReattachesAfterItsDirectoryIsDeletedAndRecreated() async throws {
        let root = makeTemporaryWatchRoot()
        defer { try? FileManager.default.removeItem(at: root) }
        let directory = root.appendingPathComponent("events")
        try FileManager.default.createDirectory(
            at: directory,
            withIntermediateDirectories: true
        )

        let watcher = DirectoryChangeWatcher(
            directoryURL: directory,
            debounceInterval: 0.05
        )
        #expect(watcher.isAttached)
        let stream = watcher.events()
        let beforeUninstall = directory.appendingPathComponent("a.json")
        #expect(
            await receivesChange(stream) {
                try Data("{}".utf8).write(to: beforeUninstall)
            }
        )

        // The descriptor now refers to an inode nothing will write to again.
        try FileManager.default.removeItem(at: directory)
        try await Task.sleep(nanoseconds: 300_000_000)

        try FileManager.default.createDirectory(
            at: directory,
            withIntermediateDirectories: true
        )
        #expect(watcher.attachIfNeeded())

        let secondStream = watcher.events()
        let afterReinstall = directory.appendingPathComponent("b.json")
        #expect(
            await receivesChange(secondStream) {
                try Data("{}".utf8).write(to: afterReinstall)
            }
        )
    }

