            hookEvents: repository,
            hookRegistrar: CodexHookRegistrar(paths: paths),
            desktopProcessIdentifierProvider: { 4_242 }
        )
        defer { Task { await service.disconnect() } }

        // Install creates the socket's directory and writes the helper.
