    /// Codex keys trust by content hash under
    /// `[hooks.state."<hooks.json path>:<event>:<group>:<handler>"]`; a changed definition silently
    /// stops executing until re-trusted in `/hooks` (measured 2026-08-15). One definition changed
    /// deliberately (`AGENTS.md` §5.2); the rest must stay byte-identical. Definitions carry no
    /// version, port or token, and the helper's wait argument is a word, not seconds.
    @Test @MainActor
    func onlyTheAnsweringDefinitionEverChangedAndTheRestAreByteIdentical() async throws {
        let paths = makeTemporaryHookPaths()
        defer { try? FileManager.default.removeItem(at: paths.supportDirectory.deletingLastPathComponent()) }

        let registrar = CodexHookRegistrar(paths: paths)
        try await registrar.install()

        let root = try #require(
            JSONSerialization.jsonObject(
                with: try Data(contentsOf: paths.hooksConfiguration)
            ) as? [String: Any]
        )
        let hooks = try #require(root["hooks"] as? [String: Any])
        let command = "/bin/sh '\(paths.hookHelper.path)'"
        // The bytes every lifecycle definition has carried since ADR 0013.
        let lifecycle: [String: Any] = [
            "type": "command",
            "command": command,
            "timeout": 3
        ]
        // The one that changed, frozen in this shape.
        let answering: [String: Any] = [
            "type": "command",
            "command": "\(command) wait",
            "timeout": 3600
        ]

        var definitionsCarryingAnArgument = 0
        for definition in CodexHookVocabulary().managedDefinitions {
            let groups = try #require(hooks[definition.event] as? [[String: Any]])
            let group = try #require(groups.last)
            // Unmatched: a matcher miss would silently hide a wait.
            #expect(group["matcher"] == nil)
            let handlers = try #require(group["hooks"] as? [[String: Any]])
            #expect(handlers.count == 1)
            let expected = definition.argument == nil ? lifecycle : answering
            #expect((handlers[0] as NSDictionary) == (expected as NSDictionary))
            if definition.argument != nil { definitionsCarryingAnArgument += 1 }
        }
        // One waiting event only: `PreToolUse` fires for every tool call.
        #expect(definitionsCarryingAnArgument == 1)

        // Rewriting the helper, how this app ships a change, leaves the registration byte-identical.
        let before = try Data(contentsOf: paths.hooksConfiguration)
        try Data("#!/bin/sh\n# something else entirely\n".utf8)
            .write(to: paths.hookHelper)
        #expect(await registrar.prepareHelper())
        #expect(try Data(contentsOf: paths.hooksConfiguration) == before)
    }

    /// Codex silently stops executing a changed definition until `/hooks` trusts it again, and the
    /// app cannot read trust, so it remembers writing it; one arriving event is the only proof.
    /// The trust key names the event, so only that definition needs re-trusting.
    @Test @MainActor
    func aRewrittenDefinitionIsRememberedUntilItFiresAgain() async throws {
        let paths = makeTemporaryHookPaths()
        defer { try? FileManager.default.removeItem(at: paths.supportDirectory.deletingLastPathComponent()) }

        // What a previous version wrote: `PermissionRequest` in the lifecycle shape too.
        let helper = "/bin/sh '\(paths.hookHelper.path)'"
        let previous: [String: Any] = [
            "hooks": Dictionary(
                uniqueKeysWithValues: CodexHookVocabulary().managedDefinitions.map {
                    (
                        $0.event,
                        [["hooks": [[
                            "type": "command", "command": helper, "timeout": 3
                        ]]]]
                    )
                }
            )
        ]
        try FileManager.default.createDirectory(
            at: paths.hooksConfiguration.deletingLastPathComponent(),
            withIntermediateDirectories: true
        )
        try JSONSerialization.data(withJSONObject: previous)
            .write(to: paths.hooksConfiguration)

        let registrar = CodexHookRegistrar(paths: paths)
        try await registrar.install()

        #expect(
            HookInstallStateFile.read(at: paths.installState).eventsAwaitingTrust
                == ["PermissionRequest"]
        )

        // Said only once hooks are demonstrably firing: a Codex not run since the upgrade is no fault.
        let repository = HookEventRepository(paths: paths)
        #expect(await repository.observedState().diagnostic == nil)

        try JSONSerialization.data(withJSONObject: [
            "hook_event_name": "UserPromptSubmit",
            "session_id": "thread-1",
            "prompt_id": "turn-1"
        ]).deliver(to: repository)
        let whileUntrusted = await repository.drainDeliveredEvents()
        let sentence = try #require(whileUntrusted.diagnostic)
        #expect(sentence.contains("PermissionRequest"))
        #expect(sentence.contains(CodexHookVocabulary().restoreDefinitionAdvice))
        // And an event on another definition is not evidence about this one.
        #expect(
            HookInstallStateFile.read(at: paths.installState).eventsAwaitingTrust
                == ["PermissionRequest"]
        )

        try JSONSerialization.data(withJSONObject: [
            "hook_event_name": "PermissionRequest",
            "session_id": "thread-1",
            "prompt_id": "turn-1",
            "tool_name": "shell"
        ]).deliver(to: repository)
        #expect(await repository.drainDeliveredEvents().diagnostic == nil)
        #expect(
            HookInstallStateFile.read(at: paths.installState).eventsAwaitingTrust == nil
        )
    }

    /// The helper's `-w` expires before the registered `timeout`: a helper the product kills is a
    /// hook error printed in the user's session (ADR 0013).
    @Test @MainActor
    func theHelperGivesUpInsideTheWindowTheDefinitionRegisters() throws {
        let vocabularies: [any AgentHookVocabulary] = [
            CodexHookVocabulary(), ClaudeCodeHookVocabulary()
        ]
        for vocabulary in vocabularies {
            let answering = vocabulary.managedDefinitions
                .filter { $0.argument != nil }
            // `PermissionRequest`, not `PreToolUse`: on Claude Code an `AskUserQuestion` raises both, and
            // this app holds the second.
            #expect(answering.count == 1)
            #expect(answering.first?.event == "PermissionRequest")
            #expect(answering.first?.argument == AgentHookHelper.answeringArgument)
            #expect(vocabulary.answerWindowSeconds < vocabulary.answeringTimeoutSeconds)
            #expect(
                answering.first?.timeoutSeconds == vocabulary.answeringTimeoutSeconds
            )
            // A wedged app still costs one second on the 99.8% of events nobody is asked about.
            for definition in vocabulary.managedDefinitions
            where definition.argument == nil {
                #expect(definition.timeoutSeconds == 3)
            }
        }
    }

    /// Stdout (the reply channel ADR 0013 closed) is opened per call only; stderr is always
    /// discarded, and `exit 0` is unconditional because `nc` exits 1 when nothing is listening.
    @Test @MainActor
    func theHelperOpensTheReplyChannelOnlyOnTheEventThatAsks() throws {
        let script = AgentHookHelper.script(
            socketPath: "/tmp/x/hook.sock",
            answerWindowSeconds: 3540
        )
        #expect(script.contains("/usr/bin/nc -U -w 3540 '/tmp/x/hook.sock'\n"))
        #expect(script.contains("/usr/bin/nc -U -w 1 '/tmp/x/hook.sock' >/dev/null"))
        #expect(script.contains("exec 2>/dev/null"))
        #expect(!script.contains("exec >/dev/null 2>&1"))
        // Read before the payload, so a nested agent costs one `sh` and no connection.
        #expect(
            script.contains("if [ -n \"${\(AgentHookHelper.suppressionEnvironmentKey):-}\" ]; then")
        )
        #expect(script.contains("if [ \"${1:-}\" = \(AgentHookHelper.answeringArgument) ]; then"))
        // Never `exec`: `nc` exits 1 whenever this app is closed.
        #expect(!script.contains("exec /usr/bin/nc"))
        #expect(script.hasSuffix("exit 0\n"))
    }

    @Test @MainActor
    func registrationAndDeliveryProjectToTheFourCards() async throws {
        #expect(
            IntegrationSetupStatus.card(registration: .absent, hasObservedEvent: false)
                == .notInstalled
        )
        #expect(
            IntegrationSetupStatus.card(registration: .absent, hasObservedEvent: true)
                == .notInstalled
        )
        // Mismatched whatever was delivered: some of ours firing is why the rest failing is invisible.
        #expect(
            IntegrationSetupStatus.card(registration: .mismatched, hasObservedEvent: false)
                == .repairRequired
        )
        #expect(
            IntegrationSetupStatus.card(registration: .mismatched, hasObservedEvent: true)
                == .repairRequired
        )
        #expect(
            IntegrationSetupStatus.card(registration: .complete, hasObservedEvent: false)
                == .reviewRequired
        )
        #expect(
            IntegrationSetupStatus.card(registration: .complete, hasObservedEvent: true)
                == .active
        )
        #expect(IntegrationSetupStatus.reviewRequired.isIntegrationEnabled)
        #expect(IntegrationSetupStatus.active.isIntegrationEnabled)
        #expect(!IntegrationSetupStatus.repairRequired.isIntegrationEnabled)
        #expect(!IntegrationSetupStatus.notInstalled.isIntegrationEnabled)

        let paths = makeTemporaryHookPaths()
        defer { try? FileManager.default.removeItem(at: paths.supportDirectory.deletingLastPathComponent()) }
        let registrar = CodexHookRegistrar(paths: paths)
        #expect(await registrar.registration() == .absent)
        try await registrar.install()

        let fresh = HookEventRepository(paths: paths)
        #expect(IntegrationSetupStatus.card(
            registration: await registrar.registration(),
            hasObservedEvent: await fresh.observedState().hasObservedEvent
        ) == .reviewRequired)

        deliverHook([
            "received_at": Date().timeIntervalSince1970,
            "hook_event_name": "UserPromptSubmit",
            "session_id": "t", "turn_id": "u"
        ], to: fresh)
        _ = await fresh.drainDeliveredEvents()

        let restarted = HookEventRepository(paths: paths)
        #expect(IntegrationSetupStatus.card(
            registration: await registrar.registration(),
            hasObservedEvent: await restarted.observedState().hasObservedEvent
        ) == .active)
    }

    /// Accepted in arrival order onto one serial read queue. Claude Code's `async` key reordered
    /// `PreToolUse`/`PostToolUse` (ADR 0013); `Task`s spawned in order need not run in order, so
    /// the inbox is taken whole.
    @Test @MainActor
    func payloadsAreReducedInTheOrderTheyLanded() async throws {
        let root = URL(fileURLWithPath: "/tmp")
            .appendingPathComponent("cin-order-\(UUID().uuidString.prefix(8))")
        defer { try? FileManager.default.removeItem(at: root) }
        let paths = HookIntegrationPaths(
            supportDirectory: root.appendingPathComponent("AS"),
            hooksConfiguration: root.appendingPathComponent(".codex/hooks.json")
        )
        let repository = HookEventRepository(paths: paths)
        let listener = AgentHookListener { body, receivedAt, descriptor in
            repository.deliver(body, at: receivedAt, on: descriptor)
        }
        defer { listener.stop() }
        #expect(listener.start(socketURL: paths.hookSocket))

        // The approval borrows the open call's id, so a reordering changes the final state.
        for body in [
            ["hook_event_name": "UserPromptSubmit", "session_id": "s", "turn_id": "t"],
            [
                "hook_event_name": "PreToolUse", "session_id": "s", "turn_id": "t",
                "tool_name": "Bash", "tool_use_id": "call-1"
            ],
            [
                "hook_event_name": "PermissionRequest", "session_id": "s",
                "turn_id": "t", "tool_name": "Bash"
            ]
        ] as [[String: Any]] {
            try send(to: paths.hookSocket, body: body)
        }

        var turns = await waitForReducedTurns(repository, count: 1)
        // A reordering leaves the turn Running for good.
        let paired = await holds {
            turns = await repository.drainDeliveredEvents().turns
            return turns.first?.status == .approvalNeeded
        }
        #expect(paired)
        #expect(turns.first?.pendingApproval?.toolUseID == "call-1")
        #expect(turns.first?.pendingApproval?.isInferred == true)

        repository.deliver(
            try JSONSerialization.data(withJSONObject: [
                "hook_event_name": "UserPromptSubmit",
                "session_id": "s", "turn_id": "t-earlier"
            ]),
            at: Date(timeIntervalSince1970: 1)
        )
        turns = (await repository.drainDeliveredEvents()).turns
        #expect(turns.first?.turnID == "t")
        #expect(turns.first?.status == .approvalNeeded)
    }

    /// Measured 2026-08-22, Codex Desktop / CLI `0.149.0-alpha.4.1`: a `spawn_agent` subagent
    /// finished 91 seconds after the main turn. Its hooks carry the **parent's** `session_id` and
    /// the **subagent's own** `turn_id`; adopting that turn id left the row *Running* for good.
    @Test @MainActor
    func aSubagentOutlivingItsTurnLeavesTheRowFinishedAndStillWorking() async throws {
        let paths = makeTemporaryHookPaths()
        defer { try? FileManager.default.removeItem(at: paths.supportDirectory.deletingLastPathComponent()) }
        let repository = HookEventRepository(paths: paths)

        let parent = "01a02d08-bace"
        let parentTurn = "01a02d0d-4be5"
        let subagentTurn = "01a02d0d-e72c"
        var clock = Date(timeIntervalSince1970: 0)
        func send(_ body: [String: Any], after seconds: TimeInterval) async {
            clock = clock.addingTimeInterval(seconds)
            repository.deliver(
                try! JSONSerialization.data(withJSONObject: body),
                at: clock
            )
            _ = await repository.drainDeliveredEvents()
        }

        await send([
            "hook_event_name": "UserPromptSubmit", "session_id": parent,
            "turn_id": parentTurn, "prompt": "draft the PRD"
        ], after: 1)

        // The spawn returns immediately (no `agent_id`); its close proves only the spawn was accepted.
        await send([
            "hook_event_name": "PreToolUse", "session_id": parent,
            "turn_id": parentTurn, "tool_name": "spawn_agent",
            "tool_use_id": "call-spawn"
        ], after: 1)
        await send([
            "hook_event_name": "PostToolUse", "session_id": parent,
            "turn_id": parentTurn, "tool_name": "spawn_agent",
            "tool_use_id": "call-spawn"
        ], after: 1)
        await send([
            "hook_event_name": "SubagentStart", "session_id": parent,
            "turn_id": parentTurn, "agent_id": "agent-1",
            "agent_type": "tikzcd_syntax_audit"
        ], after: 1)

        // The subagent's own work, under the parent's session and its own turn.
        for id in ["call-a", "call-b"] {
            await send([
                "hook_event_name": "PreToolUse", "session_id": parent,
                "turn_id": subagentTurn, "agent_id": "agent-1",
                "tool_name": "shell", "tool_use_id": id
            ], after: 1)
            await send([
                "hook_event_name": "PostToolUse", "session_id": parent,
                "turn_id": subagentTurn, "agent_id": "agent-1",
                "tool_name": "shell", "tool_use_id": id
            ], after: 1)
        }

        var turns = await repository.observedState().turns
        #expect(turns.first?.turnID == parentTurn)
        #expect(turns.first?.status == .running)

        await send([
            "hook_event_name": "Stop", "session_id": parent,
            "turn_id": parentTurn,
            "last_assistant_message": "Seven decisions to confirm."
        ], after: 1)

        turns = await repository.observedState().turns
        var turn = try #require(turns.first)
        #expect(turn.turnID == parentTurn)
        #expect(turn.status == .completed)
        #expect(turn.assistantPreview == "Seven decisions to confirm.")
        #expect(turn.runningSubagentIDs == ["agent-1"])

        var session = try #require(CodexSnapshotParser.session(
            from: turn, thread: codexRootThread(id: parent), projectName: "tikzcd-editor"
        ))
        #expect(session.status == .completed)
        #expect(session.showsSubagentBadge)
        #expect(session.subagentBadge == SubagentBadge(count: 1))

        // The subagent's terminal is `SubagentStop`; `Stop` carries no `agent_id`.
        await send([
            "hook_event_name": "SubagentStop", "session_id": parent,
            "turn_id": subagentTurn, "agent_id": "agent-1",
            "last_assistant_message": "Audit complete."
        ], after: 91)

        turn = try #require(await repository.observedState().turns.first)
        #expect(turn.runningSubagentIDs.isEmpty)
        #expect(turn.assistantPreview == "Seven decisions to confirm.")
        session = try #require(CodexSnapshotParser.session(
            from: turn, thread: codexRootThread(id: parent), projectName: "tikzcd-editor"
        ))
        #expect(session.status == .completed)
        #expect(!session.showsSubagentBadge)
    }

    /// The row's one mark is the elapsed readout (PRD §10); a subagent count shows only once the
    /// turn's clock has stopped. The reducer keeps the set either way.
    @Test @MainActor
    func aRunningRowKeepsTheTimerAsItsOnlyMark() async throws {
        let paths = makeTemporaryHookPaths()
        defer { try? FileManager.default.removeItem(at: paths.supportDirectory.deletingLastPathComponent()) }
        let repository = HookEventRepository(paths: paths)

        var clock = Date(timeIntervalSince1970: 0)
        func send(_ body: [String: Any]) async {
            clock = clock.addingTimeInterval(1)
            repository.deliver(
                try! JSONSerialization.data(withJSONObject: body),
                at: clock
            )
            _ = await repository.drainDeliveredEvents()
        }

        await send([
            "hook_event_name": "UserPromptSubmit", "session_id": "s", "turn_id": "t"
        ])
        await send([
            "hook_event_name": "SubagentStart", "session_id": "s",
            "turn_id": "t", "agent_id": "a1"
        ])
        await send([
            "hook_event_name": "SubagentStart", "session_id": "s",
            "turn_id": "t", "agent_id": "a2"
        ])

        var turn = try #require(await repository.observedState().turns.first)
        #expect(turn.runningSubagentIDs == ["a1", "a2"])
        var session = try #require(CodexSnapshotParser.session(
            from: turn, thread: codexRootThread(id: "s"), projectName: "P"
        ))
        #expect(session.status == .running)
        #expect(session.runningSubagentCount == 2)
        #expect(!session.showsSubagentBadge)

        await send([
            "hook_event_name": "Stop", "session_id": "s", "turn_id": "t"
        ])
        turn = try #require(await repository.observedState().turns.first)
        session = try #require(CodexSnapshotParser.session(
            from: turn, thread: codexRootThread(id: "s"), projectName: "P"
        ))
        #expect(session.showsSubagentBadge)
        #expect(session.subagentBadge == SubagentBadge(count: 2))

        await send([
            "hook_event_name": "UserPromptSubmit", "session_id": "s", "turn_id": "t2"
        ])
