    /// Darwin `accept` passes the listener's non-blocking flag to the connection, so a client that
    /// connected but had not written read as `EAGAIN` and was dropped (CC-023, CC-024). Repeated:
    /// the listener abandons a stalled client after 250 ms, which a 100 ms pause can overshoot.
    @Test
    func aPayloadWrittenAfterTheConnectionIsAcceptedStillArrives() async throws {
        let root = URL(fileURLWithPath: "/tmp")
            .appendingPathComponent("cin-late-\(UUID().uuidString.prefix(8))")
        try FileManager.default.createDirectory(
            at: root,
            withIntermediateDirectories: true
        )
        defer { try? FileManager.default.removeItem(at: root) }

        let recorder = RecordedHookDelivery()
        let listener = AgentHookListener(deliver: recorder.deliver)
        defer { listener.stop() }
        let socket = root.appendingPathComponent("hook.sock")
        #expect(listener.start(socketURL: socket))

        var arrived = false
        var attempt = 0
        while !arrived, attempt < 5 {
            try sendRaw(
                to: socket,
                bytes: try JSONSerialization.data(withJSONObject: [
                    "hook_event_name": "Stop",
                    "session_id": "late-\(attempt)"
                ]),
                writingAfter: 0.1
            )
            arrived = await holds(within: .seconds(1)) {
                recorder.sessions.contains("late-\(attempt)")
            }
            attempt += 1
        }
        #expect(arrived)
    }

    /// Holds nothing, so a timing assertion starts with no sleepers on the clock.
    @MainActor
    private func makeIdleStore(clock: TestClock) -> MonitorStore {
        MonitorStore(
            displays: [
                makeDisplay(id: "notched", ordinal: 1, menuBarHeight: 46, hasNotch: true)
            ],
            initialSnapshot: makeSessionSnapshot([]),
            clock: clock
        )
    }

    /// `figma-design.md` page 14: measured between the turn's own two stamps.
    @Test @MainActor
    func aFinishedRowDrawsTheLengthOfTheTurnItRan() async {
        let clock = TestClock(now: Date(timeIntervalSince1970: 1_000))
        let store = makeIdleStore(clock: clock)
        let started = Date(timeIntervalSince1970: 1_000)
        let finished = started.addingTimeInterval(83)

        let done = MonitoredSession(
            threadID: "t",
            turnID: "u",
            projectName: RowContentFallback.projectName,
            title: "Done",
            preview: nil,
            status: .completed,
            startedAt: started,
            finishedAt: finished
        )
        #expect(store.finishedElapsedText(for: done) == "1:23")
        #expect(store.spokenFinishedElapsedText(for: done) == "1 minute 23 seconds")
        await clock.advance(by: 600)
        #expect(store.finishedElapsedText(for: done) == "1:23")

        // A running turn's live reading is `elapsedText`.
        let running = MonitoredSession(
            threadID: "t",
            turnID: "u",
            projectName: RowContentFallback.projectName,
            title: "Running",
            preview: nil,
            status: .running,
            startedAt: started,
            finishedAt: nil
        )
        #expect(store.finishedElapsedText(for: running) == nil)

        // Nor a finished turn whose end was never observed: no duration is invented.
        let unobserved = MonitoredSession(
            threadID: "t",
            turnID: "u",
            projectName: RowContentFallback.projectName,
            title: "Done",
            preview: nil,
            status: .completed,
            startedAt: started,
            finishedAt: nil
        )
        #expect(store.finishedElapsedText(for: unobserved) == nil)
        #expect(
            store.finishedElapsedText(
                for: makeSession(status: .completed, startedAt: nil)
            ) == nil
        )
    }

    /// A finished turn does not sweep even while its subagents work; the badge speaks for them.
    @Test @MainActor
    func onlyAnUnfinishedTurnSweepsItsBody() {
        let store = makeIdleStore(clock: TestClock(now: Date()))
        let started = Date()
        for status in [SessionStatus.running, .inputNeeded, .approvalNeeded] {
            #expect(store.sweepsBody(for: makeSession(status: status, startedAt: started)))
        }
        #expect(!store.sweepsBody(for: makeSession(status: .completed, startedAt: started)))

        let finishedWithSubagents = makeSession(
            status: .completed,
            startedAt: started,
            runningSubagentCount: 2
        )
        #expect(!store.sweepsBody(for: finishedWithSubagents))
        #expect(finishedWithSubagents.showsSubagentBadge)
    }

    private func makeSession(
        agent: AgentKind = .codex,
        threadID: String = "thread",
        status: SessionStatus,
        startedAt: Date?,
        runningSubagentCount: Int = 0,
        subagentsAwaitingApproval: Bool = false
    ) -> MonitoredSession {
        MonitoredSession(
            agent: agent,
            threadID: threadID,
            turnID: "turn-\(threadID)",
            projectName: RowContentFallback.projectName,
            title: "Timed turn",
            preview: nil,
            status: status,
            startedAt: startedAt,
            runningSubagentCount: runningSubagentCount,
            // Keeps the Bool surface call sites want, as one blocked subagent.
            subagentsAwaitingApprovalCount: subagentsAwaitingApproval ? 1 : 0
        )
    }

    private func makeSessionSnapshot(
        _ sessions: [MonitoredSession]
    ) -> AgentSnapshot {
        AgentSnapshot(
            availability: .ready,
            sessions: sessions,
            quota: .unavailable,
            diagnostic: nil
        )
    }

    // MARK: - Overlay concealment

    /// Window-server coordinates: origin at the top-left of the global space, y growing downward.
    private static let builtInDisplay = CGRect(x: 0, y: 0, width: 1_800, height: 1_169)
    /// Above and to the right, so a test matching on origin cannot pass on size alone.
    private static let externalDisplay = CGRect(x: 1_800, y: -721, width: 3_360, height: 1_890)

    /// Only for building the Dock windows the predicate must ignore.
    private static let dockOwner = "Dock"
    private static let dockLayer = Int(CGWindowLevelForKey(.dockWindow))

    /// `slidBy` moves the bar along x only: Space transitions are a horizontal strip.
    private static func menuBar(
        of display: CGRect,
        slidBy offset: CGFloat = 0
    ) -> ChromeWindow {
        ChromeWindow(
            owner: OverlayConcealment.windowServerOwner,
            layer: OverlayConcealment.menuBarLayer,
            bounds: CGRect(
                x: display.minX + offset,
                y: display.minY,
                width: display.width,
                height: 39
            )
        )
    }

    private static func dockBacking(of display: CGRect) -> ChromeWindow {
        ChromeWindow(
            owner: Self.dockOwner,
            layer: Self.dockLayer,
            bounds: display
        )
    }

    /// Mission Control's cover: Dock-owned, display-sized, level 18 (measured; no
    /// `CGWindowLevelKey` name).
    private static func missionControlCover(of display: CGRect) -> ChromeWindow {
        ChromeWindow(
            owner: Self.dockOwner,
            layer: Self.dockLayer - 2,
            bounds: display
        )
    }

    /// A full-screen window takes the menu bar window off the on-screen list; that is the only signal.
    @Test
    func overlayFollowsTheMenuBarOfItsOwnDisplay() {
        let builtIn = Self.builtInDisplay
        let external = Self.externalDisplay
        let resting = [
            Self.menuBar(of: builtIn),
            Self.menuBar(of: external),
            Self.dockBacking(of: builtIn)
        ]

        #expect(
            OverlayConcealment.menuBarPresence(
                onDisplay: builtIn,
                windows: resting
            ) == .drawn
        )
        #expect(
            OverlayConcealment.menuBarPresence(
                onDisplay: external,
                windows: resting
            ) == .drawn
        )

        // Full screen on the external display hides only that display's menu bar.
        let externalFullScreen = resting.filter { $0 != Self.menuBar(of: external) }
        #expect(
            OverlayConcealment.menuBarPresence(
                onDisplay: external,
                windows: externalFullScreen
            ) == .away
        )
        #expect(
            OverlayConcealment.menuBarPresence(
                onDisplay: builtIn,
                windows: externalFullScreen
            ) == .drawn
        )
    }

    /// A Space switch slides the bar sideways, same top edge and width, for the transition (as long
    /// as a swipe is held); that is not concealment.
    @Test
    func aSlidingMenuBarIsASpaceSwitchAndNotAConcealment() {
        let builtIn = Self.builtInDisplay

        for offset in [-26.0, -1_800, -1_864, 1_864] as [CGFloat] {
            #expect(
                OverlayConcealment.menuBarPresence(
                    onDisplay: builtIn,
                    windows: [Self.menuBar(of: builtIn, slidBy: offset)]
                ) == .sliding
            )
        }

        // A bar at the origin answers, whatever else is still leaving.
        #expect(
            OverlayConcealment.menuBarPresence(
                onDisplay: builtIn,
                windows: [
                    Self.menuBar(of: builtIn, slidBy: 1_864),
                    Self.menuBar(of: builtIn)
                ]
            ) == .drawn
        )
    }

    /// Identical side-by-side displays share top edge and width; reading the neighbour's bar as this
    /// one mid-slide would leave the overlay over a full-screen film forever.
    @Test
    func aNeighbouringDisplaysRestingMenuBarIsNotThisDisplaySliding() {
        let left = CGRect(x: 0, y: 0, width: 1_800, height: 1_169)
        let right = CGRect(x: 1_800, y: 0, width: 1_800, height: 1_169)
        let displays = [left, right]

        // The right display's bar has the left's width and top edge, and is the only bar listed.
        #expect(
            OverlayConcealment.menuBarPresence(
                onDisplay: left,
                windows: [Self.menuBar(of: right)],
                otherDisplays: displays
            ) == .away
        )

        // Without the display list they cannot be told apart, so the watcher always passes it.
        #expect(
            OverlayConcealment.menuBarPresence(
                onDisplay: left,
                windows: [Self.menuBar(of: right)]
            ) == .sliding
        )

        // Mid-switch: the bar is between the two origins and belongs to neither.
        #expect(
            OverlayConcealment.menuBarPresence(
                onDisplay: left,
                windows: [
                    Self.menuBar(of: left, slidBy: 900),
                    Self.menuBar(of: right)
                ],
                otherDisplays: displays
            ) == .sliding
        )
    }

    /// The Dock's display-sized Mission Control cover is visible but deliberately not consulted;
    /// only the menu bar, still drawn under it, is.
    @Test
    func missionControlLeavesTheOverlayOnScreen() {
        let builtIn = Self.builtInDisplay
        let external = Self.externalDisplay
        let missionControl = [
            Self.menuBar(of: builtIn),
            Self.menuBar(of: external),
            Self.dockBacking(of: builtIn),
            Self.missionControlCover(of: builtIn),
            Self.missionControlCover(of: external)
        ]

        #expect(
            OverlayConcealment.menuBarPresence(
                onDisplay: builtIn,
                windows: missionControl
            ) == .drawn
        )
        #expect(
            OverlayConcealment.menuBarPresence(
                onDisplay: external,
                windows: missionControl
            ) == .drawn
        )

        // From a full-screen app the menu bar is still gone; the cover changes nothing.
        #expect(
            OverlayConcealment.menuBarPresence(
                onDisplay: external,
                windows: missionControl.filter { $0 != Self.menuBar(of: external) }
            ) == .away
        )
    }

    @Test
    func concealmentIgnoresOtherDisplaysMenuBars() {
        let builtIn = Self.builtInDisplay
        let external = Self.externalDisplay

        #expect(
            OverlayConcealment.menuBarPresence(
                onDisplay: builtIn,
                windows: [Self.menuBar(of: builtIn), Self.dockBacking(of: builtIn)]
            ) == .drawn
        )

        // A different width and top edge: not a candidate, not even sliding.
        #expect(
            OverlayConcealment.menuBarPresence(
                onDisplay: builtIn,
                windows: [Self.menuBar(of: external)]
            ) == .away
        )
    }

    /// Fail open: a lingering overlay is a blemish, a missing one cannot be asked back because the
    /// notch is the way in.
    @Test
    func anUnplaceableDisplayLeavesTheOverlayAlone() {
        #expect(
            OverlayConcealment.menuBarPresence(onDisplay: .zero, windows: [])
                == .drawn
        )
        #expect(
            OverlayConcealment.menuBarPresence(
                onDisplay: CGRect(x: 0, y: 0, width: 0, height: 1_169),
                windows: []
            ) == .drawn
        )
    }

    /// Reporting every sample would drive a window order 4 times a second (`AGENTS.md` §7).
    @Test @MainActor
    func theConcealmentWatcherReportsOnlyChanges() {
        let display = Self.builtInDisplay
        let displayID = CGDirectDisplayID(7)
        nonisolated(unsafe) var listed: [ChromeWindow] = [Self.menuBar(of: display)]

        let screen = StubScreenAvailability()
        let watcher = OverlayConcealmentWatcher(
            // Only the samples the test asks for; a live timer would measure the suite's load.
            interval: 3_600,
            sampleWindows: { listed },
            boundsOfDisplay: { id in id == displayID ? display : .zero },
            boundsOfActiveDisplays: { [display] },
            // Never the machine's own: the result would depend on whether the screen was locked.
            screenAvailability: screen
        )

        var reported: [Bool] = []
        watcher.observe(displayID: displayID)
        watcher.start { reported.append($0) }
        #expect(reported == [false])

        watcher.sampleNow()
        watcher.sampleNow()
        #expect(reported == [false])

        listed = []
        watcher.sampleNow()
        watcher.sampleNow()
        #expect(reported == [false, true])

        listed = [Self.menuBar(of: display)]
        watcher.sampleNow()
        #expect(reported == [false, true, false])

        // Mission Control opening is not an edge.
        listed = [Self.menuBar(of: display), Self.missionControlCover(of: display)]
        watcher.sampleNow()
        #expect(reported == [false, true, false])

        watcher.stop()
    }

    /// A sliding menu bar is not an answer, so a switch makes zero reports and the overlay does not
    /// blink out and back.
    @Test @MainActor
    func switchingDesktopsIsNotAnEdge() {
        let display = Self.builtInDisplay
        let displayID = CGDirectDisplayID(7)
        nonisolated(unsafe) var listed: [ChromeWindow] = [Self.menuBar(of: display)]

        let screen = StubScreenAvailability()
        let watcher = OverlayConcealmentWatcher(
            interval: 3_600,
            sampleWindows: { listed },
            boundsOfDisplay: { _ in display },
            boundsOfActiveDisplays: { [display] },
            screenAvailability: screen
        )

        var reported: [Bool] = []
        watcher.observe(displayID: displayID)
        watcher.start { reported.append($0) }
        #expect(reported == [false])

        for offset in [-26.0, -700, -1_864] as [CGFloat] {
            listed = [Self.menuBar(of: display, slidBy: offset)]
            watcher.sampleNow()
        }
        #expect(reported == [false])

        listed = [Self.menuBar(of: display)]
        watcher.sampleNow()
        #expect(reported == [false])
        #expect(!watcher.isConcealed)

        // A slide ending with no menu bar still conceals, on the first sample after the transition.
        listed = [Self.menuBar(of: display, slidBy: -900)]
        watcher.sampleNow()
        #expect(reported == [false])

        listed = []
        watcher.sampleNow()
        #expect(reported == [false, true])

        watcher.stop()
    }

