    /// The timer reads windows on its own queue, so its reading can land after the immediate sample
    /// a display move takes and answer for a screen the overlay has left.
    @Test @MainActor
    func aSampleOvertakenOnItsWayBackIsDiscarded() {
        let display = Self.builtInDisplay
        let displayID = CGDirectDisplayID(7)
        nonisolated(unsafe) var listed: [ChromeWindow] = [Self.menuBar(of: display)]

        let screen = StubScreenAvailability()
        let watcher = OverlayConcealmentWatcher(
            interval: 3_600,
            sampleWindows: { listed },
            boundsOfDisplay: { _ in display },
            boundsOfActiveDisplays: { [display] },
            screenAvailability: screen
        )

        var reported: [Bool] = []
        watcher.observe(displayID: displayID)
        watcher.start { reported.append($0) }
        #expect(reported == [false])

        // The stale reading must not be the last word.
        let stale = watcher.takeTicket()
        let staleWindows = listed

        listed = []
        watcher.sampleNow()
        #expect(reported == [false, true])

        watcher.deliver(staleWindows, ticket: stale)
        #expect(reported == [false, true])
        #expect(watcher.isConcealed)

        watcher.stop()
    }

    /// Otherwise the overlay vanished until the app was killed: the timer judged off-actor and
    /// applied after a hop, while ``OverlayConcealmentWatcher/sampleNow()`` (wake edge, display
    /// change) judged and applied inline first; the older verdict then won against a
    /// `lastReported` that had moved on.
    @Test @MainActor
    func aVerdictOvertakenBeforeItIsAppliedIsDiscarded() {
        let display = Self.builtInDisplay
        let displayID = CGDirectDisplayID(7)
        nonisolated(unsafe) var listed: [ChromeWindow] = [Self.menuBar(of: display)]

        let screen = StubScreenAvailability()
        let watcher = OverlayConcealmentWatcher(
            interval: 3_600,
            sampleWindows: { listed },
            boundsOfDisplay: { _ in display },
            boundsOfActiveDisplays: { [display] },
            screenAvailability: screen
        )

        watcher.observe(displayID: displayID)
        watcher.start { _ in }
        #expect(!watcher.isConcealed)

        // The timer's verdict for a missing menu bar; its hop has not run yet.
        let inFlightTicket = watcher.takeTicket()
        let inFlight = watcher.verdict(for: [], ticket: inFlightTicket)
        #expect(inFlight == true)

        // The wake edge samples and applies on the main actor before the hop lands.
        listed = [Self.menuBar(of: display)]
        watcher.sampleNow()
        #expect(!watcher.isConcealed)

        watcher.apply(inFlight ?? false, ticket: inFlightTicket)
        #expect(!watcher.isConcealed)

        // The watcher agrees with itself, so a later sample has nothing to correct.
        watcher.sampleNow()
        #expect(!watcher.isConcealed)

        watcher.stop()
    }

    /// Parking is fail-open: an unseen menu bar conceals nothing, and a hidden overlay has no Dock
    /// tile, menu bar item or window to bring it back.
    @Test @MainActor
    func parkingForWantOfAScreenPutsTheOverlayBack() async {
        let display = Self.builtInDisplay
        let displayID = CGDirectDisplayID(7)
        nonisolated(unsafe) var listed: [ChromeWindow] = [Self.menuBar(of: display)]

        let screen = StubScreenAvailability()
        let watcher = OverlayConcealmentWatcher(
            interval: 0.02,
            sampleWindows: { listed },
            boundsOfDisplay: { _ in display },
            boundsOfActiveDisplays: { [display] },
            screenAvailability: screen
        )

        watcher.observe(displayID: displayID)
        watcher.start { _ in }

        listed = []
        watcher.sampleNow()
        #expect(watcher.isConcealed)

        // Display asleep or session locked; the timer's own reading parks it.
        screen.available = false
        #expect(await holds { !watcher.isConcealed })

        // The verdict was forgotten, so waking into the same full-screen app is reported.
        screen.available = true
        screen.announce()
        #expect(await holds { watcher.isConcealed })

        watcher.stop()
    }

    /// Two of ``ScreenAvailabilityWatcher``'s five edges are distributed notifications and one
    /// arrives while still locked, so a parked watcher keeps a heartbeat: one missed edge must not
    /// end concealment for the process.
    @Test @MainActor
    func aParkedWatcherRearmsWithoutBeingTold() async {
        let display = Self.builtInDisplay
        let displayID = CGDirectDisplayID(7)
        let samples = CallCounter()
        let screen = StubScreenAvailability()
        screen.available = false

        let watcher = OverlayConcealmentWatcher(
            interval: 0.02,
            parkedInterval: 0.05,
            sampleWindows: {
                samples.record()
                return [Self.menuBar(of: display)]
            },
            boundsOfDisplay: { _ in display },
            boundsOfActiveDisplays: { [display] },
            screenAvailability: screen
        )

        watcher.observe(displayID: displayID)
        watcher.start { _ in }
        let atStart = samples.count

        // The screen comes back and *no* notification says so.
        screen.available = true
        #expect(await holds { samples.count > atStart })

        watcher.stop()
    }

    /// `screensDidWake` arrives while still locked and `loginwindow` announces unlock outside the
    /// session dictionary, so an edge arms the timer unconditionally; early costs one tick.
    @Test @MainActor
    func aWakeEdgeArmsTheTimerWithoutConsultingTheReading() async {
        let display = Self.builtInDisplay
        let displayID = CGDirectDisplayID(7)
        let samples = CallCounter()
        let screen = StubScreenAvailability()
        screen.available = false

        let watcher = OverlayConcealmentWatcher(
            interval: 0.02,
            // Long enough that the heartbeat cannot rescue this.
            parkedInterval: 3_600,
            sampleWindows: {
                samples.record()
                return [Self.menuBar(of: display)]
            },
            boundsOfDisplay: { _ in display },
            boundsOfActiveDisplays: { [display] },
            screenAvailability: screen
        )

        watcher.observe(displayID: displayID)
        watcher.start { _ in }
        let atStart = samples.count

        // Announced while the session dictionary still says locked; it agrees one reading later.
        screen.becomesAvailableAfterOneReading = true
        screen.announce()

        // Polled, not slept: a third sample proves the timer is running.
        #expect(await holds { samples.count > atStart + 2 })

        watcher.stop()
    }

    /// A sampled Release app spent 41% of its CPU here, four times a second, with no display awake.
    /// Wake re-arms *and* samples: the windows can differ after sleep.
    @Test @MainActor
    func theConcealmentTimerIsParkedWhileThereIsNoScreen() async {
        let display = Self.builtInDisplay
        let displayID = CGDirectDisplayID(7)
        let samples = CallCounter()
        let screen = StubScreenAvailability()
        screen.available = false

        let watcher = OverlayConcealmentWatcher(
            // Fifteen ticks fit in each wait below, so a running timer would be unmistakable.
            interval: 0.02,
            sampleWindows: {
                samples.record()
                return [Self.menuBar(of: display)]
            },
            boundsOfDisplay: { _ in display },
            boundsOfActiveDisplays: { [display] },
            screenAvailability: screen
        )

        watcher.observe(displayID: displayID)
        watcher.start { _ in }
        // Only what follows `observe` and `start` is under test.
        let atStart = samples.count
        let readsAtStart = screen.readCount
        try? await Task.sleep(for: .milliseconds(300))
        #expect(samples.count == atStart)
        // Stopped, not firing and declining: a running timer takes this reading every tick.
        #expect(screen.readCount == readsAtStart)

        screen.available = true
        screen.announce()
        try? await Task.sleep(for: .milliseconds(300))
        #expect(samples.count > atStart)

        watcher.stop()
    }

    /// No display (the fallback identifier path) fails open like the predicate.
    @Test @MainActor
