    /// With no subscription behind the CLI, `/usage` answers with session cost; a Desktop-only
    /// machine is that case (Desktop injects auth into its sessions). Said only while nothing draws.
    @Test @MainActor
    func aSignedOutClaudeCodeIsSaidOutLoudRatherThanDrawnAsABlank() async {
        let costSummary = """
        Total cost:            $0.0000
        Total duration (API):  0s
        Total duration (wall): 0s
        Total code changes:    0 lines added, 0 lines removed
        Usage:                 0 input, 0 output, 0 cache read, 0 cache write
        """
        let clock = TestClock(now: Date(timeIntervalSince1970: 1_788_842_253))

        let signedOut = ClaudeCodeUsageReader(
            clock: clock,
            read: { costSummary },
            readConfiguration: { nil }
        )
        _ = await signedOut.quota()
        let said = await signedOut.quotaDiagnostic()
        #expect(said?.contains("claude auth login") == true)

        // Someone refreshed the record inside the hour, so nothing is missing to explain.
        let drawing = ClaudeCodeUsageReader(
            clock: clock,
            read: { costSummary },
            readConfiguration: {
                Data("""
                {"cachedUsageUtilization":{"fetchedAtMs":1788842193281,
                 "utilization":{"limits":[
                  {"kind":"session","percent":23,"resets_at":null,"scope":null}]}}}
                """.utf8)
            }
        )
        #expect(await drawing.quota().windows.first?.remainingPercent == 77)
        #expect(await drawing.quotaDiagnostic() == nil)

        // An answer that carried the windows is not signed out, even where this app could not use it.
        let subscribed = ClaudeCodeUsageReader(
            clock: clock,
            read: { "You are currently using your subscription to power your Claude Code usage" },
            readConfiguration: { nil }
        )
        _ = await subscribed.quota()
        #expect(await subscribed.quotaDiagnostic() == nil)
    }
    /// A `claude` launch takes four to seven seconds, so the reading runs behind the answer and says
    /// when it landed.
    @Test @MainActor
    func theQuotaReadingDoesNotHoldUpTheAnswerItComesWith() async throws {
        let clock = TestClock(now: Date(timeIntervalSince1970: 10_000))
        let updates = UpdateCounter()
        let record = StubUsageRecord(usedPercent: 20)
        let reader = ClaudeCodeUsageReader(
            clock: clock,
            onUpdate: { Task { await updates.record() } },
            read: {
                await Task.yield()
                return "You are currently using your subscription"
            },
            readConfiguration: { record.data }
        )

        // Nothing suspended, so the reading cannot have finished: the un-read state is this product's
        // two windows.
        let before = await reader.currentQuota()
        #expect(before.windows.count == 2)
        #expect(before.windows.allSatisfy { $0.remainingPercent == nil })

        for _ in 0 ..< 200 {
            if await updates.count > 0 { break }
            try await Task.sleep(nanoseconds: 5_000_000)
        }
        #expect(await updates.count == 1)
        #expect(await reader.currentQuota().remainingPercent == 80)
        #expect(await updates.count == 1)
    }

    /// Claude Code's project directory name flattens separators *and* spaces (2.1.234: `…/a b` and
    /// `…/a-b` share one), so the folder can hold real work; it is counted, never cleared.
    @Test @MainActor
    func usageTranscriptsAreMeasuredAndNeverDeleted() async throws {
        let root = URL(fileURLWithPath: "/tmp")
            .appendingPathComponent("cin-usage-\(UUID().uuidString.prefix(8))")
        defer { try? FileManager.default.removeItem(at: root) }
        let shared = root.appendingPathComponent("-tmp-cin-shared", isDirectory: true)
        let elsewhere = root.appendingPathComponent("-another-project", isDirectory: true)
        for directory in [shared, elsewhere] {
            try FileManager.default.createDirectory(
                at: directory,
                withIntermediateDirectories: true
            )
        }

        let ours = UUID().uuidString
        try Data(repeating: 0x41, count: 3_000)
            .write(to: shared.appendingPathComponent("\(ours).jsonl"))
        try Data(repeating: 0x42, count: 1_000)
            .write(to: shared.appendingPathComponent("\(UUID().uuidString).jsonl"))
        // Someone else's session in the same folder: counted, since the button opens the folder.
        try Data(repeating: 0x43, count: 500)
            .write(to: shared.appendingPathComponent("\(UUID().uuidString).jsonl"))
        try Data(repeating: 0x44, count: 9_000)
            .write(to: shared.appendingPathComponent("notes.md"))
        try Data(repeating: 0x45, count: 7_000)
            .write(to: elsewhere.appendingPathComponent("\(UUID().uuidString).jsonl"))

        let clock = TestClock(now: Date(timeIntervalSince1970: 10_000))
        let transcripts = ClaudeCodeUsageTranscripts(
            projectsDirectory: root,
            clock: clock,
            freshness: 60
        )

        #expect(await transcripts.footprint() == nil)

        await transcripts.noteReading(ours)
        let footprint = try #require(await transcripts.footprint())
        // By path: the enumerator's URL lacks the trailing slash `isDirectory: true` adds.
        #expect(footprint.directory.standardizedFileURL.path == shared.standardizedFileURL.path)
        #expect(footprint.byteCount == 4_500)

        #expect(try FileManager.default.contentsOfDirectory(atPath: shared.path).count == 4)
        #expect(try FileManager.default.contentsOfDirectory(atPath: elsewhere.path).count == 1)

        // Within the window the figure stands; past it the folder is counted again.
        try Data(repeating: 0x46, count: 1_500)
            .write(to: shared.appendingPathComponent("\(UUID().uuidString).jsonl"))
        await clock.advance(by: 30)
        #expect(await transcripts.footprint()?.byteCount == 4_500)
        await clock.advance(by: 40)
        #expect(await transcripts.footprint()?.byteCount == 6_000)
    }

    /// This app measures the folder, reports its size and opens it; nothing here removes a file.
