    /// A terminal's access time records that the session read the device, not that anybody typed.
    ///
    /// Measured 2026-08-20 against the real kernel: input moves it, output does not, and a `read`
    /// returning no bytes moves it too. Hence `ClaudeCodeMonitorService` pairs it with who holds the
    /// front; mouse reporting otherwise retired unread rows.
    @Test
    func aTerminalsAccessTimeRecordsBeingReadFromRatherThanBeingTypedInto() throws {
        let master = posix_openpt(O_RDWR | O_NOCTTY)
        try #require(master >= 0)
        defer { close(master) }
        #expect(grantpt(master) == 0)
        #expect(unlockpt(master) == 0)
        let device = String(cString: try #require(ptsname(master)))
        let slave = open(device, O_RDWR | O_NOCTTY)
        try #require(slave >= 0)
        defer { close(slave) }
        // Raw mode, as Claude Code uses: a canonical terminal never hands over `ESC [ I` (no line end).
        var attributes = termios()
        #expect(tcgetattr(slave, &attributes) == 0)
        cfmakeraw(&attributes)
        #expect(tcsetattr(slave, TCSANOW, &attributes) == 0)

        let before = try #require(
            ControllingTerminalGestureReader.systemLastAccess(ofDevice: device)
        )

        "an answer\r\n".withCString { _ = write(slave, $0, strlen($0)) }
        #expect(
            ControllingTerminalGestureReader.systemLastAccess(ofDevice: device) == before
        )

        // Times have a whole-second floor on some file systems, hence the real interval.
        Thread.sleep(forTimeInterval: 1.1)
        "\u{1B}[I".withCString { _ = write(master, $0, strlen($0)) }
        var buffer = [UInt8](repeating: 0, count: 64)
        #expect(read(slave, &buffer, 64) > 0)

        let after = try #require(
            ControllingTerminalGestureReader.systemLastAccess(ofDevice: device)
        )
        #expect(after > before)

        // An empty read moves it just as far.
        Thread.sleep(forTimeInterval: 1.1)
        #expect(fcntl(slave, F_SETFL, O_NONBLOCK) == 0)
        #expect(read(slave, &buffer, 64) < 0)
        #expect(errno == EAGAIN)
        let afterAnEmptyRead = try #require(
            ControllingTerminalGestureReader.systemLastAccess(ofDevice: device)
        )
        #expect(afterAnEmptyRead > after)
    }

