        let transcript = project.appendingPathComponent("s-1.jsonl")

        func line(_ record: [String: Any]) throws -> String {
            String(decoding: try JSONSerialization.data(withJSONObject: record), as: UTF8.self)
                + "\n"
        }

        let opening = try line([
            "type": "attachment",
