        #expect(snapshot.availability == .setupRequired)
        #expect(snapshot.diagnostic != nil)

        try harness.registerHooks()
        #expect(await harness.setup.status() == .active)
    }

    /// A partial registration (from an older build) reports repair apart from "off": the missing
    /// event raises no error anywhere.
    @Test @MainActor
    func aPartialRegistrationReportsThatItNeedsRepair() async throws {
        let harness = try ClaudeCodeHarness()
        defer { harness.tearDown() }
        let settings = harness.paths.hooksConfiguration

        try await harness.service.installIntegration()
        #expect(await harness.setup.status() == .active)

        var document = try #require(
            try JSONSerialization.jsonObject(with: try Data(contentsOf: settings))
                as? [String: Any]
        )
        var hooks = try #require(document["hooks"] as? [String: Any])
        hooks.removeValue(forKey: "Stop")
        document["hooks"] = hooks
        try JSONSerialization
            .data(withJSONObject: document, options: [.withoutEscapingSlashes])
            .write(to: settings)

        #expect(await harness.setup.status() == .repairRequired)

        // Switching on again writes the missing event back without the user editing (unlike ADR 0010).
        try await harness.service.installIntegration()
        #expect(await harness.setup.status() == .active)
    }

    /// A settings file this app cannot parse is reported, never rewritten.
    @Test @MainActor
    func anUnreadableSettingsFileIsNotMistakenForMissingSetup() async throws {
        let root = URL(fileURLWithPath: "/tmp")
            .appendingPathComponent("cin-cc-\(UUID().uuidString.prefix(8))")
        defer { try? FileManager.default.removeItem(at: root) }
        try FileManager.default.createDirectory(at: root, withIntermediateDirectories: true)

        for contents in ["[1, 2, 3]", "{ not json at all", ""] {
            let settings = root
                .appendingPathComponent("s-\(abs(contents.hashValue)).json")
            try Data(contents.utf8).write(to: settings)
