        let registry = ClaudeCodeSessionRegistry(
            clock: clock,
            processStartedAt: noProcessIsVouchedFor,
            read: {
                await clock.advance(by: 4)
                return Data("""
                [{"pid": 1, "cwd": "/a", "kind": "interactive",
                  "startedAt": 1000, "sessionId": "s-1", "status": "idle"}]
                """.utf8)
            }
        )

        let session = try #require(await registry.refresh().first)
        #expect(session.activity?.state == .idle)
        #expect(session.activity?.observedAt == Date(timeIntervalSince1970: 10_000))
    }

    /// A fresh answer is not re-read; a stale one is.
    @Test @MainActor
    func theSessionListIsReadAgainOnlyOnceItIsStale() async {
        let clock = TestClock(now: Date(timeIntervalSince1970: 10_000))
        let responses = ResponseQueue(items: [
            Data("""
            [{"pid": 1, "cwd": "/a", "kind": "interactive",
              "startedAt": 1000, "sessionId": "s-1"}]
            """.utf8),
            Data("""
            [{"pid": 2, "cwd": "/b", "kind": "interactive",
              "startedAt": 2000, "sessionId": "s-2"}]
            """.utf8)
        ])
        let registry = ClaudeCodeSessionRegistry(
            clock: clock,
            freshness: 30,
            processStartedAt: noProcessIsVouchedFor,
            read: { await responses.next() }
        )

        #expect(await registry.liveSessions().first?.sessionID == "s-1")
        await clock.advance(by: 29)
        #expect(await registry.liveSessions().first?.sessionID == "s-1")
        #expect(await responses.remaining() == 1)
        await clock.advance(by: 2)
        #expect(await registry.liveSessions().first?.sessionID == "s-2")
    }

    /// An edge cuts the freshness window short.
    ///
    /// A desktop session is created by its first prompt, so the whole turn ran unlisted and
    /// `ClaudeCodeMonitorService` dropped it. Measured 2026-08-18 on 2.1.234: rows appeared 20 and
    /// 23 s after `Stop`.
    @Test @MainActor
    func aReportedChangeReadsTheSessionListWithoutWaitingOutItsFreshness() async {
        let clock = TestClock(now: Date(timeIntervalSince1970: 10_000))
        let responses = ResponseQueue(items: [
            Data("""
            [{"pid": 1, "cwd": "/a", "kind": "interactive",
              "startedAt": 1000, "sessionId": "s-1"}]
            """.utf8),
            Data("""
            [{"pid": 2, "cwd": "/b", "kind": "interactive",
              "startedAt": 2000, "sessionId": "s-2"}]
            """.utf8),
            Data("""
            [{"pid": 3, "cwd": "/c", "kind": "interactive",
              "startedAt": 3000, "sessionId": "s-3"}]
            """.utf8)
        ])
        let registry = ClaudeCodeSessionRegistry(
            clock: clock,
            freshness: 30,
            edgeFloor: 2,
            processStartedAt: noProcessIsVouchedFor,
            read: { await responses.next() }
        )

        #expect(await registry.liveSessions().first?.sessionID == "s-1")
        await clock.advance(by: 3)
        #expect(await registry.liveSessions().first?.sessionID == "s-1")
        #expect(await responses.remaining() == 2)

        await registry.invalidate()
        #expect(await registry.liveSessions().first?.sessionID == "s-2")

        // A second edge straight away is held by the floor: no second launch.
        await registry.invalidate()
        #expect(await registry.liveSessions().first?.sessionID == "s-2")
        #expect(await responses.remaining() == 1)
        await clock.advance(by: 2)
        #expect(await registry.liveSessions().first?.sessionID == "s-3")
    }

    /// An edge that lands while the command is out is not cleared by that read, which cannot have
    /// seen the change.
    @Test @MainActor
    func anEdgeDuringAReadIsNotClearedByThatRead() async {
        let clock = TestClock(now: Date(timeIntervalSince1970: 10_000))
        let responses = ResponseQueue(items: [
            Data("""
            [{"pid": 1, "cwd": "/a", "kind": "interactive",
              "startedAt": 1000, "sessionId": "s-1"}]
            """.utf8),
            Data("""
            [{"pid": 2, "cwd": "/b", "kind": "interactive",
              "startedAt": 2000, "sessionId": "s-2"}]
            """.utf8)
        ])
        let holder = RegistryHolder()
        let registry = ClaudeCodeSessionRegistry(
            clock: clock,
            freshness: 30,
            edgeFloor: 2,
            processStartedAt: noProcessIsVouchedFor,
            read: {
                await holder.registry?.invalidate()
                return await responses.next()
            }
        )
        holder.registry = registry

        #expect(await registry.liveSessions().first?.sessionID == "s-1")
        // The floor still applies: an edge asks for a read sooner, never on top of one finishing.
        #expect(await registry.liveSessions().first?.sessionID == "s-1")
        await clock.advance(by: 2)
        #expect(await registry.liveSessions().first?.sessionID == "s-2")
    }

    /// A failed read books the same wait as a successful one. Refreshes are driven by hooks, so an
    /// unpaced failure launched at hook rate: 71 launches in 110 s where the cadence allows four,
    /// and concurrent launches took 1.6 s each against 0.25 s alone (measured, live app).
    @Test @MainActor
    func aFailedSessionListReadIsPacedLikeAnAnswerAndDoesNotStormTheCommand() async {
        let clock = TestClock(now: Date(timeIntervalSince1970: 10_000))
        let counter = ReadCounter()
        let registry = ClaudeCodeSessionRegistry(
            clock: clock,
            freshness: 30,
            processStartedAt: noProcessIsVouchedFor,
            read: { await counter.read() }
        )

        _ = await registry.liveSessions()
        #expect(await counter.count == 1)

        // Ten more asks inside the window, like a busy turn's hook traffic.
        for _ in 0 ..< 10 { _ = await registry.liveSessions() }
        #expect(await counter.count == 1)

        await clock.advance(by: 31)
        _ = await registry.liveSessions()
        #expect(await counter.count == 2)
    }

    /// Presence goes `unknown` only on the third consecutive failure: the ceiling is a wall-clock
    /// interval that means three failures only when reads are paced a `freshness` apart.
    @Test @MainActor
    func presenceSurvivesTwoFailedReadsAndOnlyTheThirdCrossesTheCeiling() async {
        let clock = TestClock(now: Date(timeIntervalSince1970: 10_000))
        let responses = ResponseQueue(items: [
            Data("""
            [{"pid": 1, "cwd": "/a", "kind": "interactive",
              "startedAt": 1000, "sessionId": "s-1"}]
            """.utf8)
        ])
        let registry = ClaudeCodeSessionRegistry(
            clock: clock,
            freshness: 30,
            trustCeiling: 90,
            processStartedAt: noProcessIsVouchedFor,
            read: { await responses.next() }
        )
        #expect(await registry.presence() == .open)

        await clock.advance(by: 31)
        #expect(await registry.presence() == .open)
        await clock.advance(by: 31)
        #expect(await registry.presence() == .open)
        await clock.advance(by: 31)
        #expect(await registry.presence() == .unknown)
    }

    /// Two concurrent callers share one reading: the actor suspends at `await`, and one refresh asks
    /// twice (rows and mark), which launched two `claude`s.
    @Test @MainActor
    func twoCallersArrivingTogetherShareOneReadOfTheSessionList() async {
        let counter = ReadCounter(answer: Data("""
        [{"pid": 1, "cwd": "/a", "kind": "interactive",
          "startedAt": 1000, "sessionId": "s-1"}]
        """.utf8))
        let registry = ClaudeCodeSessionRegistry(
            freshness: 30,
            processStartedAt: noProcessIsVouchedFor,
            read: { await counter.read() }
        )

        async let rows = registry.liveSessions()
        async let mark = registry.presence()
        let (listed, presence) = await (rows, mark)

        #expect(listed.count == 1)
        #expect(presence == .open)
        #expect(await counter.count == 1)
    }

    /// A cached answer past the trust ceiling stops deciding presence, though still returned.
    ///
    /// `freshness` says when to re-read; the ceiling says how long a stale answer decides presence,
    /// or a missing `claude` reads `Connected` forever. Rows stay: the surface retires them by
    /// going `Disconnected`.
    @Test @MainActor
    func aSessionListThatCannotBeReReadStopsDecidingPresence() async {
        let clock = TestClock(now: Date(timeIntervalSince1970: 10_000))
        let responses = ResponseQueue(items: [
            Data("""
            [{"pid": 1, "cwd": "/a", "kind": "interactive",
              "startedAt": 1000, "sessionId": "s-1"}]
            """.utf8)
        ])
        let registry = ClaudeCodeSessionRegistry(
            clock: clock,
            freshness: 30,
            trustCeiling: 90,
            processStartedAt: noProcessIsVouchedFor,
            read: { await responses.next() }
        )

        #expect(await registry.presence() == .open)

        await clock.advance(by: 60)
        #expect(await registry.presence() == .open)
        #expect(await registry.liveSessions().count == 1)

        await clock.advance(by: 40)
        #expect(await registry.presence() == .unknown)
        // Sessions are still handed back: a failed read never proves a session ended.
        #expect(await registry.liveSessions().count == 1)
    }

    /// An empty list known to be empty stays `closed` until something contradicts it: the ceiling
    /// bounds failing reads, not elapsed time (CR-Fable-002). Expiry takes an edge plus a failed read.
    @Test @MainActor
    func anEmptySessionListStaysClosedUntilSomethingContradictsIt() async {
        let clock = TestClock(now: Date(timeIntervalSince1970: 10_000))
        let responses = ResponseQueue(items: [Data("[]".utf8)])
        let registry = ClaudeCodeSessionRegistry(
            clock: clock,
            freshness: 30,
            edgeFloor: 2,
            trustCeiling: 90,
            processStartedAt: noProcessIsVouchedFor,
            read: { await responses.next() }
        )

        #expect(await registry.presence() == .closed)
        await clock.advance(by: 200)
        // Long past the ceiling and still closed: nothing contradicted it.
        #expect(await registry.presence() == .closed)

        // The ceiling counts from the last answer, 200 s old.
        await registry.invalidate()
        #expect(await registry.presence() == .unknown)
    }

    /// A known-empty list is held; a listed one is still re-read on the clock (CR-Fable-002).
    ///
    /// `claude agents --json` (Node, ~0.4 s of a core, starts MCP servers) ran every 30–60 s even
    /// idle. A new session creates its record (a directory event), but a `SIGKILL`ed session leaves
    /// its record, and only the command's `pid` + `procStart` check finds that ghost.
    @Test @MainActor
    func aKnownEmptySessionListIsHeldWhileAListedOneIsStillReRead() async {
        let clock = TestClock(now: Date(timeIntervalSince1970: 10_000))
        let counter = ReadCounter(answer: Data("[]".utf8))
        let registry = ClaudeCodeSessionRegistry(
            clock: clock,
            freshness: 30,
            edgeFloor: 2,
            processStartedAt: noProcessIsVouchedFor,
            read: { await counter.read() }
        )

        #expect(await registry.liveSessions().isEmpty)
        #expect(await counter.count == 1)

        // An hour of wake-ups at the store's fastest cadence.
        for _ in 0 ..< 120 {
            await clock.advance(by: 30)
            #expect(await registry.presence() == .closed)
            #expect(await registry.liveSessions().isEmpty)
        }
        #expect(await counter.count == 1)

        // A session record appearing is answered inside `edgeFloor`.
        await counter.respond(with: Data("""
        [{"pid": 1, "cwd": "/a", "kind": "interactive",
          "startedAt": 1000, "sessionId": "s-1"}]
        """.utf8))
        await registry.invalidate()
        #expect(await registry.liveSessions().first?.sessionID == "s-1")
        #expect(await counter.count == 2)

        // A listed row may need retiring, so the clock paces it again.
        await clock.advance(by: 31)
        #expect(await registry.liveSessions().count == 1)
        #expect(await counter.count == 3)
    }

    /// A listed session still the same process (`pid` + start instant, via `sysctl`) is not worth
    /// a `claude`; this catches the `SIGKILL` case, which raises no edge.
    @Test @MainActor
    func aListedSessionStillRunningIsNotWorthACommand() async {
        let clock = TestClock(now: Date(timeIntervalSince1970: 10_000))
        let listed = Data("""
        [{"pid": 4242, "cwd": "/a", "kind": "interactive",
          "startedAt": 1000, "sessionId": "s-1"}]
        """.utf8)
        let counter = ReadCounter(answer: listed)
        let table = StubProcessTable([4_242: Date(timeIntervalSince1970: 9_000)])
        let registry = ClaudeCodeSessionRegistry(
            clock: clock,
            freshness: 30,
            processStartedAt: table.reader,
            read: { await counter.read() }
        )

        #expect(await registry.liveSessions().first?.sessionID == "s-1")
        #expect(await counter.count == 1)

        // An hour of past-due freshness windows, session still running.
        for _ in 0 ..< 120 {
            await clock.advance(by: 30)
            #expect(await registry.liveSessions().first?.sessionID == "s-1")
        }
        #expect(await counter.count == 1)
        // Nothing failed, so nothing aged.
        #expect(await registry.presence() == .open)

        // Killed: the record stays and no edge is raised; only the kernel sees it.
        await counter.respond(with: Data("[]".utf8))
        table.set(4_242, nil)
        #expect(await registry.liveSessions().isEmpty)
        #expect(await counter.count == 2)
    }

    /// A reused pid is a ghost: the check pairs the pid with its kernel start instant.
    @Test @MainActor
    func aReusedProcessIdentifierCountsAsAGhost() async {
        let clock = TestClock(now: Date(timeIntervalSince1970: 10_000))
        let counter = ReadCounter(answer: Data("""
        [{"pid": 4242, "cwd": "/a", "kind": "interactive",
          "startedAt": 1000, "sessionId": "s-1"}]
        """.utf8))
        let table = StubProcessTable([4_242: Date(timeIntervalSince1970: 9_000)])
        let registry = ClaudeCodeSessionRegistry(
            clock: clock,
            freshness: 30,
            processStartedAt: table.reader,
            read: { await counter.read() }
        )

        #expect(await registry.liveSessions().count == 1)
        #expect(await counter.count == 1)

        table.set(4_242, Date(timeIntervalSince1970: 9_500))
        await counter.respond(with: Data("[]".utf8))
        await clock.advance(by: 31)
        #expect(await registry.liveSessions().isEmpty)
        #expect(await counter.count == 2)
    }

    /// The clock's re-read waits for a screen; an edge, being evidence, does not.
    @Test @MainActor
    func theSessionListIsNotReReadOnTheClockWhileThereIsNoScreen() async {
        let clock = TestClock(now: Date(timeIntervalSince1970: 10_000))
        let counter = ReadCounter(answer: Data("""
        [{"pid": 4242, "cwd": "/a", "kind": "interactive",
          "startedAt": 1000, "sessionId": "s-1"}]
        """.utf8))
        let screen = StubScreenAvailability()
        let registry = ClaudeCodeSessionRegistry(
            clock: clock,
            freshness: 30,
            edgeFloor: 2,
            screenIsAvailable: { screen.available },
            processStartedAt: noProcessIsVouchedFor,
            read: { await counter.read() }
        )

        #expect(await registry.liveSessions().count == 1)
        #expect(await counter.count == 1)

        screen.available = false
        for _ in 0 ..< 20 {
            await clock.advance(by: 30)
            #expect(await registry.liveSessions().count == 1)
        }
        #expect(await counter.count == 1)

        await registry.invalidate()
        #expect(await registry.liveSessions().count == 1)
        #expect(await counter.count == 2)

        // The screen returning is an edge, so the skipped reading is bought once.
        screen.available = true
        await clock.advance(by: 31)
        #expect(await registry.liveSessions().count == 1)
        #expect(await counter.count == 3)
    }

    /// A failed read does not hold an empty cache: the hold keys on an answer, or an uninstalled
    /// `claude` would report `closed` instead of `unknown` forever.
    @Test @MainActor
    func anEmptyCacheWithNoAnswerBehindItKeepsRetryingOnTheClock() async {
        let clock = TestClock(now: Date(timeIntervalSince1970: 10_000))
        let counter = ReadCounter(answer: nil)
        let registry = ClaudeCodeSessionRegistry(
            clock: clock,
            freshness: 30,
            trustCeiling: 90,
            processStartedAt: noProcessIsVouchedFor,
            read: { await counter.read() }
        )

        #expect(await registry.presence() == .unknown)
        #expect(await counter.count == 1)
        await clock.advance(by: 31)
        #expect(await registry.presence() == .unknown)
        #expect(await counter.count == 2)

        await counter.respond(with: Data("[]".utf8))
        await clock.advance(by: 31)
        #expect(await registry.presence() == .closed)
        #expect(await counter.count == 3)
        await clock.advance(by: 300)
        #expect(await registry.presence() == .closed)
        #expect(await counter.count == 3)

        // A new failure ends the hold, putting the ceiling back in charge of a 300 s-old answer.
        await counter.respond(with: nil)
        await registry.invalidate()
        #expect(await registry.presence() == .unknown)
        #expect(await counter.count == 4)
    }

    /// A registry that has never had a successful read knows nothing.
    @Test @MainActor
    func aSessionListThatNeverAnsweredReportsUnknownRatherThanClosed() async {
        let registry = ClaudeCodeSessionRegistry(
            processStartedAt: noProcessIsVouchedFor,
            read: { nil })
        #expect(await registry.presence() == .unknown)
        #expect(await registry.liveSessions().isEmpty)
    }

    /// A product counts as connected only when both open and reachable (`docs/figma-design.md`
    /// §6.7); "open but unregistered" is an ordinary first run.
    @Test @MainActor
    func onlyAProductThatIsBothOpenAndReachableCountsAsConnected() {
        func merged(
            _ availability: MonitorAvailability,
            _ presence: AgentPresence
        ) -> MonitorSnapshot {
            AgentSnapshotMerge.merge([
                makeAgentSnapshot(.codex, availability: availability, presence: presence)
            ])
        }

        #expect(merged(.ready, .open).status == .connected)
        #expect(merged(.setupRequired, .open).status == .disconnected)
        #expect(merged(.ready, .closed).status == .disconnected)
        // Unknown is not a weak yes.
        #expect(merged(.ready, .unknown).status == .disconnected)
        #expect(merged(.connecting, .open).status == .disconnected)

        #expect(merged(.ready, .open).connectedAgents == [.codex])
        #expect(merged(.setupRequired, .open).connectedAgents.isEmpty)
        #expect(merged(.ready, .closed).connectedAgents.isEmpty)
    }

    /// Presence draws the mark; the reducer lights it, and the two must not be re-merged. Codex
    /// presence is known at launch while its turns are not.
    @Test @MainActor
    func aConnectedProductWithNoTurnsStillShowsItsOwnMark() {
        let quiet = AgentSnapshotMerge.merge([
            makeAgentSnapshot(.codex, availability: .ready, presence: .open)
        ])
        #expect(quiet.sessions.isEmpty)
        #expect(quiet.status == .connected)
        #expect(quiet.connectedAgents == [.codex])

        // A second mark without a status change: the pill's width cannot be derived from status.
        let both = AgentSnapshotMerge.merge([
            makeAgentSnapshot(.codex, availability: .ready, presence: .open),
            makeAgentSnapshot(.claudeCode, availability: .ready, presence: .open)
        ])
        #expect(both.status == .connected)
        #expect(both.connectedAgents == [.codex, .claudeCode])
        // One connected width for both (`compact-view-v2.md` §6.1): a product registering is not a
        // product connected, and the surface must not move for it.
        #expect(
            PanelMetrics.fixedCompactWidth(for: both.status)
                == PanelMetrics.fixedCompactWidth(for: quiet.status)
        )
    }

    /// The first product to open takes the grey ("no product") slot; only the second adds one.
    @Test @MainActor
    func theFirstConnectedProductTakesTheRestingSlotRatherThanAddingOne() {
        let nothing = AgentSnapshotMerge.merge([
            makeAgentSnapshot(.codex, availability: .ready, presence: .closed)
        ])
        #expect(nothing.status == .disconnected)
        #expect(nothing.connectedAgents.isEmpty)

        let restingWidth = PanelMetrics.fixedCompactWidth(for: .disconnected)
        let oneOpen = PanelMetrics.fixedCompactWidth(for: .connected)

        // Resting is the mark and two margins (`41`, no `8` clearance); connecting brings the whole
        // connected form; a second product adds nothing.
        #expect(restingWidth == 41)
        #expect(oneOpen == 230)
        #expect(oneOpen > restingWidth)
        #expect(
            PanelMetrics.fixedCompactWidth(for: .running) == oneOpen
        )
    }

    /// Nothing that makes an entry addressable is filled in, and an array holding one that cannot be
    /// is refused whole: keeping the rest could read non-sessions as an answered empty list, held
    /// until an edge (CR-Codex-001).
    @Test @MainActor
    func theSessionListRefusesAnArrayHoldingAnEntryItCannotAddress() async {
        let responses = ResponseQueue(items: [
            Data("""
            [{"pid": 1, "cwd": "/a", "startedAt": 1000, "sessionId": "keep"},
             {"pid": 2, "cwd": "/b", "startedAt": 1000},
             {"pid": 3, "startedAt": 1000, "sessionId": "no-cwd"},
             {"cwd": "/d", "startedAt": 1000, "sessionId": "no-pid"},
             {"pid": 5, "cwd": "/e", "sessionId": "no-start"}]
            """.utf8),
            Data("""
            [{"pid": 1, "cwd": "/a", "startedAt": 1000, "sessionId": "keep"},
             {"pid": 2, "cwd": "/b", "startedAt": 1000, "sessionId": "also"}]
            """.utf8)
        ])
        let registry = ClaudeCodeSessionRegistry(
            processStartedAt: noProcessIsVouchedFor,
            read: { await responses.next() })
        #expect(await registry.refresh().isEmpty)

        // The same array with complete identities reads in full: the missing field was refused.
        #expect(await registry.refresh().map(\.sessionID) == ["keep", "also"])
    }

    /// This app's own quota reading is neither a session nor presence.
    ///
    /// `claude -p "/usage"` reports `kind: "interactive"` like a human session; only the working
    /// directory separates them (measured on 2.1.234, 2026-08-18). Filtered here, not at the
    /// surface, or the product still reads open every five minutes.
    @Test @MainActor
    func theAppsOwnQuotaReadingIsNotCountedAsASessionOrAsPresence() async {
        let quota = URL(fileURLWithPath: "/Users/someone/Library/Application Support/Notchline/agents/claudeCode/usage")
        func registry(_ json: String) -> ClaudeCodeSessionRegistry {
            let responses = ResponseQueue(items: [Data(json.utf8)])
            return ClaudeCodeSessionRegistry(
                ignoringWorkingDirectory: quota,
                processStartedAt: noProcessIsVouchedFor,
            read: { await responses.next() }
            )
        }

        let onlyOurs = registry("""
        [{"pid": 9, "cwd": "\(quota.path)", "kind": "interactive",
          "startedAt": 1000, "sessionId": "ours"}]
        """)
        #expect(await onlyOurs.liveSessions().isEmpty)
        #expect(await onlyOurs.presence() == .closed)

        let both = registry("""
        [{"pid": 9, "cwd": "\(quota.path)", "kind": "interactive",
          "startedAt": 1000, "sessionId": "ours"},
         {"pid": 10, "cwd": "/Users/someone/Projects/thing", "kind": "interactive",
          "startedAt": 2000, "sessionId": "theirs"}]
        """)
        #expect(await both.liveSessions().map(\.sessionID) == ["theirs"])
        #expect(await both.presence() == .open)

        // A registry told to ignore nothing reports everything: the exclusion is the wiring's.
        let responses = ResponseQueue(items: [Data("""
        [{"pid": 9, "cwd": "\(quota.path)", "kind": "interactive",
          "startedAt": 1000, "sessionId": "ours"}]
        """.utf8)])
        let unfiltered = ClaudeCodeSessionRegistry(
            processStartedAt: noProcessIsVouchedFor,
            read: { await responses.next() })
        #expect(await unfiltered.liveSessions().count == 1)
    }

    /// A stray subprocess log line does not hide the session list. An MCP server wrote to a `claude`
    /// command's stdout on two runs in five; an undecodable list ages presence to the trust ceiling.
    @Test @MainActor
    func aStraySubprocessLogLineDoesNotHideTheSessionList() {
        let noise = Data("""
        Client.listTools() called but server does not advertise tools capability - returning empty list
        [
          {
            "pid": 11115,
            "cwd": "/Users/someone/Projects/thing",
            "kind": "interactive",
            "startedAt": 1786919144634,
            "sessionId": "s-1",
            "name": "thing-21"
          }
        ]
        Client.listTools() called but server does not advertise tools capability - returning empty list
        """.utf8)

        let sessions = ClaudeCodeSessionRegistry.sessions(in: noise)
        #expect(sessions?.map(\.sessionID) == ["s-1"])

        #expect(ClaudeCodeSessionRegistry.sessions(in: Data("[]".utf8))?.isEmpty == true)
        #expect(ClaudeCodeSessionRegistry.sessions(in: Data("no list here".utf8)) == nil)
    }

    /// A bracketed log prefix (`[INFO] …`, `[2026-08-21T…] …`) does not hide the session list
    /// (CR-Fable-039). The array is found by offering each balanced span to the decoder, not first
    /// `[` to last `]`.
    @Test @MainActor
    func aBracketedLogPrefixDoesNotHideTheSessionList() {
        let prefixed = Data("""
        [INFO] mcp-server: starting
        [2026-08-21T09:14:04.634Z] Client.listTools() called - returning empty list
        [
          {
            "pid": 11115,
            "cwd": "/Users/someone/Projects/thing",
            "kind": "interactive",
            "startedAt": 1786919144634,
            "sessionId": "s-1",
            "name": "thing-21"
          }
        ]
        [server] shutting down
        """.utf8)
        #expect(ClaudeCodeSessionRegistry.sessions(in: prefixed)?.map(\.sessionID) == ["s-1"])

        // Brackets are text inside strings, and in-string state ends at a newline (JSON strings hold
        // none): an unpaired quote must not swallow the array, nor a `]` in a path close it.
        let quoted = Data("""
        [INFO] mcp-server: no handler for "list_tools
        [{"pid": 3, "cwd": "/Users/someone/Projects/archive]2025",
          "startedAt": 1786919144634, "sessionId": "s-2"}]
        """.utf8)
        #expect(ClaudeCodeSessionRegistry.sessions(in: quoted)?.map(\.sessionID) == ["s-2"])

        // An unclosed bracket is skipped rather than taking the rest of the stream.
        let unclosed = Data("""
        [INFO unterminated
        [{"pid": 5, "cwd": "/w", "startedAt": 1786919144634, "sessionId": "s-4"}]
        """.utf8)
        #expect(ClaudeCodeSessionRegistry.sessions(in: unclosed)?.map(\.sessionID) == ["s-4"])
    }

    /// An empty span in a log line does not empty the session list: `[]` means known-empty (product
    /// closed), so it is the last answer taken, never the first (CR-Fable-039).
    @Test @MainActor
    func anEmptySpanInALogLineDoesNotEmptyTheSessionList() {
        let emptyAbove = Data("""
        [INFO] mcp-server: advertised tools []
        [{"pid": 4, "cwd": "/w", "startedAt": 1786919144634, "sessionId": "s-3"}]
        """.utf8)
        #expect(ClaudeCodeSessionRegistry.sessions(in: emptyAbove)?.map(\.sessionID) == ["s-3"])

        let genuinelyEmpty = Data("""
        [INFO] mcp-server: advertised tools []
        []
        """.utf8)
        #expect(ClaudeCodeSessionRegistry.sessions(in: genuinelyEmpty)?.isEmpty == true)

        // An empty span counts only standing by itself, never inside a sentence (CR-Codex-001).
        let onlyNoise = Data("[INFO] mcp-server: advertised tools []".utf8)
        #expect(ClaudeCodeSessionRegistry.sessions(in: onlyNoise) == nil)
    }

    /// An object array that is not a session list is refused, not read as empty (CR-Codex-001).
    /// `Reported` decodes any object, so a candidate must carry the four identifying fields in every
    /// entry.
    @Test @MainActor
    func anObjectArrayThatIsNotASessionListIsRefusedRatherThanReadAsEmpty() {
        // Refused outright, which keeps the last list rather than reporting the product closed.
        #expect(ClaudeCodeSessionRegistry.sessions(in: Data("[{}]".utf8)) == nil)
        #expect(ClaudeCodeSessionRegistry.sessions(in: Data("[{\"tools\": []}]".utf8)) == nil)

        // The measured shape: a server's own array printed above the command's.
        let noiseAbove = Data("""
        [mcp] tools: [{"name": "read_file"}, {"name": "write_file"}]
        [
          {
            "pid": 11115,
            "cwd": "/Users/someone/Projects/thing",
            "kind": "interactive",
            "startedAt": 1786919144634,
            "sessionId": "s-1",
            "name": "thing-21"
          }
        ]
        """.utf8)
        #expect(ClaudeCodeSessionRegistry.sessions(in: noiseAbove)?.map(\.sessionID) == ["s-1"])
    }

    /// A mixed array is refused whole: dropping entries would silently lose a live session under a
    /// trusted answer; a refused read is retried on the cadence.
    @Test @MainActor
    func aMixedArrayIsRefusedRatherThanQuietlyLosingASession() {
        let mixed = Data("""
        [
          {
            "pid": 11115,
            "cwd": "/Users/someone/Projects/thing",
            "startedAt": 1786919144634,
            "sessionId": "s-1"
          },
          { "note": "spawned by the runner" }
        ]
        """.utf8)
        #expect(ClaudeCodeSessionRegistry.sessions(in: mixed) == nil)

        // Completing the entry decodes both: the missing identity is refused, not unpromised fields.
        let whole = Data("""
        [
          {
            "pid": 11115,
            "cwd": "/Users/someone/Projects/thing",
            "startedAt": 1786919144634,
            "sessionId": "s-1"
          },
          {
            "pid": 11116,
            "cwd": "/Users/someone/Projects/other",
            "startedAt": 1786919144999,
            "sessionId": "s-2",
            "note": "spawned by the runner"
          }
        ]
        """.utf8)
        #expect(ClaudeCodeSessionRegistry.sessions(in: whole)?.map(\.sessionID) == ["s-1", "s-2"])
    }

    /// A refused list leaves ``performRead()`` like a command that never answered (last list kept,
    /// attempt unanswered, cadence resumed), not as a known-empty list held until an edge.
    @Test @MainActor
    func aReadPollutedByAnObjectArrayKeepsTheSessionsItAlreadyHad() async {
        let clock = TestClock(now: Date(timeIntervalSince1970: 10_000))
        let real = Data("""
        [{"pid": 11115, "cwd": "/w", "startedAt": 1786919144634, "sessionId": "s-1"}]
        """.utf8)
        let counter = ReadCounter(answer: real)
        let registry = ClaudeCodeSessionRegistry(
            clock: clock,
            freshness: 30,
            trustCeiling: 90,
            processStartedAt: noProcessIsVouchedFor,
            read: { await counter.read() }
        )

        #expect(await registry.presence() == .open)
        #expect(await registry.liveSessions().map(\.sessionID) == ["s-1"])

        await counter.respond(with: Data("[{\"tools\": []}]".utf8))
        await clock.advance(by: 31)
        #expect(await registry.presence() == .open)
        #expect(await registry.liveSessions().map(\.sessionID) == ["s-1"])

        // Unanswered, so retried on the cadence rather than held.
        await clock.advance(by: 31)
        _ = await registry.presence()
        #expect(await counter.count == 3)
    }

    /// The command reports each session's `status`, and `waitingFor` while a prompt waits (measured
    /// on 2.1.235, 2026-08-18); the only trace a user interrupt leaves (CC-019). Unknown words are
    /// dropped, never guessed as idle.
    @Test @MainActor
    func theSessionListCarriesWhatEachSessionIsDoing() throws {
        let json = Data("""
        [
          { "pid": 1, "cwd": "/w", "startedAt": 1786919144634, "sessionId": "busy",
            "status": "busy" },
          { "pid": 2, "cwd": "/w", "startedAt": 1786919144634, "sessionId": "waiting",
            "status": "waiting", "waitingFor": "permission prompt" },
          { "pid": 3, "cwd": "/w", "startedAt": 1786919144634, "sessionId": "idle",
            "status": "idle" },
          { "pid": 4, "cwd": "/w", "startedAt": 1786919144634, "sessionId": "shell",
            "status": "shell" },
          { "pid": 5, "cwd": "/w", "startedAt": 1786919144634, "sessionId": "unknown",
            "status": "meditating" },
          { "pid": 6, "cwd": "/w", "startedAt": 1786919144634, "sessionId": "desktop" }
        ]
        """.utf8)

        let read = Date(timeIntervalSince1970: 500)
        let sessions = try #require(
            ClaudeCodeSessionRegistry.sessions(in: json, observedAt: read)
        )
        let byID = Dictionary(uniqueKeysWithValues: sessions.map { ($0.sessionID, $0) })

        #expect(byID["busy"]?.activity?.state == .busy)
        #expect(byID["waiting"]?.activity?.state == .waiting)
        #expect(byID["idle"]?.activity?.state == .idle)
        #expect(byID["shell"]?.activity?.state == .shell)
        // Not understood, and a desktop-hosted session (#41): silence, not idleness.
        #expect(byID["unknown"]?.activity == nil)
        #expect(byID["desktop"]?.activity == nil)

        // `waiting` is working: the turn is alive and parked on the user.
        #expect(byID["busy"]?.activity?.isWorking == true)
        #expect(byID["waiting"]?.activity?.isWorking == true)
        #expect(byID["idle"]?.activity?.isWorking == false)
        #expect(byID["shell"]?.activity?.isWorking == false)

        // Stamped with the reading, to compare with the event it would overrule.
        #expect(byID["idle"]?.activity?.observedAt == read)
        // Parsed with no reading behind it, its age proves nothing.
        #expect(
            ClaudeCodeSessionRegistry.sessions(in: json)?
                .first { $0.sessionID == "idle" }?.activity?.observedAt == .distantPast
        )
    }

    /// The replaced HTTP handler stays recognisable via its URL path as a legacy marker:
    /// `isManagedHandler` (ours, any shape) makes an upgrade replace rather than accumulate;
    /// `isCurrentManagedHandler` (this build's shape) makes a stale one report repair.
    @Test @MainActor
    func theHandlerThisBuildReplacedStaysRecognisableSoAnUpgradeReplacesIt() throws {
        let definitions = [ManagedHookDefinition(event: "Stop", matcher: nil)]
        let configuration = ManagedHooksConfiguration.command(
            "/Users/someone/Library/Application Support/Notchline/agents/claudeCode/hook.sh",
            arguments: [],
            legacyCommands: [ClaudeCodeHookVocabulary.legacyHookPath],
            definitions: definitions
        )

        let legacyHandler: [String: Any] = [
            "type": "http",
            "url": "http://127.0.0.1:51741\(ClaudeCodeHookVocabulary.legacyHookPath)",
            "timeout": 5,
            "headers": ["Authorization": "Bearer abc"]
        ]
        let original: [String: Any] = [
            "theme": "auto",
            "env": ["SOME_KEY": "value"],
            "hooks": [
                "Stop": [["hooks": [legacyHandler]]],
                "PreToolUse": [["hooks": [["type": "command", "command": "theirs"]]]]
            ]
        ]

        #expect(configuration.isManagedHandler(legacyHandler))
        #expect(!configuration.isCurrentManagedHandler(legacyHandler, for: definitions[0]))
        #expect(!configuration.isFullyInstalled(in: original))

        let installed = try configuration.installing(into: original, isNewFile: false)
        #expect(configuration.isFullyInstalled(in: installed))
        let stop = try #require(
            (installed["hooks"] as? [String: Any])?["Stop"] as? [[String: Any]]
        )
        #expect(stop.count == 1)
        let handlers = try #require(stop[0]["hooks"] as? [[String: Any]])
        #expect(handlers.count == 1)
        #expect(handlers[0]["type"] as? String == "command")

        #expect(installed["theme"] as? String == "auto")
        #expect((installed["env"] as? [String: Any])?["SOME_KEY"] as? String == "value")

        let removed = try configuration.removing(from: installed)
        #expect(configuration.isFullyRemoved(from: removed))
        #expect(removed["theme"] as? String == "auto")
        let theirs = try #require(
            (removed["hooks"] as? [String: Any])?["PreToolUse"] as? [[String: Any]]
        )
        #expect(theirs.count == 1)
    }

    /// One connection, one payload, handed over whole; field selection is the store's.
    @Test @MainActor
    func theListenerHandsOverOnePayloadPerConnection() async throws {
        let root = URL(fileURLWithPath: "/tmp")
            .appendingPathComponent("cin-listener-\(UUID().uuidString.prefix(8))")
        try FileManager.default.createDirectory(at: root, withIntermediateDirectories: true)
        defer { try? FileManager.default.removeItem(at: root) }

        let clock = TestClock(now: Date(timeIntervalSince1970: 1_700))
        let recorder = RecordedHookDelivery()
        let listener = AgentHookListener(clock: clock, deliver: recorder.deliver)
        defer { listener.stop() }
        let socket = root.appendingPathComponent("hook.sock")
        #expect(listener.start(socketURL: socket))

        try send(
            to: socket,
            body: [
                "hook_event_name": "UserPromptSubmit",
                "session_id": "session-1",
                "prompt_id": "prompt-1",
                "permission_mode": "auto",
                "prompt": "what the user asked"
            ]
        )

        let received = try #require(recorder.payloads.first)
        #expect(recorder.count == 1)
        #expect(received["hook_event_name"] as? String == "UserPromptSubmit")
        #expect(received["session_id"] as? String == "session-1")

        // `prompt_id` is this product's turn id; the payload has no timestamp, so the transport stamps.
        let paths = HookIntegrationPaths(
            supportDirectory: root.appendingPathComponent("AS"),
            hooksConfiguration: root.appendingPathComponent("settings.json"),
            agent: .claudeCode
        )
        let repository = HookEventRepository(
            paths: paths,
            clock: clock,
            vocabulary: ClaudeCodeHookVocabulary()
        )
        repository.deliver(
            try JSONSerialization.data(withJSONObject: received),
            at: clock.now()
        )
        let turns = await waitForReducedTurns(repository, count: 1)
        let turn = try #require(turns.first)
        #expect(turn.threadID == "session-1")
        #expect(turn.turnID == "prompt-1")
        #expect(turn.lastEventAt == Date(timeIntervalSince1970: 1_700))
        // PRD §7: the row's fallback until this turn has printed something.
        #expect(turn.promptPreview == "what the user asked")
    }

    /// An oversized tool result does not drop its event (CR-030). A lost `PostToolUse` left the
    /// `PermissionRequest` wait open on *Approval needed* until `Stop`; the result's size is not
    /// evidence about the turn.
    @Test @MainActor
    func anOversizedToolResultStillClosesTheWaitItBelongsTo() async throws {
