        store.answerDraftChanged(to: "Render, but only in Europe")
        #expect(store.takeQuestionStep(-1))
        #expect(store.openQuestionIndex == 0)

        #expect(store.takeQuestionStep(1))
        #expect(store.openQuestionIndex == 1)
