    /// Presence `unknown` means no reading at all, so the card must not say
    /// `Connected · hooks installed` from `setup` alone. Each cause writes its own sentence under one
    /// headline.
    @Test @MainActor
    func aProductNobodyCanWatchSaysSoRatherThanSayingConnected() async throws {
        let missing = try ClaudeCodeHarness(commandIsInstalled: false)
        defer { missing.tearDown() }
        try await missing.service.installIntegration()
        missing.presence = .unknown

        let blind = await missing.service.fetchSnapshot()
        #expect(blind.availability == .disconnected)
        #expect(blind.setupStatus == .active)
        #expect(blind.isConnected == false)
        let noCommand = try #require(blind.diagnostic)
        #expect(noCommand.contains("no `claude` command could be found"))

        // The command is installed, so telling the user to install it would mislead.
        let silent = try ClaudeCodeHarness(commandIsInstalled: true)
        defer { silent.tearDown() }
        try await silent.service.installIntegration()
        silent.presence = .unknown

        let unanswered = await silent.service.fetchSnapshot()
        #expect(unanswered.availability == .disconnected)
        let notAnswering = try #require(unanswered.diagnostic)
        #expect(notAnswering.contains("not answering"))

        // `closed` means the command answered that nothing is open: healthy, no diagnostic.
        silent.presence = .closed
        let quiet = await silent.service.fetchSnapshot()
        #expect(quiet.availability == .ready)
        #expect(quiet.diagnostic == nil)

        // The headline names no cause; the diagnostic under it names the one that happened.
        let card = ProductSettingsCopy(
            descriptor: ProductRegistry.descriptor(for: .claudeCode),
            setup: .active,
            availability: .disconnected,
            diagnostic: noCommand
        )
        #expect(!card.status.contains("Connected"))
        #expect(card.diagnostic == noCommand)
    }

    /// CC-021: the risk was anything holding the port and receiving the prompt. File permissions
    /// answer that, so the socket mode is the assertion.
    @Test @MainActor
    func theSocketIsPrivateToThisUserAndDropsWhatItCannotRead() async throws {
        let root = URL(fileURLWithPath: "/tmp")
            .appendingPathComponent("cin-listener-\(UUID().uuidString.prefix(8))")
        try FileManager.default.createDirectory(at: root, withIntermediateDirectories: true)
        defer { try? FileManager.default.removeItem(at: root) }
        let paths = HookIntegrationPaths(
            supportDirectory: root.appendingPathComponent("AS"),
            hooksConfiguration: root.appendingPathComponent("settings.json"),
            agent: .claudeCode
        )
        let repository = HookEventRepository(
            paths: paths,
            vocabulary: ClaudeCodeHookVocabulary()
        )
        let listener = AgentHookListener { body, receivedAt, descriptor in
            repository.deliver(body, at: receivedAt, on: descriptor)
        }
        defer { listener.stop() }
        let socket = root.appendingPathComponent("hook.sock")
        #expect(listener.start(socketURL: socket))
        #expect(listener.socketURL == socket)

        let mode = try #require(
            try FileManager.default.attributesOfItem(atPath: socket.path)[.posixPermissions]
                as? NSNumber
        )
        #expect(mode.int16Value & 0o077 == 0)

        // None becomes a turn, and none takes the listener down.
        try sendRaw(to: socket, bytes: Data("{ not json at all".utf8))
        try send(to: socket, body: ["hook_event_name": "Stop"])
        try send(to: socket, body: ["session_id": "s"])

        // Proven against an event that does reduce, not merely nothing processed yet.
        try send(to: socket, body: [
            "hook_event_name": "Stop", "session_id": "s", "prompt_id": "p"
        ])
        let turns = await waitForReducedTurns(repository, count: 1)
        #expect(turns.count == 1)
        #expect(turns.first?.threadID == "s")
    }

    /// CC-021: an `http` handler on an unowned port prints `connect ECONNREFUSED` per event (9 lines
    /// for a two-tool turn on 2.1.237), suppressed only for `Stop` and `SubagentStop`. So the helper
    /// must never fail and never speak. Run as Claude Code runs it: argv exec form, payload on stdin.
    @Test @MainActor
    func theHelperDeliversWhenTheAppIsUpAndIsSilentWhenItIsNot() async throws {
        let root = URL(fileURLWithPath: "/tmp")
            .appendingPathComponent("cin-helper-\(UUID().uuidString.prefix(8))")
        defer { try? FileManager.default.removeItem(at: root) }
        try FileManager.default.createDirectory(at: root, withIntermediateDirectories: true)
        let paths = HookIntegrationPaths(
            supportDirectory: root.appendingPathComponent("AS"),
            hooksConfiguration: root.appendingPathComponent("settings.json"),
            agent: .claudeCode
        )
        let setup = ManagedHooksSetup(paths: paths, vocabulary: ClaudeCodeHookVocabulary())

        // A leftover `events` directory is removed when the helper is prepared.
        try FileManager.default.createDirectory(
            at: paths.agentDirectory.appendingPathComponent("events", isDirectory: true),
            withIntermediateDirectories: true
        )

        #expect(await setup.prepareHelper())
        #expect(FileManager.default.isExecutableFile(atPath: paths.hookHelper.path))
        #expect(
            !FileManager.default.fileExists(
                atPath: paths.agentDirectory.appendingPathComponent("events").path
            )
        )

        let payload = try JSONSerialization.data(withJSONObject: [
            "hook_event_name": "PreToolUse",
            "session_id": "session-1",
            "prompt_id": "prompt-1",
            "tool_name": "Bash",
            "tool_use_id": "call-1",
            "tool_input": ["command": "rm -rf /Users/someone/private"]
        ])

        // 1. App not running: exit 0, both streams empty.
        let closed = try runHelper(at: paths.hookHelper, stdin: payload)
        #expect(closed.status == 0)
        #expect(closed.stdout.isEmpty)
        #expect(closed.stderr.isEmpty)

        // 2. App running: the same helper delivers.
        let recorder = RecordedHookDelivery()
        let listener = AgentHookListener(deliver: recorder.deliver)
        defer { listener.stop() }
        #expect(listener.start(socketURL: paths.hookSocket))

        let open = try runHelper(at: paths.hookHelper, stdin: payload)
        #expect(open.status == 0)
        // Claude Code parses stdout for directives, so it must stay empty.
        #expect(open.stdout.isEmpty)
        #expect(open.stderr.isEmpty)

        let delivered = try #require(recorder.payloads.first)
        #expect(recorder.count == 1)
        #expect(delivered["session_id"] as? String == "session-1")
        #expect(delivered["tool_use_id"] as? String == "call-1")

        // 3. The waiting form, registered only on the asking event: exit 0 and silent without an
        //    answer, but stdout is not silenced. The listener closing the connection makes the empty
        //    reply arrive immediately.
        let waiting = try runHelper(
            at: paths.hookHelper,
            stdin: payload,
            arguments: [AgentHookHelper.answeringArgument]
        )
        #expect(waiting.status == 0)
        #expect(waiting.stdout.isEmpty)
        #expect(waiting.stderr.isEmpty)
        #expect(recorder.count == 2)

        // 4. Waiting form with nothing listening: still silent, still exit 0.
        listener.stop()
        let waitingWithNobodyHome = try runHelper(
            at: paths.hookHelper,
            stdin: payload,
            arguments: [AgentHookHelper.answeringArgument]
        )
        #expect(waitingWithNobodyHome.status == 0)
        #expect(waitingWithNobodyHome.stdout.isEmpty)
        #expect(waitingWithNobodyHome.stderr.isEmpty)

        // 5. One variable keeps an agent out of the notch, on either form, with no connection attempt.
        #expect(listener.start(socketURL: paths.hookSocket))
        let suppressed = try runHelperSuppressed(at: paths.hookHelper, stdin: payload)
        #expect(suppressed.status == 0)
        #expect(suppressed.stdout.isEmpty)
        #expect(suppressed.stderr.isEmpty)
        #expect(recorder.count == 2)
    }

    /// The serial read queue preserves arrival order, so holding must be a hand-off, not a wait.
    /// Only the long-window event is held, it stays open until answered, and clearing the wait
    /// closes it by a path that knows nothing of connections.
    @Test @MainActor
    func onlyTheEventThatAsksHoldsItsConnectionAndTheWaitClosesIt() async throws {
        let root = URL(fileURLWithPath: "/tmp")
            .appendingPathComponent("cin-hold-\(UUID().uuidString.prefix(8))")
        defer { try? FileManager.default.removeItem(at: root) }
        let repository = HookEventRepository(
            paths: HookIntegrationPaths(
                supportDirectory: root.appendingPathComponent("AS"),
                hooksConfiguration: root.appendingPathComponent("settings.json"),
                agent: .claudeCode
            ),
            vocabulary: ClaudeCodeHookVocabulary()
        )

        try JSONSerialization.data(withJSONObject: [
            "hook_event_name": "UserPromptSubmit",
            "session_id": "s-1", "prompt_id": "t-1"
        ]).deliver(to: repository)
        _ = await repository.drainDeliveredEvents()

        let announcing = try SocketPair()
        #expect(
            repository.deliver(
                try JSONSerialization.data(withJSONObject: [
                    "hook_event_name": "PreToolUse",
                    "session_id": "s-1", "prompt_id": "t-1",
                    "tool_name": "Bash", "tool_use_id": "call-1",
                    "tool_input": ["command": "rm -rf /tmp/x"]
                ]),
                at: Date(),
                on: announcing.app
            ) == .close
        )

        // Held: its definition registers a window a person can answer inside.
        let asking = try SocketPair()
        #expect(
            repository.deliver(
                try JSONSerialization.data(withJSONObject: [
                    "hook_event_name": "PermissionRequest",
                    "session_id": "s-1", "prompt_id": "t-1",
                    "tool_name": "Bash",
                    "tool_input": ["command": "rm -rf /tmp/x"]
                ]),
                at: Date(),
                on: asking.app
            ) == .held
        )

        let waiting = await repository.drainDeliveredEvents()
        let request = try #require(waiting.turns.first?.requestAwaitingAnAnswer)
        // Answerable only because a connection is held, not because of the status or the product.
        #expect(request.canBeAnswered)
        #expect(!asking.isPeerClosed)

        let handle = try #require(request.answerHandle)
        let granted = await repository.answer(.grant, on: handle)
        #expect(granted == .sent)
        let sent = try #require(asking.readFromPeer())
        let decoded = try JSONSerialization.jsonObject(with: sent) as? [String: Any]
        #expect(decoded?["hookSpecificOutput"] != nil)

        // Answering does not retire the row (§8.1) but ends the connection, so the affirmative stops.
        let afterAnswer = await repository.observedState()
        let stillWaiting = try #require(afterAnswer.turns.first?.requestAwaitingAnAnswer)
        #expect(!stillWaiting.canBeAnswered)
        #expect(afterAnswer.turns.first?.sessionStatus == .approvalNeeded)

        // A wait cleared the ordinary way closes its connection without the clearing sites knowing.
        let second = try SocketPair()
        #expect(
            repository.deliver(
                try JSONSerialization.data(withJSONObject: [
                    "hook_event_name": "PermissionRequest",
                    "session_id": "s-1", "prompt_id": "t-1", "tool_name": "Bash",
                    "tool_input": ["command": "rm -rf /tmp/y"]
                ]),
                at: Date(),
                on: second.app
            ) == .held
        )
        _ = await repository.drainDeliveredEvents()
        #expect(!second.isPeerClosed)

        try JSONSerialization.data(withJSONObject: [
            "hook_event_name": "PostToolUse",
            "session_id": "s-1", "prompt_id": "t-1", "tool_use_id": "call-1"
        ]).deliver(to: repository)
        _ = await repository.drainDeliveredEvents()
        #expect(second.isPeerClosed)
    }

    /// `AskUserQuestion` raises a `PreToolUse` (the input wait), then ~25 ms later a
    /// `PermissionRequest` with no `tool_use_id`: the only connection an answer can travel on. The
    /// ticket must reach the input wait's request (measured, Claude Code 2.1.263, 2026-09-06).
    @Test @MainActor
    func aQuestionIsAnswerableOnTheConnectionItsOwnApprovalHeld() async throws {
        let root = URL(fileURLWithPath: "/tmp")
            .appendingPathComponent("cin-ask-\(UUID().uuidString.prefix(8))")
        defer { try? FileManager.default.removeItem(at: root) }
        let repository = HookEventRepository(
            paths: HookIntegrationPaths(
                supportDirectory: root.appendingPathComponent("AS"),
                hooksConfiguration: root.appendingPathComponent("settings.json"),
                agent: .claudeCode
            ),
            vocabulary: ClaudeCodeHookVocabulary()
        )

        try JSONSerialization.data(withJSONObject: [
            "hook_event_name": "UserPromptSubmit",
            "session_id": "s-1", "prompt_id": "t-1"
        ]).deliver(to: repository)
        _ = await repository.drainDeliveredEvents()

        let questions: [String: Any] = [
            "questions": [[
                "header": "Store",
                "question": "Which store should the probe write to?",
                "multiSelect": false,
                "options": [
                    ["label": "DuckDB", "description": "Columnar and fast for scans"],
                    ["label": "SQLite", "description": "One file and everywhere"]
                ]
            ]]
        ]

        // Not held: `PreToolUse` does not register an answerable window.
        let announcing = try SocketPair()
        #expect(
            repository.deliver(
                try JSONSerialization.data(withJSONObject: [
                    "hook_event_name": "PreToolUse",
                    "session_id": "s-1", "prompt_id": "t-1",
                    "tool_name": "AskUserQuestion", "tool_use_id": "ask-1",
                    "tool_input": questions
                ]),
                at: Date(),
                on: announcing.app
            ) == .close
        )

        let asking = try SocketPair()
        #expect(
            repository.deliver(
                try JSONSerialization.data(withJSONObject: [
                    "hook_event_name": "PermissionRequest",
                    "session_id": "s-1", "prompt_id": "t-1",
                    "tool_name": "AskUserQuestion",
                    "tool_input": questions
                ]),
                at: Date(),
                on: asking.app
            ) == .held
        )

        let waiting = await repository.drainDeliveredEvents()
        let turn = try #require(waiting.turns.first)
        #expect(turn.status == .inputNeeded)
        #expect(turn.requestsAwaitingAnAnswer.count == 1)
        let request = try #require(turn.requestAwaitingAnAnswer)
        guard case let .questions(asked) = request.form else {
            Issue.record("the row draws \(request.form) rather than a question")
            return
        }
        #expect(asked.first?.header == "Store")
        #expect(asked.first?.options.count == 2)
        #expect(request.canBeAnswered, "a question drawn here must be answerable")
        #expect(request.answerRow() != nil)

        // `updatedInput` is the tool's own input with the choices merged in, so the call runs.
        let handle = try #require(request.answerHandle)
        #expect(
            await repository.answer(
                .answers([
                    AgentQuestionAnswer(question: try #require(asked.first), selectedOptionIDs: [1])
                ]),
                on: handle
            ) == .sent
        )
        let sent = try #require(asking.readFromPeer())
        let decoded = try JSONSerialization.jsonObject(with: sent) as? [String: Any]
        let output = try #require(decoded?["hookSpecificOutput"] as? [String: Any])
        let decision = try #require(output["decision"] as? [String: Any])
        #expect(decision["behavior"] as? String == "allow")
        let updated = try #require(decision["updatedInput"] as? [String: Any])
        let answers = try #require(updated["answers"] as? [String: Any])
        #expect(
            answers["Which store should the probe write to?"] as? String == "SQLite"
        )
        // Handed back whole: a merge that dropped `questions` would be a different call.
        #expect(updated["questions"] != nil)
    }

    /// Against the real helper: payload on stdin, the app holds the descriptor, the reply comes out
    /// of the helper's stdout. Pins that `nc` still reads the reply after its own stdin ended.
    @Test @MainActor
    func anAnswerTravelsBackUpTheConnectionTheRequestArrivedOn() async throws {
        let root = URL(fileURLWithPath: "/tmp")
            .appendingPathComponent("cin-reply-\(UUID().uuidString.prefix(8))")
        defer { try? FileManager.default.removeItem(at: root) }
        try FileManager.default.createDirectory(at: root, withIntermediateDirectories: true)
        let paths = HookIntegrationPaths(
            supportDirectory: root.appendingPathComponent("AS"),
            hooksConfiguration: root.appendingPathComponent("settings.json"),
            agent: .claudeCode
        )
        let setup = ManagedHooksSetup(paths: paths, vocabulary: ClaudeCodeHookVocabulary())
        #expect(await setup.prepareHelper())

        let recorder = RecordedHookDelivery()
        recorder.holds = true
        let listener = AgentHookListener(deliver: recorder.deliver)
        defer { listener.stop() }
        #expect(listener.start(socketURL: paths.hookSocket))

        let decision = try #require(
            ClaudeCodeRequestAnswering().hookOutput(for: .grant, updating: nil)
        )
        let answered = Task.detached {
            for _ in 0 ..< 200 where recorder.count == 0 {
                try? await Task.sleep(for: .milliseconds(10))
            }
            return recorder.answerHeld(with: decision)
        }
        let waiting = try runHelper(
            at: paths.hookHelper,
            stdin: try JSONSerialization.data(withJSONObject: [
                "hook_event_name": "PermissionRequest",
                "session_id": "session-1",
                "tool_name": "Bash"
            ]),
            arguments: [AgentHookHelper.answeringArgument]
        )
        #expect(await answered.value)
        // The decision on stdout: the stream ADR 0013 closed and ADR 0019 reopens.
        #expect(waiting.status == 0)
        #expect(waiting.stderr.isEmpty)
        #expect(waiting.stdout == decision)
    }

    /// Both spell an approval identically. Codex documents `updatedInput` as reserved and fails a
    /// `PermissionRequest` hook closed if present, so a question is not answered there.
    @Test @MainActor
    func aQuestionIsAnsweredOnOneProductAndDeclinedOnTheOther() throws {
        let claude = ClaudeCodeRequestAnswering()
        let codex = CodexRequestAnswering()

        let grant = Data(
            #"{"hookSpecificOutput":{"decision":{"behavior":"allow"},"hookEventName":"PermissionRequest"}}"#.utf8
        )
        #expect(claude.hookOutput(for: .grant, updating: nil) == grant)
        #expect(codex.hookOutput(for: .grant, updating: nil) == grant)

        // Measured against 2.1.261: the message reaches the model as the refused tool's own error.
        let refusal = try #require(
            claude.hookOutput(for: .refuse("write it to notes/ instead"), updating: nil)
        )
        let refused = try #require(
            JSONSerialization.jsonObject(with: refusal) as? [String: Any]
        )
        let output = try #require(refused["hookSpecificOutput"] as? [String: Any])
        let decision = try #require(output["decision"] as? [String: Any])
        #expect(decision["behavior"] as? String == "deny")
        #expect(decision["message"] as? String == "write it to notes/ instead")
        #expect(codex.hookOutput(for: .refuse(nil), updating: nil) != nil)
        // `interrupt` is never written: on Codex it fails the hook closed, on Claude Code it ends the
        // Turn.
        #expect(!String(decoding: refusal, as: UTF8.self).contains("interrupt"))

        let input = JSONValue.object([
            "questions": .array([.object(["question": .string("Which one?")])]),
            "somethingElse": .string("kept")
        ])
        let answers: AgentAnswer = .answers([
            AgentQuestionAnswer(
                question: AgentQuestion(
                    id: 0, header: nil, text: "Which one?", options: [],
                    allowsSeveralAnswers: false, acceptsNote: true
                ),
                text: "The first", note: "quickly"
            )
        ])
        let sent = try #require(claude.hookOutput(for: answers, updating: input))
        let root = try #require(
            JSONSerialization.jsonObject(with: sent) as? [String: Any]
        )
        let hookOutput = try #require(root["hookSpecificOutput"] as? [String: Any])
        let allow = try #require(hookOutput["decision"] as? [String: Any])
        #expect(allow["behavior"] as? String == "allow")
        let updated = try #require(allow["updatedInput"] as? [String: Any])
        // `updatedInput` replaces the input, so every original field must survive.
        #expect(updated["somethingElse"] as? String == "kept")
        #expect(updated["questions"] != nil)
        #expect(
            (updated["answers"] as? [String: Any])?["Which one?"] as? String == "The first"
        )
        let annotations = try #require(updated["annotations"] as? [String: Any])
        #expect((annotations["Which one?"] as? [String: Any])?["notes"] as? String == "quickly")

        #expect(codex.hookOutput(for: answers, updating: input) == nil)
        // Nor is an unseen input invented: a fabricated `updatedInput` would lose every field.
        #expect(claude.hookOutput(for: answers, updating: nil) == nil)
    }

