        let asked = CountingBox()
        let ran = CountingBox()
        let focuser = AppleEventsTerminalTabFocuser(
            timeout: 60,
            permission: { _ in .undecided },
            requestConsent: { _ in asked.increment() },
            execute: { _ in
                ran.increment()
                return true
            }
