/// A clock whose waits never come due, so the store refreshes only when asked.
private struct ParkedMonitorClock: MonitorClock {
    nonisolated func now() -> Date { Date(timeIntervalSince1970: 1_000_000) }

    nonisolated func sleep(nanoseconds: UInt64) async throws {
        try await Task.sleep(nanoseconds: 60 * 60 * 1_000_000_000)
    }
}

/// A clock whose sleeper wakes on a background thread, as `Task.sleep` does. ``TestClock``
/// resumes on the caller's (main) thread, which hides a missing hop to the main actor.
private struct OffMainWakingClock: MonitorClock {
    nonisolated func now() -> Date { Date(timeIntervalSince1970: 1_000_000) }

    nonisolated func sleep(nanoseconds: UInt64) async throws {
        try await withCheckedThrowingContinuation { continuation in
            DispatchQueue.global(qos: .userInitiated).async {
                continuation.resume()
            }
        }
    }
}

private final class PublishThreadRecorder: @unchecked Sendable {
    private let lock = NSLock()
    private var publishes: [Bool] = []

    var count: Int {
        lock.lock()
        defer { lock.unlock() }
        return publishes.count
    }

    var offMainCount: Int {
        lock.lock()
        defer { lock.unlock() }
        return publishes.count { !$0 }
    }

    func record(isMain: Bool) {
        lock.lock()
        publishes.append(isMain)
        lock.unlock()
    }

    func waitForPublish(
        atLeast expected: Int = 1,
        timeout: TimeInterval = 5
    ) async throws {
        let deadline = Date().addingTimeInterval(timeout)
        while count < expected {
            guard Date() < deadline else {
                Issue.record("no publish after \(timeout)s")
                return
            }
            try await Task.sleep(nanoseconds: 500_000)
        }
    }
}

private final class PreviewWakeUpCounter: @unchecked Sendable {
    private let lock = NSLock()
    private var wakeUps = 0

    var count: Int {
        lock.lock()
        defer { lock.unlock() }
        return wakeUps
    }

    func record() {
        lock.lock()
        wakeUps += 1
        lock.unlock()
    }
}

private actor GatedMonitoringStub: AgentMonitoring, IntegrationConfiguring {
    nonisolated let agent = AgentKind.codex
    nonisolated let stateChangeEvents = AsyncStream<Void> { $0.finish() }

    private var observedSnapshots = 0
    private var status: IntegrationSetupStatus = .reviewRequired
    private var waiters: [CheckedContinuation<Void, Never>] = []
    private var holdsSnapshots = false
    private var installRequests = 0
    private var removeRequests = 0
    private var isApplyingIntegrationChange = false
    private(set) var observedOverlappingIntegrationChange = false

    func nextRefreshDeadline() async -> Date? { nil }

    func fetchSnapshot(dismissedRowIDs: Set<String>) async -> AgentSnapshot {
        observedSnapshots += 1
        if holdsSnapshots {
            await withCheckedContinuation { waiters.append($0) }
        }
        return AgentSnapshot(
            availability: .ready,
            sessions: [],
            quota: .unavailable,
            diagnostic: nil,
            setupStatus: status
        )
    }

    func setupStatus() async -> IntegrationSetupStatus { status }

    func installIntegration() async throws {
        try await applyIntegrationChange {
            installRequests += 1
            status = .reviewRequired
        }
    }

    func removeIntegration() async throws {
        try await applyIntegrationChange {
            removeRequests += 1
            status = .notInstalled
        }
    }

    private func applyIntegrationChange(
        _ body: () -> Void
    ) async throws {
        if isApplyingIntegrationChange {
            observedOverlappingIntegrationChange = true
        }
        isApplyingIntegrationChange = true
        // Yielding gives an unserialised caller a chance to interleave.
        await Task.yield()
        body()
        isApplyingIntegrationChange = false
    }

    func disconnect() async {}

    func setStatus(_ status: IntegrationSetupStatus) { self.status = status }
    func setHoldsSnapshots(_ holds: Bool) { holdsSnapshots = holds }
    func snapshotCount() -> Int { observedSnapshots }
    func installCount() -> Int { installRequests }
    func removeCount() -> Int { removeRequests }

    func releaseHeldSnapshots() {
        let held = waiters
        waiters.removeAll()
        held.forEach { $0.resume() }
    }
}

