/// The smallest root Thread payload; a Turn whose thread the App Server never handed over
/// draws nothing.
private func codexRootThread(
    id: String,
    name: String? = nil,
    preview: String? = nil,
    path: String? = nil
) -> JSONValue {
    var fields: [String: JSONValue] = [
        "id": .string(id),
        "threadSource": .string("user"),
        "ephemeral": .bool(false)
    ]
    if let name { fields["name"] = .string(name) }
    if let preview { fields["preview"] = .string(preview) }
    if let path { fields["path"] = .string(path) }
    return .object(fields)
}

private func processIsAlive(_ pid: pid_t) -> Bool {
    kill(pid, 0) == 0
}

/// Waits for something the store does on its own time. Polled, not slept: parallel
/// `@MainActor` tests share one main actor, so a fixed wait flakes in a full run.
@MainActor
private func eventually(
    within seconds: TimeInterval = 5,
    _ isTrue: @MainActor () async -> Bool
) async -> Bool {
    let deadline = Date().addingTimeInterval(seconds)
    while Date() < deadline {
        if await isTrue() { return true }
        try? await Task.sleep(nanoseconds: 20_000_000)
    }
    return await isTrue()
}

