@MainActor
private func answeringStore(
    request: AgentRequest,
    status: SessionStatus = .approvalNeeded,
    outcome: AnswerOutcome = .sent
) -> (store: MonitorStore, service: AnsweringMonitoringStub, row: MonitoredSession) {
    let row = answerableSession(status: status, request: request)
    let service = AnsweringMonitoringStub(
        agent: .claudeCode,
        sessions: [row],
        outcome: outcome
    )
    let store = MonitorStore(
        displays: [],
        services: [service],
        initialSnapshot: AgentSnapshot(
            agent: .claudeCode,
            availability: .ready,
            sessions: [row],
            quota: .unavailable,
            diagnostic: nil
        )
    )
    return (store, service, row)
}

/// A provider that publishes a fixed list and records the answer and ticket it was handed.
private actor AnsweringMonitoringStub: AgentMonitoring, IntegrationConfiguring, AnswerDelivering {
    nonisolated let agent: AgentKind
    nonisolated let stateChangeEvents = AsyncStream<Void> { $0.finish() }

    private var sessions: [MonitoredSession]
    private let outcome: AnswerOutcome
    private var answers: [AgentAnswer] = []
    private var handles: [AnswerHandle] = []
    private var holdsAnswers = false
    private var pending: CheckedContinuation<AnswerOutcome, Never>?

    init(agent: AgentKind, sessions: [MonitoredSession], outcome: AnswerOutcome = .sent) {
        self.agent = agent
        self.sessions = sessions
        self.outcome = outcome
    }

    func answersTaken() -> [AgentAnswer] { answers }
    func handlesUsed() -> [AnswerHandle] { handles }

    func publish(_ sessions: [MonitoredSession]) { self.sessions = sessions }

    func holdAnswers() { holdsAnswers = true }
    var isHoldingAnAnswer: Bool { pending != nil }
    func release(with outcome: AnswerOutcome) {
        pending?.resume(returning: outcome)
        pending = nil
    }

    func answer(_ answer: AgentAnswer, on handle: AnswerHandle) async -> AnswerOutcome {
        answers.append(answer)
        handles.append(handle)
        guard holdsAnswers else { return outcome }
        return await withCheckedContinuation { pending = $0 }
    }

    func fetchSnapshot(dismissedRowIDs: Set<String>) async -> AgentSnapshot {
        AgentSnapshot(
            agent: agent,
            availability: .ready,
            sessions: sessions,
            quota: .unavailable,
            diagnostic: nil,
            setupStatus: .active
        )
    }

    func nextRefreshDeadline() async -> Date? { nil }
    func setupStatus() async -> IntegrationSetupStatus { .active }
    func installIntegration() async throws {}
    func removeIntegration() async throws {}
    func disconnect() async {}
}

private func processDies(_ pid: pid_t, within seconds: TimeInterval) async -> Bool {
    let deadline = Date().addingTimeInterval(seconds)
    while Date() < deadline {
        if !processIsAlive(pid) { return true }
        try? await Task.sleep(nanoseconds: 20_000_000)
    }
    return !processIsAlive(pid)
}

private actor CodexAppServerStub: CodexAppServerCommunicating {
    private var listedThreads: [JSONValue]
    /// Threads `thread/read` answers for that `thread/list` does not carry: measured 2026-08-25,
    /// an `exec` thread reads back from an independent App Server and never appears in the list.
    private let readableThreads: [JSONValue]
    private let connectResult: Result<Void, CodexAppServerError>
    private var threadListError: CodexAppServerError?
    private var threadListDelayNanoseconds: UInt64
    private var threadReadDelayNanoseconds: UInt64 = 0
    /// How long `thread/items/list` takes to answer; under load a whole re-entrant refresh fits
    /// inside it, which reproduces the duplicate progress read.
    private var turnItemsDelayNanoseconds: UInt64 = 0
    private var threadReadError: CodexAppServerError?
    private var loadedListResults: [Result<JSONValue, CodexAppServerError>]
    private let supportsThreadRead: Bool
    /// Off by default: a Codex without the experimental method refuses once and is never asked
    /// again.
    private let supportsTurnItems: Bool
    /// Measured: a `legacy` `historyMode` thread answers
    /// `-32601 "thread/items/list is not supported yet"`; `paginated` threads answer normally.
    private let legacyHistoryThreadIDs: Set<String>
    private var turnItemsByTurnID: [String: [JSONValue]]
    private var methods: [String] = []
    private var threadListParams: [JSONValue] = []
    private var threadReadParams: [JSONValue] = []
    private var turnItemsParams: [JSONValue] = []
    private var completedThreadListRequests = 0
    /// `thread/read` requests that have answered, so a test can wait for the queued duplicate.
    private var completedThreadReadRequests = 0
    private var disconnects = 0
    private var connects = 0

    init(
        listedThreads: [JSONValue],
        loadedListResults: [Result<JSONValue, CodexAppServerError>],
        readableThreads: [JSONValue] = [],
        threadListDelayNanoseconds: UInt64 = 0,
        connectResult: Result<Void, CodexAppServerError> = .success(()),
        threadListError: CodexAppServerError? = nil,
        supportsThreadRead: Bool = true,
        supportsTurnItems: Bool = false,
        turnItemsByTurnID: [String: [JSONValue]] = [:],
        legacyHistoryThreadIDs: Set<String> = []
    ) {
        self.listedThreads = listedThreads
        self.readableThreads = readableThreads
        self.connectResult = connectResult
        self.threadListError = threadListError
        self.loadedListResults = loadedListResults
        self.threadListDelayNanoseconds = threadListDelayNanoseconds
        self.supportsThreadRead = supportsThreadRead
        self.supportsTurnItems = supportsTurnItems
        self.turnItemsByTurnID = turnItemsByTurnID
        self.legacyHistoryThreadIDs = legacyHistoryThreadIDs
    }

    func connect() async throws {
        connects += 1
        try connectResult.get()
    }

    func request(
        method: String,
        params: JSONValue?,
        timeoutNanoseconds: UInt64?
    ) async throws -> JSONValue {
        methods.append(method)
        switch method {
        case "thread/list":
            threadListParams.append(params ?? .null)
            if let threadListError {
                throw threadListError
            }
            if threadListDelayNanoseconds > 0 {
                try await Task.sleep(
                    nanoseconds: threadListDelayNanoseconds
                )
            }
            completedThreadListRequests += 1
            return .object([
                "data": .array(listedThreads),
                "nextCursor": .null
            ])
        case "thread/read":
            threadReadParams.append(params ?? .null)
            // Before the refusals too: an instant refusal would close the window this delay holds open.
            if threadReadDelayNanoseconds > 0 {
                try await Task.sleep(nanoseconds: threadReadDelayNanoseconds)
            }
            if let threadReadError {
                throw threadReadError
            }
            guard supportsThreadRead else {
                throw CodexAppServerError.remote(
                    code: -32601,
                    message: "Method not found: thread/read"
                )
            }
            // The real server populates `turns` only when includeTurns is true.
            let requestedID = params?["threadId"]?.stringValue
            guard let thread = (listedThreads + readableThreads).first(
                where: { $0["id"]?.stringValue == requestedID }
            ) else {
                throw CodexAppServerError.remote(
                    code: -32602,
                    message: "Unknown thread"
                )
            }
            completedThreadReadRequests += 1
            var metadata = thread.objectValue ?? [:]
            if params?["includeTurns"]?.boolValue != true {
                metadata["turns"] = .array([])
            }
            return .object(["thread": .object(metadata)])
        case "thread/items/list":
            turnItemsParams.append(params ?? .null)
            if turnItemsDelayNanoseconds > 0 {
                try await Task.sleep(nanoseconds: turnItemsDelayNanoseconds)
            }
            let threadID = params?["threadId"]?.stringValue
            guard supportsTurnItems,
                  !(threadID.map(legacyHistoryThreadIDs.contains) ?? false) else {
                // The real server sends the same code for a missing method and a `legacy` thread.
                throw CodexAppServerError.remote(
                    code: -32601,
                    message: "thread/items/list is not supported yet"
                )
            }
            let turnID = params?["turnId"]?.stringValue
            let produced = turnID.flatMap { turnItemsByTurnID[$0] } ?? []
            let ordered = params?["sortDirection"]?.stringValue == "desc"
                ? produced.reversed().map { $0 }
                : produced
            let limit = params?["limit"]?.intValue ?? ordered.count
            return .object([
                "data": .array(Array(ordered.prefix(limit))),
                "nextCursor": .null
            ])
        case "thread/loaded/list":
            guard !loadedListResults.isEmpty else {
                throw CodexAppServerError.protocolViolation(
                    "unexpected thread/loaded/list request"
                )
            }
            return try loadedListResults.removeFirst().get()
        case "account/read":
            return .object([
                "account": .object([
                    "type": .string("chatgpt"),
                    "chatgptAccountId": .string("test-account")
                ])
            ])
        case "account/rateLimits/read":
            return .object([
                "rateLimits": .object([
                    "primary": .object([
                        "usedPercent": .number(30)
                    ])
                ])
            ])
        case "account/usage/read":
            return .object([
                "summary": .object([:]),
                "dailyUsageBuckets": .array([])
            ])
        default:
            throw CodexAppServerError.remote(
                code: -32601,
                message: "Unexpected method: \(method)"
            )
        }
    }

    func disconnect() async {
        disconnects += 1
    }

    func setThreadListError(_ error: CodexAppServerError?) {
        threadListError = error
    }

    /// Transport failure for every thread, distinct from the stub's unknown-thread refusal.
    func setThreadReadError(_ error: CodexAppServerError?) {
        threadReadError = error
    }

    /// Moves a thread's rollout, as Codex does when a Turn is resumed after an interrupt; both
    /// reads answer with the current path.
    func setThreadPath(_ path: String, forThread threadID: String) {
        listedThreads = listedThreads.map { thread in
            guard thread["id"]?.stringValue == threadID,
                  var fields = thread.objectValue else {
                return thread
            }
            fields["path"] = .string(path)
            return .object(fields)
        }
    }

    func requestedMethods() -> [String] {
        methods
    }

    func requestCount(method: String) -> Int {
        methods.filter { $0 == method }.count
    }

    func recordedThreadListParams() -> [JSONValue] {
        threadListParams
    }

    func recordedThreadReadParams() -> [JSONValue] {
        threadReadParams
    }

    func recordedTurnItemsParams() -> [JSONValue] {
        turnItemsParams
    }

    func appendTurnItem(_ item: JSONValue, toTurn turnID: String) {
        turnItemsByTurnID[turnID, default: []].append(item)
    }

    func completedThreadListRequestCount() -> Int {
        completedThreadListRequests
    }

    func completedThreadReadRequestCount() -> Int {
        completedThreadReadRequests
    }

    func setThreadListDelayNanoseconds(_ delay: UInt64) {
        threadListDelayNanoseconds = delay
    }

    func setThreadReadDelayNanoseconds(_ delay: UInt64) {
        threadReadDelayNanoseconds = delay
    }

    func setTurnItemsDelayNanoseconds(_ delay: UInt64) {
        turnItemsDelayNanoseconds = delay
    }

    func disconnectCount() -> Int {
        disconnects
    }

    /// Each connect is a `codex app-server` fork-and-exec in the real client.
    func connectCount() -> Int {
        connects
    }
}

private actor RecordingAppServerClient: CodexAppServerCommunicating {
    private let base: CodexAppServerClient
    private var methods: [String] = []

    init(base: CodexAppServerClient) {
        self.base = base
    }

    func connect() async throws {
        try await base.connect()
    }

    func request(
        method: String,
        params: JSONValue?,
        timeoutNanoseconds: UInt64?
    ) async throws -> JSONValue {
        methods.append(method)
        return try await base.request(
            method: method,
            params: params,
            timeoutNanoseconds: timeoutNanoseconds
        )
    }

    func disconnect() async {
        await base.disconnect()
    }

    func requestedMethods() -> [String] {
        methods
    }

    func requestCount(method: String) -> Int {
        methods.filter { $0 == method }.count
    }
}

@MainActor
private final class CodexWorkspaceStub: CodexWorkspaceOpening {
    let applicationURL: URL?
    private(set) var requestedBundleIdentifiers: [String] = []
    private(set) var openedURL: URL?
    private(set) var openedApplicationURL: URL?

    init(applicationURL: URL?) {
        self.applicationURL = applicationURL
    }

    func applicationURL(forBundleIdentifier bundleIdentifier: String) -> URL? {
        requestedBundleIdentifiers.append(bundleIdentifier)
        return applicationURL
    }

    func open(_ url: URL, withApplicationAt applicationURL: URL) async throws {
        openedURL = url
        openedApplicationURL = applicationURL
    }
}

@MainActor
private extension Collection {
    /// Bounds-checked access: a literal-index trap kills the whole test process, while this
    /// with `#require` fails only its own test.
    nonisolated subscript(checked offset: Int) -> Element? {
        guard offset >= 0, offset < count else { return nil }
        return self[index(startIndex, offsetBy: offset)]
    }
}

private final class ClaudeCodeHarness {
    let root: URL
    let paths: HookIntegrationPaths
    let setup: ManagedHooksSetup
    let service: ClaudeCodeMonitorService
    /// Each harness has its own support directory and socket, so parallel harnesses cannot
    /// collide (CC-014).
    private let listener: AgentHookListener
    let repository: HookEventRepository
    private let listing = StubSessionListing()
    private let readState: CountingClaudeReadState
    private let activationStub = StubDesktopActivation()
    private let readingStub = StubDesktopReading()
    private let terminalStub = StubControllingTerminalGestures()
    private let screenStub = StubScreenAvailability()

    /// `true` unless a test says otherwise, so re-check deadlines do not depend on whether the
    /// developer's screen is locked.
    var screenIsAvailable: Bool {
        get { screenStub.isAvailable() }
        set { screenStub.available = newValue }
    }

    func announceScreenAvailable() {
        screenStub.available = true
        screenStub.announce()
    }

    /// When the user was last at a session's terminal, by pid; no entry means no controlling
    /// terminal. Setting here also marks the terminal's application as in front; the other case
    /// uses ``setTerminalGesture(_:forPID:hostIsInFront:hostCanEverBeInFront:)``.
    var lastTerminalGestureByPID: [Int32: Date] {
        get { terminalStub.readingByPID.mapValues(\.lastGesture) }
        set {
            terminalStub.readingByPID = newValue.mapValues {
                ControllingTerminalReading(
                    lastGesture: $0,
                    hostIsInFrontOfTheUser: true,
                    hostCanEverBeInFrontOfTheUser: true
                )
            }
        }
    }

    /// - Parameter hostCanEverBeInFront: `false` is a session under `tmux`, `screen` or `ssh`,
    ///   whose ancestry runs to `launchd`, so no gesture can coincide with a front.
    func setTerminalGesture(
        _ at: Date,
        forPID pid: Int32,
        hostIsInFront: Bool,
        hostCanEverBeInFront: Bool = true
    ) {
        terminalStub.readingByPID[pid] = ControllingTerminalReading(
            lastGesture: at,
            hostIsInFrontOfTheUser: hostIsInFront,
            hostCanEverBeInFrontOfTheUser: hostCanEverBeInFront
        )
    }

    var readStateReadings: Int { readState.readings }

    /// `nil` is the state a freshly launched app is in.
    var desktopActivatedAt: Date? {
        get { activationStub.lastActivatedAt }
        set { activationStub.lastActivatedAt = newValue }
    }

    /// `false` is the state a freshly launched app is in.
    var desktopIsInFrontOfTheUser: Bool {
        get { readingStub.isInFront }
        set { readingStub.isInFront = newValue }
    }

    /// Inside the harness's own support directory, so parallel tests cannot reach each other's.
    var hookSocket: URL { paths.hookSocket }

    var live: [ClaudeCodeSession] {
        get { listing.sessions }
        set { listing.sessions = newValue }
    }

    /// Set it before an event's stamp to model a session that exists and is not listed.
    var listReadStartedAt: Date {
        get { listing.readStartedAt }
        set { listing.readStartedAt = newValue }
    }

    var liveAfterInvalidation: [ClaudeCodeSession]? {
        get { listing.sessionsAfterInvalidation }
        set { listing.sessionsAfterInvalidation = newValue }
    }

    var presence: AgentPresence? {
        get { listing.presenceOverride }
        set { listing.presenceOverride = newValue }
    }

    /// Not created here: it does not exist until Claude Code has run once.
    var sessionsDirectory: URL {
        root.appendingPathComponent("sessions", isDirectory: true)
    }

    /// Claude Desktop's own log. Not created here: a missing file answers `unknown`.
    nonisolated static func desktopLogURL(in root: URL) -> URL {
        root.appendingPathComponent("desktop-main.log")
    }

    var desktopLogURL: URL { ClaudeCodeHarness.desktopLogURL(in: root) }

    /// Not created here: a user who has never opened Claude Desktop has no tree.
    var desktopAccountDirectory: URL {
        root
            .appendingPathComponent("claude-code-sessions", isDirectory: true)
            .appendingPathComponent("org-1", isDirectory: true)
            .appendingPathComponent("account-1", isDirectory: true)
    }

    var invalidations: Int { listing.invalidations }

    var watchedRecords: Int { service.recordWatcher.watchedCount }

    var watchedTranscripts: Int { service.transcriptWatcher.watchedCount }

    /// Counts rather than the change stream: only the two directory watchers and their first
    /// attach call ``ClaudeCodeSessionListing/invalidate()``; the stream also carries hook and
    /// quota edges.
    func invalidationsRise(above count: Int, within seconds: Double = 3) async -> Bool {
        let deadline = Date().addingTimeInterval(seconds)
        while Date() < deadline {
            if invalidations > count { return true }
            try? await Task.sleep(nanoseconds: 50_000_000)
        }
        return invalidations > count
    }

    /// - Parameters:
    ///   - ownedSessionRecords: Sessions-directory entries treated as a `claude` the app launched;
    ///     named, because launching one would run the user's real Claude Code.
    ///   - usage: The quota reader; the default answers nothing and runs no command.
    /// - Parameter commandIsInstalled: `true` unless a test says otherwise, never the developer's
    ///   installed `claude`.
    init(
        ownedSessionRecords: Set<String> = [],
        usage: ClaudeCodeUsageReader = .silent(),
        commandIsInstalled: Bool = true
    ) throws {
        root = URL(fileURLWithPath: "/tmp")
            .appendingPathComponent("cin-svc-\(UUID().uuidString.prefix(8))")
        try FileManager.default.createDirectory(at: root, withIntermediateDirectories: true)
        paths = HookIntegrationPaths(
            supportDirectory: root.appendingPathComponent("AS"),
            hooksConfiguration: root.appendingPathComponent("settings.json"),
            agent: .claudeCode
        )
        setup = ManagedHooksSetup(paths: paths, vocabulary: ClaudeCodeHookVocabulary())
        readState = CountingClaudeReadState(
            wrapping: ClaudeCodeDesktopReadStateRepository(
                stateDirectoryURL: root.appendingPathComponent(
                    "claude-code-sessions",
                    isDirectory: true
                ),
                changeDebounceInterval: 0.01
            )
        )
        let store = HookEventRepository(
            paths: paths,
            vocabulary: ClaudeCodeHookVocabulary()
        )
        repository = store
        listener = AgentHookListener { body, receivedAt, descriptor in
            store.deliver(body, at: receivedAt, on: descriptor)
        }
        service = ClaudeCodeMonitorService(
            paths: paths,
            setup: setup,
            hookEvents: store,
            sessions: listing,
            listener: listener,
            transcripts: ClaudeCodeTranscriptReader(
                projectsDirectory: root.appendingPathComponent("projects", isDirectory: true)
            ),
            // Injected (see `ClaudeCodeUsageReader.silent()`): the default runs a real `/usage` and leaves
            // a transcript folder in the real `~/.claude/projects`.
            usage: usage,
            // Real adapter over this harness's tree; the default reads the machine's Claude Desktop state.
            readState: readState,
            activations: activationStub,
            // Injected: the real one reads whether Claude Desktop is in front on this machine.
            reading: readingStub,
            // Real reader over the harness's own log; absent until a test writes to it.
            displayed: ClaudeDesktopFocusLogReader(
                logURL: ClaudeCodeHarness.desktopLogURL(in: root)
            ),
            // Real, so it parses Claude Desktop's actual line shapes rather than the test's idea of them.
            permissions: ClaudeDesktopPermissionLogReader(
                logURL: ClaudeCodeHarness.desktopLogURL(in: root)
            ),
            permissionLogURL: ClaudeCodeHarness.desktopLogURL(in: root),
            // Injected: the real reader resolves each session's controlling terminal on this machine.
            terminalGestures: terminalStub,
            // Injected: the real one reads this machine's display and lock state.
            screenAvailability: screenStub,
            sessionsDirectory: root.appendingPathComponent("sessions", isDirectory: true),
            ownsSessionRecord: { ownedSessionRecords.contains($0) },
            commandIsInstalled: { commandIsInstalled }
        )
    }

    /// - Parameter lastFocusedAt: Seconds since the epoch, the same scale as the hook events.
    func writeDesktopRecord(
        session: String,
        lastFocusedAt: Double?,
        isArchived: Bool = false,
        desktopID: String = UUID().uuidString,
        namesItself: Bool = true
    ) throws {
        try FileManager.default.createDirectory(
            at: desktopAccountDirectory,
            withIntermediateDirectories: true
        )
        var record: [String: Any] = [
            "cliSessionId": session,
            "cwd": "/Users/someone/Projects/thing",
            "title": "Something the user typed",
            "isArchived": isArchived
        ]
        if let lastFocusedAt {
            record["lastFocusedAt"] = lastFocusedAt * 1_000
        }
        // Desktop's own id, which its log names. `namesItself: false` models a record that stopped
        // carrying it, so the log can no longer be joined.
        if namesItself {
            record["sessionId"] = "local_\(desktopID)"
        }
        try JSONSerialization.data(withJSONObject: record).write(
            to: desktopAccountDirectory
                .appendingPathComponent("local_\(desktopID).json"),
            options: .atomic
        )
    }

    /// - Parameter desktopID: Without the `local_` prefix. `nil` writes `sessionId=null`, which
    ///   Desktop writes for a non-session view (a new composer, the home view).
    func appendDesktopFocusStatement(desktopID: String?) throws {
        let identifier = desktopID.map { "local_\($0)" } ?? "null"
        let line = "2026-08-19 21:04:18 [info] "
            + "[CCD] LocalSessions.setFocusedSession: sessionId=\(identifier)\n"
        try append(toDesktopLog: line)
    }

    /// Appends the three lines Claude Desktop writes around one permission dialog, as captured
    /// 2026-08-23; the unread middle line stays in on purpose.
    ///
    /// - Parameter answeredAt: `nil` leaves the dialog open, which must not end a wait.
    func appendDesktopPermissionDialog(
        requestID: String = UUID().uuidString,
        desktopID: String,
        tool: String = "Bash",
        raisedAt: Double,
        answeredAt: Double?
    ) throws {
        func stamp(_ seconds: Double) -> String {
            let formatter = DateFormatter()
            formatter.locale = Locale(identifier: "en_US_POSIX")
            formatter.dateFormat = "yyyy-MM-dd HH:mm:ss"
            return formatter.string(from: Date(timeIntervalSince1970: seconds))
        }
        var text = "\(stamp(raisedAt)) [info] Emitted tool permission request "
            + "\(requestID) for \(tool) in session local_\(desktopID)\n"
        if let answeredAt {
            text += "\(stamp(answeredAt)) [info] "
                + "LocalSessions.respondToToolPermission: requestId=\(requestID), "
                + "decision=once, hasUpdatedInput=true\n"
            text += "\(stamp(answeredAt)) [info] Received permission response for "
                + "\(requestID): once (tool: \(tool))\n"
        }
        try append(toDesktopLog: text)
    }

    var watchedPermissionLogs: Int { service.permissionLogWatcher.watchedCount }

    func append(toDesktopLog text: String) throws {
        let data = Data(text.utf8)
        guard let handle = try? FileHandle(forWritingTo: desktopLogURL) else {
            try data.write(to: desktopLogURL)
            return
        }
        defer { try? handle.close() }
        try handle.seekToEnd()
        try handle.write(contentsOf: data)
    }

    func writeUnreadableDesktopRecord(named name: String = UUID().uuidString) throws {
        try FileManager.default.createDirectory(
            at: desktopAccountDirectory,
            withIntermediateDirectories: true
        )
        try Data("{\"sessionId\": \"local_x\"}".utf8).write(
            to: desktopAccountDirectory.appendingPathComponent("local_\(name).json")
        )
    }

    func tearDown() {
        // Unlinks the socket; otherwise each harness held its descriptor until the process exited.
        listener.stop()
        try? FileManager.default.removeItem(at: root)
    }

    /// The registration this build writes, asked of the product so the fixture cannot drift into
    /// `repairRequired`.
    func registerHooks() throws {
        let configuration = ManagedHooksSetup(paths: paths, vocabulary: ClaudeCodeHookVocabulary()).configuration
        var hooks: [String: Any] = [:]
        for definition in configuration.definitions {
            hooks[definition.event] = [["hooks": [configuration.handler(for: definition)]]]
        }
        try JSONSerialization
            .data(withJSONObject: ["theme": "auto", "hooks": hooks])
            .write(to: paths.hooksConfiguration)
    }

    /// Writes the legacy block pointing every event at an HTTP handler this build no longer
    /// installs.
    func registerLegacyHTTPHooks(port: UInt16 = 51_741) throws {
        var hooks: [String: Any] = [:]
        let handler: [String: Any] = [
            "type": "http",
            "url": "http://127.0.0.1:\(port)\(ClaudeCodeHookVocabulary.legacyHookPath)",
            "timeout": 5,
            "headers": ["Authorization": "Bearer whatever-they-pasted"]
        ]
        for definition in ClaudeCodeHookVocabulary().managedDefinitions {
            hooks[definition.event] = [["hooks": [handler]]]
        }
        try JSONSerialization
            .data(withJSONObject: ["theme": "auto", "hooks": hooks])
            .write(to: paths.hooksConfiguration)
    }

    /// - Parameter agentID: Claude Code stamps a subagent's hooks with the parent's `session_id`
    ///   and `prompt_id`, so this is the only thing separating them.
    /// - Parameter prompt: What the user typed, as `UserPromptSubmit` carries it.
    func queue(
        event: String,
        session: String,
        turn: String,
        at received: Double,
        toolName: String? = nil,
        toolUseID: String? = nil,
        agentID: String? = nil,
        prompt: String? = nil
    ) throws {
        var payload: [String: Any] = [
            "event_id": UUID().uuidString,
            "received_at": received,
            "hook_event_name": event,
            "session_id": session,
            "turn_id": turn
        ]
        if let prompt { payload["prompt"] = prompt }
        if let toolName { payload["tool_name"] = toolName }
        if let toolUseID { payload["tool_use_id"] = toolUseID }
        if let agentID { payload["agent_id"] = agentID }
        try JSONSerialization.data(withJSONObject: payload)
            .deliver(to: repository)
    }

    /// RFC 3339, UTC, fractional seconds, on the hook events' scale of seconds.
    static func transcriptInstant(_ seconds: Double) -> String {
        let formatter = ISO8601DateFormatter()
        formatter.formatOptions = [.withInternetDateTime, .withFractionalSeconds]
        formatter.timeZone = TimeZone(secondsFromGMT: 0)
        return formatter.string(from: Date(timeIntervalSince1970: seconds))
    }

    /// The record Claude Code writes when it aborts a Turn, field for field as captured from
    /// 2.1.237; the rule reads only its shape and Turn.
    func interruptRecord(turn: String, at seconds: Double) -> [String: Any] {
        [
            "parentUuid": UUID().uuidString,
            "isSidechain": false,
            "promptId": turn,
            "type": "user",
            "uuid": UUID().uuidString,
            "timestamp": ClaudeCodeHarness.transcriptInstant(seconds),
            "userType": "external",
            "entrypoint": "claude-desktop",
            "cwd": "/Users/someone/Projects/thing",
            "sessionId": "whatever",
            "version": "2.1.237",
            "gitBranch": "master",
            "message": [
                "role": "user",
                "content": [["type": "text", "text": "[Request interrupted by user]"]]
            ]
        ]
    }

    func writeTranscript(session: String, cwd: String, title: String) throws {
        try writeTranscript(session: session, cwd: cwd, records: [
            ["type": "ai-title", "aiTitle": title]
        ])
    }

    func writeTranscript(session: String, cwd: String, records: [[String: Any]]) throws {
        let project = root
            .appendingPathComponent("projects", isDirectory: true)
            .appendingPathComponent(cwd.replacingOccurrences(of: "/", with: "-"),
                                    isDirectory: true)
        try FileManager.default.createDirectory(at: project, withIntermediateDirectories: true)
        let lines = try records.map {
            String(decoding: try JSONSerialization.data(withJSONObject: $0), as: UTF8.self)
        }
        try Data((lines.joined(separator: "\n") + "\n").utf8)
            .write(to: project.appendingPathComponent("\(session).jsonl"))
    }

    /// - Parameters:
    ///   - activity: `nil` must keep working: every desktop-hosted session reports no activity.
    ///   - observedAt: Seconds since the epoch, on the same scale as
    ///     ``queue(event:session:turn:at:toolName:toolUseID:)``.
    func session(
        id: String,
        cwd: String,
        activity: ClaudeCodeActivity.State? = nil,
        observedAt: Double = 1_000,
        pid: Int32 = 1
    ) -> ClaudeCodeSession {
        ClaudeCodeSession(
            sessionID: id,
            processIdentifier: pid,
            workingDirectory: URL(fileURLWithPath: cwd),
            startedAt: Date(timeIntervalSince1970: 100),
            name: nil,
            activity: activity.map {
                ClaudeCodeActivity(
                    state: $0,
                    observedAt: Date(timeIntervalSince1970: observedAt)
                )
            }
        )
    }
}

/// Lets a registry's read closure, injected at `init`, call back into the registry.
private final class RegistryHolder: @unchecked Sendable {
    var registry: ClaudeCodeSessionRegistry?
}

private final class StubDesktopActivation: DesktopActivationReporting, @unchecked Sendable {
    var lastActivatedAt: Date?
    func lastActivation() async -> Date? { lastActivatedAt }
    func changeEvents() -> AsyncStream<Void> { AsyncStream { $0.finish() } }
}

/// An unknown pid answers `nil`: no controlling terminal, which keeps a row listed.
private final class StubControllingTerminalGestures:
    ControllingTerminalGestureReporting, @unchecked Sendable {
    var readingByPID: [Int32: ControllingTerminalReading] = [:]

    func reading(
        forProcessIdentifier pid: Int32
    ) async -> ControllingTerminalReading? {
        readingByPID[pid]
    }
}

private final class CallCounter: @unchecked Sendable {
    private let lock = NSLock()
    private var stored = 0

    var count: Int {
        lock.lock()
        defer { lock.unlock() }
        return stored
    }

    func record() {
        lock.lock()
        stored += 1
        lock.unlock()
    }
}

private final class StubProcessTable: @unchecked Sendable {
    private let lock = NSLock()
    private var startedAt: [Int32: Date]

    init(_ startedAt: [Int32: Date] = [:]) {
        self.startedAt = startedAt
    }

    var reader: @Sendable (Int32) -> Date? {
        { pid in
            self.lock.lock()
            defer { self.lock.unlock() }
            return self.startedAt[pid]
        }
    }

    func set(_ pid: Int32, _ startedAt: Date?) {
        lock.lock()
        defer { lock.unlock() }
        self.startedAt[pid] = startedAt
    }
}

/// Registry tests use `pid: 1`, `pid: 2`…, which are live system processes on a real machine;
/// nil is also the registry's fail-closed answer.
private let noProcessIsVouchedFor: @Sendable (Int32) -> Date? = { _ in nil }

private final class StubScreenAvailability:
    ScreenAvailabilityReporting, @unchecked Sendable {
    private let lock = NSLock()
    nonisolated(unsafe) private var stored = true
    nonisolated(unsafe) private var continuations: [
        UUID: AsyncStream<Void>.Continuation
    ] = [:]

    var available: Bool {
        get { lock.lock(); defer { lock.unlock() }; return stored }
        set { lock.lock(); stored = newValue; lock.unlock() }
    }

    /// Readings taken: the only way to tell a parked timer from one firing and declining to
    /// sample (``theConcealmentTimerIsParkedWhileThereIsNoScreen``).
    var readCount: Int {
        lock.lock()
        defer { lock.unlock() }
        return reads
    }
    nonisolated(unsafe) private var reads = 0

    /// Makes the next reading the last false one: after an unlock, `loginwindow` posts the
    /// notification before the session dictionary behind ``isAvailable()`` agrees.
    var becomesAvailableAfterOneReading: Bool {
        get { lock.lock(); defer { lock.unlock() }; return catchesUp }
        set { lock.lock(); catchesUp = newValue; lock.unlock() }
    }
    nonisolated(unsafe) private var catchesUp = false

    func isAvailable() -> Bool {
        lock.lock()
        reads += 1
        let answer = stored
        if catchesUp {
            stored = true
            catchesUp = false
        }
        lock.unlock()
        return answer
    }

    func changeEvents() -> AsyncStream<Void> {
        AsyncStream(bufferingPolicy: .bufferingNewest(1)) { continuation in
            let identifier = UUID()
            lock.lock()
            continuations[identifier] = continuation
            lock.unlock()
            continuation.onTermination = { [weak self] _ in
                guard let self else { return }
                lock.lock()
                continuations.removeValue(forKey: identifier)
                lock.unlock()
            }
        }
    }

    func announce() {
        lock.lock()
        let continuations = Array(self.continuations.values)
        lock.unlock()
        continuations.forEach { $0.yield(()) }
    }
}

/// The real read-state adapter, counting reads: a skipped reading and a no-op one produce the
/// same rows (``theClaudeReadStateIsNotReadWhileNoRowHasFinished``).
private final class CountingClaudeReadState: ClaudeCodeReadStateProviding,
                                             @unchecked Sendable {
    private let wrapped: ClaudeCodeDesktopReadStateRepository
    var readings = 0

    init(wrapping wrapped: ClaudeCodeDesktopReadStateRepository) {
        self.wrapped = wrapped
    }

    func snapshot() async -> ClaudeCodeReadStateSnapshot {
        readings += 1
        return await wrapped.snapshot()
    }

    nonisolated func changeEvents() -> AsyncStream<Void> { wrapped.changeEvents() }
}

private final class StubDesktopReading: DesktopReadingReporting, @unchecked Sendable {
    /// `false` covers another front application, a sleeping display, a locked screen, a
    /// screensaver, or another user switched in.
    var isInFront = false
    func isInFrontOfTheUser() async -> Bool { isInFront }
}

/// A machine's `claude` installs inside a throwaway directory. ``ClaudeExecutableLocator``
/// reaches three absolute paths and the home, so ``ScopedFileManager`` confines both.
private struct ClaudeInstallLayout {
    let root: URL
    let fileManager: ScopedFileManager

    init() throws {
        root = FileManager.default.temporaryDirectory
            .appendingPathComponent("cin-claude-\(UUID().uuidString.prefix(8))", isDirectory: true)
        try FileManager.default.createDirectory(at: root, withIntermediateDirectories: true)
        fileManager = ScopedFileManager(
            root: root,
            home: root.appendingPathComponent("home", isDirectory: true)
        )
    }

    func tearDown() {
        try? FileManager.default.removeItem(at: root)
    }

    func url(_ relativePath: String) -> URL {
        root.appendingPathComponent(relativePath)
    }

    /// Compares resolved files, not strings: `/var` symlinks to `/private/var`, and which
    /// spelling comes back is unstable (passed alone, failed in the full suite).
    func isSameFile(_ lhs: URL, as rhs: URL) -> Bool {
        lhs.resolvingSymlinksInPath().standardizedFileURL
            == rhs.resolvingSymlinksInPath().standardizedFileURL
    }

    /// Claude Desktop's application-support root, moved by the same override its session records
    /// honour.
    var desktopHome: URL {
        url("desktop")
    }

    func desktopBundledClaude(version: String) -> URL {
        desktopHome
            .appendingPathComponent("claude-code", isDirectory: true)
            .appendingPathComponent(version, isDirectory: true)
            .appendingPathComponent("claude.app/Contents/MacOS/claude")
    }

    func environment(path: [URL] = []) -> [String: String] {
        [
            ClaudeCodeDesktopReadStateRepository.homeOverrideKey: desktopHome.path,
            "PATH": path.map(\.path).joined(separator: ":")
        ]
    }

    @discardableResult
    func writeDesktopBundledClaude(version: String) throws -> URL {
        try write(executableAt: desktopBundledClaude(version: version))
    }

    @discardableResult
    func writeExecutable(at relativePath: String) throws -> URL {
        try write(executableAt: url(relativePath))
    }

    private func write(executableAt destination: URL) throws -> URL {
        try FileManager.default.createDirectory(
            at: destination.deletingLastPathComponent(),
            withIntermediateDirectories: true
        )
        try Data("#!/bin/sh\nexit 0\n".utf8).write(to: destination)
        try FileManager.default.setAttributes(
            [.posixPermissions: 0o755],
            ofItemAtPath: destination.path
        )
        return destination
    }
}

private final class ScopedFileManager: FileManager, @unchecked Sendable {
    /// Resolved once; incoming paths are spelled differently (``ClaudeInstallLayout/isSameFile(_:as:)``).
    private let rootPath: String
    private let home: URL

    init(root: URL, home: URL) {
        rootPath = root.resolvingSymlinksInPath().standardizedFileURL.path
        self.home = home
        super.init()
    }

    override var homeDirectoryForCurrentUser: URL { home }

    /// Nothing outside the root is executable, keeping the developer's `/opt/homebrew/bin/claude`
    /// out.
    override func isExecutableFile(atPath path: String) -> Bool {
        let resolved = URL(fileURLWithPath: path)
            .resolvingSymlinksInPath()
            .standardizedFileURL
            .path
        guard resolved.hasPrefix(rootPath + "/") else { return false }
        return super.isExecutableFile(atPath: path)
    }
}

private final class StubSessionListing: ClaudeCodeSessionListing, @unchecked Sendable {
    var sessions: [ClaudeCodeSession] = []
    var invalidations = 0
    /// Set when the list and presence must disagree, as the real registry reports once reads
    /// have failed past the trust ceiling.
    var presenceOverride: AgentPresence?
    /// `.distantFuture` by default (an in-memory list is current). Set it before an event to model
    /// a list read too early to know that session.
    var readStartedAt: Date = .distantFuture
    /// Left nil, an invalidation changes nothing.
    var sessionsAfterInvalidation: [ClaudeCodeSession]?
    func liveSessions() async -> [ClaudeCodeSession] { sessions }
    func presence() async -> AgentPresence {
        presenceOverride ?? (sessions.isEmpty ? .closed : .open)
    }
    func invalidate() async {
        invalidations += 1
        if let sessionsAfterInvalidation {
            sessions = sessionsAfterInvalidation
            readStartedAt = .distantFuture
            self.sessionsAfterInvalidation = nil
        }
    }
    func listReadStartedAt() async -> Date { readStartedAt }
}

private actor ReadCounter {
    private(set) var count = 0
    private var answer: Data?

    init(answer: Data? = nil) { self.answer = answer }

    func read() -> Data? {
        count += 1
        return answer
    }

    func respond(with data: Data?) { answer = data }
}

private actor UpdateCounter {
    private(set) var count = 0

    func record() { count += 1 }
}

/// A quota reading a test can hold open, and count: ``AgentDiskFootprintReport/measuring``
/// exists only while a reading is out.
///
/// - Parameter open: `false` holds every reading at ``hold()`` until ``release()``.
private actor HeldReading {
    private var isOpen: Bool
    private(set) var count = 0
    private var releaseWaiters: [CheckedContinuation<Void, Never>] = []
    private var arrivalWaiters: [CheckedContinuation<Void, Never>] = []

    init(open: Bool = false) {
        isOpen = open
    }

    func hold() async {
        count += 1
        arrivalWaiters.forEach { $0.resume() }
        arrivalWaiters.removeAll()
        guard !isOpen else { return }
        await withCheckedContinuation { releaseWaiters.append($0) }
    }

    func waitUntilReading(_ wanted: Int = 1) async {
        while count < wanted {
            await withCheckedContinuation { arrivalWaiters.append($0) }
        }
    }

    func release() {
        isOpen = true
        releaseWaiters.forEach { $0.resume() }
        releaseWaiters.removeAll()
    }

    func rearm() {
        isOpen = false
    }
}

