/// A provider that keeps asking for a re-check while one of its rows is unread, and stops
/// once told the user removed that row. No terminal gate, so only the removal is tested.
private actor RowRemovalMonitoringStub: AgentMonitoring, IntegrationConfiguring {
    nonisolated let agent: AgentKind
    nonisolated let stateChangeEvents = AsyncStream<Void> { $0.finish() }

    private let row: MonitoredSession
    private let recheck: Date
    private var removed: Set<String> = []

    init(agent: AgentKind, row: MonitoredSession, recheck: Date) {
        self.agent = agent
        self.row = row
        self.recheck = recheck
    }

    func rowsRemovedByTheUser() -> Set<String> { removed }

    func fetchSnapshot(dismissedRowIDs: Set<String>) async -> AgentSnapshot {
        removed = dismissedRowIDs
        return AgentSnapshot(
            agent: agent,
            availability: .ready,
            // Reported either way: withholding a removed row would tell the store the Turn had ended.
            sessions: [row],
            quota: .unavailable,
            diagnostic: nil,
            setupStatus: .active
        )
    }

    func nextRefreshDeadline() async -> Date? {
        removed.contains(row.id) ? nil : recheck
    }

    func setupStatus() async -> IntegrationSetupStatus { .active }
    func installIntegration() async throws {}
    func removeIntegration() async throws {}
    func disconnect() async {}
}

private actor HoldableMonitoringStub: AgentMonitoring, IntegrationConfiguring {
    nonisolated let agent: AgentKind
    nonisolated let stateChangeEvents = AsyncStream<Void> { $0.finish() }

    private let snapshot: AgentSnapshot
    private let deadline: Date?
    private var isHeld: Bool
    private var waiters: [CheckedContinuation<Void, Never>] = []

    init(
        agent: AgentKind,
        sessions: [MonitoredSession] = [],
        availability: MonitorAvailability = .ready,
        setupStatus: IntegrationSetupStatus = .active,
        deadline: Date? = nil,
        heldOpen: Bool = false
    ) {
        self.agent = agent
        self.deadline = deadline
        self.isHeld = heldOpen
        self.snapshot = AgentSnapshot(
            agent: agent,
            availability: availability,
            sessions: sessions,
            quota: .unavailable,
            diagnostic: nil,
            setupStatus: setupStatus
        )
    }

    func release() {
        isHeld = false
        waiters.forEach { $0.resume() }
        waiters.removeAll()
    }

    func nextRefreshDeadline() async -> Date? { deadline }

    func fetchSnapshot(dismissedRowIDs: Set<String>) async -> AgentSnapshot {
        if isHeld {
            await withCheckedContinuation { waiters.append($0) }
        }
        return snapshot
    }

    func setupStatus() async -> IntegrationSetupStatus { snapshot.setupStatus }
    func installIntegration() async throws {}
    func removeIntegration() async throws {}
    func disconnect() async {}
}

