private final class IntervalBox: @unchecked Sendable {
    private let lock = NSLock()
    private var interval: TimeInterval?

    func record(_ value: TimeInterval) {
        lock.lock()
        interval = value
        lock.unlock()
    }

    var value: TimeInterval? {
        lock.lock()
        defer { lock.unlock() }
        return interval
    }
}

private final class CountingBox: @unchecked Sendable {
    private let lock = NSLock()
    private var count = 0

    func increment() {
        lock.lock()
        count += 1
        lock.unlock()
    }

    var value: Int {
        lock.lock()
        defer { lock.unlock() }
        return count
    }
}

