extension NotchlineTests {
    /// A Completed unread row still books a re-check: reading arrives only as a watcher hint
    /// (traced at eight seconds late). The deadline is measured from `now`, not the terminal
    /// boundary, which the store would clamp to its one-second floor forever.
    @Test
    func terminalGateBooksARecheckWhileARowIsStillUnread() {
        var gate = TerminalUnreadMembershipGate(
            settlingInterval: 2,
            unreadRecheckInterval: 1
        )
        let start = Date(timeIntervalSince1970: 1_000)
        let unread = desktopReading(unread: ["thread"], after: start)

        let displayedAtOnce = gate.shouldDisplay(
            sessionID: "thread:turn", threadID: "thread", status: .completed,
            turnEndedAt: start,
            terminalBoundaryAt: start, unreadState: unread, now: start
        )
        #expect(displayedAtOnce)

        let later = start.addingTimeInterval(600)
        let stillDisplayed = gate.shouldDisplay(
            sessionID: "thread:turn", threadID: "thread", status: .completed,
            turnEndedAt: start,
            terminalBoundaryAt: start, unreadState: unread, now: later
        )
        #expect(stillDisplayed, "an unread terminal row stays listed")

        let deadline = gate.nextDeadline(now: later)
        #expect(
            deadline == later.addingTimeInterval(1),
            "an unread row must book a re-check, not go unwatched: got \(String(describing: deadline?.timeIntervalSince(later)))"
        )
        #expect(
            deadline.map { $0 > later } == true,
            "a deadline already in the past is the busy loop this replaced"
        )
    }

    /// The re-check moves forward with each look, so it never goes stale.
    @Test
    func terminalGateRecheckMovesForwardOnEveryLook() {
        var gate = TerminalUnreadMembershipGate(
            settlingInterval: 2,
            unreadRecheckInterval: 1
        )
        let start = Date(timeIntervalSince1970: 1_000)
        let unread = desktopReading(unread: ["thread"], after: start)

        _ = gate.shouldDisplay(
            sessionID: "thread:turn", threadID: "thread", status: .completed,
            turnEndedAt: start,
            terminalBoundaryAt: start, unreadState: unread, now: start
        )
        let first = gate.nextDeadline(now: start)

        let woken = start.addingTimeInterval(1)
        _ = gate.shouldDisplay(
            sessionID: "thread:turn", threadID: "thread", status: .completed,
            turnEndedAt: start,
            terminalBoundaryAt: start, unreadState: unread, now: woken
        )
        let second = gate.nextDeadline(now: woken)

        #expect(first == start.addingTimeInterval(1))
        #expect(second == woken.addingTimeInterval(1))
        #expect(
            second.map { $0 > woken } == true,
            "the re-check must stay ahead of the refresh that served it"
        )
    }

    /// Once Desktop reports the thread read, the row hides on that evaluation.
    @Test
    func terminalGateHidesOnTheFirstLookAfterTheUserReadsIt() {
        var gate = TerminalUnreadMembershipGate(
            settlingInterval: 2,
            unreadRecheckInterval: 1
        )
        let start = Date(timeIntervalSince1970: 1_000)
        let unread = desktopReading(unread: ["thread"], after: start)
        let read = desktopReading(unread: [], after: start)

        _ = gate.shouldDisplay(
            sessionID: "thread:turn", threadID: "thread", status: .completed,
            turnEndedAt: start,
            terminalBoundaryAt: start, unreadState: unread, now: start
        )

        let readAt = start.addingTimeInterval(600)
        let displayed = gate.shouldDisplay(
            sessionID: "thread:turn", threadID: "thread", status: .completed,
            turnEndedAt: start,
            terminalBoundaryAt: start, unreadState: read, now: readAt
        )
        #expect(!displayed, "a row observed unread hides the moment it reads as read")
        #expect(
            gate.nextDeadline(now: readAt) == nil,
            "a hidden row asks for nothing"
        )
    }

    /// A settling window that can actually clear is still reported.
    @Test
    func terminalGateStillSchedulesTheWindowItCanActuallyClear() {
        var gate = TerminalUnreadMembershipGate(settlingInterval: 2)
        let start = Date(timeIntervalSince1970: 1_000)
        let read = desktopReading(unread: [], after: start)

        let displayed = gate.shouldDisplay(
            sessionID: "thread:turn", threadID: "thread", status: .completed,
            turnEndedAt: start,
            terminalBoundaryAt: start, unreadState: read, now: start
        )
        #expect(displayed, "a just-finished turn is not hidden instantly")
        #expect(gate.nextDeadline(now: start) == start.addingTimeInterval(2))

        let hidden = gate.shouldDisplay(
            sessionID: "thread:turn", threadID: "thread", status: .completed,
            turnEndedAt: start,
            terminalBoundaryAt: start, unreadState: read,
            now: start.addingTimeInterval(2.1)
        )
        #expect(!hidden)
        #expect(gate.nextDeadline(now: start.addingTimeInterval(2.1)) == nil)
    }

    /// A reading older than the Turn is not evidence it was read. Desktop's file goes through a
    /// trailing 500 ms debounce with no maximum wait, starved by composer keystrokes: measured
    /// 45.4 s (165 characters) with one write. Hiding is final, so a stale reading must not
    /// retire the row.
    @Test
    func terminalGateWillNotRetireATurnAgainstAReadingOlderThanIt() {
        var gate = TerminalUnreadMembershipGate(
            settlingInterval: 2,
            unreadRecheckInterval: 1
        )
        let boundary = Date(timeIntervalSince1970: 1_000)
        // Authoritative but written half a minute before this Turn ended (a starved debounce).
        let stale = DesktopUnreadStateSnapshot(
            unreadThreadIDs: [],
            source: .current,
            currentAsOf: boundary.addingTimeInterval(-30)
        )

        let listed = gate.shouldDisplay(
            sessionID: "thread:turn", threadID: "thread", status: .completed,
            turnEndedAt: boundary,
            terminalBoundaryAt: boundary, unreadState: stale, now: boundary
        )
        #expect(listed)

        let hidden = !gate.shouldDisplay(
            sessionID: "thread:turn", threadID: "thread", status: .completed,
            turnEndedAt: boundary,
            terminalBoundaryAt: boundary, unreadState: stale,
            now: boundary.addingTimeInterval(600)
        )
        #expect(!hidden, "a row nobody has read must not leave on old silence")

        // The debounce fires and the write still omits the thread (read and cleared inside the
        // burst); now the silence is about this Turn.
        let written = DesktopUnreadStateSnapshot(
            unreadThreadIDs: [],
            source: .current,
            currentAsOf: boundary.addingTimeInterval(45)
        )
        let hiddenNow = !gate.shouldDisplay(
            sessionID: "thread:turn", threadID: "thread", status: .completed,
            turnEndedAt: boundary,
            terminalBoundaryAt: boundary, unreadState: written,
            now: boundary.addingTimeInterval(600)
        )
        #expect(hiddenNow, "a reading that does reach the Turn still retires it")
    }

    /// A reading that predates the Turn books the same forward-measured re-check as an unreadable
    /// one: the settling deadline is in the past, and Desktop's write lands even with a dark screen.
    @Test
    func terminalGateBooksARecheckWhileTheReadingPredatesTheTurn() {
        var gate = TerminalUnreadMembershipGate(
            settlingInterval: 2,
            unreadRecheckInterval: 1
        )
        let boundary = Date(timeIntervalSince1970: 1_000)
        let stale = DesktopUnreadStateSnapshot(
            unreadThreadIDs: [],
            source: .current,
            currentAsOf: boundary.addingTimeInterval(-30)
        )

        let now = boundary.addingTimeInterval(600)
        let displayed = gate.shouldDisplay(
            sessionID: "thread:turn", threadID: "thread", status: .completed,
            turnEndedAt: boundary,
            terminalBoundaryAt: boundary, unreadState: stale, now: now
        )
        #expect(displayed)
        #expect(
            gate.nextDeadline(now: now) == now.addingTimeInterval(1),
            "it waits on the next write, so the re-check is measured from now"
        )
        #expect(
            gate.nextDeadline(now: now, screenIsAvailable: false)
                == now.addingTimeInterval(1),
            "this row waits on the file, not on the user"
        )
    }

    /// Hiding is final within one finished Turn: the sources disagree momentarily, and un-hiding
    /// flashed retired rows back onto the notch (CC-024).
    @Test
    func terminalGateDoesNotBringBackARowItHasAlreadyHidden() {
        var gate = TerminalUnreadMembershipGate(
            settlingInterval: 2,
            unreadRecheckInterval: 1
        )
        let boundary = Date(timeIntervalSince1970: 1_000)
        let unread = desktopReading(unread: ["thread"], after: boundary)
        let read = desktopReading(unread: [], after: boundary)

        let listed = gate.shouldDisplay(
            sessionID: "thread:turn", threadID: "thread", status: .completed,
            turnEndedAt: boundary,
            terminalBoundaryAt: boundary, unreadState: unread, now: boundary
        )
        #expect(listed)

        let hidden = !gate.shouldDisplay(
            sessionID: "thread:turn", threadID: "thread", status: .completed,
            turnEndedAt: boundary,
            terminalBoundaryAt: boundary, unreadState: read,
            now: boundary.addingTimeInterval(0.1)
        )
        #expect(hidden)

        let flashed = gate.shouldDisplay(
            sessionID: "thread:turn", threadID: "thread", status: .completed,
            turnEndedAt: boundary,
            terminalBoundaryAt: boundary, unreadState: unread,
            now: boundary.addingTimeInterval(0.2)
        )
        #expect(!flashed, "a hidden row stays hidden for the Turn it was hidden for")
        #expect(
            gate.nextDeadline(now: boundary.addingTimeInterval(0.2)) == nil,
            "and it goes on asking for nothing"
        )

        // Only a newer Turn brings it back (here without a refresh seeing the running status).
        let again = boundary.addingTimeInterval(10)
        let relisted = gate.shouldDisplay(
            sessionID: "thread:turn", threadID: "thread", status: .completed,
            turnEndedAt: again,
            terminalBoundaryAt: again, unreadState: unread, now: again
        )
        #expect(relisted, "a Turn nobody has read is a Turn to show")
    }

    /// An unreadable state can become readable, so it books the forward-measured re-check too.
    @Test
    func terminalGateBooksARecheckWhileTheUnreadStateIsUnreadable() {
        var gate = TerminalUnreadMembershipGate(
            settlingInterval: 2,
            unreadRecheckInterval: 1
        )
        let start = Date(timeIntervalSince1970: 1_000)
        let unreadable = desktopReading(
            unread: [], source: .lastKnownGood, after: start
        )

        let now = start.addingTimeInterval(600)
        let displayed = gate.shouldDisplay(
            sessionID: "thread:turn", threadID: "thread", status: .completed,
            turnEndedAt: start,
            terminalBoundaryAt: start, unreadState: unreadable, now: now
        )
        #expect(displayed, "an unreadable state must never hide a row")
        #expect(gate.nextDeadline(now: now) == now.addingTimeInterval(1))
    }

    /// A thread Codex will not vouch for (a sub-agent) renders no row on any pass and leaves no
    /// deadline behind; eligibility fails closed.
    @Test @MainActor
    func aSessionThatStopsRenderingStopsSchedulingWakeUps() async throws {
        let paths = makeTemporaryHookPaths()
        defer {
            try? FileManager.default.removeItem(
                at: paths.supportDirectory.deletingLastPathComponent()
            )
        }

        let installer = CodexHookRegistrar(paths: paths)
        let clock = TestClock()
        let repository = HookEventRepository(
            paths: paths,
            clock: clock
        )
        try await installer.install()
        // Hook timestamps must sit on the test clock's timeline, or the settling window is far off.
        let base = clock.now().timeIntervalSince1970
        for event in [
            [
                "received_at": base,
                "hook_event_name": "UserPromptSubmit",
                "session_id": "thread-sub",
                "turn_id": "turn-1"
            ],
            [
                "received_at": base + 1,
                "hook_event_name": "Stop",
                "session_id": "thread-sub",
                "turn_id": "turn-1"
            ]
        ] {
            try JSONSerialization.data(withJSONObject: event).deliver(to: repository)
        }

        let client = CodexAppServerStub(
            listedThreads: [
                .object([
                    "id": .string("thread-sub"),
                    "ephemeral": .bool(false),
                    "threadSource": .string("user"),
                    "agentRole": .string("reviewer"),
                    "name": .string("Sub-agent work")
                ])
            ],
            loadedListResults: []
        )
        let service = LiveCodexMonitorService(
            client: client,
            hookEvents: repository,
            hookRegistrar: installer,
            unreadState: DesktopUnreadStateStub(unreadThreadIDs: []),
            clock: clock,
            desktopProcessIdentifierProvider: { 4_242 }
        )

        let first = await service.fetchSnapshot()
        #expect(first.sessions.isEmpty, "no row before metadata lands")
        await waitForThreadListRequests(client, atLeast: 1, completed: true)

        // Past the settling window but inside every other, so only the gate's deadline could be stale.
        await clock.advance(by: 10)
        let second = await service.fetchSnapshot()
        #expect(second.sessions.isEmpty, "a sub-agent thread renders no row")

        let deadline = await service.nextRefreshDeadline()
        await service.disconnect()

        let staleBy = deadline.map { Int(clock.now().timeIntervalSince($0)) } ?? 0
        #expect(
            deadline == nil || deadline! >= clock.now(),
            "a row nobody renders left a deadline \(staleBy)s in the past"
        )
    }

    /// A suppressed disconnect schedules its own grace expiry; otherwise it waits for an unrelated
    /// wake-up or the 60s heartbeat against a 3s grace budget.
    @Test
    func connectionGateSchedulesItsOwnGraceExpiry() {
        var gate = ConnectionStabilityGate(gracePeriod: 3)
        let t0 = Date(timeIntervalSince1970: 1_000)

        #expect(gate.nextPublishDeadline == nil, "nothing suppressed yet")

        let publishedImmediately = gate.shouldPublish(
            candidate: .disconnected, current: .ready, observedAt: t0
        )
        #expect(!publishedImmediately, "a blip is suppressed")
        #expect(
            gate.nextPublishDeadline == t0.addingTimeInterval(3),
            "the suppression must schedule the moment it expires"
        )

        let publishedAtExpiry = gate.shouldPublish(
            candidate: .disconnected, current: .ready,
            observedAt: t0.addingTimeInterval(3)
        )
        #expect(publishedAtExpiry)

        // Publishing clears it, so the deadline is not re-reported forever.
        let afterPublish = gate.shouldPublish(
            candidate: .disconnected, current: .disconnected,
            observedAt: t0.addingTimeInterval(4)
        )
        #expect(afterPublish)
        #expect(gate.nextPublishDeadline == nil)
    }

    @Test
    func connectionGateStopsSchedulingWhenTheBlipRecovers() {
        var gate = ConnectionStabilityGate(gracePeriod: 3)
        let t0 = Date(timeIntervalSince1970: 1_000)
        _ = gate.shouldPublish(candidate: .disconnected, current: .ready, observedAt: t0)
        #expect(gate.nextPublishDeadline != nil)

        let recovered = gate.shouldPublish(
            candidate: .ready, current: .ready,
            observedAt: t0.addingTimeInterval(1)
        )
        #expect(recovered)
        #expect(gate.nextPublishDeadline == nil, "a recovery must cancel the wake-up")
    }
}

extension Data {
    /// Hands this payload to the store as the transport does; `received_at` becomes the arrival
    /// stamp so ordering tests can choose the instant.
    func deliver(to repository: HookEventRepository) {
        let object = (try? JSONSerialization.jsonObject(with: self)) as? [String: Any]
        let stamp = (object?["received_at"] as? Double)
            .map(Date.init(timeIntervalSince1970:)) ?? Date()
        repository.deliver(self, at: stamp)
    }
}

/// Records what the transport handed over, without reducing any of it.
private final class RecordedHookDelivery: @unchecked Sendable {
    private let lock = NSLock()
    private var bodies: [Data] = []

    /// `.close` by default, as for every lifecycle event; set to hold connections to answer them.
    var holds = false
    private var heldDescriptors: [Int32] = []

    var deliver: @Sendable (Data, Date, Int32) -> AgentHookListener.Disposition {
        { [self] body, _, descriptor in
            lock.lock()
            bodies.append(body)
            let held = holds
            if held { heldDescriptors.append(descriptor) }
            lock.unlock()
            return held ? .held : .close
        }
    }

    /// Writes one answer onto the most recently held connection, as ``HookReplyRegistry`` does,
    /// and closes it.
    @discardableResult
    func answerHeld(with body: Data) -> Bool {
        lock.lock()
        let descriptor = heldDescriptors.popLast()
        lock.unlock()
        guard let descriptor else { return false }
        defer { close(descriptor) }
        return body.withUnsafeBytes { raw in
            guard let base = raw.baseAddress else { return true }
            return write(descriptor, base, raw.count) == raw.count
        }
    }

    var payloads: [[String: Any]] {
        lock.lock()
        let received = bodies
        lock.unlock()
        return received.compactMap {
            (try? JSONSerialization.jsonObject(with: $0)) as? [String: Any]
        }
    }

    var count: Int {
        lock.lock()
        defer { lock.unlock() }
        return bodies.count
    }

    var sessions: [String] {
        payloads.compactMap { $0["session_id"] as? String }
    }
}

// MARK: - Deadlines nothing can clear

/// `nextRefreshDeadline()` may only report an instant a refresh can advance. Three routes
/// broke that with a one-second re-check:
/// - CR-Fable-001: the Codex gate is pruned only on the live-hook branch, so losing Desktop
///   freezes its entries at `now + 1s` forever.
/// - CR-Fable-018: the re-check ran through a sleeping display and a locked screen.
/// - CR-Fable-036: a `tmux` or `ssh` session has no host that can ever hold the front.
extension NotchlineTests {
    /// A row waiting on the user books nothing without a screen: every route to "read" needs an
    /// awake, unlocked display. Ungated, this woke once a second all night.
    @Test
    func terminalGateBooksNothingForARowWaitingOnAUserWithNoScreen() {
        var gate = TerminalUnreadMembershipGate(
            settlingInterval: 2,
            unreadRecheckInterval: 1
        )
        let start = Date(timeIntervalSince1970: 1_000)
        let unread = desktopReading(unread: ["thread"], after: start)

        let now = start.addingTimeInterval(600)
        let displayed = gate.shouldDisplay(
            sessionID: "thread:turn", threadID: "thread", status: .completed,
            turnEndedAt: start,
            terminalBoundaryAt: start, unreadState: unread, now: now
        )
        #expect(displayed, "a locked screen must not retire anything")
        #expect(
            gate.nextDeadline(now: now, screenIsAvailable: false) == nil,
            "a re-check nothing can answer is a busy loop with a deadline's face"
        )
        #expect(
            gate.nextDeadline(now: now, screenIsAvailable: true)
                == now.addingTimeInterval(1)
        )
    }

    /// A row waiting on a file still re-checks through a locked screen: the other application
    /// rewrites it regardless.
    @Test
    func terminalGateStillWatchesAnUnreadableStateThroughALockedScreen() {
        var gate = TerminalUnreadMembershipGate(
            settlingInterval: 2,
            unreadRecheckInterval: 1
        )
        let start = Date(timeIntervalSince1970: 1_000)
        let unreadable = desktopReading(
            unread: [], source: .lastKnownGood, after: start
        )

        let now = start.addingTimeInterval(600)
        _ = gate.shouldDisplay(
            sessionID: "thread:turn", threadID: "thread", status: .completed,
            turnEndedAt: start,
            terminalBoundaryAt: start, unreadState: unreadable, now: now
        )
        #expect(
            gate.nextDeadline(now: now, screenIsAvailable: false)
                == now.addingTimeInterval(1),
            "this row waits on the file, not on the user"
        )
    }

    /// A row waiting on time still clears its settling window through a locked screen.
    @Test
    func terminalGateStillClearsItsSettlingWindowThroughALockedScreen() {
        var gate = TerminalUnreadMembershipGate(settlingInterval: 2)
        let start = Date(timeIntervalSince1970: 1_000)
        let read = desktopReading(unread: [], after: start)

        _ = gate.shouldDisplay(
            sessionID: "thread:turn", threadID: "thread", status: .completed,
            turnEndedAt: start,
            terminalBoundaryAt: start, unreadState: read, now: start
        )
        #expect(
            gate.nextDeadline(now: start, screenIsAvailable: false)
                == start.addingTimeInterval(2)
        )
    }
}

extension NotchlineTests {
    /// A multiplexer session has a terminal and no host: both chains end at `launchd`, but the
    /// emulator's passes through an `.app` bundle and the multiplexer's through a daemonised server.
    @Test
    func aTerminalWhoseAncestryHasNoApplicationCanNeverBeInFront() async throws {
        let ancestry: [Int32: Int32] = [
            100: 200, 200: 300, 300: 1,
            400: 500, 500: 600, 600: 700, 700: 1
        ]
        let executables: [Int32: String] = [
            200: "/bin/zsh",
            300: "/opt/homebrew/bin/tmux",
            500: "/bin/zsh",
            600: "/usr/bin/login",
            700: "/Applications/Ghostty.app/Contents/MacOS/ghostty"
        ]
        let reader = ControllingTerminalGestureReader(
            controllingTerminalPath: { _ in "/dev/ttys009" },
            lastAccess: { _ in Date(timeIntervalSince1970: 500) },
            parentProcessIdentifier: { ancestry[$0] },
            executablePath: { executables[$0] },
            frontmostProcessIdentifier: { 9_999 },
            screenIsAvailable: { true }
        )

        let multiplexed = try #require(await reader.reading(forProcessIdentifier: 100))
        #expect(!multiplexed.hostIsInFrontOfTheUser)
        #expect(
            !multiplexed.hostCanEverBeInFrontOfTheUser,
            """
            nothing in this chain is an application, so no gesture at it can \
            ever coincide with its host holding the front
            """
        )

        let hosted = try #require(await reader.reading(forProcessIdentifier: 400))
        #expect(!hosted.hostIsInFrontOfTheUser, "another application is in front")
        #expect(
            hosted.hostCanEverBeInFrontOfTheUser,
            "a terminal on another display is a question worth asking again"
        )
    }

    /// The front check still requires a screen, even though the ancestry walk now always runs.
    @Test
    func aTerminalInFrontOfALockedScreenIsNotInFrontOfAnybody() async throws {
        let ancestry: [Int32: Int32] = [100: 200, 200: 300, 300: 1]
        let executables: [Int32: String] = [
            200: "/bin/zsh",
            300: "/Applications/Ghostty.app/Contents/MacOS/ghostty"
        ]
        func reader(screenIsAvailable: Bool) -> ControllingTerminalGestureReader {
            ControllingTerminalGestureReader(
                controllingTerminalPath: { _ in "/dev/ttys009" },
                lastAccess: { _ in Date(timeIntervalSince1970: 500) },
                parentProcessIdentifier: { ancestry[$0] },
                executablePath: { executables[$0] },
                frontmostProcessIdentifier: { 300 },
                screenIsAvailable: { screenIsAvailable }
            )
        }

        let lit = try #require(
            await reader(screenIsAvailable: true).reading(forProcessIdentifier: 100)
        )
        #expect(lit.hostIsInFrontOfTheUser)

        let dark = try #require(
            await reader(screenIsAvailable: false).reading(forProcessIdentifier: 100)
        )
        #expect(!dark.hostIsInFrontOfTheUser, "a locked screen shows nobody anything")
        #expect(
            dark.hostCanEverBeInFrontOfTheUser,
            "the host still exists; it is the screen that is off"
        )
    }
}

extension NotchlineTests {
    /// A `tmux` or `ssh` session's finished row stays listed and books nothing; it once entered
    /// the unread gate for having a device and refreshed both products once a second.
    @Test @MainActor
    func aSessionUnderAMultiplexerBooksNoRecheckForItsFinishedRow() async throws {
        let harness = try ClaudeCodeHarness()
        defer { harness.tearDown() }
        try harness.registerHooks()
        let cwd = "/Users/someone/Projects/thing"

        try harness.queue(event: "UserPromptSubmit", session: "cli", turn: "p-1", at: 100)
        try harness.queue(event: "Stop", session: "cli", turn: "p-1", at: 101)
        harness.live = [harness.session(id: "cli", cwd: cwd, pid: 4_242)]

        // A real device, under a host that runs to `launchd` without passing through an application.
        harness.setTerminalGesture(
            Date(timeIntervalSince1970: 100),
            forPID: 4_242,
            hostIsInFront: false,
            hostCanEverBeInFront: false
        )

        let snapshot = await harness.service.fetchSnapshot()
        #expect(snapshot.sessions.count == 1, "the row is right to stay listed")
        let deadline = await harness.service.nextRefreshDeadline()
        #expect(
            (deadline?.timeIntervalSinceNow ?? .infinity) > 2,
            "a question with no possible answer must book no re-check"
        )

        harness.setTerminalGesture(
            Date(timeIntervalSince1970: 100),
            forPID: 4_242,
            hostIsInFront: false,
            hostCanEverBeInFront: true
        )
        _ = await harness.service.fetchSnapshot()
        let asking = await harness.service.nextRefreshDeadline()
        #expect((asking?.timeIntervalSinceNow ?? .infinity) <= 1.1)
    }

    /// A removed row stays in what Claude Code reports, since delisting signals a Turn ended
    /// (CR-Fable-004), but leaves the unread gate (CR-Fable-003).
    @Test @MainActor
    func aRowTheUserRemovedLeavesTheGateWithoutLeavingTheList() async throws {
        let harness = try ClaudeCodeHarness()
        defer { harness.tearDown() }
        try harness.registerHooks()
        let cwd = "/Users/someone/Projects/thing"

        try harness.queue(event: "UserPromptSubmit", session: "cli", turn: "p-1", at: 100)
        try harness.queue(event: "Stop", session: "cli", turn: "p-1", at: 101)
        harness.live = [harness.session(id: "cli", cwd: cwd, pid: 4_242)]
        harness.lastTerminalGestureByPID = [4_242: Date(timeIntervalSince1970: 100)]

        let unread = await harness.service.fetchSnapshot()
        let row = try #require(unread.sessions.first)
        let asking = await harness.service.nextRefreshDeadline()
        #expect((asking?.timeIntervalSinceNow ?? .infinity) <= 1.1)

        let afterRemoval = await harness.service
            .fetchSnapshot(dismissedRowIDs: [row.id])
        #expect(
            afterRemoval.sessions.map(\.id) == [row.id],
            "the Turn has not gone anywhere, so the product still reports it"
        )
        let quiet = await harness.service.nextRefreshDeadline()
        #expect(
            (quiet?.timeIntervalSinceNow ?? .infinity) > 2,
            """
            nothing can change what the user has already decided, so nothing \
            should wake for it
            """
        )

        // One removal must not quieten the rows the user is still waiting on.
        try harness.queue(event: "UserPromptSubmit", session: "two", turn: "p-2", at: 100)
        try harness.queue(event: "Stop", session: "two", turn: "p-2", at: 101)
        harness.live = [
            harness.session(id: "cli", cwd: cwd, pid: 4_242),
            harness.session(id: "two", cwd: cwd, pid: 4_243)
        ]
        harness.lastTerminalGestureByPID = [
            4_242: Date(timeIntervalSince1970: 100),
            4_243: Date(timeIntervalSince1970: 100)
        ]
        _ = await harness.service.fetchSnapshot(dismissedRowIDs: [row.id])
        let stillAsking = await harness.service.nextRefreshDeadline()
        #expect((stillAsking?.timeIntervalSinceNow ?? .infinity) <= 1.1)
    }

    /// A locked screen stops the re-check; the display-wake edge restarts it, or the row would
    /// wait for the heartbeat.
    @Test @MainActor
    func aLockedScreenStopsTheRecheckAndComingBackRestartsIt() async throws {
        let harness = try ClaudeCodeHarness()
        defer { harness.tearDown() }
        try harness.registerHooks()
        let cwd = "/Users/someone/Projects/thing"

        try harness.queue(event: "UserPromptSubmit", session: "cli", turn: "p-1", at: 100)
        try harness.queue(event: "Stop", session: "cli", turn: "p-1", at: 101)
        harness.live = [harness.session(id: "cli", cwd: cwd, pid: 4_242)]
        harness.lastTerminalGestureByPID = [4_242: Date(timeIntervalSince1970: 100)]

        let lit = await harness.service.fetchSnapshot()
        #expect(lit.sessions.count == 1)
        let asking = await harness.service.nextRefreshDeadline()
        #expect((asking?.timeIntervalSinceNow ?? .infinity) <= 1.1)

        harness.screenIsAvailable = false
        let dark = await harness.service.fetchSnapshot()
        #expect(dark.sessions.count == 1, "a locked screen retires nothing")
        let quiet = await harness.service.nextRefreshDeadline()
        #expect(
            (quiet?.timeIntervalSinceNow ?? .infinity) > 2,
            """
            nothing can retire this row until there is a screen, so nothing \
            should wake for it
            """
        )

        // The edge re-arms the row; the deadline bounds how late it leaves after that.
        let triggers = harness.service.stateChangeEvents
        let observer = Task {
            for await _ in triggers { return true }
            return false
        }
        harness.announceScreenAvailable()
        let signalled = await withTaskGroup(of: Bool.self) { group in
            group.addTask { await observer.value }
            group.addTask {
                try? await Task.sleep(nanoseconds: 3_000_000_000)
                return false
            }
            let result = await group.next() ?? false
            group.cancelAll()
            return result
        }
        observer.cancel()
        #expect(signalled, "the screen coming back has to wake the loop")

        _ = await harness.service.fetchSnapshot()
        let askingAgain = await harness.service.nextRefreshDeadline()
        #expect((askingAgain?.timeIntervalSinceNow ?? .infinity) <= 1.1)
    }
}

private final class MutableDesktopProcessIdentifier: @unchecked Sendable {
    private let lock = NSLock()
    private var stored: pid_t?

    init(_ value: pid_t?) { stored = value }

    var value: pid_t? {
        get { lock.lock(); defer { lock.unlock() }; return stored }
        set { lock.lock(); stored = newValue; lock.unlock() }
    }
}

extension NotchlineTests {
    /// Losing Desktop must not freeze the Codex gate at 1 Hz. Entries are pruned only in
    /// `sessions(from:)` (live-hook branch); the stuck-deadline filter misses it because the
    /// instant moves on every call.
    @Test @MainActor
    func losingHookObservationPrunesTheCodexUnreadGate() async throws {
        let paths = makeTemporaryHookPaths()
        defer {
            try? FileManager.default.removeItem(
                at: paths.supportDirectory.deletingLastPathComponent()
            )
        }
        let installer = CodexHookRegistrar(paths: paths)
        let repository = HookEventRepository(paths: paths)
        try await installer.install()
        for event in ["UserPromptSubmit", "Stop"] {
            try JSONSerialization.data(withJSONObject: [
                "received_at": Date().timeIntervalSince1970,
                "hook_event_name": event,
                "session_id": "thread-frozen",
                "turn_id": "turn-frozen"
            ]).deliver(to: repository)
        }

        let client = CodexAppServerStub(
            listedThreads: [.object([
                "id": .string("thread-frozen"),
                "ephemeral": .bool(false),
                "threadSource": .string("user"),
                "updatedAt": .number(Date().timeIntervalSince1970),
                "name": .string("Frozen")
            ])],
            loadedListResults: []
        )
        let unreadState = DesktopUnreadStateStub(
            unreadThreadIDs: ["thread-frozen"]
        )
        let desktop = MutableDesktopProcessIdentifier(4_242)
        let service = LiveCodexMonitorService(
            client: client,
            hookEvents: repository,
            hookRegistrar: installer,
            unreadState: unreadState,
            desktopProcessIdentifierProvider: { desktop.value }
        )
        defer { Task { await service.disconnect() } }

        var listed = false
        for _ in 0 ..< 100 {
            let snapshot = await service.fetchSnapshot()
            if snapshot.sessions.first?.status == .completed {
                listed = true
                break
            }
            try await Task.sleep(nanoseconds: 10_000_000)
        }
        #expect(listed, "an unread finished row is listed")
        let asking = await service.nextRefreshDeadline()
        #expect(
            (asking?.timeIntervalSinceNow ?? .infinity) <= 1.1,
            "while it is on screen, the row asks to be looked at again"
        )

        // Quitting Desktop loses hook observation; this branch publishes no rows.
        desktop.value = nil
        let quiet = await service.fetchSnapshot()
        #expect(quiet.sessions.isEmpty, "nothing is on screen any more")
        let deadline = await service.nextRefreshDeadline()
        #expect(
            (deadline?.timeIntervalSinceNow ?? .infinity) > 1.5,
            """
            a branch that cannot evaluate a row must not book a re-check for \
            one: this is the 1 Hz that ran with an empty notch
            """
        )
    }

