        #expect(turn.runningSubagentIDs == [agent])
        #expect(turn.pausedForBackgroundWork)
        #expect(MonitorAggregation.effectiveStatus(of: row(turn)) == .running)

        // Its own payload still lists it, so nothing reads that copy of the list.
        try deliver([
            "received_at": 118.05, "hook_event_name": "SubagentStop",
            "session_id": thread, "prompt_id": prompt, "agent_id": agent,
            "agent_type": "general-purpose", "background_tasks": inFlight
        ])
        turn = try #require(await repository.drainDeliveredEvents().turns.first)
        #expect(turn.runningSubagentIDs.isEmpty)
        #expect(turn.status == .completed)
        #expect(!row(turn).showsSubagentBadge)
        #expect(
            MonitorAggregation.effectiveStatus(of: row(turn)) == .running,
            "the parent is re-entered 50 ms from here; Completed is a state the thread is never in"
        )

        // 50 ms later, measured: Claude Code re-enters the parent under its own prompt id.
        try deliver([
            "received_at": 118.10, "hook_event_name": "UserPromptSubmit",
            "session_id": thread, "prompt_id": resumed
        ])
        turn = try #require(await repository.drainDeliveredEvents().turns.first)
        #expect(turn.turnID == resumed)
        #expect(turn.status == .running)
        #expect(!turn.pausedForBackgroundWork)

        // An empty list means nothing is in flight.
        try deliver([
            "received_at": 121.22, "hook_event_name": "Stop",
            "session_id": thread, "prompt_id": resumed,
            "background_tasks": [[String: Any]]()
        ])
        turn = try #require(await repository.drainDeliveredEvents().turns.first)
        #expect(turn.status == .completed)
        #expect(!turn.pausedForBackgroundWork)
        #expect(MonitorAggregation.effectiveStatus(of: row(turn)) == .completed)
    }

    /// Every terminal event writes the flag: an empty list clears it, and an absent field (every
    /// Codex stop, older Claude Code) reads as finished.
    @Test @MainActor
    func aTerminalThatNamesNoBackgroundWorkIsTheThreadFinishing() async throws {
        for kind in [AnyHookVocabularyCase.codex, .claudeCode] {
            let paths = makeTemporaryHookPaths()
            defer {
                try? FileManager.default.removeItem(
                    at: paths.supportDirectory.deletingLastPathComponent()
                )
            }
            let repository = HookEventRepository(
                paths: paths,
                vocabulary: kind.vocabulary
            )
            let thread = "586df4ed-e1db-4405-bfd4-e9977957b132"

            func deliver(_ body: [String: Any]) throws {
                try JSONSerialization.data(withJSONObject: body).deliver(to: repository)
            }

            try deliver([
                "received_at": 100.0, "hook_event_name": "UserPromptSubmit",
                "session_id": thread, kind.turnKey: "t-1"
            ])
            try deliver([
                "received_at": 101.0, "hook_event_name": "Stop",
                "session_id": thread, kind.turnKey: "t-1"
            ])
            var turn = try #require(await repository.drainDeliveredEvents().turns.first)
            #expect(!turn.pausedForBackgroundWork, "\(kind.name)")
            #expect(turn.status == .completed, "\(kind.name)")

            try deliver([
                "received_at": 102.0, "hook_event_name": "UserPromptSubmit",
                "session_id": thread, kind.turnKey: "t-2"
            ])
            try deliver([
                "received_at": 103.0, "hook_event_name": "Stop",
                "session_id": thread, kind.turnKey: "t-2",
                "background_tasks": [[String: Any]]()
            ])
            turn = try #require(await repository.drainDeliveredEvents().turns.first)
            #expect(!turn.pausedForBackgroundWork, "\(kind.name)")
            #expect(turn.status == .completed, "\(kind.name)")
        }
    }

    /// The list is carried whole or not at all; losing it costs only the pause.
    @Test @MainActor
    func aListTooLongToCarryIsLeftOutRatherThanCutShort() throws {
        func payload(taskCount: Int, description: String) throws -> Data {
            try JSONSerialization.data(withJSONObject: [
                "hook_event_name": "Stop",
                "session_id": "s-1",
                "prompt_id": "p-1",
                "background_tasks": (0 ..< taskCount).map {
                    [
                        "id": "task-\($0)", "type": "subagent",
                        "status": "running", "description": description
                    ]
                }
            ])
        }

        // Past the identity limit, so this pins the list's own ceiling.
        let carried = try #require(
            HookPayload.distilled(
                from: try payload(
                    taskCount: 12,
                    description: String(repeating: "d", count: 200)
                ),
                admittingRequestWhere: admitsNoRequest
            )
        )
        #expect(carried.backgroundTasks?.count == 12)
        #expect(carried.pausesForBackgroundWork)

        let refused = try #require(
            HookPayload.distilled(
                from: try payload(
                    taskCount: 16,
                    description: String(repeating: "d", count: 1_000)
                ),
                admittingRequestWhere: admitsNoRequest
            )
        )
        #expect(refused.backgroundTasks == nil)
        #expect(!refused.pausesForBackgroundWork)
        #expect(refused.turnID == "p-1")
        #expect(refused.sessionID == "s-1")
    }
}

private enum AnyHookVocabularyCase {
    case codex
    case claudeCode

    var vocabulary: any AgentHookVocabulary {
        switch self {
        case .codex: CodexHookVocabulary()
        case .claudeCode: ClaudeCodeHookVocabulary()
        }
    }

    /// Codex calls the turn identity `turn_id`; Claude Code calls it `prompt_id`.
    var turnKey: String {
        switch self {
        case .codex: "turn_id"
        case .claudeCode: "prompt_id"
        }
    }

    var name: String {
        switch self {
        case .codex: "Codex"
        case .claudeCode: "Claude Code"
        }
    }
}

extension NotchlineTests {
    /// A read Turn stays read when its subagent stops after the reading (Codex). A subagent can
    /// outlive its Turn by 91 s (measured 2026-08-22); the unread reading must be newer than the
    /// Turn's own end, not ``HookTurnState/terminalBoundaryAt``. The settling window still starts
    /// at the subagent's boundary.
    @Test
    func terminalGateKeepsAReadVerdictWhenASubagentOutlivesTheTurn() {
        var gate = TerminalUnreadMembershipGate(
            settlingInterval: 2,
            unreadRecheckInterval: 1
        )
        let turnEnded = Date(timeIntervalSince1970: 1_000)
        let subagentStopped = turnEnded.addingTimeInterval(91)
        let unread = DesktopUnreadStateSnapshot(
            unreadThreadIDs: ["thread"],
            source: .current,
            currentAsOf: turnEnded.addingTimeInterval(0.6)
        )
        let read = DesktopUnreadStateSnapshot(
            unreadThreadIDs: [],
            source: .current,
            currentAsOf: turnEnded.addingTimeInterval(20.5)
        )

        let listed = gate.shouldDisplay(
            sessionID: "thread:turn", threadID: "thread", status: .completed,
            turnEndedAt: turnEnded, terminalBoundaryAt: turnEnded,
            unreadState: unread, now: turnEnded
        )
        #expect(listed)

        // While the subagent works the row shows via the running path and holds no gate entry.
        let running = gate.shouldDisplay(
            sessionID: "thread:turn", threadID: "thread", status: .running,
            turnEndedAt: turnEnded, terminalBoundaryAt: turnEnded,
            unreadState: read, now: turnEnded.addingTimeInterval(20.6)
        )
        #expect(running)

        let graced = gate.shouldDisplay(
            sessionID: "thread:turn", threadID: "thread", status: .completed,
            turnEndedAt: turnEnded, terminalBoundaryAt: subagentStopped,
            unreadState: read, now: subagentStopped
        )
        #expect(
            graced,
            "a row does not vanish in the same instant its last subagent does"
        )
        #expect(
            gate.nextDeadline(now: subagentStopped)
                == subagentStopped.addingTimeInterval(2),
            "and the window that clears it is measured from that instant"
        )

        let hidden = !gate.shouldDisplay(
            sessionID: "thread:turn", threadID: "thread", status: .completed,
            turnEndedAt: turnEnded, terminalBoundaryAt: subagentStopped,
            unreadState: read, now: subagentStopped.addingTimeInterval(2)
        )
        #expect(
            hidden,
            "the read the user actually performed still retires the row"
        )
        #expect(
            gate.nextDeadline(now: subagentStopped.addingTimeInterval(2)) == nil
        )
    }

    /// `endedAgain` asks the Turn's own terminal: a subagent's boundary is not a new answer.
    @Test
    func terminalGateDoesNotRelistARowBecauseASubagentStopped() {
        var gate = TerminalUnreadMembershipGate(settlingInterval: 2)
        let turnEnded = Date(timeIntervalSince1970: 1_000)
        let unread = desktopReading(unread: ["thread"], after: turnEnded)
        let read = desktopReading(unread: [], after: turnEnded)

        _ = gate.shouldDisplay(
            sessionID: "thread:turn", threadID: "thread", status: .completed,
            turnEndedAt: turnEnded, terminalBoundaryAt: turnEnded,
            unreadState: unread, now: turnEnded
        )
        let hidden = !gate.shouldDisplay(
            sessionID: "thread:turn", threadID: "thread", status: .completed,
            turnEndedAt: turnEnded, terminalBoundaryAt: turnEnded,
            unreadState: read, now: turnEnded.addingTimeInterval(0.1)
        )
        #expect(hidden)

        let late = turnEnded.addingTimeInterval(120)
        let relisted = gate.shouldDisplay(
            sessionID: "thread:turn", threadID: "thread", status: .completed,
            turnEndedAt: turnEnded, terminalBoundaryAt: late,
            unreadState: read, now: late
        )
        #expect(
            !relisted,
            "a subagent stopping is not a Turn the user has not read"
        )
    }

    /// The same defect on Claude Code: `ClaudeCodeDesktopReadStateRepository` compares against
    /// the Turn's own end, not `terminalBoundaryAt`.
    @Test
    func readStateAnswersForTheTurnRatherThanItsSubagents() throws {
        let turnEnded = Date(timeIntervalSince1970: 1_000)
        let readAt = turnEnded.addingTimeInterval(20)
        let subagentStopped = turnEnded.addingTimeInterval(91)
        let snapshot = ClaudeCodeReadStateSnapshot(
            entries: [
                "session": ClaudeCodeReadStateSnapshot.Entry(
                    lastFocusedAt: readAt,
                    isArchived: false
                )
            ],
            source: .current
        )

        #expect(
            snapshot.readState(
                forSession: "session",
                terminalBoundaryAt: turnEnded
            ) == .read,
            "a focus after the answer landed is the user having read it"
        )
        #expect(
            snapshot.readState(
                forSession: "session",
                terminalBoundaryAt: subagentStopped
            ) == .unread,
            "and dating it against the subagent's boundary is what threw it away"
        )
    }
}

// MARK: - What this build says it is

extension NotchlineTests {
    /// The windows read `MARKETING_VERSION` and `CURRENT_PROJECT_VERSION`; figures are not
    /// pinned so releases need no test edit.
    @Test
    func theVersionOnTheWindowIsTheOneTheBuildStamped() throws {
        let marketing = try #require(
            Bundle.main.object(forInfoDictionaryKey: "CFBundleShortVersionString") as? String
        )
        let build = try #require(
            Bundle.main.object(forInfoDictionaryKey: "CFBundleVersion") as? String
        )

        #expect(AppVersion.marketing == marketing)
        #expect(AppVersion.build == build)

        let stage = try #require(AppVersion.stage, "this build is still qualified")
        #expect(AppVersion.name == "\(marketing) \(stage)")
        #expect(AppVersion.summary == "Version \(marketing) \(stage) (\(build))")
        // The build number is what a bug report needs; VoiceOver would read it as punctuation.
        #expect(AppVersion.spokenSummary == "Version \(marketing) \(stage), build \(build)")
    }

    /// `CFBundleShortVersionString` must be dot-separated numbers, so `0.1.0 Alpha` fails
    /// notarisation; the stage word is joined only where drawn.
    @Test
    func theStageWordIsNeverStampedIntoTheMarketingVersion() throws {
        let marketing = try #require(AppVersion.marketing)
        let components = marketing.split(separator: ".", omittingEmptySubsequences: false)

        #expect(!components.isEmpty)
        for component in components {
            #expect(
                !component.isEmpty && component.allSatisfy(\.isNumber),
                "\(marketing) is not a version macOS can compare"
            )
        }

        if let stage = AppVersion.stage {
            #expect(!marketing.localizedCaseInsensitiveContains(stage))
            #expect(!stage.isEmpty)
        }
    }
}

private extension Path {
    var elements: [Path.Element] {
        var collected: [Path.Element] = []
        forEach { collected.append($0) }
        return collected
    }
}

private extension CGPoint {
    func isNear(_ other: CGPoint, within tolerance: CGFloat = 0.000_1) -> Bool {
        hypot(x - other.x, y - other.y) < tolerance
    }
}

@MainActor
private func findField(_ view: NSView) -> AnswerFieldView? {
    if let field = view as? AnswerFieldView { return field }
    for child in view.subviews {
        if let found = findField(child) { return found }
    }
    return nil
}
